INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'I begynnelsen skapte Gud himmelen og jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Og jorden var øde og tom, og det var mørke over det store dyp, og Guds Ånd svevde over vannene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Da sa Gud: Det bli lys! Og det blev lys.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Og Gud så at lyset var godt, og Gud skilte lyset fra mørket.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Og Gud kalte lyset dag, og mørket kalte han natt. Og det blev aften, og det blev morgen, første dag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Og Gud sa: Det bli en hvelving midt i vannene, og den skal skille vann fra vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Og Gud gjorde hvelvingen og skilte vannet som er under hvelvingen, fra vannet som er over hvelvingen. Og det blev så.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Og Gud kalte hvelvingen himmel. Og det blev aften, og det blev morgen, annen dag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Og Gud sa: Vannet under himmelen samle sig til ett sted, og det blev så.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Og Gud kalte det tørre land jord, og vannet som hadde samlet sig, kalte han hav. Og Gud så at det var godt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Og Gud sa: Jorden bære frem gress, urter som sår sig, frukttrær som bærer frukt med deres frø i, på jorden, hvert efter sitt slag. Og det blev så.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Og jorden bar frem gress, urter som sår sig, hver efter sitt slag, og trær som bærer frukt med deres frø i, hvert efter sitt slag. Og Gud så at det var godt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Og det blev aften, og det blev morgen, tredje dag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Og Gud sa: Det bli lys på himmelhvelvingen til å skille dagen fra natten! Og de skal være til tegn og fastsatte tider og dager og år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Og de skal være til lys på himmelhvelvingen, til å lyse over jorden. Og det blev så.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Og Gud gjorde de to store lys, det største til å råde om dagen og det mindre til å råde om natten, og stjernene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Og Gud satte dem på himmelhvelvingen til å lyse over jorden');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'og til å råde om dagen og om natten og til å skille lyset fra mørket. Og Gud så at det var godt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Og det blev aften, og det blev morgen, fjerde dag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Og Gud sa: Det vrimle av liv i vannet, og fugler flyve over jorden under himmelhvelvingen!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Og Gud skapte de store sjødyr og alt levende som rører sig, som det vrimler av i vannet, hvert efter sitt slag, og alle vingede fugler, hver efter sitt slag. Og Gud så at det var godt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Og Gud velsignet dem og sa: Vær fruktbare og bli mange og opfyll vannet i havet, og fuglene skal bli tallrike på jorden!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Og det blev aften, og det blev morgen, femte dag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Og Gud sa: Jorden la fremgå levende vesener, hvert efter sitt slag, fe, kryp og ville dyr, hvert efter sitt slag! Og det blev så.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Og Gud gjorde de ville dyr, hvert efter sitt slag, og feet efter sitt slag og alt jordens kryp, hvert efter sitt slag. Og Gud så at det var godt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Og Gud sa: La oss gjøre mennesker i vårt billede, efter vår lignelse, og de skal råde over fiskene i havet og over fuglene under himmelen og over feet og over all jorden og over alt kryp som rører sig på jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Og Gud skapte mennesket i sitt billede, i Guds billede skapte han det; til mann og kvinne skapte han dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Og Gud velsignet dem og sa til dem: Vær fruktbare og bli mange og opfyll jorden og legg den under eder, og råd over fiskene i havet og over fuglene under himmelen og over hvert dyr som rører sig på jorden!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Og Gud sa: Se, jeg gir eder alle urter som sår sig, alle som finnes på jorden, og alle trær med frukt som sår sig; de skal være til føde for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Og alle dyr på jorden og alle fugler under himmelen og alt som rører sig på jorden, alt som det er livsånde i, gir jeg alle grønne urter å ete. Og det blev så.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Og Gud så på alt det han hadde gjort, og se, det var såre godt. Og det blev aften, og det blev morgen, sjette dag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Så blev himmelen og jorden med hele sin hær fullendt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Og Gud fullendte på den syvende dag det verk som han hadde gjort, og han hvilte på den syvende dag fra all den gjerning som han hadde gjort.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Og Gud velsignet den syvende dag og helliget den; for på den hvilte han fra all sin gjerning, den som Gud gjorde da han skapte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Dette er himmelens og jordens historie, da de blev skapt, den tid da Gud Herren gjorde jord og himmel:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Det var ennu ingen markens busk på jorden, og ingen markens urt var ennu vokset frem; for Gud Herren hadde ikke latt det regne på jorden, og der var intet menneske til å dyrke jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Da steg det op en damp av jorden og vannet hele jordens overflate.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Og Gud Herren dannet mennesket av jordens muld og blåste livets ånde i hans nese; og mennesket blev til en levende sjel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Og Gud Herren plantet en have i Eden, i Østen, og der satte han mennesket som han hadde dannet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Og Gud Herren lot trær av alle slag vokse op av jorden, prektige å se til og gode å ete av, og midt i haven livsens tre og treet til kunnskap om godt og ondt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Og det gikk en elv ut fra Eden og vannet haven; og siden delte den sig i fire strømmer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Den første heter Pison; det er den som løper omkring hele landet Havila, der hvor det er gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Og gullet i dette land er godt; der er bdellium og onyks-stenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Den annen elv heter Gihon; det er den som løper omkring hele landet Kus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Den tredje elv heter Hiddekel; det er den som går østenfor Assur. Og den fjerde elv er Frat.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Og Gud Herren tok mennesket og satte ham i Edens have til å dyrke og vokte den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Og Gud Herren bød mennesket: Du må fritt ete av alle trær i haven;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'men treet til kunnskap om godt og ondt, det må du ikke ete av; for på den dag du eter av det, skal du visselig dø.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Og Gud Herren sa: Det er ikke godt at mennesket er alene; jeg vil gjøre ham en medhjelp som er hans like.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Og Gud Herren hadde dannet av jorden alle dyr på marken og alle fugler under himmelen, og han ledet dem til mennesket for å se hvad han vilde kalle dem; og som mennesket kalte hver levende skapning, så skulde den hete.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Så gav mennesket navn til alt feet og fuglene under himmelen og alle ville dyr; men for et menneske fant han ingen medhjelp som var hans like.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Da lot Gud Herren en dyp søvn falle på mennesket, og mens han sov, tok han et av hans ribben og fylte igjen med kjøtt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Og Gud Herren bygget av det ribben han hadde tatt av mennesket, en kvinne og ledet henne til mennesket.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Da sa mennesket: Dette er endelig ben av mine ben og kjøtt av mitt kjøtt; hun skal kalles manninne, for av mannen er hun tatt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Derfor skal mannen forlate sin far og sin mor og bli hos sin hustru, og de skal være ett kjød.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Og de var nakne både Adam og hans hustru, men bluedes ikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Men slangen var listigere enn alle dyr på marken som Gud Herren hadde gjort, og den sa til kvinnen: Har Gud virkelig sagt: I skal ikke ete av noget tre i haven?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Og kvinnen sa til slangen: Vi kan ete av frukten på trærne i haven;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'men om frukten på det tre som er midt i haven, har Gud sagt: I skal ikke ete av den og ikke røre ved den, for da skal I dø.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Da sa slangen til kvinnen: I skal visselig ikke dø;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'for Gud vet at på den dag I eter av det, skal eders øine åpnes, og I skal bli likesom Gud og kjenne godt og ondt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Og kvinnen så at treet var godt å ete av, og at det var en lyst for øinene, og at det var et prektig tre, siden en kunde få forstand av det, og hun tok av frukten og åt; og hun gav sin mann med sig, og han åt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Da blev begges øine åpnet, og de blev var at de var nakne, og de heftet fikenblad sammen og bandt dem om livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Og de hørte Gud Herren som vandret i haven, da dagen var blitt kjølig; og Adam og hans hustru skjulte sig for Gud Herrens åsyn mellem trærne i haven.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Da kalte Gud Herren på Adam og sa til ham: Hvor er du?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Og han svarte: Jeg hørte dig i haven; da blev jeg redd, fordi jeg var naken, og jeg skulte mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Da sa han: Hvem har sagt dig at du er naken? Har du ett av det tre som jeg forbød dig å ete av?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Og Adam sa: Kvinnen som du gav mig til å være hos mig, hun gav mig av treet, og jeg åt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Da sa Gud Herren til kvinnen: Hvad er det du har gjort! Og kvinnen sa: Slangen dåret mig, og jeg åt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Da sa Gud Herren til slangen: Fordi du gjorde dette, så skal du være forbannet blandt alt feet og blandt alle de ville dyr. På din buk skal du krype, og støv skal du ete alle ditt livs dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Og jeg vil sette fiendskap mellem dig og kvinnen og mellem din ætt og hennes ætt; den skal knuse ditt hode, men du skal knuse dens hæl.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Til kvinnen sa han: Jeg vil gjøre din møie stor i ditt svangerskap; med smerte skal du føde dine barn, og til din mann skal din attrå stå, og han skal råde over dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Og til Adam sa han: Fordi du lød din hustru og åt av det tre som jeg forbød dig å ete av, så skal jorden være forbannet for din skyld! Med møie skal du nære dig av den alle ditt livs dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Torner og tistler skal den bære dig, og du skal ete urtene på marken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'I ditt ansikts sved skal du ete ditt brød, inntil du vender tilbake til jorden, for av den er du tatt; for støv er du, og til støv skal du vende tilbake.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Og Adam kalte sin hustru Eva, fordi hun er alle levendes mor.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Og Gud Herren gjorde kjortler av skinn til Adam og hans hustru og klædde dem med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Og Gud Herren sa: Se, mennesket er blitt som en av oss til å kjenne godt og ondt; bare han nu ikke rekker ut sin hånd og tar også av livsens tre og eter og lever til evig tid!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Så viste Gud Herren ham ut av Edens have og satte ham til å dyrke jorden, som han var tatt av.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Og han drev mennesket ut, og foran Edens have satte han kjerubene med det luende sverd som vendte sig hit og dit, for å vokte veien til livsens tre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Og Adam holdt sig til sin hustru Eva, og hun blev fruktsommelig og fødte Kain; da sa hun: Jeg har fått en mann ved Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Siden fødte hun Abel, hans bror. Og Abel blev fårehyrde, men Kain blev jorddyrker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Da nogen tid var gått, hendte det at Kain bar frem for Herren et offer av jordens grøde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Og Abel bar også frem et offer, som han tok av de førstefødte lam i sin hjord og deres fett; og Herren så til Abel og hans offer,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'men til Kain og hans offer så han ikke. Da blev Kain meget vred, og han stirret ned for sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Og Herren sa til Kain: Hvorfor er du vred, og hvorfor stirrer du ned for dig?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Er det ikke så at dersom du har godt i sinne, da kan du løfte op ditt ansikt? Men har du ikke godt i sinne, da ligger synden på lur ved døren, og dens attrå står til dig, men du skal være herre over den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Og Kain talte til Abel, sin bror. Og da de engang var ute på marken, for Kain løs på Abel, sin bror, og slo ham ihjel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Da sa Herren til Kain: Hvor er Abel, din bror? Han svarte: Jeg vet ikke; skal jeg passe på min bror?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Men han sa: Hvad har du gjort? Hør, din brors blod roper til mig fra jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Og nu skal du være bannlyst fra den jord som lot op sin munn og tok imot din brors blod av din hånd!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Når du dyrker jorden, skal den ikke mere gi dig sin grøde; omflakkende og hjemløs skal du være på jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Da sa Kain til Herren: Min misgjerning er større enn at jeg kan bære den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Se, du har idag drevet mig ut av landet, og jeg må skjule mig for ditt åsyn; og jeg vil bli omflakkende og hjemløs på jorden, og det vil gå så at hver den som finner mig, slår mig ihjel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Men Herren sa til ham: Nei! for slår nogen Kain ihjel, skal han lide syvfold hevn. Og Herren gav Kain et merke, forat ikke nogen som møtte ham, skulde slå ham ihjel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Så gikk Kain bort fra Herrens åsyn og bosatte sig i landet Nod, østenfor Eden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Og Kain holdt sig til sin hustru, og hun blev fruktsommelig og fødte Hanok; og han tok sig for å bygge en by og kalte byen Hanok efter sin sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Og Hanok fikk sønnen Irad, og Irad blev far til Mehujael, og Mehujael blev far til Metusael, og Metusael blev far til Lamek.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Og Lamek tok sig to hustruer; den ene hette Ada, og den andre hette Silla.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Og Ada fødte Jabal; han blev stamfar til dem som bor i telt og holder buskap.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Og hans bror hette Jubal; han blev stamfar til alle dem som spiller på harpe og fløite.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Og Silla fødte Tubalkain; han smidde alle slags skarpe redskaper av kobber og jern; og Tubalkains søster var Na\'ama.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Og Lamek sa til sine hustruer: Ada og Silla, hør mine ord, Lameks hustruer, merk min tale! En mann dreper jeg for hvert sår jeg får, og en gutt for hver skramme jeg får;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'for hevnes Kain syv ganger, da skal Lamek hevnes syv og sytti ganger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Og Adam holdt sig atter til sin hustru, og hun fødte en sønn og kalte ham Set; for sa hun Gud har satt mig en annen sønn i Abels sted, fordi Kain slo ham ihjel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Og Set fikk en sønn og kalte ham Enos. På den tid begynte de å påkalle Herrens navn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Dette er boken om Adams ætt: På den dag Gud skapte mennesket, skapte han det i Guds lignelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Til mann og kvinne skapte han dem; og han velsignet dem og gav dem navnet menneske på den dag de blev skapt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Da Adam var hundre og tretti år gammel, fikk han en sønn i sin lignelse, efter sitt billede; og han kalte ham Set.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Og efterat Adam hadde fått Set, levde han ennu åtte hundre år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Og alle Adams levedager blev ni hundre og tretti år; så døde han.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Da Set var hundre og fem år gammel, fikk han sønnen Enos.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Og efterat Set hadde fått Enos, levde han ennu åtte hundre og syv år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Og alle Sets dager blev ni hundre og tolv år; så døde han.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Da Enos var nitti år gammel, fikk han sønnen Kenan.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Og efterat Enos hadde fått Kenan, levde han ennu åtte hundre og femten år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Og alle Enos\' dager blev ni hundre og fem år; så døde han.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Da Kenan var sytti år gammel, fikk han sønnen Mahalalel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Og efterat Kenan hadde fått Mahalalel, levde han ennu åtte hundre og firti år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Og alle Kenans dager blev ni hundre og ti år; så døde han.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Da Mahalalel var fem og seksti år gammel, fikk han sønnen Jared.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Og efterat Mahalalel hadde fått Jared, levde han ennu åtte hundre og tretti år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Og alle Mahalalels dager blev åtte hundre og fem og nitti år; så døde han.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Da Jared var hundre og to og seksti år gammel, fikk han sønnen Enok.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Og efterat Jared hadde fått Enok, levde han ennu åtte hundre år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Og alle Jareds dager blev ni hundre og to og seksti år; så døde han.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Da Enok var fem og seksti år gammel, fikk han sønnen Metusalah.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Og Enok vandret med Gud i tre hundre år, efterat han hadde fått Metusalah; og han fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Og alle Enoks dager blev tre hundre og fem og seksti år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Og Enok vandret med Gud; så blev han borte, for Gud tok ham til sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Da Metusalah var hundre og syv og åtti år gammel, fikk han sønnen Lamek.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Og efterat Metusalah hadde fått Lamek, levde han ennu syv hundre og to og åtti år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Og alle Metusalahs dager blev ni hundre og ni og seksti år; så døde han.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Da Lamek var hundre og to og åtti år gammel, fikk han en sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'og han kalte ham Noah og sa: Han skal trøste oss under vårt arbeid og våre henders møie på den jord som Herren har forbannet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Og efterat Lamek hadde fått Noah, levde han ennu fem hundre og fem og nitti år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Og alle Lameks dager blev syv hundre og syv og sytti år; så døde han.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Da Noah var fem hundre år gammel, fikk han sønnene Sem, Kam og Jafet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Da nu menneskene begynte å bli tallrike på jorden, og de fikk døtre,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'så Guds sønner at menneskenes døtre var vakre; og de tok sig hustruer, hvem de hadde lyst til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Da sa Herren: Min Ånd skal ikke dømme blandt menneskene til evig tid; for sin villfarelses skyld er det kjød, og dets dager skal være hundre og tyve år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'I de dager var kjempene på jorden og likeså siden, da Guds sønner gikk inn til menneskenes døtre, og de fødte dem barn; det er de veldige fra fordums tid, de navnkundige.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Og Herren så at menneskets ondskap var stor på jorden, og at alle dets hjertes tanker og påfund bare var onde den hele dag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Da angret Herren at han hadde skapt mennesket på jorden, og han var full av sorg i sitt hjerte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Og Herren sa: Jeg vil utrydde menneskene som jeg har skapt, av jorden, både mennesker og fe og kryp og fuglene under himmelen; for jeg angrer at jeg har skapt dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Men Noah fant nåde for Herrens øine.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Dette er historien om Noah og hans ætt: Noah var en rettferdig og ulastelig mann blandt sine samtidige; Noah vandret med Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Og Noah fikk tre sønner: Sem, Kam og Jafet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Men jorden blev fordervet for Guds åsyn, og jorden blev full av urett.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Og Gud så på jorden, og se, den var fordervet; for alt kjød hadde fordervet sin ferd på jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Da sa Gud til Noah: Jeg har satt mig fore å gjøre ende på alt kjød, for de har fylt jorden med urett; og nu vil jeg ødelegge både dem og jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Gjør dig en ark av gofertre, gjør kammer i arken og stryk den innvendig og utvendig med bek!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Således skal du gjøre den: Arken skal være tre hundre alen lang, femti alen bred, og tretti alen høi.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Øverst på arken skal du gjøre en glugg som når en alen ned på veggen, og døren på arken skal du sette på den ene side; du skal bygge den i tre stokkverk, et nederste, et mellemste og et øverste, med kammer i hvert stokkverk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Og se, jeg vil la en vannflom komme over jorden til å ødelegge alt kjød under himmelen som det er livsånde i; alt som er på jorden, skal omkomme.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Men jeg vil oprette min pakt med dig, og du skal gå inn i arken, du og dine sønner og din hustru og dine sønners hustruer med dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Og av alt som lever, av alt kjød, skal du ta et par av hvert slag med inn i arken for å holde dem i live med dig; han og hun skal det være.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Av alle slags fugler og av alle slags fe og av alle slags kryp på jorden skal par for par komme inn til dig for å holdes i live.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Og du skal ta til dig av allslags mat som etes, og samle det hos dig, sa det kan være til føde for dig og for dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Og Noah gjorde så; han gjorde i ett og alt som Gud hadde befalt ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Så sa Herren til Noah: Gå inn i arken, du og hele ditt hus! For jeg har funnet at du er rettferdig for mitt åsyn i denne slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Av alle rene dyr skal du ta dig ut syv par, han og hun, men av de dyr som ikke er rene, ett par, han og hun;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'likeså av himmelens fugler syv par, han og hun, for å holde deres slekter i live på jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'For om syv dager vil jeg la det regne på jorden i firti dager og firti netter, og jeg vil utrydde av jorden alt levende som jeg har skapt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Og Noah gjorde i ett og alt som Herren hadde befalt ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Noah var seks hundre år gammel da vannflommen kom over jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Da gikk Noah og hans sønner og hans hustru og hans sønners hustruer med ham inn i arken for å berge sig for vannflommen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Av de rene dyr og av de dyr som ikke er rene, og av fuglene og av alt det som kryper på jorden,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'gikk par for par inn til Noah i arken, han og hun, således som Gud hadde befalt Noah.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Da nu de syv dager var til ende, kom flommens vann strømmende over jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'I det år da Noah var seks hundre år gammel, i den annen måned, den syttende dag i måneden, den dag brast alle kilder i det store dyp, og himmelens sluser åpnedes,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'og regnet strømmet ned på jorden i firti dager og firti netter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'På denne samme dag gikk Noah og Sem og Kam og Jafet, Noahs sønner, og Noahs hustru og hans sønners tre hustruer med dem inn i arken,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'de og alle de ville dyr efter sitt slag og alt feet efter sitt slag og alt krypet som rører sig på jorden, efter sitt slag og alle fuglene efter sitt slag, alt som flyver, alt som har vinger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Og de gikk inn til Noah i arken, par for par av alt kjød som det var livsånde i.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Og de som gikk inn, var han og hun av alt kjød, således som Gud hadde befalt ham. Og Herren lukket efter ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Da kom vannflommen strømmende over jorden i firti dager, og vannet vokste og løftet arken, og den blev hevet over jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Og vannet steg og øket storlig over jorden; og arken fløt bortover vannflaten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Og vannet steg høiere og høiere over jorden, så alle de høie fjell under hele himmelen blev skjult.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Femten alen høit steg vannet over fjellene, så de skjultes.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Da omkom alt kjød som rørte sig på jorden, både fuglene og feet og de ville dyr og alt det som yrte og vrimlet på jorden, og alle menneskene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Alt som hadde livsens åndedrag i sin nese, alt det som var på det tørre land, døde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Og han utryddet hvert liv som var på jorden, både mennesker og fe og kryp og fuglene under himmelen; de blev utryddet av jorden, og bare Noah blev igjen, og det som var med ham i arken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Og vannet holdt sig over jorden i hundre og femti dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Da kom Gud Noah i hu og alle de ville dyr og alt feet som var med ham i arken; og Gud lot en vind fare over jorden, og vannet falt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Og det store dyps kilder og himmelens sluser lukkedes, og regnet fra himmelen stanset.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Og vannet vek efterhånden tilbake fra jorden, og vannet begynte å ta av, da hundre og femti dager var gått.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Og i den syvende måned, på den syttende dag i måneden, blev arken stående på Ararat-fjellene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Og vannet tok mere og mere av inntil den tiende måned; i den tiende måned, på den første dag i måneden, kom fjelltoppene til syne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Og da firti dager var gått, åpnet Noah vinduet på arken som han hadde gjort,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'og sendte ut en ravn; den fløi frem og tilbake, inntil vannet var tørket bort av jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Så sendte han en due ut fra sig for å se om vannet var sunket bort fra jordens overflate.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Men duen fant ikke noget hvilested for sin fot, og den kom tilbake til ham i arken, for det stod vann over hele jorden. Da rakte han ut sin hånd og tok den inn til sig i arken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Så bidde han ennu syv dager til og sendte så atter duen ut av arken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Og duen kom til ham ved aftenstid, og se, den hadde et friskt oljeblad i nebbet; da skjønte Noah at vannet var sunket bort fra jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Men han bidde ennu syv dager til; så sendte han duen ut, og da kom den ikke tilbake til ham mere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'I det seks hundre og første år, i den første måned, på den første dag i måneden, var vannet tørket bort fra jorden. Da tok Noah taket av arken; og han så ut, og se, jorden var tørr.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Og i den annen måned, på den syv og tyvende dag i måneden, var jorden aldeles tørr.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Da talte Gud til Noah og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Gå ut av arken, du og din hustru og dine sønner og dine sønners hustruer med dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Alle de dyr som er hos dig, alt kjød, både fuglene og feet og alt krypet som rører sig på jorden, skal du føre ut med dig, og de skal vrimle på jorden og være fruktbare og bli mange på jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Så gikk han ut, og hans sønner og hans hustru og hans sønners hustruer med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Alle dyrene, alt krypet og alle fuglene, alt som rører sig på jorden, gikk ut av arken, hvert efter sitt slag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Og Noah bygget Herren et alter, og han tok av alle de rene dyr og av alle de rene fugler og ofret brennoffer på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Og Herren kjente den velbehagelige duft. Og Herren sa i sitt hjerte: Jeg vil aldri mere forbanne jorden for menneskets skyld; for menneskehjertets tanker er onde fra ungdommen av; og jeg vil aldri mere drepe alt levende, som jeg nu har gjort.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Herefter skal, så lenge jorden står, sæd og høst, og frost og hete, og sommer og vinter, og dag og natt aldri høre op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Og Gud velsignet Noah og hans sønner, og sa til dem: Vær fruktbare og bli mange og opfyll jorden!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Og frykt og redsel for eder skal være over alle dyr på jorden og over alle fugler under himmelen, over alt det som rører sig på jorden, og over alle fiskene i havet; i eders hånd er de gitt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Alt det som rører sig og lever, skal I ha til føde; likesom jeg gav eder de grønne urter, gir jeg eder alt dette.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Men kjøtt med dets sjel i, det er dets blod, skal I ikke ete.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Men for eders eget blod vil jeg kreve hevn; av hvert dyr vil jeg kreve hevn for det, og av mennesket, av enhvers bror, vil jeg kreve hevn for menneskets liv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Den som utøser menneskets blod, ved mennesket skal hans blod utøses; for i Guds billede skapte han mennesket.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Og vær I fruktbare og bli mange, vrimle på jorden og bli mange på den!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Og Gud sa til Noah og til hans sønner, som var med ham:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Nu vil jeg oprette min pakt med eder og med eders efterkommere,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'og med alt levende som er hos eder, både fugler og fe og alle de ville dyr som er hos eder, alt som gikk ut av arken, alt som lever på jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Jeg opretter min pakt med eder, og aldri mere skal alt kjød utryddes ved vannflom, og aldri mere skal der komme en vannflom som ødelegger jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Og Gud sa: Dette er tegnet på den pakt som jeg gjør mellem mig og eder og alt levende som er hos eder, til evige tider:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Min bue setter jeg i skyen, og den skal være et tegn på pakten mellem mig og jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Og når jeg fører skyer over jorden, og buen sees i skyen,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'da vil jeg komme i hu den pakt som er mellem mig og eder og alt levende av alt kjød, og vannet skal aldri mere bli en flom som ødelegger alt kjød.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Og buen skal stå i skyen, og jeg vil se på den og komme i hu den evige pakt mellem Gud og alt levende av alt kjød som er på jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Og Gud sa til Noah: Dette er tegnet på den pakt jeg har oprettet mellem mig og alt kjød som er på jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Noahs sønner, som gikk ut av arken, var Sem, Kam og Jafet; og Kam var far til Kana\'an.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Disse tre var Noahs sønner, og fra dem bredte menneskene sig ut over hele jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Og Noah var jorddyrker, og han var den første som plantet en vingård.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Og han drakk av vinen og blev drukken, og han klædde sig naken inne i sitt telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Og da Kam, Kana\'ans far, så sin far ligge naken, fortalte han det til begge sine brødre, som var utenfor.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Da tok Sem og Jafet et klæde og la det på sine skuldrer og gikk baklengs inn og dekket over sin fars blusel; og de vendte sine øine bort, så de ikke så sin fars blusel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Da så Noah våknet av sitt rus, fikk han vite hvad hans yngste sønn hadde gjort imot ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Da sa han: Forbannet være Kana\'an! trælers træl skal han være for sine brødre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Så sa han: Lovet være Herren, Sems Gud, og Kana\'an være deres træl!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Gud gjøre det vidt for Jafet, han skal bo i Sems telter, og Kana\'an være deres træl!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Efter vannflommen levde Noah ennu tre hundre og femti år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Og alle Noahs dager blev ni hundre og femti år; så døde han.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Dette er de ætter som stammer fra Noahs sønner Sem, Kam og Jafet: De fikk sønner efter vannflommen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Jafets sønner var Gomer og Magog og Madai og Javan og Tubal og Mesek og Tiras.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Og Gomers sønner var Askenas og Rifat og Togarma.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Og Javans sønner var Elisa og Tarsis, Kittim og Dodanim.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Fra disse bredte de som bor på hedningenes kyster, sig ut i sine land, med sine forskjellige tungemål, efter sine ætter, i sine folkeslag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Og Kams sønner var Kus og Misra\'im og Put og Kana\'an.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Og Kus\' sønner var Seba og Havila og Sabta og Raema og Sabteka, og Raemas sønner var Sjeba og Dedan.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Og Kus fikk sønnen Nimrod; han var den første som fikk stort velde på jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Han var en veldig jeger for Herrens åsyn; derfor sier folk: En veldig jeger for Herrens åsyn som Nimrod.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Først hersket han over Babel og Erek og Akkad og Kalne i landet Sinear.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Fra dette land drog han ut til Assur og bygget Ninive og Rehobot-Ir og Kalah');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'og Resen mellem Ninive og Kalah; dette er den store stad.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Og Misra\'im blev stamfar til luderne og anamerne og lehaberne og naftuherne');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'og patruserne og kasluherne, som filistrene er kommet fra, og kaftorerne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Og Kana\'an blev far til Sidon, som var hans førstefødte, og til Het');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'og til jebusittene og amorittene og girgasittene');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'og hevittene og arkittene og sinittene');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'og arvadittene og semarittene og hamatittene; siden bredte kana\'anittenes ætter sig videre ut.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Og kana\'anittenes grense gikk fra Sidon bortimot Gerar like til Gasa, og bortimot Sodoma og Gomorra og Adma og Sebo\'im like til Lesa.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Dette var Kams barn, efter sine ætter, med sine tungemål, i sine land, i sine folkeslag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Også Sem fikk barn; han var stamfar til alle Ebers barn og var den eldste bror av Jafet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Sems sønner var Elam og Assur og Arpaksad og Lud og Aram.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Og Arams sønner var Us og Hul og Geter og Mas.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Og Arpaksad fikk sønnen Salah, og Salah fikk sønnen Eber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Og Eber fikk to sønner; den ene hette Peleg, for i hans dager blev menneskene spredt over jorden; og hans bror hette Joktan.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Og Joktan blev far til Almodad og Salef og Hasarmavet og Jarah');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'og Hadoram og Usal og Dikla');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'og Obal og Abimael og Sjeba');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'og Ofir og Havila og Jobab; alle disse var Joktans sønner.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'De hadde sine bosteder i fjellbygdene i øst fra Mesa bortimot Sefar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Dette var Sems barn efter sine ætter, med sine tungemål, i sine land, i sine folkeslag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Dette var Noahs sønners ætter efter sin avstamning, i sine folkeslag; og fra dem har folkene utbredt sig på jorden efter vannflommen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Og hele jorden hadde ett tungemål og ens tale.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Og da de drog frem mot øst, fant de en slette i landet Sinear, og de bosatte sig der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Og de sa til hverandre: Kom, la oss gjøre teglsten og brenne dem vel! Og de brukte tegl istedenfor sten, og jordbek istedenfor kalk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Så sa de: Kom, la oss bygge oss en by med et tårn som når op til himmelen, og gjøre oss et navn, så vi ikke skal spres over hele jorden!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Da steg Herren ned for å se byen og tårnet som menneskenes barn hadde begynt å bygge.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Og Herren sa: Se, de er ett folk, og ett tungemål har de alle; dette er det første de tar sig fore, og nu vil intet være umulig for dem, hvad de så får i sinne å gjøre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'La oss da stige ned der og forvirre deres tungemål, så den ene ikke forstår den andres tungemål!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Så spredte Herren dem derfra over hele jorden, og de holdt op med å bygge på byen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Derfor kalte de den Babel; for der forvirret Herren hele jordens tungemål, og derfra spredte Herren dem ut over hele jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Dette er historien om Sems ætt: Da Sem var hundre år gammel, fikk han sønnen Arpaksad to år efter vannflommen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Og efterat Sem hadde fått Arpaksad, levde han ennu fem hundre år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Da Arpaksad var fem og tretti år gammel, fikk han sønnen Salah.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Og efterat Arpaksad hadde fått Salah, levde han ennu fire hundre og tre år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Da Salah var tretti år gammel, fikk han sønnen Eber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Og efterat Salah hadde fått Eber, levde han ennu fire hundre og tre år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Da Eber var fire og tretti år gammel, fikk han sønnen Peleg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Og efterat Eber hadde fått Peleg, levde han ennu fire hundre og tretti år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Da Peleg var tretti år gammel, fikk han sønnen Re\'u.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Og efterat Peleg hadde fått Re\'u, levde han ennu to hundre og ni år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Da Re\'u var to og tretti år gammel, fikk han sønnen Serug.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Og efterat Re\'u hadde fått Serug, levde han ennu to hundre og syv år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Da Serug var tretti år gammel, fikk han sønnen Nakor.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Og efterat Serug hadde fått Nakor, levde han ennu to hundre år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Da Nakor var ni og tyve år gammel, fikk han sønnen Tarah.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Og efterat Nakor hadde fått Tarah, levde han ennu hundre og nitten år og fikk sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Da Tarah var sytti år gammel, fikk han sønnene Abram, Nakor og Haran.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Dette er historien om Tarah og hans ætt: Tarah fikk sønnene Abram, Nakor og Haran. Og Haran fikk sønnen Lot.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Og Haran døde hos sin far Tarah i sitt fedreland, i Ur i Kaldea.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Og Abram og Nakor tok sig hustruer; Abrams hustru hette Sarai, og Nakors hustru hette Milka og var en datter av Haran, far til Milka og Jiska.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Og Sarai var ufruktbar, hun hadde ikke noget barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Og Tarah tok med sig Abram, sin sønn, og Lot, Harans sønn, sin sønnesønn, og Sarai, sin sønnekone, sin sønn Abrams hustru; og de drog ut sammen fra Ur i Kaldea for å reise til Kana\'ans land, og de kom til Karan og bosatte sig der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Og Tarahs dager blev to hundre og fem år; så døde Tarah i Karan.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Og Herren sa til Abram: Dra bort fra ditt land og fra din slekt og fra din fars hus til det land som jeg vil vise dig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Og jeg vil gjøre dig til et stort folk; jeg vil velsigne dig og gjøre ditt navn stort, og du skal bli en velsignelse!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Og jeg vil velsigne dem som velsigner dig, og den som forbanner dig, vil jeg forbanne; og i dig skal alle jordens slekter velsignes');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Så drog Abram bort som Herren hadde sagt til ham, og Lot drog med ham. Og Abram var fem og sytti år gammel da han drog ut fra Karan.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Og Abram tok med sig Sarai, sin hustru, og Lot, sin brorsønn, og all deres eiendom som de hadde vunnet, og de folk som de hadde fått i Karan; og de drog ut for å reise til Kana\'ans land, og de kom til Kana\'ans land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Og Abram drog gjennem landet til Sikem-bygden, til Mores terebintelund; og kana\'anittene bodde dengang der i landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Da åpenbarte Herren sig for Abram og sa: Din ætt vil jeg gi dette land. Og han bygget der et alter for Herren, som hadde åpenbaret sig for ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Derfra flyttet han til fjellene østenfor Betel og slo op sitt telt med Betel i vest og Ai i øst; og han bygget der et alter for Herren og påkalte Herrens navn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Og Abram drog efter hvert videre til sydlandet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Så blev det hungersnød i landet; og Abram drog ned til Egypten for å opholde sig der, for hungersnøden var stor i landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Og da han ikke hadde langt igjen til Egypten, sa han til Sarai, sin hustru: Jeg vet jo at du er en vakker kvinne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Når nu egypterne får se dig, vil de si: Dette er hans hustru, og så slår de mig ihjel og lar dig leve.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Kjære, si at du er min søster, så det kan gå mig vel, og mitt liv kan bli spart for din skyld!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Da nu Abram kom til Egypten, så egypterne at kvinnen var meget vakker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Også Faraos høvdinger så henne og roste henne for Farao, og så blev kvinnen hentet til Faraos hus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Og han gjorde vel imot Abram for hennes skyld, og han fikk både småfe og storfe og asener og træler og trælkvinner og aseninner og kameler.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Men Herren hjemsøkte Farao og hans hus med store plager for Abrams hustru Sarais skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Da kalte Farao Abram til sig og sa: Hvad er det du har gjort imot mig? Hvorfor lot du mig ikke vite at hun er din hustru?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Hvorfor sa du: Hun er min søster, så jeg tok henne til hustru? Se, her har du din hustru, ta henne og gå!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Og Farao gav nogen menn befaling til å følge ham på veien med hans hustru og alt det han eide.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Så drog Abram fra Egypten op til sydlandet med sin hustru og alt det han eide, og Lot var med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Og Abram var meget rik på buskap og på sølv og gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Og han drog i dagsreiser fra sydlandet, til han kom til Betel, til det sted hvor hans telt før hadde vært, mellem Betel og Ai,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'der hvor det alter var som han hadde bygget første gang han var der; og der påkalte Abram Herrens navn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Men også Lot, som drog med Abram, hadde småfe og storfe og telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Og landet kunde ikke rumme dem, så de kunde bo sammen; for deres eiendom var for stor til at de kunde bo sammen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Så blev det trette mellem Abrams hyrder og Lots hyrder; og kana\'anittene og ferisittene bodde dengang i landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Da sa Abram til Lot: Kjære, la det ikke være trette mellem mig og dig og mellem mine hyrder og dine hyrder! Vi er jo brødre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Ligger ikke hele landet åpent for dig? Skill dig heller fra mig! Drar du til venstre, vil jeg dra til høire, og drar du til høire, vil jeg dra til venstre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Da så Lot ut over landet, og han så at hele Jordan-sletten like til Soar overalt var rik på vann, som Herrens have, som Egyptens land - det var før Herren hadde ødelagt Sodoma og Gomorra.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Og Lot valgte for sig hele Jordan-sletten. Så drog Lot østover, og de skiltes fra hverandre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram blev boende i Kana\'ans land, og Lot bodde i byene på sletten og drog med sine telt like bort til Sodoma.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Men mennene i Sodoma var onde og syndet storlig mot Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Og Herren sa til Abram efterat Lot hadde skilt sig fra ham: Løft dine øine og se fra det sted hvor du står, mot nord og mot syd og mot øst og mot vest!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'For hele det land du ser, vil jeg gi dig og din ætt til evig tid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Og jeg vil la din ætt bli som støvet på jorden; kan nogen telle støvet på jorden, så skal også din ætt kunne telles.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Stå op, og dra gjennem landet så langt og så bredt som det er! For dig vil jeg gi det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Og Abram flyttet sine telt og kom til Mamres terebinte-lund i Hebron; der bosatte han sig, og han bygget der et alter for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'I den tid da Amrafel var konge i Sinear, Arjok konge i Ellasar, Kedorlaomer konge i Elam, og Tideal konge over Gojim,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'da hendte det at disse konger førte krig med Bera, kongen i Sodoma, og Birsa, kongen i Gomorra, og Sineab, kongen i Adma, og Semeber, kongen i Sebo\'im, og kongen i Bela, det er Soar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Alle disse slo sig sammen og drog til Siddim-dalen, der hvor Salthavet nu er.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Tolv år hadde de tjent Kedorlaomer, men i det trettende år var de falt fra.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Og i det fjortende år kom Kedorlaomer og de konger som var med ham, og slo refa\'ittene i Asterot-Karna\'im og susittene i Ham og emittene i Sjave-Kirjata\'im');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'og horittene på deres fjell - Se\'ir-fjellene - like til El-Paran ved utkanten av ørkenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Derefter vendte de om og kom til En-Mispat, det er Kades, og la under sig hele amalekittenes land og likeså amorittene, som bodde i Haseson-Tamar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Da drog kongen i Sodoma ut og kongen i Gomorra og kongen i Adma og kongen i Sebo\'im og kongen i Bela, det er Soar, og stilte sig i fylkning mot dem i Siddim-dalen,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'mot Kedorlaomer, kongen i Elam, og Tideal, kongen over Gojim, og Amrafel, kongen i Sinear, og Arjok, kongen i Ellasar, fire konger mot fem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Men Siddim-dalen var full av jordbek-gruber, og kongene i Sodoma og Gomorra måtte flykte og falt da i dem; og de som blev igjen, flyktet op i fjellene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Så tok de alt godset i Sodoma og Gomorra og all deres mat og drog bort.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'De tok også med sig Abrams brorsønn Lot og hans gods og drog bort; for han bodde i Sodoma.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Da kom det nogen som var undsloppet, og fortalte det til hebreeren Abram; han bodde ved den terebinte-lund som tilhørte amoritten Mamre - Mamre var bror til Eskol og Aner, og de hadde alle gjort en pakt med Abram.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Da nu Abram hørte at hans frende var bortført som fange, lot han sine våbenvante folk, som var født i hans hus, tre hundre og atten i tallet, dra ut og forfulgte dem like til Dan.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Der delte han sine folk og overfalt dem om natten og slo dem; og han forfulgte dem like til Hoba, som ligger i nord for Damaskus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Så tok han tilbake alt godset; Lot, sin frende, og hans gods tok han også tilbake, og likeså kvinnene og folket.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Da han så vendte tilbake efter å ha slått Kedorlaomer og de konger som var med ham, gikk kongen i Sodoma ham i møte til Sjave-dalen, det er Kongedalen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Og Melkisedek, kongen i Salem, kom ut med brød og vin; han var prest for den høieste Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Og han velsignet ham og sa: Velsignet være Abram av den høieste Gud, som eier himmel og jord!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Og lovet være den høieste Gud, som har gitt dine fiender i din hånd! Og Abram gav ham tiende av alt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Og kongen i Sodoma sa til Abram: Gi mig folket, og ta du godset!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Da sa Abram til kongen i Sodoma: Jeg løfter min hånd til Herren, den høieste Gud, som eier himmel og jord:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Jeg vil ikke ta så meget som en tråd eller en skorem av alt som ditt er, forat du ikke skal si: Jeg har gjort Abram rik.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Jeg vil intet ha, bare det som mine folk har fortært; og det som faller på de menn som drog med mig, Aner, Eskol og Mamre - la dem få sin del.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Nogen tid derefter kom Herrens ord til Abram i et syn, og det lød så: Frykt ikke, Abram! Jeg er ditt skjold; din lønn skal være meget stor.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Og Abram sa: Herre, Herre, hvad vil du gi mig? Jeg går jo barnløs bort, og den som skal ta mitt hus i eie, er Elieser fra Damaskus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Og Abram sa videre: Se, mig har du ikke gitt noget barn, og en tjener som er født i mitt hus, kommer til å arve mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Men se, da kom Herrens ord til ham, og det lød så: Nei, han skal ikke arve dig, men en som skal utgå av ditt eget liv, skal arve dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Og han førte ham utenfor og sa: Se op til himmelen og tell stjernene, om du kan telle dem! Og han sa til ham: Så skal din ætt bli.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Og Abram trodde på Herren, og han regnet ham det til rettferdighet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Og han sa til ham: Jeg er Herren, som førte dig ut fra Ur i Kaldea for å gi dig dette land til eie.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Da sa han: Herre, Herre, hvorav kan jeg vite at jeg skal eie det?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Da sa han til ham: Hent mig en treårsgammel kvige og en treårsgammel gjet og en treårsgammel vær og en turteldue og en dueunge.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Så hentet han alt dette til ham og skar dyrene midt over og la det ene stykket av hvert dyr rett imot det andre; men fuglene skar han ikke over.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Og rovfugler for ned på de døde kropper, men Abram jaget dem bort.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Da nu solen var nær ved å gå ned, og en dyp søvn var falt over Abram, se, da falt redsel, et stort mørke, over ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Og han sa til Abram: Det skal du vite, at din ætt skal bo som fremmede i et land som ikke hører dem til, og de skal træle for folket der og plages av dem i fire hundre år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Men det folk som de skal træle for, vil jeg også dømme; og derefter skal de dra ut med meget gods.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Men du skal fare til dine fedre i fred og bli begravet i en god alderdom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Og i det fjerde ættledd skal de komme hit igjen; for amorittene har ennu ikke fylt sin ondskaps mål.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Da nu solen var gått ned, og det var blitt aldeles mørkt, fikk han se en rykende ovn og en luende ild som for frem mellem kjøttstykkene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Den dag gjorde Herren en pakt med Abram og sa: Din ætt gir jeg dette land, fra Egyptens elv like til den store elv, elven Frat,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'kenittenes og kenisittenes og kadmonittenes');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'og hetittenes og ferisittenes og refa\'ittenes');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'og amorittenes og kana\'anittenes og girgasittenes og jebusittenes land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Sarai, Abrams hustru, fødte ham ikke barn; men hun hadde en egyptisk trælkvinne, som hette Hagar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Og Sarai sa til Abram: Se, Herren har nektet mig barn; gå derfor inn til min trælkvinne! Kanskje jeg kunde få et barn ved henne. Og Abram lød Sarais råd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Så tok Sarai, Abrams hustru, og lot Abram, sin mann, få egypterkvinnen Hagar, som var hennes trælkvinne, til hustru; da var det ti år siden Abram hadde bosatt sig i Kana\'ans land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Og han gikk inn til Hagar, og hun blev fruktsommelig; men da hun så at hun var blitt fruktsommelig, ringeaktet hun sin frue.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Da sa Sarai til Abram: Den urett jeg lider, er du skyld i; jeg har selv gitt min trælkvinne i din favn; men nu, da hun ser at hun er fruktsommelig, ringeakter hun mig; Herren skal dømme mellem mig og dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Da sa Abram til Sarai: Se, din trælkvinne råder du selv over; gjør med henne som du synes. Og Sarai var hård mot henne, og hun rømte fra henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Men Herrens engel fant henne ved vannkilden i ørkenen, ved kilden på veien til Sur.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Og han sa: Hagar, Sarais trælkvinne, hvor kommer du fra, og hvor akter du dig hen? Hun svarte: Jeg har flyktet fra min frue Sarai.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Da sa Herrens engel til henne: Gå tilbake til din frue, og bøi dig under henne!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Og Herrens engel sa til henne: Jeg vil gjøre din ætt så tallrik at den ikke skal kunne telles for mengde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Og Herrens engel sa videre til henne: Se, du er fruktsommelig og skal føde en sønn, og du skal kalle ham Ismael; for Herren har hørt din nød.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Og han skal bli et vill-asen av et menneske; hans hånd skal være mot alle, og alles hånd mot ham; og han skal bo østenfor alle sine brødre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Og hun gav Herren, som hadde talt med henne, navnet \"Du er Gud, den som ser\". For hun sa: Har jeg virkelig fått se ham som ser mig?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Derfor kaller de brønnen Lakai Ro\'is brønn; den ligger mellem Kades og Bered.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Og Hagar fødte Abram en sønn; og Abram kalte den sønn som Hagar hadde født ham, Ismael.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Abram var seks og åtti år gammel da Hagar fødte ham Ismael.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Da Abram var ni og nitti år gammel, åpenbarte Herren sig for ham og sa til ham: Jeg er Gud den allmektige; vandre for mitt åsyn og vær ustraffelig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Jeg vil gjøre en pakt mellem mig og dig, og jeg vil gjøre din ætt såre tallrik.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Da falt Abram på sitt ansikt; og Gud talte med ham og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Se, jeg gjør en pakt med dig, og du skal bli far til en mengde folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Ditt navn skal ikke mere være Abram; men ditt navn skal være Abraham, for jeg gjør dig til far for en mengde folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Og jeg vil gjøre dig såre fruktbar, så du blir til mange folk, og konger skal utgå fra dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Og jeg vil oprette en pakt mellem mig og dig og din ætt efter dig, fra slekt til slekt, en evig pakt, så jeg vil være din Gud og Gud for din ætt efter dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Og jeg vil gi dig og din ætt efter dig det land hvor du bor som fremmed, hele Kana\'ans land, til en evig eiendom; og jeg vil være deres Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Derefter sa Gud til Abraham: Og du skal holde min pakt, du og din ætt efter dig, fra slekt til slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Dette er den pakt mellem mig og eder og din ætt efter dig som I skal holde: Alt mannkjønn hos eder skal omskjæres');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'I skal omskjæres på eders forhud; det skal være tegnet på pakten mellem mig og eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Åtte dager gammelt skal hvert guttebarn hos eder omskjæres, slekt efter slekt, både den som er født hjemme, og den som er kjøpt for penger, alle som hører til et fremmed folk og ikke er av din ætt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Omskjæres skal både den som er født i ditt hus, og den som er kjøpt for dine penger. Så skal min pakt være på eders kjøtt - en evig pakt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Men en uomskåret av mannkjønn, en hvis forhud ikke blir omskåret, han skal utryddes av sitt folk; han har brutt min pakt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Og Gud sa til Abraham: Sarai, din hustru, skal du ikke lenger kalle Sarai - Sara skal være hennes navn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Og jeg vil velsigne henne, og jeg vil gi dig en sønn også med henne; ja, jeg vil velsigne henne, og hun skal bli til mange folk, konger over folkeslag skal fremgå av henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Da falt Abraham på sitt ansikt og lo, og han sa ved sig selv: Skulde en som er hundre år gammel, få barn? Og skulde Sara, som er nitti år gammel, føde?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Og Abraham sa til Gud: Måtte bare Ismael få leve for ditt åsyn!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Da sa Gud: Sannelig, Sara, din hustru, skal føde dig en sønn, og du skal kalle ham Isak, og jeg vil oprette min pakt med ham, en evig pakt for hans ætt efter ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Og Ismael - også om ham har jeg hørt din bønn: Se, jeg vil velsigne ham og gjøre ham fruktbar og gi ham en såre tallrik ætt; tolv høvdinger skal han bli far til, og jeg vil gjøre ham til et stort folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Men min pakt vil jeg oprette med Isak, som Sara skal føde dig på denne tid næste år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Så holdt han op å tale med ham; og Gud for op igjen fra Abraham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Samme dag tok Abraham Ismael, sin sønn, og alle som var født i hans hus, og alle som var kjøpt for hans penger, alt mannkjønn blandt folkene i Abrahams hus, og omskar deres forhud, således som Gud hadde sagt til ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Abraham var ni og nitti år gammel da hans forhud blev omskåret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Og Ismael, hans sønn, var tretten år da hans forhud blev omskåret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Denne samme dag blev de omskåret, både Abraham og Ismael, hans sønn;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'og alle menn i hans hus, både de som var født hjemme, og de fremmede som var kjøpt for penger. blev omskåret med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Og Herren åpenbarte sig for ham i Mamres terebinte-lund, mens han satt i døren til sitt telt midt på heteste dagen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Da han så op, fikk han se tre menn som stod foran ham; og da han blev dem var, løp han dem i møte fra teltdøren og bøide sig til jorden');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'og sa: Herre! Dersom jeg har funnet nåde for dine øine, så gå ikke din tjener forbi!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'La oss få hente litt vann, så I kan få tvette eders føtter, og hvil eder under treet!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Og la mig hente et stykke brød, så I kan vederkvege eder før I drar videre - siden I nu har lagt veien om eders tjener. De sa: Ja, gjør som du sier!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Da skyndte Abraham sig inn i teltet til Sara og sa: Skynd dig og ta tre mål fint mel; elt det og bak kaker!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Og selv sprang Abraham bort til buskapen og hentet en fin og god kalv; den gav han til drengen, og han skyndte sig å lage den til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Så tok han rømme og søt melk og kalven som han hadde latt drengen lage til, og satte det for dem; og han stod hos dem under treet mens de åt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Da sa de til ham: Hvor er Sara, din hustru? Han svarte: Hun er der inne i teltet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Da sa han: Jeg vil komme igjen til dig på denne tid næste år, og da skal Sara, din hustru, ha en sønn. Og Sara hørte det i teltdøren, for den var bak ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Men Abraham og Sara var gamle og langt ute i årene; Sara hadde det ikke lenger på kvinners vis.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Derfor lo Sara ved sig selv og sa: Skulde jeg, nu jeg er blitt gammel, ha attrå, og min mann er også gammel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Da sa Herren til Abraham: Hvorfor ler Sara og tenker: Skal jeg da virkelig få barn, nu jeg er blitt gammel?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Skulde nogen ting være umulig for Herren? På denne tid næste år vil jeg komme til dig igjen, og da skal Sara ha en sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Men Sara nektet og sa: Jeg lo ikke. For hun var redd. Da sa han: Jo, du lo.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Så stod mennene op for å gå derfra, og de tok veien bortimot Sodoma; og Abraham gikk med dem for å følge dem på veien.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Da sa Herren: Skulde jeg vel dølge for Abraham det som jeg tenker å gjøre?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Abraham skal jo bli et stort og tallrikt folk, og alle jordens folk skal velsignes i ham;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'for jeg har utvalgt ham forat han skal byde sine barn og sitt hus efter sig at de skal holde sig efter Herrens vei og gjøre rett og rettferdighet, så Herren kan la Abraham få det som han har lovt ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Og Herren sa: Ropet over Sodoma og Gomorra er sannelig stort, og deres synd er sannelig meget svær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Jeg vil stige ned og se om de i alt har båret sig slik at som det lyder det rop som er nådd op til mig, og hvis ikke, så vil jeg vite det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Så vendte mennene sig derfra og gikk til Sodoma, men Abraham blev stående for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Og Abraham trådte nærmere og sa: Vil du da rykke den rettferdige bort sammen med den ugudelige?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Kanskje det er femti rettferdige i byen; vil du da rykke dem bort og ikke spare byen for de femti rettferdiges skyld som kunde være der?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Det være langt fra dig å gjøre slikt og slå ihjel den rettferdige sammen med den ugudelige, så det går den rettferdige på samme vis som den ugudelige! Det være langt fra dig! Den som dømmer hele jorden, skulde ikke han gjøre rett?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Da sa Herren: Dersom jeg i byen Sodoma finner femti rettferdige, da vil jeg spare hele byen for deres skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Men Abraham tok atter til orde og sa: Se, jeg har dristet mig til å tale til Herren, enda jeg er støv og aske;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'kanskje det fattes fem i de femti rettferdige, vil du da ødelegge hele byen for disse fems skyld? Han svarte: Jeg skal ikke ødelegge den dersom jeg finner fem og firti der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Men han blev ennu ved å tale til ham og sa: Kanskje det finnes firti. Han svarte: Jeg skal ikke gjøre det - for de firtis skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Men han sa: Herre, bli ikke vred om jeg taler! Kanskje det finnes tretti. Han svarte: Jeg skal ikke gjøre det dersom jeg finner tretti der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Da sa han: Se, jeg har dristet mig til å tale til Herren; kanskje det finnes tyve. Han svarte: Jeg skal ikke ødelegge den - for de tyves skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Da sa han: Herre, bli ikke vred om jeg taler bare denne ene gang til! Kanskje det finnes ti. Han svarte: Jeg skal ikke ødelegge den - for de tis skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Så gikk Herren bort, da han hadde talt ut med Abraham; og Abraham vendte tilbake til det sted hvor han bodde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Og de to engler kom til Sodoma om aftenen, mens Lot satt i Sodomas port; og da Lot så dem, stod han op og gikk dem i møte og bøide sig med sitt ansikt til jorden');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'og sa: I herrer! Ta inn i eders tjeners hus og bli der inatt, og tvett eders føtter! Så kan I stå tidlig op imorgen og dra videre. Men de sa: Nei, vi vil bli på gaten inatt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Da nødde han dem meget, og de tok inn hos ham i hans hus; og han gjorde i stand et måltid for dem og bakte usyrede brød, og de åt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Før de ennu hadde lagt sig, kom byens folk, mennene i Sodoma, både unge og gamle, hele folket fra alle kanter og omringet huset.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Og de ropte på Lot og sa til ham: Hvor er de menn som er kommet til dig inatt? Før dem ut til oss, så vi kan få vår vilje med dem!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Da gikk Lot ut til dem i døren og lukket den efter sig');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'og sa: Mine brødre, gjør da ikke så ond en gjerning!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Se, jeg har to døtre som ikke har hatt med nogen mann å gjøre; la mig få føre dem ut til eder, og gjør med dem som I synes! Gjør bare ikke disse menn noget, siden de er kommet inn under skyggen av mitt tak!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Men de ropte: Gå av veien! Og så sa de: Her er denne ene mann kommet for å bo som fremmed her, og så vil han alltid opkaste sig til dommer! Nu vil vi fare verre med dig enn med dem. Så trengte de hårdt inn på mannen, på Lot, og stormet frem for å sprenge døren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Da strakte mennene hånden ut og tok Lot inn til sig i huset og lukket døren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Og de folk som stod utenfor døren til huset, slo de med blindhet, både små og store, så de forgjeves søkte å finne døren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Da sa mennene til Lot: Har du ennu nogen her, enten svigersønn eller sønner eller døtre eller nogen annen som hører dig til i byen, så før dem bort fra dette sted!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'For nu skal vi ødelegge dette sted, fordi et sterkt klagerop over dem er nådd op til Herren, og Herren har sendt oss for å ødelegge det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Da gikk Lot ut og talte til sine svigersønner, dem som skulde ha hans døtre. og sa: Stå op og gå bort fra dette sted! For Herren vil ødelegge byen. Men hans svigersønner tenkte at han bare spøkte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Da nu morgenen grydde, skyndte englene på Lot og sa: Stå op, ta din hustru og dine to døtre som er her, forat du ikke skal bli revet bort på grunn av alt det onde som er gjort her i byen!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Og da han nølte, tok mennene ham og hans hustru og hans to døtre ved hånden, fordi Herren vilde spare ham; og de førte ham ut og slapp ham ikke før de var ute av byen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Da de hadde ført dem ut, sa den ene: Fly for ditt livs skyld, se dig ikke tilbake og stans ikke på hele sletten, fly op i fjellene, forat du ikke skal bli revet bort!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Da sa Lot til dem: Å nei, Herre!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Se, din tjener har funnet nåde for dine øine, og stor er den miskunnhet du har vist mig ved å frelse mitt liv. Men jeg kan ikke fly op i fjellene; for da kunde ulykken nå mig, så jeg døde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Se, byen der borte er nær og lett å fly til, og den er liten; la mig da fly dit - er den ikke liten? - så jeg kan berge livet!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Da sa han til ham: Vel, jeg har også bønnhørt dig i dette stykke; jeg skal ikke ødelegge den by du taler om.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Skynd dig, fly dit! For jeg kan intet gjøre før du kommer dit. Derfor kaller de den by Soar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Solen var gått op over jorden da Lot kom til Soar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Da lot Herren det regne svovel og ild - fra Herren, fra himmelen - ned over Sodoma og Gomorra.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Og han ødela disse byer og hele sletten og alle dem som bodde i byene, og det som vokste på marken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Men Lots hustru, som fulgte efter ham, så sig tilbake; da blev hun til en saltstøtte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Tidlig om morgenen gikk Abraham til det sted hvor han hadde stått for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Og han så utover Sodoma og Gomorra og utover hele landet på sletten; da fikk han se at røken steg op fra landet som røken fra en smelteovn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Således gikk det til at da Gud ødela byene på sletten, da kom Gud Abraham i hu og førte Lot midt ut av ødeleggelsen - dengang han ødela de byer som Lot hadde bodd i.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Og Lot drog fra Soar op i fjellene og blev boende der, og hans to døtre med ham, for han torde ikke bo i Soar. Og han bodde i en hule, han og hans to døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Da sa den eldste til den yngste: Vår far er gammel, og det finnes ingen mann her i landet som kan gå inn til oss efter all verdens vis.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Kom, la oss gi vår far vin å drikke og legge oss hos ham, så vi kan holde ætten i live ved vår far!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Så gav de sin far vin å drikke den natt; og den eldste gikk inn og la sig hos sin far, og han merket det ikke, hverken da hun la sig, eller da hun stod op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Dagen efter sa den eldste til den yngste: Se, inatt lå jeg hos min far; la oss også denne natt gi ham vin å drikke, og gå så du inn og legg dig hos ham, så vi kan holde ætten i live ved vår far!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Så gav de også den natt sin far vin å drikke; og den yngste gikk og la sig hos ham, og han merket det ikke, hverken da hun la sig, eller da hun stod op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Og begge Lots døtre blev fruktsommelige ved sin far.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Og den eldste fødte en sønn og kalte ham Moab; han er stamfar til moabittene, som er til den dag idag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Den yngste fødte også en sønn og kalte ham Ben-Ammi; han er stamfar til ammonittene, som også er til den dag idag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Så drog Abraham derfra til sydlandet og bodde mellem Kades og Sur, og siden opholdt han sig en tid i Gerar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Og Abraham sa om Sara, sin hustru: Hun er min søster. Da sendte Abimelek, kongen i Gerar, folk avsted og tok Sara.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Men Gud kom til Abimelek i en drøm om natten og sa til ham: Nu skal du dø for den kvinnes skyld som du har tatt; for hun er en annen manns hustru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Men Abimelek hadde ikke kommet henne nær, og han sa: Herre, vil du da også slå rettferdige folk ihjel?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Har han ikke selv sagt til mig: Hun er min søster? Og hun har også sagt: Han er min bror. I mitt hjertes uskyldighet og med rene hender har jeg gjort dette.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Og Gud sa til ham i drømmen: Ja, jeg vet at du har gjort dette i ditt hjertes uskyldighet, og jeg har også hindret dig fra å synde mot mig; derfor har jeg ikke latt dig få røre henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Men la nu mannen få sin hustru tilbake! For han er en profet. Og han skal bede for dig, så du får leve. Men dersom du ikke gir henne tilbake, da vit at du visselig skal dø, du og alle dine.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Da stod Abimelek tidlig op om i morgenen og kalte på alle sine tjenere og fortalte dem alt dette, og mennene blev meget redde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Og Abimelek kalte Abraham til sig og sa til ham: Hvad er det du har gjort mot oss! Hvad har jeg syndet mot dig, siden du har ført så stor en synd over mig og mitt rike? Du har båret dig slik at mot mig som ingen skulde gjøre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Og Abimelek sa videre til Abraham: Hvad mente du med å gjøre dette?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Da sa Abraham: Jeg tenkte: Det er visst ingen gudsfrykt på dette sted, og de vil slå mig ihjel for min hustrus skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Hun er også virkelig min søster, min fars datter, men ikke min mors datter; og hun blev min hustru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Og da Gud bød mig å vandre om borte fra min fars hus, sa jeg til henne: Således må du vise din kjærlighet mot mig: Hvor vi så kommer, må du si om mig: Han er min bror.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Så tok Abimelek småfe og storfe og træler og trælkvinner og gav Abraham og lot ham få Sara, sin hustru, tilbake.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Og Abimelek sa: Se, mitt land ligger åpent for dig; bo hvor du selv vil!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Og til Sara sa han: Se, her gir jeg din bror tusen sekel sølv; det skal være en sonegave for dig i alles øine som er sammen med dig, og for alle har du nu fått opreisning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Og Abraham bad til Gud, og Gud helbredet Abimelek og hans hustru og hans tjenestekvinner, så de fikk barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'For Herren hadde aldeles lukket for hvert morsliv i Abimeleks hus for Abrahams hustru Saras skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Og Herren så til Sara som han hadde sagt, og Herren gjorde med Sara som han hadde lovt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Sara blev fruktsommelig og fødte Abraham en sønn i hans alderdom på den fastsatte tid som Gud hadde talt til ham om.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Og Abraham kalte den sønn han hadde fått, den som Sara hadde født ham, Isak.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Og Abraham omskar Isak, sin sønn, da han var åtte dager gammel, således som Gud hadde befalt ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Abraham var hundre år gammel da han fikk sin sønn Isak.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Da sa Sara: Gud har gjort det så at jeg må le; alle som hører dette, vil le av mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Og hun sa: Hvem skulde vel ha sagt til Abraham at Sara gir barn å die? Og nu har jeg født ham en sønn i hans alderdom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Og gutten vokste op og blev avvent; og Abraham gjorde et stort gjestebud den dag Isak blev avvent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Og Sara så at egypterkvinnen Hagars sønn, som hun hadde født Abraham, spottet,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'og hun sa til Abraham: Driv ut denne trælkvinne og hennes sønn! For denne trælkvinnes sønn skal ikke arve med min sønn, med Isak.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Dette gjorde Abraham meget ondt for hans sønns skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Men Gud sa til Abraham: La det ikke gjøre dig ondt for guttens og for din trælkvinnes skyld! Lyd Sara i alt det hun sier til dig! For i Isak skal det nevnes dig en ætt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Men også trælkvinnens sønn vil jeg gjøre til et folk, fordi han er din sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Da stod Abraham tidlig op om morgenen og tok brød og en skinnsekk med vann og gav Hagar og la det på hennes skulder; han gav henne også gutten med og lot henne fare. Og hun gikk avsted og for vill i Be\'erseba-ørkenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Da det var forbi med vannet i sekken, kastet hun gutten fra sig under en busk');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'og gikk bort og satte sig et stykke ifra, sa langt som et bueskudd; for hun tenkte: Jeg vil ikke se på at gutten dør. Så satt hun et stykke ifra og brast i gråt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Men Gud hørte gutten ynke sig, og Guds engel ropte til Hagar fra himmelen og sa til henne: Hvad fattes dig, Hagar? Frykt ikke! For Gud har hørt gutten ynke sig der han ligger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Reis dig, løft gutten op og hold ham ved hånden! For jeg vil gjøre ham til et stort folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Og Gud åpnet hennes øine, så hun så en brønn; da gikk hun dit og fylte sekken med vann og gav gutten å drikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Og Gud var med gutten; han blev stor og bodde i ørkenen, og da han vokste til, blev han bueskytter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Han bosatte sig i ørkenen Paran, og hans mor tok en hustru til ham fra Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Ved denne tid kom Abimelek og Pikol, hans hærfører, og sa til Abraham: Gud er med dig i alt det du gjør.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Så tilsverg mig nu her ved Gud at du ikke vil fare med svik mot mig og mine barn og min ætt! Likesom jeg har vist godhet mot dig, så skal du gjøre det samme mot mig og mot det land du bor i som fremmed.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Da sa Abraham: Ja, det skal jeg tilsverge dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Men Abraham gikk i rette med Abimelek for en brønn som Abimeleks tjenere hadde tatt med vold.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Da sa Abimelek: Jeg vet ikke hvem som har gjort dette; hverken har du sagt mig det, eller har jeg hørt det før idag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Da tok Abraham småfe og storfe og gav Abimelek, og de gjorde en pakt med hverandre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Og Abraham stilte syv får av småfeet for sig selv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Da sa Abimelek til Abraham Hvad skal disse syv får her som du har stilt for sig selv?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Han svarte: Disse syv får skal du ta imot av mig; det skal være til et vidnesbyrd for mig at jeg har gravd denne brønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Derfor kalte de dette sted Be\'erseba; for der gjorde de begge sin ed.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Så gjorde de da en pakt i Be\'erseba; og Abimelek og Pikol, hans hærfører, brøt op og vendte tilbake til filistrenes land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Og Abraham plantet en tamarisk i Be\'erseba, og der påkalte han Herrens, den evige Guds navn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Og Abraham bodde som fremmed i filistrenes land en lang tid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Nogen tid derefter satte Gud Abraham på prøve, og han sa til ham: Abraham! Og han svarte: Ja, her er jeg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Da sa han: Ta din sønn, din eneste, ham som du har så kjær, Isak, og gå til Moria land og ofre ham der til brennoffer på et av fjellene, som jeg skal si dig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Så stod Abraham tidlig op om morgenen og lesste på sitt asen og tok to av sine drenger med sig og Isak, sin sønn; han kløvde ved til brennofferet og gav sig på veien til det sted Gud hadde sagt ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'På den tredje dag, da Abraham så sig omkring, fikk han øie på stedet langt borte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Da sa Abraham til sine drenger: Bli I her med asenet! Jeg og gutten, vi vil gå dit bort og bede og så komme tilbake til eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Så tok Abraham veden til brennofferet og la den på Isak, sin sønn, og selv tok han ilden og kniven i sin hånd; og så gikk de begge sammen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Da talte Isak til Abraham, sin far, og sa: Du far! Han svarte: Ja, min sønn! Han sa: Se, her er ilden og veden, men hvor er lammet til brennofferet?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraham svarte: Gud skal selv utse sig lammet til brennofferet, min sønn! Så gikk de begge sammen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Og da de kom til det sted Gud hadde sagt ham, bygget Abraham et alter der og la veden til rette; så bandt han Isak, sin sønn, og la ham på alteret ovenpå veden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Og Abraham rakte ut hånden og tok kniven for å ofre sin sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Da ropte Herrens engel til ham fra himmelen og sa: Abraham, Abraham! - Han svarte: Ja, her er jeg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Da sa han: Legg ikke hånd på gutten og gjør ham ikke noget! For nu vet jeg at du frykter Gud, siden du ikke har spart din eneste sønn for min skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Da nu Abraham så op, fikk han se en vær bakenfor sig, som hang fast i buskene med sine horn; og Abraham gikk bort og tok væren og ofret den til brennoffer istedenfor sin sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Og Abraham kalte dette sted: Herren ser. Derfor sier folk den dag idag: På Herrens berg skal han la sig se.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Og Herrens engel ropte ennu en gang til Abraham fra himmelen');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'og sa: Ved mig selv sverger jeg, sier Herren: Fordi du gjorde dette og ikke sparte din eneste sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'så vil jeg storlig velsigne dig og gjøre din ætt såre tallrik, som stjernene på himmelen og som sanden på havets bredd, og din ætt skal ta sine fienders porter i eie;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'og i din ætt skal alle jordens folk velsignes, fordi du lød mitt ord.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Så gikk Abraham tilbake til sine drenger, og de brøt op og drog sammen til Be\'erseba; og Abraham blev boende i Be\'erseba.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Nogen tid derefter kom det nogen og sa til Abraham: Din bror Nakor og Milka har også fått sønner:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Us, den eldste, og Bus, hans bror, og Kemuel, far til Aram,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'og Kesed og Haso og Pildas og Jidlaf og Betuel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Og Betuel var far til Rebekka. Disse åtte barn fikk Nakor, Abrahams bror, med Milka.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Også hans medhustru, som hette Re\'uma, fikk barn: Tebah og Gaham og Tahas og Ma\'aka.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Saras alder blev hundre og syv og tyve år; det var Saras leveår.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Og Sara døde i Kirjat-Arba, det er Hebron, i Kana\'ans land; og Abraham kom for å holde sørgehøitid og gråte over Sara.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Derefter stod Abraham op og gikk bort fra sin døde hustru, og han talte til Hets barn og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Jeg er en fremmed og utlending hos eder; la mig få et gravsted til eiendom hos eder, så jeg kan føre min døde hustru bort og begrave henne!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Da svarte Hets barn Abraham og sa til ham:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Hør på oss, herre! Du er en Guds høvding iblandt oss; begrav din døde i den beste av våre graver! Ingen av oss skal nekte dig sin grav til å begrave henne i.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Da stod Abraham op og bøide sig for landets folk, for Hets barn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'og han talte med dem og sa: Dersom I samtykker i at jeg fører min døde bort og begraver henne, så hør på mig og legg et godt ord inn for mig hos Efron, Sohars sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'at han lar mig få Makpela-hulen, som tilhører ham og ligger i utkanten av hans mark. Han skal få full betaling for den hvis han vil selge mig den, her midt iblandt eder, til eiendoms-gravsted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Men Efron satt midt iblandt Hets barn; og Efron, hetitten, svarte Abraham så Hets barn hørte på det, alle de som hørte hjemme i hans by, og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nei, herre! Hør på mig: Jeg gir dig marken, og hulen som er på den, gir jeg dig også; for mine landsmenns øine gir jeg dig den: begrav din døde der!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Da bøide Abraham sig for landets folk,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'og han talte til Efron så landets folk hørte på det, og sa: Bare du nu vilde høre på mig! Jeg betaler dig det marken er verd; ta imot det av mig og la mig få begrave min døde der!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Da svarte Efron Abraham og sa til ham:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Herre, hør på mig! Et jordstykke som er verd fire hundre sekel sølv, hvad har det å si mellem mig og dig? Begrav du din døde!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Og Abraham skjønte hvad Efron mente, og Abraham veide op til Efron det sølv som han hadde talt om i påhør av Hets barn, fire hundre sekel sølv, slike som var gangbare i handel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Og Efrons mark i Makpela, som ligger østenfor Mamre, både marken og hulen som er på den, og alle trærne som fantes på marken, så langt den rakk rundt omkring, blev tilskjøtet');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Abraham som eiendom, så Hets barn så på det, alle de som hørte hjemme i hans by.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Derefter begravde Abraham Sara, sin hustru, i hulen på Makpelamarken østenfor Mamre, det er Hebron, i Kana\'ans land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Og marken og hulen på den gikk fra Hets barn over til Abraham som eiendoms-gravsted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Abraham var nu gammel og langt ute i årene, og Herren hadde velsignet Abraham i alle ting.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Da sa Abraham til sin tjener, han som var den eldste i hans hus og rådet over alt det han hadde: Kjære, legg din hånd under min lend,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'så vil jeg la dig sverge ved Herren, himmelens Gud og jordens Gud, at du ikke skal la min sønn ta sig en hustru av døtrene til kana\'anitterfolket, som jeg bor iblandt,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'men du skal dra til mitt eget land og til min slekt og hente en hustru til min sønn Isak.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Tjeneren sa til ham: Men om nu kvinnen ikke vil følge mig hit til dette land, skal jeg da føre din sønn tilbake til det land som du er kommet fra?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham svarte: Vokt dig for å føre min sønn tilbake dit!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Herren, himmelens Gud, som førte mig bort fra min fars hus og fra mitt fedreland, og som talte til mig, og som svor mig til og sa: Din ætt vil jeg gi dette land, han skal sende sin engel foran dig, så du kan hente en hustru til min sønn derfra.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Men dersom kvinnen ikke vil følge dig, da skal du være løst fra denne din ed til mig; bare du ikke fører min sønn tilbake dit!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Da la tjeneren sin hånd under Abrahams, sin herres lend og lovte ham dette med ed.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Så tok tjeneren ti kameler av dem som hørte hans herre til, og drog avsted, og han hadde med sig alleslags kostelige ting som hørte hans herre til; han tok avsted og drog til Mesopotamia, til Nakors by.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Og han lot kamelene legge sig utenfor byen ved brønnen ved aftenstid, den tid da kvinnene pleier å komme ut og hente vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Og han sa: Herre, min herre Abrahams Gud! La det lykkes for mig idag, og gjør miskunnhet mot min herre Abraham!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Se, nu står jeg her ved denne kilde mens døtrene til mennene i byen kommer ut for å hente vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'La det nu bli så at den pike som jeg sier således til: Hell på din krukke, så jeg kan få drikke, og som da sier: Drikk, og jeg vil også gi dine kameler å drikke - at hun er den du har utsett for din tjener Isak, og av det vil jeg skjønne at du har gjort miskunnhet mot min herre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Og se, før han hadde holdt op å tale, hendte det at Rebekka, en datter av Betuel, som var sønn til Milka og Nakor, Abrahams bror, kom ut med sin krukke på skulderen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Det var en meget vakker pike, en jomfru, som ingen mann var kommet nær. Hun gikk ned til kilden og fylte sin krukke og steg op igjen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Da løp tjeneren henne i møte og sa: Kjære, la mig få drikke litt vann av din krukke!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Og hun sa: Drikk, herre! Og hun skyndte sig og tok krukken ned i sin hånd og lot ham få drikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Og da hun hadde latt ham drikke så meget han vilde, sa hun: Jeg vil også hente vann til dine kameler, til de har fått nok.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Og hun skyndte sig og tømte sin krukke i vanntrauet og løp atter til brønnen efter vann og lot alle hans kameler få drikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Og mannen så på henne og undret sig, men tidde stille for å få vite om Herren hadde latt hans reise lykkes eller ikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Da så kamelene hadde drukket, tok mannen en gullring som veide en halv sekel, og to armbånd som veide ti sekel gull, og la dem om hennes armer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Og han sa: Hvem er du datter til? Kjære, si mig det! Er det rum nok i din fars hus, sa vi kan overnatte der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Hun svarte: Jeg er datter til Betuel, som er sønn til Nakor og Milka.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Så sa hun til ham: Det er fullt op både av halm og fôr hos oss, og det er også rum til å overnatte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Da bøide mannen sig ned og tilbad Herren');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'og sa: Lovet være Herren, min herre Abrahams Gud, som ikke har tatt sin miskunn og sin trofasthet fra min herre! Herren har ført mig på rette vei til min herres frender.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Men piken sprang hjem til sin mor og fortalte alt dette.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Rebekka hadde en bror, som hette Laban; han sprang ut til mannen der ute ved kilden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'For da han så ringen og armbåndene som hans søster bar, og hørte sin søster Rebekka si: Således talte mannen til mig, gikk han ut til mannen, og se, der stod han hos kamelene ved kilden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'og han sa: Kom inn, du Herrens velsignede! Hvorfor står du her ute? Jeg har jo gjort huset i stand, og der er rum for kamelene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Så gikk mannen inn i huset og lesste av kamelene; og Laban gav kamelene halm og fôr og kom med vann til ham og de menn som var med ham, til å tvette føttene i.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Og de satte frem mat for ham; men han sa: Jeg vil ikke ete før jeg har båret frem mitt ærend. Og Laban sa: Tal!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Da sa han: Jeg er Abrahams tjener;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'og Herren har storlig velsignet min herre, så han er blitt rik, og han har gitt ham småfe og storfe og sølv og gull og træler og trælkvinner og kameler og asener.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Og Sara, min herres hustru, fødte min herre en sønn på sine gamle dager; og ham har han gitt alt det han eier.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Og min herre lot mig sverge og sa: Du skal ikke la min sønn ta sig en hustru av døtrene til kana\'anitterfolket, i hvis land jeg bor;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'men du skal gå til min fars hus og til min slekt og hente en hustru til min sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Da sa jeg til min herre: Men om nu kvinnen ikke vil følge mig?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Men han sa til mig: Herren, for hvis åsyn jeg har vandret, skal sende sin engel med dig og la din reise lykkes, sa du finner en hustru til min sønn av min slekt og av min fars hus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Da skal du være løst fra din ed til mig, når du kommer til mitt folk; og vil de ikke gi dig henne, så er du også løst fra eden til mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Så kom jeg da idag til kilden, og jeg sa: Herre, min herre Abrahams Gud! Å, om du vilde la denne min reise lykkes!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Se, nu står jeg her ved denne kilde; la det nu bli så at om en ung pike kommer ut for å hente vann, og jeg sier til henne: Kjære, la mig få litt vann av din krukke,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'og hun da sier til mig: Drikk du, og jeg vil også hente vann til dine kameler - så er hun den kvinne som Herren har utsett for min herres sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Før jeg hadde holdt op å tale således ved mig selv, se, da kom Rebekka ut med sin krukke på skulderen, og hun gikk ned til kilden og øste op vann; da sa jeg til henne: Kjære, la mig få drikke!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Og hun skyndte sig og tok sin krukke ned og sa: Drikk, og jeg vil også la dine kameler få drikke. Så drakk jeg, og hun lot også kamelene få drikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Og jeg spurte henne: Hvem er du datter til? Hun svarte: Jeg er datter til Betuel, som er sønn til Nakor og Milka. Da satte jeg ringen i hennes nese og armbåndene på hennes armer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Og jeg bøide mig ned og tilbad Herren, og jeg lovet Herren, min herre Abrahams Gud, som hadde ledet mig på rette vei til å finne min herres brordatter til hustru for hans sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Dersom I nu vil vise godhet og trofasthet mot min herre, da si mig det, og hvis ikke, da si mig det, så jeg kan vende mig til en annen kant, til høire eller til venstre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Da svarte Laban og Betuel og sa: Dette kommer fra Herren; vi kan intet si dig, hverken ondt eller godt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Se, der står Rebekka; ta henne og dra bort og la din herres sønn få henne til hustru, som Herren har sagt!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Da Abrahams tjener hørte disse ord, bøide han sig til jorden for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Og tjeneren tok frem sølvsmykker og gullsmykker og klær og gav Rebekka; og hennes bror og hennes mor gav han også kostelige gaver.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Så åt de og drakk, han og de menn som var med ham, og de blev der om natten. Men da de stod op om morgenen, sa han: La mig nu fare hjem til min herre!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Da sa hennes bror og hennes mor: La piken bli hos oss en tid, en ti dager eller så! Siden kan du reise.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Men han sa til dem: Hold mig ikke tilbake, nu da Herren har latt min reise lykkes! La mig få ta avsted, så jeg kan komme hjem til min herre!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Da sa de: La oss kalle på piken og spørre henne selv!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Så kalte de på Rebekka og sa til henne: Vil du reise med denne mann? Hun svarte: Ja, det vil jeg. -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Så lot de Rebekka, sin søster, og hennes fostermor og Abrahams tjener og hans menn reise.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Og de velsignet Rebekka og sa til henne: Vår søster, bli til tusen ganger ti tusen, og måtte din ætt ta sine fienders porter i eie!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Og Rebekka og hennes piker gjorde sig ferdig, og de satte sig på kamelene og fulgte med mannen og tjeneren tok Rebekka med sig og drog avsted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Isak var nettop kommet tilbake fra en vandring til brønnen Lakai Ro\'i; for han bodde i sydlandet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Og Isak gikk ved aftenstid ut på marken for å ha en stille stund og da han så op, fikk han se nogen kameler som kom gående.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Og da Rebekka så op, fikk hun øie på Isak; og hun skyndte sig og steg ned av kamelen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Og hun sa til tjeneren: Hvem er denne mann som kommer oss i møte på marken? Tjeneren svarte Det er min herre. Så tok hun sløret og tilhyllet sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Og tjeneren fortalte Isak alt det han hadde gjort.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Og Isak førte henne inn i sin mor Saras telt; han tok Rebekka hjem, og hun blev hans hustru, og han hadde henne kjær. Så blev Isak trøstet i sorgen over sin mor.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Og Abraham tok sig atter en hustru; hun hette Ketura.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Med henne fikk han Simran og Joksan og Medan og Midian og Jisbak og Suah.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Og Joksan fikk sønnene Sjeba og Dedan; og Dedans barn var assurerne og letuserne og le\'ummerne');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Og Midians barn var Efa og Efer og Hanok og Abida og Elda\'a; alle disse var Keturas barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Og Abraham gav Isak alt det han eide.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Men sønnene til de medhustruer som Abraham hadde, gav han gaver og lot dem, mens han enn levde, flytte bort fra Isak, sin sønn, østover, til Østerland.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Abrahams levetid og den alder han nådde, var hundre og fem og sytti år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Så opgav Abraham ånden og døde i en god alderdom, gammel og mett av dager, og han blev samlet til sine fedre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Og Isak og Ismael, hans sønner, begravde ham i Makpela-hulen på den mark som hadde tilhørt hetitten Efron, Sohars sønn, østenfor Mamre,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'den mark Abraham hadde kjøpt av Hets barn; der blev Abraham begravet likesom Sara, hans hustru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Og efter Abrahams død velsignet Gud Isak, hans sønn. Og Isak bodde ved brønnen Lakai Ro\'i.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Dette er Ismaels, Abrahams sønns ættetavle, han som Abraham fikk med egypterkvinnen Hagar, Saras trælkvinne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Dette er navnene på Ismaels sønner - de navn som de har i sin ættetavle: Nebajot, Ismaels førstefødte, og Kedar og Adbe\'el og Mibsam.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'og Misma og Duma og Massa,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar og Tema, Jetur, Nafis og Kedma.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Dette var Ismaels sønner, og dette var deres navn, i deres byer og leire, tolv ættehøvdinger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Ismaels leveår var hundre og syv og tretti år; så opgav han ånden og døde og blev samlet til sine fedre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Og de bodde fra Havila til Sur, som ligger midt for Egypten, og bortimot Assyria; han nedsatte sig østenfor alle sine brødre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Dette er historien om Abrahams sønn Isaks ætt: Abraham fikk sønnen Isak.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Og Isak var firti år gammel da han ektet Rebekka, som var datter til arameeren Betuel fra Mesopotamia og søster til arameeren Laban.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Og Isak bad til Herren for sin hustru, for hun var barnløs; og Herren bønnhørte ham, og Rebekka, hans hustru, blev fruktsommelig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Men fosterne støtte til hverandre i hennes liv; da sa hun: Er det således, hvorfor skal jeg da være til? Og hun gikk for å spørre Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Og Herren sa til henne: I ditt liv er det to folk, og fra ditt skjød skal to folkeslag skille sig at; det ene folk skal være sterkere enn det andre, og den eldste skal tjene den yngste.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Da nu hennes tid var kommet at hun skulde føde, se, da var det tvillinger i hennes liv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Og den som kom først frem, var rød og over hele kroppen som en lodden kappe; og de kalte ham Esau.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Derefter kom hans bror frem, og hans hånd holdt i Esaus hæl, og ham kalte de Jakob. Isak var seksti år gammel da de blev født.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Da nu guttene vokste til, blev Esau en dyktig jeger, en mann som holdt til i skog og mark; men Jakob var en stillferdig mann, som holdt sig ved teltene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Og Isak holdt mest av Esau, for han var glad i vilt; men Rebekka holdt mest av Jakob.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Engang da Jakob holdt på å koke en velling, kom Esau hjem fra marken og var rent opgitt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Og Esau sa til Jakob: La mig få til livs noget av det røde, det røde du har der, for jeg er rent opgitt! Derfor kalte de ham Edom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Men Jakob sa: Selg mig først din førstefødselsrett!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Esau svarte: Jeg holder på å dø; hvad skal jeg da med førstefødselsretten?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Da sa Jakob: Gjør først din ed på det! Og han gjorde sin ed på det og solgte så sin førstefødselsrett til Jakob.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Og Jakob gav Esau brød og linsevelling, og han åt og drakk og stod op og gikk sin vei. Således ringeaktet Esau førstefødselsretten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Og det var atter hungersnød i landet - likesom forrige gang på Abrahams tid; og Isak drog til filistrenes konge Abimelek i Gerar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Da åpenbarte Herren sig for ham og sa: Dra ikke ned til Egypten! Bo i det land som jeg sier dig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Bli boende her i landet! Jeg vil være med dig og velsigne dig; for dig og din ætt vil jeg gi alle disse land - jeg vil holde den ed jeg har svoret Abraham, din far.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Og jeg vil gjøre din ætt tallrik som stjernene på himmelen, og jeg vil gi din ætt alle disse land, og i din ætt skal alle jordens folk velsignes,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'fordi Abraham lød mitt ord og holdt alt det jeg bød ham å holde, mine bud, mine forskrifter og mine lover.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Så blev Isak boende i Gerar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Og mennene der på stedet spurte ham ut om hans hustru. Da sa han: Hun er min søster. For han torde ikke si at hun var hans hustru; han tenkte: Mennene her på stedet kunde da slå mig ihjel for Rebekkas skyld, siden hun er så vakker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Da han nu hadde vært der en tid, hendte det engang at Abimelek, filistrenes konge, så ut gjennem vinduet og fikk se at Isak kjærtegnet Rebekka, sin hustru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Da kalte Abimelek Isak til sig og sa: Hun er jo din hustru, hvor kunde du da si: Hun er min søster? Isak svarte: Jeg tenkte jeg kunde komme til å miste livet for hennes skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Da sa Abimelek: Hvorfor har du gjort dette mot oss? Hvor lett kunde det ikke ha hendt at en eller annen av folket hadde lagt sig hos din hustru, og da hadde du ført skyld over oss.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Så bød Abimelek alt folket og sa: Den som rører ved denne mann eller hans hustru, han skal late sitt liv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Isak sådde korn der i landet og fikk det år hundre fold, for Herren velsignet ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Og han blev en rik mann, og blev rikere og rikere, så han til sist var overmåte rik.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Han eide småfe og storfe og mange tjenere, så filistrene blev misunnelige på ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Og alle de brønner som hans fars tjenere hadde gravd i Abrahams, hans fars dager, dem kastet filistrene til og fylte dem med jord.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Og Abimelek sa til Isak: Dra bort fra oss, for du er blitt oss altfor mektig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Så drog Isak derfra og slo leir i Gerar-dalen og blev boende der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Og Isak gravde op igjen de brønner som de hadde gravd i Abrahams, hans fars dager, og som filistrene hadde kastet til efter Abrahams død; og han gav dem de samme navn som hans far hadde gitt dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Og Isaks tjenere gravde i dalen og fant der en brønn med rinnende vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Men hyrdene fra Gerar trettet med Isaks hyrder og sa: Vannet hører oss til. Og han kalte brønnen Esek, fordi de stredes med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Siden gravde de en annen brønn, og den trettet de også om; og han kalte den Sitna.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Så brøt han op derfra og gravde ennu en brønn; den trettet de ikke om; og han kalte den Rehobot og sa: Nu har Herren gjort det rummelig for oss, så vi kan bli tallrike i landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Siden drog han derfra op til Be\'erseba.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'samme natt åpenbarte Herren sig for ham og sa: Jeg er Abrahams, din fars Gud; frykt ikke, for jeg er med dig, og jeg vil velsigne dig og gjøre din ætt tallrik for Abrahams, min tjeners skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Der bygget han et alter og påkalte Herrens navn; og han slo op sitt telt der; og Isaks tjenere gravde der en brønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Siden kom Abimelek til ham fra Gerar, med Akussat, sin venn, og Pikol, sin hærfører.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Da sa Isak til dem: Hvorfor kommer I til mig, I som hater mig og har drevet mig bort fra eder?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'De svarte: Vi har sett det grant at Herren er med dig; derfor sier vi: Kom, la oss sverge en ed oss imellem, vi og du, og la oss få gjøre en pakt med dig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'at du ikke skal gjøre oss noget ondt, likesom heller ikke vi har rørt dig, men bare gjort dig godt og latt dig fare i fred. Du er nu Herrens velsignede.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Så gjorde han et gjestebud for dem, og de åt og drakk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Morgenen efter stod de tidlig op og svor hverandre sin ed; siden lot Isak dem fare, og de drog fra ham fred.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Samme dag hendte det at Isaks tjenere kom og fortalte ham om den brønn de hadde gravd, og sa til ham: Vi har funnet vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Og han kalte den Siba; derfor heter byen Be\'erseba den dag i dag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Da Esau var firti år gammel, tok han til hustruer Judit, datter til hetitten Be\'eri, og Basmat, datter til hetitten Elon.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Men de blev en hjertesorg for Isak og Rebekka.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Da Isak var blitt gammel, og hans øine var blitt sløve, så han ikke kunde se, kalte han til sig Esau, sin eldste sønn, og sa til ham: Min sønn! Han svarte: Ja, her er jeg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Da sa han: Jeg er blitt gammel og vet ikke hvad dag jeg skal dø.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Så ta nu dine jaktredskaper, ditt kogger og din bue, og gå ut på marken og skyt mig noget vilt,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'og lag en velsmakende rett for mig, slik som jeg liker det, og kom så hit med den! Da vil jeg ete, så min sjel kan velsigne dig, før jeg dør.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Men Rebekka hørte på at Isak talte til Esau, sin sønn. Så gikk Esau ut på marken for å skyte noget vilt og ha det med sig hjem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Da sa Rebekka til Jakob, sin sønn: Jeg hørte din far tale til Esau, din bror, og si:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Hent mig noget vilt og lag en velsmakende rett for mig, så jeg kan ete av den og velsigne dig for Herrens åsyn, før jeg dør.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Lyd nu mitt ord, min sønn, og gjør det jeg byder dig:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Gå bort til hjorden og hent mig derfra to gode kje, så skal jeg lage en velsmakende rett av dem for din far, slik som han liker det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Og du skal gå inn med den til din far, så han kan ete av den og velsigne dig, før han dør.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Da sa Jakob til Rebekka, sin mor: Esau, min bror, er jo lodden, og jeg er glatt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Kanskje min far kjenner på mig og så tror at jeg vil ha ham til narr, og jeg kommer til å føre en forbannelse over mig og ikke en velsignelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Da sa hans mor til ham: Den forbannelse skal jeg ta på mig min sønn! Bare lyd mitt råd og gå og hent mig kjeene!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Da gikk han og hentet dem og kom til sin mor med dem, og hans mor laget en velsmakende rett, slik som hans far likte det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Så tok Rebekka sin eldste sønn Esaus høitidsklær, som hun hadde hos sig i huset, og hun lot Jakob, sin yngste sønn, ta dem på.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Men skinnene av kjeene hadde hun om hans hender og om den glatte del av hans hals.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Så lot hun sin sønn Jakob få den velsmakende rett og brødet som hun hadde laget,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'og han gikk inn til sin far og sa: Far! Han svarte: Ja, her er jeg; hvem er du, min sønn?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Da sa Jakob til sin far: Jeg er Esau, din førstefødte; jeg har gjort som du sa til mig. Sett dig nu op og et av mitt vilt, så din sjel kan velsigne mig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Men Isak sa til sin sønn: Hvorledes har du da så snart kunnet finne noget, min sønn? Han, svarte: Herren din Gud sendte mig det i møte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Da sa Isak til Jakob: Kom hit og la mig få kjenne på dig, min sønn, om du er min sønn Esau, eller ikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Så gikk Jakob frem til Isak, sin far; og han kjente på ham og sa: Røsten er Jakobs, men hendene er Esaus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Og han kjente ham ikke, fordi hans hender var lodne som hans bror Esaus hender; og han velsignet ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Og han sa: Er du virkelig min sønn Esau? Han svarte: Ja, det er jeg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Da sa han: Kom hit med det til mig og la mig få ete av min sønns vilt, så min sjel kan velsigne dig. Så satte han det frem for ham, og han åt, og han kom med vin til ham, og han drakk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Så sa Isak, hans far, til ham: Kom nu hit og kyss mig, min sønn!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Da gikk han frem og kysset ham; og han kjente lukten av hans klær og velsignet ham og sa: Se, duften av min sønn er som duften av en mark som Herren har velsignet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Så gi Gud dig av himmelens dugg og av jordens fedme og korn og most i overflod.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Folk skal tjene dig, og folkeslag skal falle dig til fote; vær herre over dine brødre, og måtte din mors sønner falle dig til fote! Forbannet være den som forbanner dig, og velsignet den som velsigner dig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Men da Isak hadde endt sin velsignelse over Jakob, og Jakob nettop var gått ut fra Isak, sin far, da kom Esau, hans bror, hjem fra jakten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Han laget også en velsmakende rett og bar den inn til sin far; og han sa til sin far: Vil ikke far reise sig op og ete av sin sønns vilt, så din sjel kan velsigne mig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Og Isak, hans far, spurte ham: Hvem er du? Han svarte: Jeg er Esau, din førstefødte sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Da blev Isak overmåte forferdet, og han sa: Hvem var det da som hadde skutt noget vilt og kom til mig med det? Jeg åt av alt, før du kom, og velsignet ham! Han skal også være velsignet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Da Esau hørte disse ord av sin far, satte han i et høit og sårt skrik, og han sa til sin far: Velsign også mig, min far!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Men han sa: Din bror kom med list og tok din velsignelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Da sa han: Er det fordi han har fått navnet Jakob, at han nu to ganger har overlistet mig? Min førstefødselsrett tok han, og se, nu har han tatt min velsignelse. Så sa han: Har du ikke en velsignelse igjen til mig og?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Isak svarte og sa til Esau: Se, jeg har satt ham til herre over dig, og alle hans brødre har jeg gjort til hans tjenere, og jeg har gitt ham korn og most i overflod; hvad skal jeg da gjøre for dig, min sønn?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Og Esau sa til sin far: Har du da bare denne ene velsignelse, min far? Velsign også mig, min far! Og Esau gråt høit.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Da tok Isak, hans far, til orde igjen og sa til ham: Se, uten jordens fedme skal din bolig være og uten himmelens dugg fra oven.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Av ditt sverd skal du leve, og din bror skal du tjene; men når du engang river dig løs, da skal du bryte hans åk av din nakke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Og Esau hatet Jakob for den velsignelse som hans far hadde lyst over ham. Og Esau sa ved sig selv: Snart kommer den tid da vi må sørge over min far; da skal jeg slå Jakob, min bror, ihjel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Og Rebekka fikk vite hvad Esau, hennes eldste sønn, hadde sagt; da sendte hun bud efter Jakob, sin yngste sønn, og sa til ham: Se, Esau, din bror, vil hevne sig på dig og slå dig ihjel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Lyd nu mitt ord, min sønn: Gjør dig ferdig og flykt til min bror Laban i Karan,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'og bli hos ham en tid, til din brors vrede har lagt sig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'til din brors vrede har vendt sig fra dig, og han har glemt det du har gjort mot ham! Da skal jeg sende bud og hente dig derfra. Hvorfor skulde jeg miste eder begge på én dag!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Så sa Rebekka til Isak: Jeg er kjed av mitt liv for disse Hets døtres skyld; skulde nu også Jakob ta sig en hustru av Hets døtre, slik en som disse, en av landets døtre, hvad skulde jeg da leve efter?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Da kalte Isak Jakob til sig og velsignet ham og bød ham og sa til ham: Du skal ikke ta nogen av Kana\'ans døtre til hustru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Gjør dig rede og dra til Mesopotamia, til din morfar Betuels hus, og hent dig en hustru derfra, en av din morbror Labans døtre!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Og Gud den allmektige velsigne dig og gjøre dig fruktbar og gi dig en tallrik ætt, så du blir til en hel skare av folkeslag,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'han gi dig Abrahams velsignelse, både dig og din ætt, så du kommer til å eie det land hvor du nu bor som fremmed, det som Gud gav Abraham!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Så lot Isak Jakob reise; og han drog til Mesopotamia, til arameeren Laban, Betuels sønn, som var bror til Rebekka, Jakobs og Esaus mor.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Da Esau så at Isak hadde velsignet Jakob og sendt ham til Mesopotamia for å hente sig en hustru derfra - at han hadde velsignet ham og gitt ham den befaling: Du skal ikke ta nogen av Kana\'ans døtre til hustru -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'og at Jakob hadde adlydt sin far og sin mor og var reist til Mesopotamia,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'og da Esau så at Kana\'ans døtre mishaget Isak, hans far,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'så gikk han til Ismael og tok Mahalat, datter til Abrahams sønn Ismael, Nebajots søster, til hustru foruten sine andre hustruer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Jakob tok ut fra Be\'erseba og gav sig på veien til Karan.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Og han kom til et sted hvor han blev natten over, for solen var gått ned; og han tok en av stenene som lå der, og la den under sitt hode, og så la han sig til å sove der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Da drømte han og så en stige som var stilt op på jorden, og hvis topp nådde til himmelen, og se, Guds engler steg op og steg ned på den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Og se, Herren stod øverst på den og sa: Jeg er Herren, din far Abrahams Gud og Isaks Gud; det land som du nu ligger i, det vil jeg gi dig og din ætt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Og din ætt skal bli som støvet på jorden, og du skal utbrede dig mot vest og mot øst og mot nord og mot syd, og i dig og i din ætt skal alle jordens slekter velsignes');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Og se, jeg er med dig og vil bevare dig hvor du så går, og jeg vil føre dig tilbake til dette land; jeg vil ikke forlate dig før jeg har gjort det jeg har lovt dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Da Jakob våknet av sin søvn, sa han: Sannelig, Herren er på dette sted, og jeg visste det ikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Og det kom en frykt over ham, og han sa: Hvor forferdelig er ikke dette sted! Her er visselig Guds hus, her er himmelens port.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Morgenen efter stod Jakob tidlig op og tok den sten han hadde lagt under sitt hode, og reiste den op som en minnesten, og han helte olje over den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Og han kalte dette sted Betel; før hette byen Luz.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Og Jakob gjorde et løfte og sa: Dersom Gud vil være med mig og bevare mig på denne min ferd og gi mig brød å ete og klær å klæ mig med,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'og jeg kommer vel hjem igjen til min fars hus, så skal Herren være min Gud,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'og denne sten som jeg har reist op som en minnesten, skal være et Guds hus, og av alt det du gir mig, vil jeg gi dig tiende.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Så gav Jakob sig atter på veien og drog til Østens barns land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Og da han så sig omkring, fikk han se en brønn på marken, og ved den lå det tre flokker småfe. for av denne brønn vannet de feet; men stenen som lå over brønnens åpning, var stor.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Der samlet alle feflokkene sig, og gjæterne veltet stenen fra brønnens åpning og vannet småfeet, og så la de stenen tilbake på sitt sted, over brønnens åpning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Jakob spurte dem: Mine brødre, hvor er I fra? De svarte: Vi er fra Karan.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Så spurte han dem: Kjenner I Laban, sønn til Nakor? De svarte: Ja, vi kjenner ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Da spurte han dem: Står det vel til med ham? De svarte: Ja, det gjør det, og se, der kommer hans datter Rakel med småfeet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Da sa han: Det er jo ennu høi dag, det er ennu ikke tid til å samle buskapen; vann småfeet og gå avsted igjen og gjæt!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Men de sa: Det kan vi ikke før alle feflokkene er samlet, og stenen blir veltet fra brønnens åpning; da vanner vi småfeet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Mens han ennu talte med dem, kom Rakel med sin fars småfe; for det var hun som gjætte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Og da Jakob så Rakel, sin morbror Labans datter, og så småfeet som hørte hans morbror til, gikk han frem og veltet stenen fra brønnens åpning og vannet sin morbror Labans småfe.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Og Jakob kysset Rakel og brast i gråt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Og Jakob fortalte Rakel at han var hennes fars frende, og at han var sønn til Rebekka; da sprang hun avsted og fortalte det til sin far.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Da nu Laban fikk høre om Jakob, sin søstersønn, løp han ham i møte og omfavnet ham og kysset ham og førte ham inn i sitt hus; og han fortalte Laban alt det som hadde hendt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Da sa Laban til ham: Sannelig, vi er av samme kjød og blod. Og han blev hos ham en måneds tid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Så sa Laban til Jakob: Skulde du tjene mig for intet, fordi om du er min frende? Si mig hvad du vil ha i lønn!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Nu hadde Laban to døtre, den eldste hette Lea, og den yngste hette Rakel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Lea hadde matte øine; men Rakel var vakker av skapning og vakker å se til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Og Jakob hadde Rakel kjær; derfor sa han: Jeg vil tjene dig syv år for Rakel, din yngste datter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laban svarte: Det er bedre at jeg gir henne til dig, enn at jeg gir henne til en annen mann; bli hos mig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Så tjente Jakob i syv år for Rakel; og disse år syntes han var nogen få dager, fordi han hadde henne kjær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Derefter sa Jakob til Laban: La mig nu få min hustru, for min tid er ute, og jeg vil gå inn til henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Da samlet Laban alle menn der på stedet og gjorde et gjestebud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Og om aftenen tok han sin datter Lea og førte henne inn til ham, og han gikk inn til henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Og Laban gav sin trælkvinne Silpa til sin datter Lea som trælkvinne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Men om morgenen - se, da var det Lea. Da sa han til Laban: Hvad er det du har gjort mot mig? Var det ikke for Rakel jeg tjente hos dig? Hvorfor har du sveket mig?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laban svarte: Det er ikke skikk her hos oss å gi den yngste bort før den eldste.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'La nu Leas bryllups-uke gå til ende, så vil vi også gi dig den andre, hvis du vil tjene hos mig i syv år til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Og Jakob gjorde så, og han lot bryllups-uken gå til ende. Da gav han ham sin datter Rakel til hustru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Og Laban gav sin trælkvinne Bilha til sin datter Rakel som trælkvinne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Så gikk han også inn til Rakel, og han holdt mere av Rakel enn av Lea. Siden tjente han ennu syv år til hos Laban.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Da Herren så at Lea blev tilsidesatt, åpnet han hennes morsliv; men Rakel var barnløs.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Og Lea blev fruktsommelig og fødte en sønn, og hun kalte ham Ruben; for hun sa: Herren har sett til mig i min ulykke; nu vil min mann elske mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Og hun blev atter fruktsommelig og fødte en sønn og sa: Herren har hørt at jeg var tilsidesatt; derfor har han gitt mig også denne sønn. Så kalte hun ham Simeon.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Og hun blev atter fruktsommelig og fødte en sønn og sa: Nu må vel endelig min mann holde sig til mig, for jeg har født ham tre sønner. Derfor kalte de ham Levi.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Og hun blev atter fruktsommelig og fødte en sønn og sa: Nu vil jeg prise Herren. Derfor kalte hun ham Juda. Så fikk hun ikke flere barn da.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Da Rakel så at hun og Jakob ikke fikk barn, blev hun misunnelig på sin søster og sa til Jakob: La mig få barn! Ellers dør jeg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Da optendtes Jakobs vrede mot Rakel, og han sa: Er jeg i Guds sted, som har nektet dig livsfrukt?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Da sa hun: Se, der er min trælkvinne Bilha; gå inn til henne, forat hun kan føde på mine knær, så også jeg kan få barn ved henne!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Så gav hun sin trælkvinne Bilha til hustru, og Jakob gikk inn til henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Og Bilha blev fruktsommelig og fødte Jakob en sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Da sa Rakel: Gud har dømt i min sak; han har hørt min bønn og gitt mig en sønn. Derfor kalte hun ham Dan.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Og Bilha, Rakels trælkvinne, blev atter fruktsommelig og fødte Jakob ennu en sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Da sa Rakel: Jeg har kjempet Guds kamper med min søster, og nu har jeg vunnet. Og hun kalte ham Naftali.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Da Lea så at hun ikke fikk flere barn, tok hun sin trælkvinne Silpa og gav Jakob til hustru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Og Silpa, Leas trælkvinne, fødte Jakob en sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Da sa Lea: Til lykke! Og hun kalte ham Gad.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Og Silpa, Leas trælkvinne, fødte Jakob ennu en sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Da sa Lea: Hvor lykkelig jeg er! For alle kvinner vil prise mig lykkelig. Og hun kalte ham Aser.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'En dag i hvetehøstens tid gikk Ruben ut og fant alruner på marken og bar dem hjem til Lea, sin mor; da sa Rakel til Lea: Kjære, gi mig nogen av din sønns alruner!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Men hun svarte henne: Er det ikke nok at du har tatt min mann? Vil du nu også ta min sønns alruner? Da sa Rakel: Nu vel, han kan sove hos dig inatt, hvis jeg får din sønns alruner!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Da Jakob om aftenen kom hjem fra marken, gikk Lea ham i møte og sa: Det er hos mig du skal være inatt; jeg har tinget dig for min sønns alruner. Så lå han hos henne den natt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Og Gud hørte Lea, og hun blev fruktsommelig og fødte Jakob en femte sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Da sa Lea: Gud har gitt mig min lønn, fordi jeg lot min mann få min trælkvinne. Og hun kalte ham Issakar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Og Lea blev atter fruktsommelig og fødte Jakob en sjette sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Da sa Lea: Gud har gitt mig en god gave; nu kommer min mann til å bo hos mig, for jeg har født ham seks sønner. Og hun kalte ham Sebulon.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Siden fødte hun en datter og kalte henne Dina.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Da kom Gud Rakel i hu, og Gud hørte henne og åpnet hennes morsliv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Hun blev fruktsommelig og fødte en sønn. Da sa hun: Gud har tatt bort min skam.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Og hun kalte ham Josef og sa: Herren gi mig ennu en sønn!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Da nu Rakel hadde født Josef, sa Jakob til Laban: La mig fare, så jeg kan dra hjem til mitt eget land!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Gi mig mine hustruer og mine barn, som jeg har tjent dig for, så vil jeg dra bort; du vet jo selv hvorledes jeg har tjent dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Da sa Laban til ham: Om du bare hadde nogen godhet for mig! Jeg er blitt varslet om at det er for din skyld Herren har velsignet mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Så sa han: Si selv hvad du vil ha i lønn, så skal jeg gi dig det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Og Jakob sa til ham: Du vet selv hvorledes jeg har tjent dig, og hvad din buskap er blitt til under mine hender.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'For det var lite det du hadde før jeg kom, men nu har det øket til en stor mengde, og Herren har velsignet dig hvor jeg satte min fot. Men når skal jeg nu også få gjøre noget for mitt eget hus?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Da sa Laban: Hvad skal jeg gi dig? Jakob svarte: Du skal ikke gi mig noget; dersom du vil gjøre som jeg nu sier, så skal jeg gjæte din buskap og vokte den, som jeg har gjort.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Jeg vil idag gå gjennem hele din hjord og skille ut alt som er flekket og spraglet og alt som er sort blandt fårene, og likeså alt som er spraglet og flekket blandt gjetene; og det skal være min lønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Og min ærlighet skal vidne for mig, når du siden engang kommer og ser over min lønn. Finnes det hos mig nogen gjet som ikke er flekket og spraglet, og noget får som ikke er sort, så er det stjålet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Da sa Laban: Vel, la det være som du har sagt!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Og samme dag skilte han ut de stripete og spraglete gjetebukker og alle flekkete og spraglete gjeter, alt det som hadde noget hvitt på sig, og alt sort blandt fårene; og han lot sine sønner ta vare på det,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'og han la tre dagsreiser mellem sig og Jakob. Og Jakob gjætte resten av Labans småfe.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Men Jakob tok sig friske kjepper av poppel-, hassel- og lønnetrær og skavde hvite striper på dem, så det hvite på kjeppene kom frem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Og han la kjeppene som han hadde skavd, i rennene - i vanntrauene, hvor småfeet kom for å drikke, like foran småfeet; for de parret sig når de kom for å drikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Så parret småfeet sig ved kjeppene og fikk stripete, flekkete og spraglete unger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Men lammene skilte Jakob ut og lot småfeet vende øinene mot det stripete og alt det sorte blandt Labans småfe; og således fikk han sig hjorder for sig selv og slapp dem ikke sammen med Labans småfe.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Og hver gang det sterke småfe parret sig, la Jakob kjeppene midt for øinene på dem i rennene, forat de skulde parre sig ved kjeppene;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'men når det var svakt småfe, la han ikke kjeppene der; således kom de svake til å tilhøre Laban og de sterke Jakob.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Og mannen blev rikere og rikere, og han fikk meget småfe og trælkvinner og træler og kameler og asener.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Så fikk han høre at Labans sønner hadde sagt: Jakob har tatt alt det som vår far eide, og av det som vår far eide, har han lagt sig til all denne rikdom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Og Jakob så på Labans ansikt at han ikke var den samme mot ham som før.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Og Herren sa til Jakob: Vend tilbake til dine fedres land og ditt eget folk, og jeg vil være med dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Da sendte Jakob bud efter Rakel og Lea og bad dem komme ut på marken, hvor han var med sin buskap.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Og han sa til dem: Jeg ser på eders fars ansikt at han ikke er den samme mot mig som før; men min fars Gud har vært med mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Og I vet selv at jeg av all min evne har tjent eders far.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Men eders far har sveket mig og forandret min lønn ti ganger; men Gud lot ham ikke få gjøre mig noget ondt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Når han sa: Det flekkete skal være din lønn, da fikk alt småfeet flekkete unger, og når han sa: Det stripete skal være din lønn, da fikk alt småfeet stripete unger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Således tok Gud eders fars fe fra ham og gav mig det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Og ved den tid småfeet parret sig, så jeg frem for mig i drømme og fikk se at bukkene som parret sig med småfeet, var stripete, flekkete og prikkete.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Og Guds engel sa til mig i drømmen: Jakob! Og jeg sa: Ja, her er jeg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Da sa han: Se nu frem for dig, så skal du få se at alle bukkene som parrer sig med småfeet, er stripete, flekkete og prikkete; for jeg har sett alt det Laban gjør mot dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Jeg er den Gud som du så i Betel, der hvor du salvet en minnesten, og hvor du gjorde mig et løfte; gjør dig nu rede og dra bort fra dette land, og vend tilbake til ditt fødeland.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Da svarte Rakel og Lea og sa til ham: Har vi vel ennu nogen lodd og arv i vår fars hus?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Har han ikke aktet oss som fremmede? Han har jo solgt oss og selv fortært det han fikk for oss.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'All den rikdom Gud har tatt fra vår far, den hører oss og våre barn til; gjør nu bare du alt det Gud har sagt til dig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Så gjorde Jakob sig ferdig og satte sine barn og hustruer på kamelene,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'og han tok med sig hele sin buskap og alt det gods som han hadde samlet sig, det fe han eide, og som han hadde lagt sig til i Mesopotamia, og vilde dra til Isak, sin far, i Kana\'ans land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Men Laban hadde draget bort for å klippe sine får; da stjal Rakel sin fars husguder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Og Jakob stjal sig bort fra arameeren Laban; han sa ikke noget til ham om at han vilde flykte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Så flyktet han med alt det han hadde; han gjorde sig ferdig og satte over elven og tok veien til Gileadfjellet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Den tredje dag efter fikk Laban vite at Jakob var flyktet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Da tok han med sig sine frender og satte efter ham syv dagsreiser, og nådde ham igjen på Gilead-fjellet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Men Gud kom til arameeren Laban i en drøm om natten og sa til ham: Vokt dig og si ikke noget til Jakob, hverken godt eller ondt!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Da Laban nådde Jakob igjen, hadde Jakob slått op sitt telt på fjellet, og Laban med sine frender slo også op sitt telt på Gilead-fjellet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Da sa Laban til Jakob: Hvad er det du har gjort? Du har stjålet dig bort fra mig og ført mine døtre avsted som om de var tatt i krig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Hvorfor flyktet du hemmelig og stjal dig bort fra mig og sa ikke noget om det til mig, så jeg kunde ha fulgt dig på veien med gledesrop og sanger, med trommer og harper?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Du lot mig ikke engang få kysse mine sønner og døtre; det var uforstandig gjort av dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Jeg har det i min makt å gjøre ondt mot eder; men eders fars Gud sa til mig inatt: Vokt dig og si ikke noget til Jakob, hverken godt eller ondt!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Men når du nu har draget bort, fordi du lengtes så såre efter din fars hus, hvorfor stjal du da mine guder?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Da svarte Jakob og sa til Laban: Jeg var redd; jeg tenkte at du kunde ta dine døtre fra mig med makt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Men den som du finner dine guder hos, han skal ikke leve. Se nu efter i våre frenders nærvær, om du kjennes ved noget av det jeg har med mig, og ta det så! Men Jakob visste ikke at Rakel hadde stjålet dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Da gikk Laban inn i Jakobs telt og i Leas telt og i begge trælkvinnenes telt, men fant ikke noget. Så gikk han ut av Leas telt og inn i Rakels telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Men Rakel hadde tatt husgudene og lagt dem i kamelsalen og satt sig på dem; og Laban gjennemsøkte hele teltet, men fant ikke noget.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Og hun sa til sin far: Min herre må ikke bli vred fordi jeg ikke kan reise mig for dig; for det går mig på kvinners vis. Så lette han efter husgudene, men fant dem ikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Da blev Jakob vred og gikk i rette med Laban. Og Jakob tok til orde og sa til Laban: Hvad er min brøde, hvad er min synd, siden du forfølger mig så?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Du har nu gjennemsøkt alt det jeg har; hvad fant du da som hører ditt hus til? Legg det frem her for mine og dine frender, så de kan dømme mellem oss to!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Nu har jeg vært hos dig i tyve år; dine får og dine gjeter har ikke født i utide, og værene av ditt småfe har jeg ikke ett op;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'det som var sønderrevet, kom jeg ikke hjem til dig med; jeg godtgjorde selv skaden; av mig krevde du det, enten det var stjålet om dagen, eller det var stjålet om natten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Slik hadde jeg det: Om dagen fortærtes jeg av hete og av kulde om natten, og søvnen flydde fra mine øine.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'I tyve år har jeg nu vært i ditt hus, jeg har tjent dig fjorten år for dine to døtre og seks år for ditt småfe; men du forandret min lønn ti ganger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Hadde ikke min fars Gud vært med mig, han som var Abrahams Gud, og som også Isak frykter, sannelig, du hadde nu latt mig fare med tomme hender. Men Gud har sett min møie og alt mitt strev, og han har dømt inatt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Da svarte Laban og sa til Jakob: Døtrene er mine døtre, og barna er mine barn, og buskapen er min buskap, og alt det du ser, er mitt; hvad skulde jeg da nu kunne gjøre mot disse mine døtre eller mot deres barn, som de har født?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Så kom nu og la oss gjøre en pakt, jeg og du, og den skal være et vidne mellem mig og dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Da tok Jakob en sten og reiste den op som en minnesten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Og Jakob sa til sine frender: Sank sammen stener! Og de tok stener og laget en røs; og de holdt måltid der ved stenrøsen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Og Laban kalte den Jegar-Sahaduta, men Jakob kalte den Gal-Ed.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Da sa Laban: Denne røs skal være et vidne mellem mig og dig idag. Derfor kalte de den Gal-Ed,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'og tillike Mispa, fordi han sa: Herren holde vakt mellem mig og dig, når vi kommer hverandre av syne;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'dersom du farer ille med mine døtre eller tar dig andre hustruer foruten mine døtre, da er det vel intet menneske hos oss, men se, Gud er vidne mellem mig og dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Så sa Laban til Jakob: Se, denne røs og denne minnesten som jeg har reist mellem mig og dig -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'vidner skal de være, både røsen og minnestenen, at ikke skal jeg dra til dig forbi denne røs, og at heller ikke skal du dra til mig forbi denne røs og denne minnesten med ondt i sinne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Abrahams Gud og Nakors Gud skal dømme mellem oss, han som var deres fars Gud. Så svor Jakob ved ham som hans far Isak fryktet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Og Jakob ofret et slaktoffer på fjellet og innbød sine frender til måltid. Og de holdt måltid og blev natten over på fjellet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Morgenen efter stod Laban tidlig op, og han kysset sine sønner og sine døtre og velsignet dem. Så drog Laban hjem igjen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Og Jakob drog videre, og Guds engler møtte ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Da Jakob så dem, sa han: Dette er Guds leir. Og han kalte stedet Mahana\'im.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Og Jakob sendte bud foran sig til sin bror Esau i landet Se\'ir, på Edoms mark.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Og han bød dem og sa: Således skal I si til min herre Esau: Så sier din tjener Jakob: Jeg har opholdt mig hos Laban og vært der helt til nu,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'og jeg har fått okser og asener, småfe og træler og trælkvinner; og nu vilde jeg sende bud til min herre om dette for å finne nåde for dine øine');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Og budene kom tilbake til Jakob og sa: Vi kom til Esau, din bror, og han drar dig nu selv i møte, og fire hundre mann med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Da blev Jakob overmåte forferdet; og han delte folket som var med ham, og småfeet og storfeet og kamelene i to leire.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'For han tenkte: Om Esau kommer til den ene leir og slår den, da kan den leir som er igjen, få berge sig unda.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Og Jakob sa: Min far Abrahams Gud og min far Isaks Gud, Herre, du som sa til mig: Dra tilbake til ditt land og til ditt folk, og jeg vil gjøre vel imot dig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Jeg er ringere enn all den miskunnhet og all den trofasthet som du har vist mot din tjener; for med min stav gikk jeg over Jordan her, og nu er jeg blitt til to leire.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Fri mig ut av Esaus, min brors hånd; for jeg er redd han skal komme og slå ihjel mig og mine, både mor og barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Du har jo selv sagt: Jeg vil alltid gjøre vel mot dig og la din ætt bli som havets sand, som ikke kan telles for mengde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Så blev han der den natt, og av alt det han eide, tok han ut en gave til Esau, sin bror:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'to hundre gjeter og tyve bukker, to hundre får og tyve værer,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'tretti kameler som gav die, med sine føll, firti kjør og ti okser, tyve aseninner og ti asenfoler.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Og han lot sine tjenere dra avsted med dem, hver hjord for sig, og han sa til sine tjenere: Far i forveien, og la det være et mellemrum mellem hver hjord!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Og han bød den første og sa: Når min bror Esau møter dig og han taler til dig og spør: Hvem hører du til, og hvor skal du hen, og hvem eier denne hjord som du driver foran dig?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'da skal du si: Din tjener Jakob; det er en gave han sender til min herre Esau, og snart kommer han selv efter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Og han bød likeledes den annen og den tredje og alle de andre som drev hjordene, og sa: Således skal I tale til Esau når I møter ham,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'I skal si: Snart kommer din tjener Jakob selv efter. For han tenkte: Jeg vil forsone ham ved den gave som jeg sender foran mig, og siden vil jeg selv trede frem for ham; kanskje han vil ta nådig imot mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Så drog de i forveien med gaven; men selv blev han i leiren den natt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'samme natt stod han op og tok sine hustruer og de to trælkvinner og sine elleve sønner og gikk over Jabboks vadested.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Han tok og satte dem over åen og førte over alt det han eide.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Så var Jakob alene tilbake. Da kom det en mann og kjempet med ham inntil morgenen grydde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Og da mannen så at han ikke kunde rå med ham, rørte han ved hans hofteskål; og Jakobs hofteskål gikk av ledd, mens han kjempet med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Og han sa: Slipp mig, for morgenen gryr! Men han sa: Jeg slipper dig ikke, uten du velsigner mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Da sa han til ham: Hvad er ditt navn? Han svarte: Jakob.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Han sa: Du skal ikke lenger hete Jakob, men Israel; for du har kjempet med Gud og med mennesker og vunnet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Da spurte Jakob: Si mig ditt navn! Han svarte: Hvorfor spør du om mitt navn? Og han velsignet ham der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Og Jakob kalte stedet Pniel; for sa han jeg har sett Gud åsyn til åsyn og enda berget livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Og da han var kommet forbi Pnuel så han solen rinne; og han haltet på sin hofte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Derfor er det så den dag idag at Israels barn aldrig eter spennesenen som er på hofteskålen, fordi han rørte ved Jakobs hofteskål på spennesenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Da Jakob så op, fikk han se Esau som kom med fire hundre mann. Da delte han barna mellem Lea og Rakel og begge trælkvinnene,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'og han satte trælkvinnene med sine barn fremst og Lea med sine barn bakenfor dem og Rakel med Josef bakerst.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Og selv gikk han foran dem og bøide sig syv ganger til jorden, inntil han kom frem til sin bror.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Men Esau løp ham i møte og omfavnet ham og falt ham om halsen og kysset ham, og de gråt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Da han så op, fikk han øie på kvinnene og barna; da sa han: Hvem er det du har der? Han svarte: Det er de barn som Gud har unt din tjener.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Så gikk trælkvinnene frem med sine barn og bøide sig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'og Lea gikk også frem med sine barn, og de bøide sig, og derefter gikk Josef og Rakel frem og bøide sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Da sa han: Hvad vilde du med hele den leir som jeg møtte? Han svarte: Jeg vilde finne nåde for min herres øine.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Da sa Esau: Jeg har nok; ha du selv, min bror, det som ditt er!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Jakob svarte: Nei, kjære! Dersom jeg har funnet nåde for dine øine, så ta imot min gave! For da jeg så ditt ansikt, var det som om jeg så Guds ansikt, siden du var så vennlig mot mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Kjære, ta imot gaven som jeg sendte dig! For Gud har vært mig nådig, og jeg har nok av alle ting. Og han nødde ham til han tok imot det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Da sa Esau: La oss bryte op og dra videre, og la mig dra side om side med dig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Men han svarte ham: Min herre vet at barna er svake, og småfeet og storfeet har nylig båret hos mig; og driver en dem bare en eneste dag for sterkt, så dør alt småfeet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Vil ikke min herre dra foran. sin tjener, så vil jeg dra langsomt efter, som det kan passe for buskapen som drives foran mig, og for barna, inntil jeg kommer til min herre i Se\'ir.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Da sa Esau: Så vil jeg få lov til å la nogen av de folk jeg har med, bli hos dig. Men han svarte: Hvorfor det? La mig bare finne nåde for min herres øine!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Så drog Esau samme dag sin vei tilbake til Se\'ir');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Og Jakob drog til Sukkot og bygget sig et hus og gjorde løvhytter til sin buskap; derfor kalte de stedet Sukkot.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Og Jakob kom lykkelig frem til byen Sikem, som ligger i Kana\'ans land, da han kom fra Mesopotamia; og han slo leir utenfor byen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Og det stykke mark hvor han hadde slått op sitt telt, kjøpte han av sønnene til Hemor, Sikems far, for hundre kesitter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Der reiste han et alter og kalte det El Elohe Israel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Dina, Jakobs datter med Lea, gikk engang ut for å se på landets døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Og Sikem, som var sønn av hevitten Hemor, høvdingen i landet, så henne; og han tok henne og lå hos henne og krenket henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Men hans hjerte hang ved Dina, Jakobs datter, og han elsket piken og talte kjærlig til henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Så sa Sikem til Hemor, sin far: La mig få denne pike til hustru!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Og Jakob fikk høre at han hadde vanæret Dina, hans datter; men hans sønner var med buskapen ute på marken, og Jakob tidde med det til de kom hjem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Men Hemor, Sikems far, gikk ut til Jakob for å tale med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Jakobs sønner kom hjem fra marken da de fikk høre om dette; og mennene gremmet sig og var harmfulle; for han hadde gjort en skammelig gjerning mot Israel ved å ligge hos Jakobs datter. Slikt burde ikke skje.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Da talte Hemor med dem og sa: Min sønn Sikems hjerte henger ved eders datter; kjære, la ham få henne til hustru,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'og inngå svogerskap med oss, gi oss eders døtre og ta I våre døtre!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Bli boende hos oss! Landet skal stå åpent for eder; bo her og dra omkring og få eder eiendommer her!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Og Sikem sa til hennes far og hennes brødre: La mig finne nåde for eders øine! Det I krever av mig, vil jeg gi eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Krev så meget I vil av mig i morgengave og andre gaver! Jeg skal gi det I vil ha; la mig bare få piken til hustru!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Da svarte Jakobs sønner Sikem og Hemor, hans far, med svikefulle ord, fordi han hadde vanæret deres søster Dina,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'og sa til dem: Det kan vi ikke gjøre, å gi vår søster til en mann som har forhud; det vilde være en skam for oss.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Bare på det vilkår vil vi være eder til vilje, at I blir som vi, og alt mannkjønn hos eder lar sig omskjære.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Da vil vi gi eder våre døtre og gifte oss med eders døtre og bo hos eder, så vi blir ett folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Men dersom I ikke vil høre på oss og la eder omskjære, da tar vi vår søster og drar bort.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Og de syntes godt om deres ord, både Hemor og Sikem, Hemors sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Og den unge mann drygde ikke med å gjøre dette, for han var glad i Jakobs datter, og han var den som hadde mest å si i sin fars hus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Så gikk Hemor og hans sønn Sikem til porten i sin by, og de talte til mennene i byen og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Disse menn vil gjerne være venner med oss og vil bo her i landet og dra omkring her, og landet er jo vidt nok for dem; vi vil gifte oss med deres døtre og gi dem våre døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Men bare på det vilkår vil mennene være oss til vilje og bo hos oss og bli til ett folk med oss, at alt mannkjønn iblandt oss lar sig omskjære, likesom de selv er omskåret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Deres buskap og deres gods og alle deres kløvdyr, blir ikke alt det vårt når vi bare er dem til vilje, så de blir boende hos oss?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Og de gjorde som Hemor og hans sønn Sikem vilde, alle som hørte hjemme i hans by; og alt mannkjønn, alle som hørte hjemme i hans by, blev omskåret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Men på den tredje dag, da de var syke av sine sår, da tok Jakobs to sønner, Simeon og Levi, Dinas brødre, hver sitt sverd, og de kom uforvarende over byen og slo alt mannkjønn ihjel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Også Hemor og Sikem, hans sønn, slo de ihjel med sverdets egg, og de tok Dina ut av Sikems hus og drog bort.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Jakobs sønner kom over de drepte og plyndret byen, fordi deres søster var blitt vanæret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'De tok deres småfe og storfe og deres asener, både det som var i byen, og det som var på marken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Og alt deres gods og alle deres barn og deres kvinner førte de bort som bytte, og alt annet som var i husene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Da sa Jakob til Simeon og Levi: I har gjort mig en stor sorg! I har ført mig i vanrykte hos landets innbyggere, Kana\'anittene og ferisittene; jeg råder jo bare over en liten flokk, og samler de sig imot mig, kommer de til å slå mig ihjel, sa både jeg og mitt hus går til grunne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Men de svarte: Skulde han da få gjøre med vår søster som med en skjøge?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Og Gud sa til Jakob: Gjør dig rede, dra op til Betel og bli der, og bygg der et alter for den Gud som åpenbarte sig for dig da du flyktet for din bror Esau!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Da sa Jakob til sine husfolk og alle dem som var med ham: Ha bort de fremmede guder som finnes hos eder, og rens eder og skift klær,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'og la oss ta avsted og dra op til Betel; der vil jeg bygge et alter for den Gud som bønnhørte mig den dag jeg var i fare, og som var med mig på min ferd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Da lot de Jakob få alle de fremmede guder som de hadde hos sig, og ringene som de hadde i sine ører; og Jakob gravde dem ned under terebinten ved Sikem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Så brøt de op, og en redsel fra Gud kom over byene rundt omkring dem, så de ikke forfulgte Jakobs sønner.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Og Jakob kom til Luz, som ligger i Kana\'ans land - nu heter det Betel - han og alt det folk som var med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Og han bygget der et alter og kalte stedet El-Betel; for der hadde Gud åpenbaret sig for ham da han flyktet for sin bror.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Da døde Debora, Rebekkas fostermor, og hun blev begravet nedenfor Betel under eken; og han kalte den gråts - eken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Og Gud åpenbarte sig atter for Jakob, da han kom fra Mesopotamia, og velsignet ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Og Gud sa til ham: Du heter Jakob; herefter skal du ikke mere hete Jakob, men Israel skal være ditt navn. Således fikk han navnet Israel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Og Gud sa til ham: Jeg er Gud den allmektige; vær fruktbar og bli tallrik! Et folk, ja en mengde med folkeslag skal stamme fra dig, og konger skal utgå av dine lender.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Og det land som jeg gav Abraham og Isak, det vil jeg gi dig; og din ætt efter dig vil jeg gi landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Så fór Gud op fra ham på det sted hvor han hadde talt med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Og Jakob reiste op en minnestøtte på det sted hvor han hadde talt med ham, en minnestøtte av sten; og han øste drikkoffer på den og helte olje over den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Og Jakob kalte det sted hvor Gud hadde talt med ham, Betel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Så brøt de op fra Betel, og da det ennu var et stykke vei igjen til Efrat, fødte Rakel, og hun hadde en hård fødsel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Og under hennes hårde fødsel sa jordmoren til henne: Frykt ikke; for også denne gang får du en sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Men i det samme hun opgav ånden - for hun måtte dø - kalte hun ham Benoni; men hans far kalte ham Benjamin.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Så døde Rakel, og hun blev begravet på veien til Efrat, det er Betlehem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Og Jakob reiste op en minnesten på hennes grav; det er Rakels gravsten; den står der den dag idag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Så brøt Israel op igjen og slo op sitt telt bortenfor Migdal-Eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Og mens Israel bodde der i landet, hendte det at Ruben gikk avsted og lå hos Bilha, sin fars medhustru; og Israel fikk høre om det - Jakob hadde tolv sønner.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Leas sønner var: Ruben, Jakobs førstefødte, og Simeon og Levi og Juda og Issakar og Sebulon.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Rakels sønner var: Josef og Benjamin.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Og Rakels trælkvinne Bilhas sønner var: Dan og Naftali.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Og Leas trælkvinne Silpas sønner var: Gad og Aser. Dette var Jakobs sønner, som han fikk i Mesopotamia.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Og Jakob kom til sin far Isak i Mamre ved Kirjat-Arba, det er Hebron, hvor Abraham og Isak hadde bodd som fremmede.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Og Isaks dager blev hundre og åtti år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Da opgav Isak ånden og døde og blev samlet til sine fedre, gammel og mett av dager; og Esau og Jakob, hans sønner, begravde ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Dette er Esaus eller Edoms ætt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau tok sig hustruer av Kana\'ans døtre: Ada, hetitten Elons datter, og Oholibama, Anas datter, hevitten Sibeons sønnedatter,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'og Basmat, Ismaels datter, Nebajots søster.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Med Ada fikk Esau Elifas, og med Basmat Re\'uel,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'og med Oholibama fikk han Je\'us og Jalam og Korah; dette var Esaus sønner, som han fikk i Kana\'ans land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Og Esau tok sine hustruer, sine sønner og døtre og alt sitt husfolk og sin buskap og alle sine kløvdyr og alt sitt gods som han hadde samlet i Kana\'ans land, og drog til et annet land for sin bror Jakobs skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'For deres eiendom var for stor til at de kunde bo sammen - det land som de bodde i som fremmede, kunde ikke rumme dem, så stor buskap hadde de.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Så bosatte Esau sig i Se\'ir-fjellene - Esau, det er den samme som Edom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Og dette er Esaus ætt i Se\'irfjellene, han som var stamfar til edomittene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Dette er navnene på Esaus sønner: Elifas, sønn av Esaus hustru Ada, og Re\'uel, sønn av Esaus hustru Basmat.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Og Elifas\' sønner var Teman, Omar, Sefo, Gatam og Kenas.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Og Elifas, Esaus sønn, hadde en medhustru som hette Timna, og med henne fikk Elifas Amalek. Dette var Esaus hustru Adas sønner.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Og dette var Re\'uels sønner: Nahat og Serah, Samma og Missa. Dette var Esaus hustru Basmats sønner.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Og dette var sønnene til Oholibama, Anas datter, Sibeons sønnedatter, Esaus hustru: Med henne fikk Esau Je\'us og Jalam og Korah.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Dette var stammefyrstene for Esaus barn: Sønnene til Esaus eldste sønn Elifas var stammefyrsten Teman, stammefyrsten Omar, stammefyrsten Sefo, stammefyrsten Kenas,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'stammefyrsten Korah, stammefyrsten Gatam, stammefyrsten Amalek; dette var de stammefyrster som nedstammet fra Elifas i Edom-landet. Dette var Adas sønner.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Og dette var sønnene til Esaus sønn Re\'uel: stammefyrsten Nahat, stammefyrsten Serah, stammefyrsten Samma, stammefyrsten Missa, dette var de stammefyrster som nedstammet fra Re\'uel i Edom-landet. Dette var Esaus hustru Basmats sønner.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Og dette var Esaus hustru Oholibamas sønner: stammefyrsten Je\'usj stammefyrsten Jalam, stammefyrsten Korah; dette var de stammefyrster som nedstammet fra Oholibama, Anas datter, Esaus hustru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Dette var Esaus sønner, og dette deres stammefyrster. Dette var Edom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Dette var horitten Se\'irs sønner, som bodde i landet: Lotan og Sobal og Sibeon og Ana');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'og Dison og Eser og Disan; dette var horittenes stammefyrster, Se\'irs sønner i Edom-landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Og Lotans sønner var Hori og Hemam, og Lotans søster var Timna.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Og dette var Sobals sønner: Alvan og Manahat og Ebal, Sefo og Onam.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Og dette var Sibeons sønner: Aja og Ana; det var den Ana som fant de varme kilder i ørkenen, mens han gjætte sin far Sibeons asener.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Og dette var Anas barn: Dison og datteren Oholibama.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Og dette var Disons sønner: Hemdan og Esban og Jitran og Keran.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Dette var Esers sønner: Bilhan og Sa\'avan og Akan.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Dette var Disans sønner: Us og Aran.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Dette var horittenes stammefyrster: stammefyrsten Lotan, stammefyrsten Sobal, stammefyrsten Sibeon, stammefyrsten Ana,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'stammefyrsten Dison, stammefyrsten Eser, stammefyrsten Disan; dette var horittenes stammefyrster, deres stammefyrster i Se\'ir-landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Og dette var de konger som regjerte i Edom-landet før det regjerte nogen konge over Israels barn:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela, Beors sønn, var konge i Edom, og hans by hette Dinhaba.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Da Bela døde, blev Jobab, Serahs sønn, fra Bosra konge i hans sted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Da Jobab døde, blev Husam fra temanittenes land konge i hans sted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Da Husam døde, blev Hadad, Bedads sønn, konge i hans sted; det var han som slo midianittene på Moabs mark; hans by hette Avit.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Da Hadad døde, blev Samla fra Masreka konge i hans sted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Da Samla døde, blev Saul fra Rehobot ved elven konge i hans sted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Da Saul døde, blev Ba\'al-Hanan, Akbors sønn, konge i hans sted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Da Ba\'al-Hanan, Akbors sønn, døde, blev Hadar konge i hans sted; hans by hette Pa\'u, og hans hustru hette Mehetabel, en datter av Matred, Mesahabs datter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Og dette er navnene på Esaus stammefyrster efter deres ætter, efter deres bosteder, med deres navn: stammefyrsten Timna, stammefyrsten Alva, stammefyrsten Jetet,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'stammefyrsten Oholibama, stammefyrsten Ela, stammefyrsten Pinon,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'stammefyrsten Kenas, stammefyrsten Teman, stammefyrsten Mibsar,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'stammefyrsten Magdiel, stammefyrsten Iram; dette var Edoms stammefyrster efter sine bosteder i sitt eiendomsland. Dette var Esaus, edomittenes fars ætt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Men Jakob bodde i det land hvor hans far hadde bodd som fremmed, i Kana\'ans land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Dette er historien om Jakobs ætt. Da Josef var sytten år gammel, gjætte han buskapen sammen med sine brødre; ung som han var, fulgte han med sønnene til Bilha og Silpa, sin fars hustruer; alt det onde som blev sagt om dem, gikk han til deres far med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Men Israel hadde Josef kjær fremfor alle sine sønner, fordi han var hans alderdoms sønn; og han hadde latt gjøre en sid kjortel til ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Og da hans brødre så at deres far hadde ham mere kjær enn alle hans brødre, hatet de ham og kunde ikke tale vennlig til ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Engang hadde Josef en drøm, som han fortalte sine brødre; da hatet de ham enda mere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Han sa til dem: Hør nu hvad jeg har drømt:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Jeg syntes vi bandt kornbånd ute på akeren, og se, mitt kornbånd reiste sig op og blev stående, og eders kornbånd stod rundt omkring og bøide sig for mitt kornbånd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Da sa hans brødre til ham: Skal du kanskje være vår konge og råde over oss? Siden hatet de ham enda mere for hans drømmer og for hans ord.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Og han hadde ennu en annen drøm og fortalte den til sine brødre; han sa: Jeg hadde ennu en drøm, og se, solen og månen og elleve stjerner bøide sig for mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Og da han fortalte det til sin far og til sine brødre, skjente hans far på ham og sa til ham: Hvad er dette for en drøm du har hatt? Skal da jeg og din mor og dine brødre komme og bøie oss til jorden for dig?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Og hans brødre var misunnelige på ham; men hans far gjemte det i sitt minne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Engang gikk hans brødre avsted for å gjæte sin fars buskap i Sikem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Da sa Israel til Josef: Gjæter ikke dine brødre ved Sikem? Kom, jeg vil sende dig til dem. Og han svarte: Ja, her er jeg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Da sa han til ham: Kjære, gå og se om det står vel til med dine brødre, og om det står vel til med buskapen, og kom så tilbake til mig med svar! Så sendte han ham avsted fra Hebron-dalen, og han kom til Sikem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Mens han nu vanket om på marken, møtte han en mann, og mannen spurte ham: Hvad leter du efter?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Han svarte: Jeg leter efter mine brødre; kjære, si mig hvor de gjæter!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Mannen sa: De har draget herfra; jeg hørte dem si: La oss gå til Dotan! Så gikk Josef efter sine brødre og fant dem i Dotan.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'De så ham langt borte, og før han kom nær til dem, la de op råd om å drepe ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'De sa sig imellem: Se, der kommer denne drømmeren!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Kom nu og la oss slå ham ihjel og kaste ham ned i en av brønnene her, og så vil vi si: Et vilt dyr har ett ham op. Så får vi se hvad det blir av hans drømmer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Da Ruben hørte dette, vilde han fri ham ut av deres hender og sa: La oss ikke slå ham ihjel!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Og han sa til dem: Utøs ikke blod, kast ham ned i denne brønn her i ørkenen, men legg ikke hånd på ham - for han vilde fri ham ut av deres hånd og føre ham tilbake til hans far.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Da nu Josef kom til sine brødre, klædde de av ham hans kjortel, den side kjortel som han hadde på.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Og de tok og kastet ham ned i brønnen; men brønnen var tom, det var intet vann i den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Så satte de sig til å holde måltid; og da de så op, fikk de se et reisefølge av ismaelitter som kom fra Gilead, og deres kameler bar krydderier og balsam og ladanum; de var på vei med dette ned til Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Da sa Juda til sine brødre: Hvad gagner det at vi slår var bror ihjel og skjuler drapet?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Kom og la oss selge ham til ismaelittene, men la oss ikke legge hånd på ham, han er jo vår egen kjødelige bror. Og hans brødre gjorde som han sa.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Da nu de midianittiske kjøbmenn kom forbi, drog de Josef op av brønnen, og så solgte de Josef til ismaelittene for tyve sekel sølv; og ismaelittene tok Josef med sig til Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Da Ruben kom tilbake til brønnen, fikk han se at Josef ikke var i brønnen. Da sønderrev han sine klær,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'og han gikk tilbake til sine brødre og sa: Gutten er der ikke, og jeg - hvor skal jeg gjøre av mig?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Så tok de Josefs kjortel og slaktet en gjetebukk og dyppet kjortelen i blodet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Og de sendte den side kjortel hjem til faren og sa: Denne har vi funnet; se efter om det ikke er din sønns kjortel!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Og han kjente den igjen og sa: Jo, det er min sønns kjortel; et vilt dyr har ett ham op, Josef er visselig revet ihjel!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Og Jakob sønderrev sine klær og bandt sekk om sine lender og sørget over sin sønn i lang tid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Og alle hans sønner og alle hans døtre kom for å trøste ham; men han vilde ikke la sig trøste; han sa: Med sorg må jeg fare ned til min sønn i dødsriket. Og hans far gråt over ham..');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Men midianittene solgte ham i Egypten til Potifar, som var hoffmann hos Farao og høvding over livvakten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'På denne tid drog Juda ned fra det sted hvor hans brødre bodde, og han tok inn til en mann i Adullam, som hette Hira.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Der så Juda datteren til en kana\'anittisk mann som hette Sua; og han tok henne til hustru og gikk inn til henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Og hun blev fruktsommelig og fødte en sønn og kalte ham Er.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Så blev hun atter fruktsommelig og fødte en sønn, og hun kalte ham Onan.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Siden fødte hun ennu en sønn og kalte ham Sela; da han blev født, var Juda i Kesib.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Og Juda tok en hustru til Er, sin førstefødte sønn; hun hette Tamar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Men Er, Judas førstefødte, mishaget Herren, og Herren lot ham dø.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Da sa Juda til Onan: Gå inn til din brors hustru, og ta henne til ekte i din brors sted og opreis din bror avkom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Men Onan visste at avkommet ikke skulde høre ham til; når han derfor gikk inn til sin brors hustru, spilte han sæden på jorden for ikke å gi sin bror avkom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Men det var ondt i Herrens øine det han gjorde, og han lot også ham dø.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Da sa Juda til Tamar, sin sønnekone: Bo som enke i din fars hus, til Sela, min sønn, er blitt voksen! For han tenkte: Ellers kommer også han til å dø, som hans brødre. Så drog Tamar hjem og bodde i sin fars hus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Da nu en lengere tid var gått, døde Suas datter, Judas hustru, og da sørgetiden var over, gikk Juda op til Timna, til dem som klippet hans får, og hans venn Hira fra Adullam var med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Da det nu blev fortalt Tamar at hennes svigerfar var på vei op til Timna for å klippe sine får,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'tok hun sine enkeklær av og la et slør om sig og hyllet sig inn i det og satte sig ved inngangen til Ena\'im, på veien til Timna; for hun så at Sela var blitt voksen, og at hun allikevel ikke var gitt ham til hustru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Da Juda så henne, tenkte han det var en skjøge; for hun hadde tilhyllet sitt ansikt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Så bøide han av fra veien og gikk bort til henne og sa: Kom, la mig gå inn til dig! For han visste ikke at det var hans sønnekone. Da sa hun: Hvad vil du gi mig for å gå inn til mig?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Han svarte: Jeg vil sende dig et kje av min buskap. Da sa hun: Ja, dersom du vil gi mig et pant, til du sender mig det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Han sa: Hvad skal jeg gi dig til pant? Hun svarte: Ditt signet og din snor og staven som du har i hånden. Det gav han henne og gikk så inn til henne, og hun blev fruktsommelig med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Og hun stod op og gikk sin vei, og hun la sitt slør av sig og tok på sig sine enkeklær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Og Juda sendte kjeet med sin venn fra Adullam for å få pantet tilbake av kvinnen; men han fant henne ikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Og han spurte folkene der på stedet og sa: Hvor er skjøgen, hun i Ena\'im, ved veien? De sa: Det har ikke vært nogen skjøge her.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Så kom han tilbake til Juda og sa: Jeg fant henne ikke, og tilmed sa folkene der på stedet: Det har ikke vært nogen skjøge her.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Da sa Juda: La henne ha det, så vi ikke skal få skam av denne sak! Kjeet har jeg jo sendt henne, men du fant henne ikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Så gikk det omkring tre måneder; da kom folk og sa til Juda: Tamar, din sønnekone, har drevet hor, og nu er hun også blitt fruktsommelig i hor. Og Juda sa: Før henne ut, hun skal brennes!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Men da hun blev ført ut, sendte hun bud til sin svigerfar og lot si: Det er med den mann som eier disse ting, jeg er blitt fruktsommelig. Og hun sa: Se efter hvem som eier dette signet og disse snorer og denne stav!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Og Juda kjente dem igjen og sa: Hun er i sin gode rett mot mig fordi jeg ikke har gitt henne til min sønn Sela. Og han hadde ikke siden omgang med henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Da den tid kom at hun skulde føde, se, da var det tvillinger i hennes liv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Og i det samme hun fødte, stakk den ene hånden frem; da tok jordmoren og bandt en rød tråd om hans hånd og sa: Denne kom først frem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Men så drog han sin hånd tilbake, og da kom hans bror frem, og hun sa: Hvor du har brutt dig frem! Og de kalte ham Peres.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Så kom hans bror frem, han som hadde den røde tråd om hånden; ham kalte de Serah.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Josef blev ført ned til Egypten; og Potifar, en egypter, som var hoffmann hos Farao og høvding over livvakten, kjøpte ham av ismaelittene som hadde hatt ham med sig dit.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Men Herren var med Josef, så alt lyktes for ham; og han vedblev å være i huset hos sin herre egypteren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Da hans herre så at Herren var med ham, og at Herren lot alt det han gjorde, lykkes for ham,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'fant Josef nåde for hans øine og fikk gå ham til hånde; og han satte ham over sitt hus, og alt det han hadde, la han i hans hender.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Og helt fra den tid han hadde satt ham over sitt hus og over alt det han hadde, velsignet Herren egypterens hus for Josefs skyld, og Herrens velsignelse var over alt det han hadde, både i huset og på marken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Og han overlot alt det han hadde, i Josefs hender, og han så ikke til med ham i noget, uten med den mat han selv åt. Og Josef var vakker av skapning og vakker å se til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Og nogen tid efter hendte det at hans herres hustru kastet sine øine på Josef og sa: Kom og ligg hos mig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Men han vilde ikke og sa til sin herres hustru: Min herre ser ikke til med mig i nogen ting i hele sitt hus, og alt det han eier, har han lagt i mine hender;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'han har ikke mere å si her i huset enn jeg, og han har ikke nektet mig noget uten dig, fordi du er hans hustru. Hvorledes skulde jeg da gjøre denne store ondskap og synde mot Gud?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Som hun nu dag efter dag talte til Josef, og han ikke føide henne i å ligge hos henne og være sammen med henne,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'så hendte det en dag at han kom inn i huset for å gjøre sitt arbeid, mens ingen av husets folk var inne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Da grep hun fatt i hans kappe og sa: Ligg hos mig! Men han lot sin kappe efter sig i hennes hånd og flyktet ut av huset.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Og da hun så at han hadde latt sin kappe efter sig i hennes hånd og var flyktet ut av huset,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'ropte hun på sine husfolk og sa til dem: Se, her har han ført en hebraisk mann hit til oss for å føre skam over oss; han kom inn til mig for å ligge hos mig, men jeg ropte så høit jeg kunde,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'og da han hørte at jeg satte i å rope, lot han sin kappe efter sig hos mig og flyktet ut av huset.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Så lot hun hans kappe bli liggende hos sig til hans herre kom hjem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Da talte hun likedan til ham og sa: Den hebraiske træl som du har ført hit til oss, kom inn til mig for å føre skam over mig;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'men da jeg satte i å rope, lot han sin kappe efter sig hos mig og flyktet ut av huset.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Da nu hans herre hørte hvad hans hustru fortalte, hvorledes hun sa: Således har din træl gjort mot mig, da optendtes hans vrede.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Og Josefs herre tok og satte ham i fengslet, der hvor kongens fanger holdtes fengslet; og han blev sittende der i fengslet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Men Herren var med Josef og lot ham vinne alles hjerter og gav ham yndest hos fengslets overopsynsmann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Og fengslets overopsynsmann satte Josef til å se efter alle fangene som var i fengslet; og alt det som skulde gjøres der, det gjorde han.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Fengslets overopsynsmann så ikke efter nogen ting som han hadde under hender, fordi Herren var med ham; og hvad han gjorde, gav Herren lykke til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Nogen tid derefter hendte det at munnskjenken og bakeren hos kongen i Egypten forså sig mot sin herre, kongen i Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Og Farao blev vred på sine to hoffmenn, den øverste munnskjenk og den øverste baker');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'og satte dem fast hos høvdingen over livvakten, i fengslet hvor Josef var fange.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Og høvdingen over livvakten satte Josef til å være hos dem, og han gikk dem til hånde; og de blev sittende en tid i fengslet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Engang drømte begge hver sin drøm i samme natt og hver drøm med sin mening - munnskjenken og bakeren hos kongen i Egypten, de som satt fanget i fengslet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Da Josef kom inn til dem om morgenen, så han på dem at de var motfalne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Da spurte han Faraos hoffmenn, de som satt fengslet med ham hos hans herre: Hvorfor ser I så sorgfulle ut idag?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'De svarte: Vi har drømt, og det er ingen som kan tyde det. Da sa Josef til dem: Å tyde drømmer - er ikke det Guds sak? Fortell mig hvad I har drømt!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Da fortalte den øverste munnskjenk Josef sin drøm og sa til ham: Jeg så i drømme et vintre som stod foran mig;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'og på vintreet var det tre grener, og det skjøt knopper, blomstene kom frem, klasene modnedes til druer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Og jeg holdt Faraos beger i min hånd, og jeg tok druene og krystet dem ut i Faraos beger, og så rakte jeg Farao begeret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Da sa Josef til ham: Dette er tydningen: De tre grener er tre dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Om tre dager skal Farao ophøie dig og sette dig i ditt embede igjen, og du skal rekke Farao begeret, som du gjorde før, da du var hans munnskjenk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Men kom mig i hu, når det går dig vel, og vis barmhjertighet mot mig, så du taler om mig for Farao og hjelper mig ut av dette hus!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'For de har stjålet mig fra hebreernes land, og heller ikke her har jeg gjort noget som de kunde sette mig i fengslet for.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Da den øverste baker så at Josef hadde gitt en så god tydning, sa han til ham: Også jeg hadde en drøm og syntes jeg så at jeg bar tre kurver med hvetebrød på mitt hode.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Og i den øverste kurv var det allslags bakverk, sånt som Farao pleier å ete, og fuglene åt det av kurven på mitt hode.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Da svarte Josef og sa: Dette er tydningen: De tre kurver er tre dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Om tre dager skal Farao ophøie dig, hugge hodet av dig og henge dig på et tre, og fuglene skal ete kjøttet av dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Den tredje dag, da det var Faraos fødselsdag, gjorde han et gjestebud for alle sine tjenere; og han ophøiet den øverste munnskjenk og den øverste baker iblandt sine tjenere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Han satte den øverste munnskjenk i hans embede igjen, og han rakte Farao begeret,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'og den øverste baker lot han henge, således som Josef hadde tydet drømmene for dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Men den øverste munnskjenk kom ikke Josef i hu - han glemte ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Så hendte det da to år var omme, at Farao drømte han stod ved elven.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Og se, det steg op av elven syv kyr, vakre å se til og fete, og de gikk og beitet i elvegresset.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Og efter dem steg det op av elven syv andre kyr, stygge å se til og magre, og de stod ved siden av de andre kyr på elvebredden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Og de stygge og magre kyr åt op de syv vakre og fete kyr. Da våknet Farao.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Så sovnet han igjen og drømte annen gang, og se, syv aks, frodige og gode, vokste op på ett strå.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Og efter dem skjøt det op syv aks som var tynne og svidd av østenvind.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Og de tynne aks slukte de syv frodige og fulle aks. Da våknet Farao, og skjønte at det var en drøm.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Men om morgenen var han urolig til sinns, og han sendte bud og lot kalle alle tegnsutleggerne og alle vismennene i Egypten; og Farao fortalte dem sine drømmer, men det var ingen som kunde tyde dem for ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Da talte den øverste munnskjenk til Farao og sa: Jeg må idag minne om mine synder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Farao blev vred på sine tjenere og satte mig fast hos høvdingen over livvakten, både mig og den øverste baker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Da hadde vi hver sin drøm i samme natt, jeg og han, og våre drømmer hadde hver sin mening.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Og det var en hebraisk gutt sammen med oss der; han var tjener hos høvdingen over livvakten; ham fortalte vi våre drømmer, og han tydet dem for oss; efter som enhver hadde drømt, tydet han dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Og som han tydet dem for oss, således gikk det; jeg blev satt i mitt embede igjen, og han blev hengt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Da sendte Farao bud og lot Josef kalle, og de førte ham skyndsomt ut av fengslet; og han lot sig rake og skiftet klær og trådte frem for Farao.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Da sa Farao til Josef: Jeg har hatt en drøm, og det er ingen som kan tyde den; men jeg har hørt si om dig at så snart du hører en drøm, kan du tyde den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Og Josef svarte Farao og sa: Det står ikke til mig; Gud vil gi et svar som spår lykke for Farao.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Da sa Farao til Josef: Jeg syntes i drømme at jeg stod på elvebredden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Og se, av elven steg det op syv kyr, fete og vakre av skikkelse, og de gikk og beitet i elvegresset.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Og efter dem steg det op syv andre kyr, tynne og svært stygge av skikkelse og magre; jeg har aldri sett så stygge kyr i hele Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Og de magre og stygge kyr åt op de syv første, fete kyr.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Og da de hadde fått dem til livs, kunde det ikke merkes på dem, de var like stygge å se til som før. Da våknet jeg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Så drømte jeg igjen, og se: Syv aks, fulle og gode, vokste op på ett strå.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Og efter dem skjøt det op syv aks som var fortørket og tynne og svidd av østenvind.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Og de tynne aks slukte de syv gode aks. Og jeg fortalte det til tegnsutleggerne, men ingen kunde forklare det for mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Da sa Josef til Farao: Faraos drømmer har én mening; hvad Gud vil gjøre, har han latt Farao få vite.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'De syv gode kyr er syv år, og de syv gode aks er syv år; det er en og samme drøm.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Og de syv magre og stygge kyr som steg op efter dem, er syv år, og de syv tomme aks som var svidd av østenvinden, er syv hungersår, som skal komme.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Det er som jeg sa til Farao: Hvad Gud vil gjøre, har han latt Farao se.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Det kommer syv år med stor overflod i hele Egyptens land;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'men efter dem kommer det syv hungersår, så all denne overflod skal bli glemt i Egyptens land, og hungeren skal arme ut landet;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'og ingen skal minnes den overflod som var i landet, for hungeren bakefter; for den skal bli meget hård.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Men at drømmen kom to ganger for Farao, det vil si at saken er fast besluttet av Gud, og at Gud vil gjøre det snart.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Nu skulde Farao utse sig en forstandig og vis mann og sette ham over Egyptens land!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Det skulde Farao gjøre og så sette opsynsmenn over landet og ta femtedelen av avgrøden i Egyptens land i de syv overflodsår.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Og de skal samle alt som kan tjene til føde, i disse gode år som kommer, og under Faraos hånd dynge op korn i byene til føde og ta vare på det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Og kornet skal tjene til forråd for landet i de syv hungersår som skal komme over Egyptens land, så landet ikke skal ødelegges av hungeren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Disse ord syntes Farao og alle hans tjenere godt om.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Og Farao sa til sine tjenere: Mon det finnes nogen som han, en mann som har Guds ånd?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Så sa Farao til Josef: Siden Gud har latt dig vite alt dette, så er det ingen så forstandig og vis som du.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Du skal forestå mitt hus, og hele mitt folk skal rette sig efter ditt ord; bare tronen vil jeg ha fremfor dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Og Farao sa fremdeles til Josef: Se, jeg setter dig over hele Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Og Farao tok sin signetring av sin hånd og satte den på Josefs hånd og klædde ham i klær av fint lin og hengte en gullkjede om hans hals.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Og han lot ham kjøre i den vogn som var nærmest efter hans egen, og de ropte foran ham: Abrek!. Og han satte ham over hele Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Og Farao sa til Josef: Jeg er Farao, og uten din vilje skal ingen mann løfte hånd eller fot i hele Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Og Farao gav Josef navnet Sofnat-Paneah og gav ham til hustru Asnat, en datter av Potifera, presten i On. Så drog Josef omkring i Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Josef var tretti år gammel da han stod for Egyptens konge Faraos åsyn. Og efterat Josef var gått ut fra Farao, reiste han gjennem hele Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Og jorden bar rikelig i de syv overflodsår.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Og han samlet alle slags grøde i de syv gode år som kom i Egyptens land, og la den op i byene; i hver by la han op avgrøden fra landet som lå omkring.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Så hopet da Josef op korn som havets sand, i svære mengder, inntil de holdt op med å telle; for det var ikke tall på det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Før det første hungersår kom, fikk Josef to sønner med Asnat, datter av Potifera, presten i On.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Og Josef kalte sin førstefødte sønn Manasse; for sa han Gud har latt mig glemme all min møie og hele min fars hus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Og den andre sønn kalte han Efra\'im; for sa han Gud har gjort mig fruktbar i det land som jeg led ondt i.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Da de syv overflodsår i Egyptens land var til ende,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'begynte de syv hungersår å komme, således som Josef hadde sagt. Da blev det hungersnød i alle landene, men i hele Egyptens land var det brød.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Og da hele Egyptens land led hunger, ropte folket til Farao om brød. Da sa Farao til alle egypterne: Gå til Josef! Hvad han sier eder, skal I gjøre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Da det nu var hungersnød over hele landet, åpnet Josef alle oplagshusene og solgte korn til egypterne; for hungersnøden var hård i Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Og fra alle landene kom de til Josef i Egypten for å kjøpe korn; for hungersnøden var hård i alle landene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Da Jakob fikk vite at det var korn i Egypten, sa han til sine sønner: Hvorfor sitter I og ser på hverandre?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Og han sa: Jeg har hørt at det er korn i Egypten; dra dit ned og kjøp korn til oss der, så vi kan leve og ikke dø!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Da drog Josefs ti brødre ned for å kjøpe korn i Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Men Benjamin, Josefs bror, sendte Jakob ikke avsted med hans brødre; for han sa: Det kunde møte ham en ulykke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Så kom Israels sønner for å kjøpe korn blandt alle de andre som kom; for det var hungersnød i Kana\'ans land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Og Josef var den som rådet i landet; det var han som solgte korn til alt folket i landet; og Josefs brødre kom og bøide sig med sitt ansikt til jorden for ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Da Josef så sine brødre, kjente han dem igjen; men han lot som om de var fremmede for ham, og talte hårdt til dem og sa til dem: Hvor kommer I fra? De sa: Fra Kana\'ans land for å kjøpe korn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Josef kjente sine brødre, men de kjente ikke ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Og Josef kom i hu det han hadde drømt om dem, og sa til dem: I er speidere, I er kommet for å se hvor landet ligger åpent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'De svarte ham: Nei, herre, dine tjenere er kommet for å kjøpe korn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Vi er alle sønner av én mann; vi er ærlige folk, dine tjenere er ikke speidere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Men han sa til dem: Jo, I er kommet for å se hvor landet ligger åpent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Men de sa: Vi, dine tjenere, er tolv brødre, sønner av én mann i Kana\'ans land, den yngste er nu hjemme hos vår far, og én er ikke mere til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Josef sa til dem: Det er som jeg har sagt til eder: I er speidere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Men nu skal I prøves: Så sant Farao lever, skal I ikke komme herfra før eders yngste bror kommer hit.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Send en av eder avsted for å hente eders bror, men I andre skal holdes fanget, og eders ord skal prøves, om det er sant det I sier; hvis ikke, så er I, så sant Farao lever, speidere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Og han holdt dem alle sammen i fengsel i tre dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Men den tredje dag sa Josef til dem: Gjør som jeg nu sier, så skal I leve! Jeg frykter Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Dersom I er ærlige folk, så skal en av eder brødre bli tilbake i fengslet, men I andre kan dra avsted og ha med eder korn til hjelp mot hungersnøden i eders hjem,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'og før eders yngste bror til mig, så eders ord kan sannes, og I ikke skal dø. Og de så gjorde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Og de sa sig imellem: Sannelig, vi har skyld på oss for vår bror. Vi så hans sjeleangst da han bønnfalt oss, og vi vilde ikke høre; derfor er denne nød kommet over oss.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Da tok Ruben til orde og sa til dem: Sa jeg ikke til eder: Gjør ikke synd mot gutten? Men I vilde ikke høre; se, derfor kreves nu hans blod.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Men de visste ikke at Josef forstod det; for han brukte tolk når han talte med dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Og han vendte sig fra dem og gråt. Så vendte han sig til dem igjen og talte til dem, og han tok Simeon fra dem og lot ham binde så de så på.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Og Josef bød sine folk at de skulde fylle deres sekker med korn og legge enhvers penger igjen i hans sekk og gi dem niste med på veien. Og de gjorde således med dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Så la de kornet på sine asener og drog derfra.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Men da en av dem åpnet sin sekk for å gi sitt asen fôr i herberget, da fikk han se sine penger, de lå øverst i hans sekk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Og han sa til sine brødre: Mine penger er kommet igjen, og se, de ligger her i min sekk. Da blev de motfalne og vendte sig forferdet til hverandre og sa: Hvad er det Gud har gjort mot oss?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Så kom de hjem til Jakob, sin far, i Kana\'ans land, og de fortalte ham alt det som hadde hendt dem, og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Mannen som råder der i landet, talte hårdt til oss og tok oss for folk som vilde speide ut landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Og vi sa til ham: Vi er ærlige folk, vi er ikke speidere;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'vi er tolv brødre, alle sønner av samme far, én er ikke mere til, og den yngste er nu hjemme hos vår far i Kana\'ans land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Da sa mannen som råder der i landet, til oss: Av dette vil jeg forstå om I er ærlige folk: La en av eder brødre bli her hos mig og ta hvad I trenger mot hungersnøden i eders hjem, og far eders vei;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'og kom så hit til mig med eders yngste bror, så jeg kan forstå at I ikke er speidere, men ærlige folk! Da vil jeg gi eder eders bror igjen, og I kan fritt dra omkring i landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Da de så tømte sine sekker, se, da lå enhvers pengepung i hans sekk; og da de og deres far så pengepungene, blev de redde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Og Jakob, deres far, sa til dem: I gjør mig barnløs; Josef er ikke mere til, og Simeon er ikke mere til, og Benjamin vil I ta fra mig; det kommer over mig alt sammen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Da sa Ruben til sin far: Begge mine sønner kan du drepe hvis jeg ikke kommer tilbake til dig med ham; gi ham i min hånd, så vil jeg føre ham tilbake til dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Men han sa: Min sønn skal ikke dra ned med eder; for hans bror er død, og han er alene tilbake, og dersom det møter ham nogen ulykke på den vei som I drar, så kommer I til å sende mine grå hår med sorg ned i dødsriket.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Men hungersnøden var hård i landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Og da de hadde brukt op det korn de hadde hentet fra Egypten, sa deres far til dem: Dra atter avsted og kjøp oss litt korn!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Men Juda sa til ham: Mannen sa så alvorlig til oss: I skal ikke komme for mine øine uten eders bror er med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Dersom du vil sende vår bror med oss, vil vi dra ned og kjøpe korn til dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Men dersom du ikke vil sende ham, vil vi ikke dra ned; for mannen sa til oss: I skal ikke komme for mine øine uten eders bror er med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Da sa Israel: Hvorfor har I gjort så ille mot mig og fortalt mannen at I har ennu en bror?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'De svarte: Mannen spurte oss nøie ut både om oss og om vår ætt og sa: Lever eders far ennu? Har I nogen bror? Og vi svarte ham efter som han spurte; kunde vi vel vite at han vilde si: Kom her ned med eders bror?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Og Juda sa til Israel, sin far: Send gutten med mig I Så vil vi gjøre oss rede og dra avsted, så vi kan leve og ikke skal dø, både vi og du og våre små barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Jeg skal svare for ham, av mig kan du kreve ham; dersom jeg ikke har ham med tilbake til dig og stiller ham for ditt ansikt, da vil jeg være din skyldner alle mine dager;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'for dersom vi ikke hadde dryget så lenge, da kunde vi nu to ganger vært her igjen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Da sa Israel, deres far, til dem: Skal det nu så være, så gjør som jeg sier: Ta i eders sekker av alt det ypperste landet eier, og ha det med til mannen som gave, litt balsam og litt honning, krydderier og ladanum, pistasienøtter og mandler,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'og ta dobbelt så mange penger med eder, for de penger som kom igjen og lå øverst i eders sekker, må I ha med tilbake; kanskje det var en feiltagelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Ta så eders bror med, og gjør eder rede og dra tilbake til mannen!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Og den allmektige Gud la eder finne barmhjertighet hos mannen, så han lar eders andre bror og Benjamin dra hjem igjen med eder; og jeg - skal jeg være barnløs, så får jeg være barnløs!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Så tok mennene denne gave, og de tok dobbelte penger med sig, og Benjamin; og de gjorde sig rede og drog ned til Egypten og trådte frem for Josef.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Da Josef så Benjamin sammen med dem, sa han til den som forestod hans hus: Før mennene inn i huset og la slakte og lage til; for mennene skal ete til middag hos mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Og mannen gjorde som Josef sa, og førte mennene inn i Josefs hus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Men mennene blev redde fordi de blev ført inn i Josefs hus, og de sa: Det er vel for de pengers skyld som forrige gang kom tilbake i våre sekker, vi føres inn her, forat han kan velte sig inn på oss og kaste sig over oss og gjøre oss til træler og ta våre asener.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'De gikk derfor til mannen som forestod Josefs hus, og talte til ham ved inngangen til huset');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'og sa: Hør, herre! Vi kom forrige gang ned her for å kjøpe korn;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'men da vi kom til herberget og åpnet våre sekker, se, da lå enhvers penger øverst i hans sekk, våre penger med sin fulle vekt, og nu har vi dem med oss igjen,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'og vi har tatt andre penger ned med oss til å kjøpe korn for; vi vet ikke hvem som har lagt våre penger i våre sekker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Da sa han: I kan være rolige, frykt ikke! Eders Gud og eders fars Gud har gitt eder en skatt i eders sekker; eders penger har jeg fått. Så førte han Simeon ut til dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Derefter førte mannen dem inn i Josefs hus og gav dem vann, og de tvettet sine føtter, og han gav dem fôr til deres asener.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Så la de gaven til rette til Josef skulde komme hjem om middagen; for de hadde hørt at de skulde ete der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Og da Josef var kommet hjem, bar de inn til ham gaven som de hadde med sig, og kastet sig ned på jorden for ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Men han spurte dem om det gikk dem vel, og han sa: Går det eders far vel, den gamle som I talte om? Lever han ennu?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'De svarte: Ja! Det går din tjener vår far vel; han lever ennu. Og de bøide sig og kastet sig ned for ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Og da han så op og fikk øie på Benjamin, sin bror, sin mors sønn, sa han: Er dette eders yngste bror, som I talte til mig om? Og han sa: Gud velsigne dig, min sønn!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Og Josef skyndte sig bort, for hans hjerte brente mot hans bror, og han søkte et sted hvor han kunde gråte; og han gikk inn i sitt kammer og gråt der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Så tvettet han sitt ansikt og gikk ut, og han gjorde sig sterk og sa: Sett maten frem!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Og de satte frem for ham særskilt og for dem særskilt, og for egypterne som åt hos ham, særskilt; for egypterne kan ikke ete sammen med hebreerne, det er en vederstyggelighet for egypterne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Og mennene fikk sine plasser midt imot ham efter alderen, den førstefødte øverst og den yngste nederst, og de så på hverandre og undret sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Og han lot bære til dem av maten på sitt bord, og Benjamin fikk fem ganger så meget som enhver av de andre; og de drakk, og drakk sig glade med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Siden bød han den som forestod hans hus: Fyll mennenes sekker med korn så meget de kan føre, og legg enhvers penger øverst i hans sekk!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Men mitt beger, sølvbegeret, skal du legge øverst i den yngstes sekk sammen med pengene for hans korn. Og han gjorde som Josef bød ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Om morgenen, da det blev lyst, lot de mennene med sine asener fare.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Da de hadde draget ut av byen og ennu ikke var langt kommet, sa Josef til den som forestod hans hus: Ta avsted, sett efter mennene, og når du når dem, skal du si til dem: Hvorfor har I gjengjeldt godt med ondt?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Er det ikke det beger som min herre drikker av, og som han spår i? Dette var ille gjort av eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Og han innhentet dem og sa dette til dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Da sa de til ham: Hvorfor taler min herre således? Det være langt fra dine tjenere å gjøre noget slikt!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Se, de penger som vi fant øverst i våre sekker, hadde vi med oss tilbake til dig fra Kana\'ans land; hvorledes skulde vi da stjele sølv eller gull fra din herres hus?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Den av dine tjenere som det finnes hos, han skal dø, og vi andre skal være min herres træler.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Og han sa: Vel, la det være som I har sagt! Den som det finnes hos, skal være min træl, men I skal være uten skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Så skyndte de sig og løftet hver sin sekk ned på jorden, og enhver åpnet sin sekk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Og han så efter; han begynte hos den eldste og endte hos den yngste, og begeret blev funnet i Benjamins sekk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Da sønderrev de sine klær og lesste hver på sitt asen og vendte tilbake til byen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Og Juda og hans brødre kom til Josefs hus mens han ennu var der, og de kastet sig til jorden for ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Da sa Josef til dem: Hvad er det for noget I har gjort? Visste I ikke at en mann som jeg kan spå?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Og Juda sa: Hvad skal vi svare min herre? Hvad skal vi si, og hvad skal vi rettferdiggjøre oss med? Gud har funnet dine tjeneres misgjerning; se, vi er min herres træler, både vi og den som begeret blev funnet hos.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Men han sa: Det være langt fra mig å gjøre slikt! Den mann som begeret blev funnet hos, han skal være min træl, men dra I andre i fred op til eders far!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Da gikk Juda frem til ham og sa: Hør mig, herre! La din tjener få tale et ord for min herres ører, og la ikke din vrede optendes mot din tjener; for du er som Farao selv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Min herre spurte sine tjenere: Har I far eller bror?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Da sa vi til min herre: Vi har en gammel far, og han har en ung sønn, som er født i hans alderdom; hans bror er død, og han er alene igjen efter sin mor, og hans far har ham så kjær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Og du sa til dine tjenere: Før ham ned til mig, så jeg kan få se ham med mine egne øine!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Da sa vi til min herre: Gutten kan ikke forlate sin far; for hvis han forlater sin far, da vil hans far dø.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Men du sa til dine tjenere: Dersom ikke eders yngste bror kommer ned med eder, skal I ikke mere komme for mine øine.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Da vi så kom hjem til din tjener min far, fortalte vi ham hvad min herre hadde sagt');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Og vår far sa: dra avsted igjen og kjøp litt korn til oss!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Da sa vi: Vi kan ikke dra ned, men dersom vår yngste bror er med oss, da vil vi dra ned; for vi kan ikke komme mannen for øie uten at vår yngste bror er med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Men din tjener min far sa til - oss: I vet at min hustru fødte mig to sønner,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'og den ene gikk bort fra mig, og jeg sa: han er visselig revet ihjel; og jeg har aldri sett ham siden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Tar I nu også denne fra mig, og det møter ham nogen ulykke, så sender I mine grå hår med sorg ned i dødsriket.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Skal jeg nu komme hjem til din tjener min far, og gutten, som han henger ved med hele sin sjel, ikke er med oss,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'så blir det hans død med det samme han ser at gutten ikke er med, og vi må sende din tjener vår fars grå hår med sorg ned i dødsriket.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'For din tjener tok på sig å svare for gutten hos min far og sa: dersom jeg ikke har ham med tilbake til dig, vil jeg være min fars skyldner alle mine dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'La derfor din tjener bli i guttens sted som træl hos min herre, men la gutten dra hjem med sine brødre!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'For hvorledes skulde jeg dra hjem til min far uten at gutten var med mig? Jeg kunde ikke se på den sorg som vilde komme over min far.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Da kunde ikke Josef lenger legge bånd på sig for alle dem som stod hos ham; han ropte: La hver mann gå ut fra mig! Og det var ingen tilstede da Josef gav sig til kjenne for sine brødre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Og han brast i gråt og gråt så høit at egypterne hørte det, og de hørte det i Faraos hus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Og Josef sa til sine brødre: Jeg er Josef, lever min far ennu? Men hans brødre kunde ikke svare ham, så forferdet stod de der foran ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Da sa Josef til sine brødre: Kjære, kom hit til mig! Så gikk de bort til ham; og han sa: Jeg er Josef, eders bror, som I solgte til Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Men vær nu ikke bekymret og sørg ikke over at I solgte mig hit! For å holde eder i live har Gud sendt mig hit i forveien for eder;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'for nu har det vært hungersnød i landet i to år, og ennu kommer det fem år da der hverken skal pløies eller høstes.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Men Gud har sendt mig i forveien for eder fordi han vilde levne eder en rest på jorden, og fordi han vilde holde eder i live, så det blev en stor frelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Så er det da ikke I som har sendt mig hit, men Gud; og han har satt mig til far for Farao og til herre over hele hans hus og til hersker i hele Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Skynd eder og dra op til min far og si til ham: Så sier din sønn Josef: Gud har satt mig til herre over hele Egypten; kom ned til mig, dryg ikke!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Du skal få bo i landet Gosen og være mig nær, både du og dine barn og dine barnebarn med ditt småfe og storfe og alt det du har.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Og jeg vil sørge for dig der - for ennu kommer det fem hungersår - forat du ikke skal utarmes, du og ditt hus og alle de som hører dig til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Og nu ser både I og min bror Benjamin med egne øine at det er jeg som taler med eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Fortell da min far om all min herlighet i Egypten og om alt det I har sett; og skynd eder å føre min far her ned!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Så falt han sin bror Benjamin om halsen og gråt, og Benjamin gråt i hans armer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Og han kysset alle sine brødre og gråt ved deres bryst; og siden talte hans brødre med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Og da det spurtes i Faraos hus at Josefs brødre var kommet, blev Farao og hans tjenere glade.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Og Farao sa til Josef: Si til dine brødre: Så skal I gjøre: I skal lesse på eders dyr og fare hjem til Kana\'ans land,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'og ta så eders far og eders husfolk og kom til mig, og jeg vil gi eder det beste i Egyptens land, og I skal ete av landets fedme.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Dette byder jeg dig nu å si til dem: Så skal I gjøre: I skal ta med eder vogner fra Egypten til eders barn og hustruer og hente eders far og komme hit,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'og I skal ikke kvie eder for å reise fra eders eiendeler; for det beste i hele Egyptens land skal være eders.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Og Israels sønner gjorde så; og Josef gav dem vogner efter Faraos befaling og gav dem niste med på veien.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Og han gav dem alle hver sin høitidsklædning, men Benjamin gav han tre hundre sekel sølv og fem høitidsklædninger..');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Likeledes sendte han til sin far ti asener som bar av det beste Egypten hadde, og ti aseninner som bar korn og brød og fødevarer for hans far. på reisen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Så lot han sine brødre fare, og de reiste; og han sa til dem: Trett ikke med hverandre på veien!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Så drog de op fra Egypten og kom til Kana\'ans land, til Jakob, sin far.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Og de fortalte ham at Josef ennu var i live, og at han var hersker over hele Egyptens land. Men hans hjerte var og blev koldt, for han trodde dem ikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Så fortalte de ham alt det Josef hadde sagt til dem, og han så vognene som Josef hadde sendt til å hente ham i; da oplivedes Jakobs deres fars ånd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Og Israel sa: Det er nok; Josef, min sønn, lever ennu; jeg vil dra avsted og se ham før jeg dør.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Og Israel brøt op med alt det han hadde, og da han kom til Be\'erseba, ofret han slaktoffer til sin far Isaks Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Og Gud sa til Israel i et syn om natten: Jakob, Jakob! Han svarte: Ja, her er jeg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Da sa han: Jeg er Gud, din fars Gud; frykt ikke for å dra ned til Egypten, for der vil jeg gjøre dig til et stort folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Jeg skal selv dra ned med dig til Egypten, jeg skal visselig også føre dig op igjen; og Josef skal lukke dine øine.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Så brøt Jakob op fra Be\'erseba; og Israels sønner kjørte Jakob, sin far, og sine barn og sine hustruer i de vogner som Farao hadde sendt til å hente ham i.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Og de tok med sig sin buskap og sitt gods som de hadde lagt sig til i Kana\'ans land, og de kom til Egypten, Jakob og hele hans ætt med ham;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'sine sønner og sine sønnesønner, sine døtre og sine sønnedøtre, hele sin ætt førte han med sig til Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Og dette er navnene på Israels barn som kom til Egypten, Jakob og hans sønner: Jakobs førstefødte sønn Ruben,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'og Rubens sønner: Hanok og Pallu og Hesron og Karmi,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'og Simeons sønner: Jemuel og Jamin og Ohad og Jakin og Sohar og Saul, som han hadde fått med en kana\'anitterkvinne,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'og Levis sønner: Gerson, Kahat og Merari,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'og Judas sønner: Er og Onan og Sela og Peres og Serah - men Er og Onan døde i Kana\'ans land - og Peres\' sønner var Hesron og Hamul;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'og Issakars sønner: Tola og Puva og Job og Simron,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'og Sebulons sønner: Sered og Elon og Jahle\'el;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'dette var Leas sønner, som hun fødte Jakob i Mesopotamia, og dessuten Dina, hans datter, i alt tre og tretti sjeler, sønner og døtre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Og Gads sønner: Sifion og Haggi, Suni og Esbon, Eri og Arodi og Areli,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, '- og Asers sønner: Jimna og Jisva og Jisvi og Bria og Serah, deres søster, og Brias sønner var Heber og Malkiel;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'dette var barn av Silpa, som Laban gav sin datter Lea; hun fødte Jakob disse barn, seksten sjeler.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Jakobs hustru Rakels sønner: Josef og Benjamin;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'og Josef fikk barn i Egyptens land med Asnat, datter til Potifera, presten i On: Manasse og Efra\'im;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'og Benjamins sønner: Bela og Beker og Asbel, Gera og Na\'aman, Ehi og Ros, Muppim og Huppim og Ard;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'dette var de barn som Jakob fikk med Rakel, i alt fjorten sjeler.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Og Dans sønn: Husim,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'og Naftalis sønner: Jahse\'el og Guni og Jeser og Sillem;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'dette var sønnene til Bilha, som Laban gav sin datter Rakel; hun fødte Jakob disse barn, i alt syv sjeler.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Alle de som kom med Jakob til Egypten, og som var utgått av hans lend, foruten Jakobs sønnekoner, var i alt seks og seksti sjeler.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Og Josefs sønner, som han fikk i Egypten, var to; alle av Jakobs hus, som kom til Egypten, var sytti sjeler.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Og han sendte Juda i forveien til Josef og bad at han skulde vise ham vei til Gosen; så kom de til landet Gosen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Og Josef lot spenne for sin vogn og drog op til Gosen for å møte Israel, sin far; og da han fikk se ham, falt han ham om halsen og gråt lenge i hans armer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Da sa Israel til Josef: Nu vil jeg gjerne dø, efterat jeg har sett ditt ansikt og vet at du ennu lever.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Og Josef sa til sine brødre og til sin fars hus: Jeg vil dra op og melde det til Farao og si til ham: Mine brødre og min fars hus, som var i Kana\'ans land, er kommet til mig;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Og mennene er fehyrder, de er folk som driver feavl, og sitt småfe og sitt storfe og alt det de eier, har de hatt med sig hit.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Og når Farao kaller eder til sig og sier: Hvad er eders levevei?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'da skal I si: Dine tjenere har drevet feavl fra vår ungdom av og til nu, både vi og våre fedre - da får I bo i landet Gosen; for alle fehyrder er en vederstyggelighet for egypterne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Så kom Josef og meldte dette til Farao og sa: Min far og mine brødre er kommet hit fra Kana\'ans land med sitt småfe og storfe og alt det de har; og nu er de i Gosen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Og av alle sine brødre tok han ut fem og fremstilte dem for Farao.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Da sa Farao til hans brødre: Hvad er eders levevei? De svarte Farao: Dine tjenere er fehyrder, vi som våre fedre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Så sa de til Farao: Vi er kommet for å bo en tid her i landet; for dine tjenere hadde ikke beite for sin buskap, fordi det er en hård hungersnød i Kana\'ans land; la derfor dine tjenere få bo i landet Gosen!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Da sa Farao til Josef: Din far og dine brødre er kommet til dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Egyptens land ligger åpent for dig; la din far og dine brødre bo i den beste del av landet, la dem bo i Gosen! Og dersom du vet at det er dyktige menn iblandt dem, da sett dem til opsynsmenn over min buskap!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Og Josef førte Jakob, sin far, inn og fremstilte ham for Farao; og Jakob velsignet Farao.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Og Farao spurte Jakob: Hvor mange er dine leveår?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jakob svarte Farao: Min utlendighets år er hundre og tretti år; få og onde har mine leveår vært, og de har ikke nådd mine fedres leveår i deres utlendighets tid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Og Jakob velsignet Farao, og så gikk han ut fra Farao.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Og Josef lot sin far og sine brødre bosette sig og gav dem eiendom i Egyptens land, i den beste del av landet, i landet Ra\'amses, således som Farao hadde pålagt ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Og Josef forsørget sin far og sine brødre og hele sin fars hus med brød efter barnas tall.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Og det fantes ikke brød i hele landet; for hungersnøden var meget hård, så Egyptens land og Kana\'ans land vansmektet av hunger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Og Josef samlet alle de penger som fantes i Egyptens land og i Kana\'ans land; han fikk dem for det korn de kjøpte, og Josef la pengene op i Faraos hus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Men da det var forbi med pengene i Egyptens land og i Kana\'ans land, da kom alle egypterne til Josef og sa: Gi oss brød! Hvorfor skal vi dø for dine øine? Vi har ikke flere penger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Og Josef sa: Kom hit med eders buskap, så vil jeg gi eder brød for eders buskap, dersom I ikke har flere penger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Så kom de til Josef med sin buskap, og Josef gav dem brød for hestene og for småfeet og storfeet som de hadde, og for asenene, og han holdt dem med brød det år for hele deres buskap.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Så gikk det år til ende, og året efter kom de til ham og sa: Vi vil ikke dølge for min herre at det er forbi med pengene, og buskapen som vi eide, har min herre fått; det er intet tilbake for min herre uten vårt legeme og vår jord.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Hvorfor skal vi gå til grunne for dine øine, både vi og vår jord? Kjøp oss og vår jord for brød, så skal vi med vår jord være Faraos træler; og gi oss såkorn, så vi kan leve og ikke skal dø, og jorden ikke legges øde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Så kjøpte Josef all jorden i Egypten til Farao; for egypterne solgte hver sin jordvei, fordi hungersnøden trykket dem hårdt; og landet blev Faraos eiendom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Men folket flyttet han om i byene, fra den ene ende av Egyptens land til den andre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Bare prestenes jord kjøpte han ikke; for Farao hadde gitt prestene faste inntekter, og de levde av sine faste inntekter, som Farao hadde gitt dem; derfor solgte de ikke sin jord.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Og Josef sa til folket: Nu har jeg kjøpt eder og eders jord til Farao; se, her har I såkorn, tilså nu jorden!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Og når avgrøden kommer inn, da skal I gi en femtedel til Farao, og de fire deler skal I ha til utsæd på eders akrer og til føde for eder og dem som er i eders hus, og til føde for eders barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Da sa de: Du har holdt oss i live; la oss finne nåde for min herres øine, så skal vi være Faraos træler.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Så satte Josef dette som en lov - og den lov gjelder den dag idag for jorden i Egypten - at Farao skulde ha femtedelen; bare Prestenes jord blev ikke Faraos eiendom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Israel blev boende i Egyptens land, i landet Gosen. og de fikk sig eiendom der og var fruktbare og blev meget tallrike.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Og Jakob levde i Egyptens land i sytten år; og Jakobs dager, hans leveår, blev hundre og syv og firti år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Da det led mot den tid at Israel skulde dø, kalte han sin sønn Josef til sig og sa til ham: Kjære, har jeg funnet nåde for dine øine, så legg din hånd under min lend og vis mig den kjærlighet og trofasthet at du ikke begraver mig i Egypten,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'men la mig få hvile hos mine fedre, før mig bort fra Egypten og legg mig i deres grav! Og han svarte: Jeg skal gjøre som du sier.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Da sa han: Tilsverg mig det! Og han tilsvor ham det. Og Israel bøide sig ned over hodegjerdet i sengen og tilbad.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Nogen tid efter kom de og sa til Josef: Din far er syk. Da tok han begge sine sønner med sig, Manasse og Efra\'im.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Og de meldte det til Jakob og sa: Din sønn Josef er kommet til dig. Da gjorde Israel sig sterk og satte sig op i sengen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Og Jakob sa til Josef: Den allmektige Gud åpenbarte sig for mig i Luz i Kana\'ans land og velsignet mig');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'og sa til mig: Se, jeg vil gjøre dig fruktbar og tallrik og gjøre dig til en mengde folkeslag, og jeg vil gi din ætt efter dig dette land til evig eiendom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Og dine to sønner som du har fått i Egyptens land, før jeg kom til dig her i Egypten, de skal nu være mine; Efra\'im og Manasse skal tilhøre mig likesom Ruben og Simeon.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Men de barn som du har fått efter dem, skal være dine; de skal kalles efter sine brødre i deres arvelodd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'For da jeg kom fra Mesopotamia, døde Rakel fra mig i Kana\'ans land på reisen, da vi ennu hadde et stykke vei igjen til Efrat; og jeg begravde henne der på veien til Efrat, det er Betlehem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Da Israel fikk se Josefs sønner, spurte han: Hvem er det?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Josef svarte sin far: Det er mine sønner, som Gud har gitt mig her. Da sa han: Kjære, kom hit til mig med dem, så vil jeg velsigne dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Men Israels øine var sløve av alderdom, han kunde ikke se; og Josef førte dem bort til ham, og han kysset dem og tok dem i favn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Og Israel sa til Josef: Jeg hadde ikke tenkt å få se ditt ansikt, og nu har Gud endog latt mig få se dine barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Så førte Josef dem bort fra hans knær og bøide sig til jorden for ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Siden tok Josef dem begge, Efra\'im i sin høire hånd mot Israels venstre og Manasse i sin venstre hånd mot Israels høire, og førte dem frem til ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Og Israel rakte ut sin høire hånd og la den på Efra\'ims hode, enda han var den yngste, og sin venstre hånd på Manasses hode; han la sine hender således med vilje, for Manasse var den førstefødte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Og han velsignet Josef og sa: Den Gud for hvis åsyn mine fedre Abraham og Isak vandret, den Gud som var min hyrde, fra jeg blev til og til denne dag,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'den engel som forløste mig fra alt ondt, han velsigne guttene, så de må kalles med mitt navn og med mine fedre Abrahams og Isaks navn, og bli meget tallrike i landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Da Josef så at hans far la sin høire hånd på Efra\'ims hode, syntes han ille om det, og han grep sin fars hånd for å føre den fra Efra\'ims hode bort på Manasses hode.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Og Josef sa til sin far: Ikke så, far! For denne er den førstefødte; legg din høire hånd på hans hode!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Men hans far vilde ikke det, og han sa: Jeg vet det, min sønn, jeg vet det. Han skal og bli et folk, han skal og bli stor; men enda skal hans yngre bror bli større enn han, og hans ætt skal bli en mengde folkeslag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Så velsignet han dem samme dag og sa: Ved dig skal Israel velsigne og si: Gud gjøre dig som Efra\'im og som Manasse! Og han satte Efra\'im foran Manasse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Og Israel sa til Josef Se, jeg dør, men Gud skal være med eder og føre eder tilbake til eders fedres land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Og jeg gir dig fremfor dine brødre et stykke land som jeg tar fra amorittenes hånd med mitt sverd og min bue.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Og Jakob kalte sine sønner til sig og sa: samle eder, så vil jeg forkynne eder hvad som skal hende eder i de siste dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Kom sammen og hør, I Jakobs sønner, hør på Israel, eders far!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, min førstefødte er du, min kraft og min styrkes første frukt, høiest i ære og størst i makt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Du bruser over som vannet, du skal intet fortrin ha; for du steg op på din fars leie; da vanhelliget du det - i min seng steg han op!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon og Levi er brødre, voldsvåben er deres sverd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Møt ikke i deres hemmelige råd, min sjel, ta ikke del i deres sammenkomster, min ære! For i sin vrede slo de menn ihjel, og i sin selvrådighet skamskar de okser.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Forbannet være deres vrede, for den var vill, og deres grumhet, for den var hård! Jeg vil kaste dem omkring i Jakob og sprede dem i Israel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda - dig skal dine brødre prise, din hånd skal være på dine fienders nakke, for dig skal din fars sønner bøie sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'En ung løve er Juda; fra rov er du steget op, min sønn! Han legger sig ned, han hviler som en løve, som en løvinne; hvem våger å vekke ham?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Ikke skal kongespir vike fra Juda, ikke herskerstav fra hans føtter, inntil fredsfyrsten kommer, og folkene blir ham lydige.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Han binder til vintreet sitt unge asen og til den edle ranke sin aseninnes fole; han tvetter i vin sitt klædebon og i druers blod sin kjortel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Dunkle er hans øine av vin, og hvite hans tenner av melk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sebulon - ved havets strand skal han bo, ved stranden hvor skibene lander; hans side er vendt mot Sidon.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Issakar er et sterktbygget asen, som hviler mellem sine hegn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Og han så at hvilen var god, og at landet var fagert; da bøide han sin rygg under byrden og blev en ufri træl.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan skal dømme sitt folk, han som de andre Israels stammer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan skal være en slange på veien, en huggorm på stien, som biter hesten i hælene, så rytteren faller bakover.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Efter din frelse bier jeg, Herre!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad - en fiendeflokk hugger inn på ham, men han hugger dem i hælene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Fra Aser kommer fedmen, hans mat, og lekre retter som for konger har han å gi.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naftali er en lekende hind; liflig er ordet han taler.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Et ungt frukttre er Josef, et ungt frukttre ved kilden; grenene skyter ut over muren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Og de egger ham og skyter på ham, de forfølger ham - de pileskyttere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Men fast står han der med sin bue, og hans hender og armer er raske - ved Jakobs Veldiges hender, fra ham, fra hyrden, Israels klippe,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'fra din fars Gud, og han hjelpe dig, fra den Allmektige, og han velsigne dig med velsignelser fra himmelen der oppe, med velsignelser fra dypet der nede, med brysters og morslivs velsignelser!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Din fars velsignelser stiger høit op over mine forfedres velsignelser, de når op til de evige høiders grense; de skal komme over Josefs hode, over hans isse, han som er høvding blandt sine brødre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin er en glupende ulv; om morgenen eter han op rov, og om aftenen deler han ut hærfang.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Alle disse er Israels stammer, tolv i tallet, og således var det deres far talte til dem; han velsignet dem, hver av dem velsignet han med den velsignelse som tilkom ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Og han bød dem og sa til dem: Jeg samles nu til mitt folk; begrav mig hos mine fedre i hulen på hetitten Efrons mark,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'i hulen på Makpela-marken, østenfor Mamre i Kana\'ans land, den mark som Abraham kjøpte av hetitten Efron til eiendoms-gravsted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Der begravde de Abraham og Sara, hans hustru, der begravde de Isak og Rebekka, hans hustru, og der begravde jeg Lea,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'på den mark og i den hule der som blev kjøpt av Hets barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Da Jakob var ferdig med de pålegg han vilde gi sine sønner, trakk han føttene op i sengen; og han opgav sin ånd og blev samlet til sine fedre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Og Josef bøide sig ned over sin fars ansikt og gråt over ham og kysset ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Og Josef bød lægene som han hadde i sin tjeneste, å balsamere hans far; og lægene balsamerte Israel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Firti dager gikk med hertil, for så mange dager går med til balsameringen; og egypterne gråt over ham i sytti dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Da sørgedagene over ham var til ende, talte Josef til Faraos husfolk og sa: Dersom jeg har funnet nåde for eders øine, så tal for mig til Farao og si:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Min far tok en ed av mig og sa: Jeg dør; i min grav som jeg lot grave for mig i Kana\'ans land, der skal du begrave mig. La mig derfor få dra op og begrave min far og så vende tilbake!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Og Farao sa: Dra op og begrav din far, således som du tilsvor ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Så drog Josef op for å begrave sin far; og alle Faraos tjenere, de eldste i hans hus, og alle de eldste i Egyptens land drog op med ham,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'og hele Josefs hus og hans brødre og hans fars hus; bare sine små barn og sitt småfe og storfe lot de bli tilbake i landet Gosen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Og både vogner og hestfolk drog op med ham, så det blev et meget stort tog.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Da de kom til Goren-Ha\'atad på hin side Jordan, holdt de der en stor og høitidelig sørgefest, og han gjorde likferd efter sin far i syv dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Og da landets innbyggere, kana\'anittene, så likferden i Goren-Ha\'atad, sa de: Det er en prektig likferd egypterne holder der. Derfor kalte de stedet Abel Misra\'im; det ligger på hin side Jordan.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Og hans sønner gjorde med ham således som han hadde pålagt dem;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'hans sønner førte ham til Kana\'ans land og begravde ham i hulen på Makpela-marken, den mark som Abraham hadde kjøpt av hetitten Efron til eiendoms-gravsted, østenfor Mamre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Og da Josef hadde begravet sin far, vendte han tilbake til Egypten, både han og hans brødre og alle de som hadde draget op med ham for å begrave hans far.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Da Josefs brødre så at deres far var død, sa de: Bare nu ikke Josef vil hate oss og gjengjelde oss alt det onde vi gjorde mot ham!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Så sendte de bud til Josef og lot si: Din far gav oss før sin død dette pålegg:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Så skal I si til Josef: Tilgi, kjære, dine brødres misgjerning og deres synd, at de har gjort ille mot dig! Så tilgi nu oss, som også tjener din fars Gud, vår misgjerning! Og Josef gråt da de talte således til ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Siden kom også hans brødre selv og falt ned for ham og sa: Se, vi vil være dine tjenere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Da sa Josef til dem: Vær ikke redde; er vel jeg i Guds sted?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'I tenkte ondt mot mig; men Gud tenkte det til det gode for å gjøre det han nu har gjort, og holde meget folk i live.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Så vær da ikke redde, jeg vil sørge for eder og eders barn. Og han trøstet dem og talte vennlig til dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Josef blev boende i Egypten, både han og hans fars hus; og Josef blev hundre og ti år gammel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Og Josef fikk se Efra\'ims barn i tredje ledd; også barna til Makir, Manasses sønn, blev født på Josefs knær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Og Josef sa til sine brødre: Jeg dør, men Gud skal visselig se til eder og føre eder op fra dette land til det land han har tilsvoret Abraham, Isak og Jakob.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Og Josef tok en ed av Israels sønner og sa: Gud skal visselig se til eder, og da skal I føre mine ben op herfra.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Og Josef døde, hundre og ti år gammel; og de balsamerte ham og la ham i kiste i Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Dette er navnene på Israels sønner som kom til Egypten; med Jakob kom de, hver med sitt hus:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi og Juda,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Issakar, Sebulon og Benjamin,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan og Naftali, Gad og Aser.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'De som nedstammet fra Jakob, var i alt sytti sjeler; men Josef var allerede i Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Og Josef døde og alle hans brødre og hele den slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Men Israels barn var fruktbare og tok sterkt til og blev mange og overmåte tallrike, og landet blev fullt av dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Da kom det en ny konge over Egypten, som ikke visste noget om Josef.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Og han sa til sitt folk: Se, israelittenes folk er større og tallrikere enn vi.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Nu vel, la oss gå klokt til verks mot dem, forat de ikke skal ta mere til, og forat de ikke, om det kommer krig, skal slå sig i lag med våre fiender og føre krig mot oss og dra ut av landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Så satte de arbeidsfogder over dem til å plage dem med tvangsarbeid; og de måtte bygge for Farao to byer til oplagssteder, Pitom og Ra\'amses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Men jo mere de plaget dem, dess mere tok de til, og dess mere bredte de sig ut, så egypterne begynte å grue for Israels barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Og egypterne tvang Israels barn til å træle for sig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'og de forbitret livet for dem med hårdt trælarbeid i ler og tegl og med alle slags trælarbeid på marken, alt det trælarbeid som de tvang dem til å gjøre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Og kongen i Egypten sa til de hebraiske jordmødre - den ene av dem hette Sifra og den andre Pua -:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Når I hjelper de hebraiske kvinner til å føde, så skal I se efter i jordmorstolen; er det da en sønn, sa drep ham, men er det en datter, da kan hun leve.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Men jordmødrene fryktet Gud og gjorde ikke som kongen i Egypten bød dem, men lot guttebarna leve.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Da kalte kongen i Egypten jordmødrene til sig og sa til dem: Hvorfor gjør I dette og lar guttebarna leve?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Jordmødrene svarte Farao: De hebraiske kvinner er ikke som de egyptiske, de er sterkere; før jordmoren kommer til dem, har de født.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Og Gud gjorde vel imot jordmødrene; og folket tok til og blev overmåte tallrikt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Og fordi jordmødrene fryktet Gud, gav han dem avkom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Da bød Farao alt sitt folk og sa: Hver sønn som fødes, skal kastes i elven, men hver datter skal I la leve.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Så var det en mann av Levis hus som gikk bort og tok en Levis datter til ekte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Og kvinnen blev fruktsommelig og fødte en sønn; og da hun så at det var et vakkert barn, skjulte hun ham i tre måneder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Men da hun ikke lenger kunne skjule ham, tok hun en kiste til ham av rør og smurte den over med jordbek og tjære, og hun la gutten i den og satte den i sivet ved elvebredden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Men hans søster stod et stykke fra for å få vite hvorledes det gikk ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Da kom Faraos datter ned til elven for å bade sig, mens hennes jomfruer gikk frem og tilbake på elvebredden; hun fikk se kisten midt i sivet og sendte sin pike avsted og lot den hente.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Da hun åpnet den, så hun barnet, og se, det var en gutt som lå der og gråt; da ynkedes hun over ham og sa: Det er en av hebreernes guttebarn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Da sa hans søster til Faraos datter: Skal jeg gå og hente en amme til dig blandt de hebraiske kvinner, så hun kan fostre op barnet for dig?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Faraos datter svarte henne: Ja, gå! Og piken gikk og hentet guttens mor.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Da sa Faraos datter til henne: Ta denne gutt og fostre ham op for mig; jeg vil gi dig lønn for det. Og konen tok gutten og fostret ham op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Da gutten blev voksen, gikk hun med ham til Faraos datter, og han blev som en sønn for henne; hun kalte ham Moses, for - sa hun - av vannet har jeg dradd ham op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Og det hendte på den tid da Moses var blitt voksen, at han gikk ut til sine brødre og så på deres slit og slep, og han fikk se en egyptisk mann som slo en hebraisk mann, en av hans brødre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Da vendte han sig hit og dit og så at det ikke var nogen der, og så slo han egypteren ihjel og skjulte ham i sanden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Den andre dag gikk han atter ut og så to hebraiske menn som holdt på å slåss; da sa han til ham som hadde urett: Hvorfor slår du din landsmann?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Han svarte: Hvem har satt dig til høvding og dommer over oss? Tenker du å slå mig ihjel, likesom du slo egypteren ihjel? Da blev Moses redd og sa: Sannelig, saken er blitt kjent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Da Farao fikk høre det, søkte han å slå Moses ihjel; men Moses flyktet for Farao, og han tok bolig i landet Midian og bodde ved en brønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Presten i Midian hadde syv døtre; de kom og øste op vann og fylte vannrennene for å vanne sin fars småfe.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Så kom det nogen gjætere og drev dem bort; men Moses stod op og hjalp dem og vannet deres småfe.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Da de så kom hjem til Re\'uel, sin far, sa han: Hvorfor kommer I så snart idag?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'De svarte: En egyptisk mann hjalp oss mot gjæterne, og han øste også vann for oss og vannet småfeet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Da sa han til sine døtre: Hvor er han da? Hvorfor lot I mannen bli igjen der? Be ham inn, så han kan ete med oss!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Og Moses samtykket i å bli hos mannen; og han lot Moses få sin datter Sippora til hustru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Hun fikk en sønn, og han kalte ham Gersom; for han sa: Jeg er blitt en gjest i et fremmed land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Da lang tid var gått, døde kongen i Egypten, og Israels barn sukket over sin trældom og klaget; og deres rop over trældommen steg op til Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Og Gud hørte deres sukk, og Gud kom i hu sin pakt med Abraham, Isak og Jakob.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Og Gud så til Israels barn, og Gud kjentes ved dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Og Moses gjætte småfeet hos Jetro, sin svigerfar, presten i Midian, og han drev engang småfeet bortom ørkenen og kom til Guds berg, til Horeb.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Der åpenbarte Herrens engel sig for ham i en luende ild, midt ut av en tornebusk; og han så op, og se, tornebusken stod i lys lue, men tornebusken brente ikke op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Og Moses sa: Jeg vil gå bort og se dette vidunderlige syn, hvorfor tornebusken ikke brenner op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Da Herren så at han gikk bort for å se, ropte Gud til ham midt ut av tornebusken og sa: Moses, Moses! Og han svarte: Ja, her er jeg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Da sa han: Kom ikke nærmere, dra dine sko av dine føtter! For det sted du står på, er hellig jord.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Så sa han: Jeg er din fars Gud, Abrahams Gud, Isaks Gud og Jakobs Gud. Da skjulte Moses sitt ansikt, for han fryktet for å skue Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Og Herren sa: Jeg har sett mitt folks nød i Egypten, og jeg har hørt deres klagerop over arbeidsfogdene; jeg vet hvad de lider.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Og nu er jeg steget ned for å utfri dem av egypternes hånd og for å føre dem op fra dette land til et godt og vidtstrakt land, til et land som flyter med melk og honning, det land hvor kana\'anittene bor og hetittene og amorittene og ferisittene og hevittene og jebusittene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Nu er Israels barns skrik nådd op til mig, og jeg har også sett hvorledes egypterne mishandler dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Så gå nu du avsted, jeg vil sende dig til Farao, og du skal føre mitt folk, Israels barn, ut av Egypten!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Men Moses sa til Gud: Hvem er jeg, at jeg skulde gå til Farao, og at jeg skulde føre Israels barn ut av Egypten?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Og han sa: Sannelig, jeg vil være med dig, og dette skal være dig et tegn på at jeg har sendt dig: Når du har ført folket ut av Egypten, da skal I holde gudstjeneste på dette fjell.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Da sa Moses til Gud: Men når jeg nu kommer til Israels barn og sier til dem: Eders fedres Gud har sendt mig til eder, og de så spør mig: Hvad er hans navn? - hvad skal jeg da svare dem?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Og Gud sa til Moses: Jeg er den jeg er; og han sa: Så skal du si til Israels barn: \"Jeg er\" har sendt mig til eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Og Gud sa fremdeles til Moses: Så skal du si til Israels barn: Herren, eders fedres Gud, Abrahams Gud, Isaks Gud og Jakobs Gud, har sendt mig til eder. Dette er mitt navn til evig tid, og så skal de kalle mig fra slekt til slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Gå nu og kall sammen de eldste i Israel og si til dem: Herren, eders fedres Gud, har åpenbaret sig for mig, Abrahams, Isaks og Jakobs Gud, og sagt: Jeg har sett til eder og vet hvorledes de farer frem mot eder i Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Og jeg sa: Jeg vil føre eder ut av alt det onde I lider i Egypten, til kana\'anittenes og hetittenes og amorittenes og ferisittenes og hevittenes og jebusittenes land, til et land som flyter med melk og honning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Og de skal høre på dine ord, og du skal gå inn til kongen i Egypten, du og de eldste i Israel, og I skal si til ham: Herren, hebreernes Gud, har møtt oss; la oss nu gå tre dagsreiser ut i ørkenen og ofre til Herren vår Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Men jeg vet at kongen i Egypten ikke vil gi eder lov til å dra ut, ikke engang om han får kjenne en sterk hånd over sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Derfor vil jeg rekke ut min hånd og slå Egypten med alle mine under, som jeg vil gjøre midt iblandt dem; så skal han la eder fare.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Og jeg vil la dette folk finne yndest hos egypterne, så I, når I drar ut, ikke skal dra tomhendt bort;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'men enhver kvinne skal be sin grannekvinne og den som bor i hennes hus, om smykker av sølv og gull og om klær, og I skal la eders sønner og eders døtre ta dem på sig; dette er det bytte I skal ta av egypterne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Moses svarte: De vil visst ikke tro mig og ikke høre på mig, de vil si: Herren har ikke åpenbaret sig for dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Da sa Herren til ham: Hvad er det du har i hånden? Han svarte: En stav.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Da sa han: Kast den på jorden! Og han kastet den på jorden, og den blev til en slange; og Moses flyktet for den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Og Herren sa til Moses: Rekk ut din hånd og grip den i halen! Så rakte han ut hånden og grep fatt i den, og den blev til en stav i hans hånd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Så må de vel tro at Herren, deres fedres Gud, Abrahams Gud, Isaks Gud og Jakobs Gud, har åpenbaret sig for dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Og Herren sa fremdeles til ham: Stikk din hånd i barmen! Og han stakk sin hånd i barmen; og da han drog den ut, se, da var hans hånd spedalsk, som sne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Og han sa: Stikk din hånd i barmen igjen! Og han stakk igjen sin hånd i barmen; og da han drog den ut av sin barm, se, da var den igjen blitt som hans legeme ellers.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Om de nu ikke tror dig eller akter på det første tegn, så vil de da visst tro på det andre tegn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Men tror de ikke engang på disse to tegn, og vil de ikke høre på dig, da skal du ta vann av elven og helle det ut på jorden, og det vann du tar av elven, det skal bli til blod på jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Men Moses sa til Herren: Hør mig, Herre! Jeg har aldri vært nogen ordets mann, hverken før, eller siden du begynte å tale til din tjener; jeg er tung i mæle og tung i tale.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Men Herren sa til ham: Hvem har gitt mennesket munn, og hvem gjør stum eller døv eller seende eller blind? Er det ikke jeg, Herren?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Gå nu du, og jeg vil være med din munn og lære dig hvad du skal tale.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Men han sa: Hør mig, Herre! Send bud med hvem du ellers vil!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Da optendtes Herrens vrede mot Moses, og han sa: Har du ikke din bror Aron, levitten? Han, vet jeg, kan tale; og nu kommer han dig også i møte, og når han ser dig, blir han glad.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Og du skal tale til ham og legge ordene i hans munn, og jeg skal være med din munn og med hans munn og lære eder hvad I skal gjøre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Og han skal tale til folket for dig; han skal være din munn, og du skal være Gud for ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Og du skal ta denne stav i din hånd; med den skal du gjøre tegnene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Så gikk Moses, og da han kom tilbake til Jetro, sin svigerfar, sa han til ham: Kjære, la mig få dra tilbake til mine brødre i Egypten og se om de ennu er i live. Og Jetro sa til Moses: Dra bort i fred!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Og Herren sa til Moses i Midian: Dra avsted og vend tilbake til Egypten! Nu er de døde alle de som stod dig efter livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Så tok Moses sin hustru og sine sønner og satte dem på asenet og vendte tilbake til Egyptens land; og Moses tok Guds stav i sin hånd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Og Herren sa til Moses: Når du nu vender tilbake til Egypten, så se til at du gjør alle de under som jeg har gitt dig makt til å gjøre, for Faraos øine; men jeg vil forherde hans hjerte, så han ikke lar folket fare.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Da skal du si til Farao: Så sier Herren: Min sønn, min førstefødte, er Israel,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'og jeg sa til dig: La min sønn fare, så han kan tjene mig, men du vilde ikke la ham fare; derfor vil jeg nu slå ihjel din sønn, din førstefødte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Underveis, på et hvilested, hendte det at Herren kom imot ham og søkte å ta hans liv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Da tok Sippora en skarp sten og skar bort sin sønns forhud og kastet den for hans føtter og sa: Sannelig, du er mig en blodbrudgom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Så lot han ham være; da sa hun: En blodbrudgom for omskjærelsens skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Og Herren sa til Aron: Gå Moses i møte i ørkenen! Og han gikk og traff ham ved Guds berg og kysset ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Og Moses forkynte Aron alt hvad Herren, som sendte ham, hadde talt, og alle de tegn han hadde pålagt ham å gjøre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Så gikk Moses og Aron; og de samlet alle de eldste av Israels barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Og Aron bar frem alle de ord Herren hadde talt til Moses, og han gjorde tegnene for folkets øine.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Og folket trodde; og da de hørte hvorledes Herren hadde sett til Israels barn og gitt akt på deres nød, bøide de sig og tilbad.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Derefter gikk Moses og Aron inn til Farao og sa: Så sier Herren, Israels Gud: La mitt folk fare, så de kan holde høitid for mig i ørkenen!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Men Farao sa: Hvem er Herren som jeg skal lyde og la Israel fare? Jeg kjenner ikke Herren, og heller ikke vil jeg la Israel fare.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Da sa de: Hebreernes Gud har møtt oss; la oss dra tre dagsreiser ut i ørkenen og ofre til Herren vår Gud, så han ikke skal slå oss med pest eller sverd!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Men kongen i Egypten sa til dem: Hvorfor vil I, Moses og Aron, dra folket fra dets arbeid? Gå og gjør det I skal!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Så sa Farao: Se, folket er nu blitt altfor tallrikt i landet, og så vil I dra dem bort fra det de har å gjøre!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Og samme dag bød Farao arbeidsfogdene og opsynsmennene over folket og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'I skal ikke mere gi folket halm til teglarbeidet, som før; de skal selv gå og sanke sig halm.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Men den samme mengde teglsten som de før har gjort, skal I pålegge dem; I skal ikke avkorte noget i deres arbeid. For de er dovne; derfor skriker de og sier: La oss gå og ofre til vår Gud!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Legg tungt arbeid på disse mennesker, så de har nok med det og ikke hører efter løgnaktige ord!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Da gikk arbeidsfogdene og opsynsmennene ut og sa til folket: Så sier Farao: Jeg gir eder ikke lenger halm.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Gå selv og finn eder halm, hvor I kan; Men i eders arbeid skal det ikke avkortes noget.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Da spredte folket sig over hele Egyptens land for å sanke stubber til å bruke istedenfor halm.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Men arbeidsfogdene drev på og sa: Gjør eders arbeid ferdig, fullt dagsverk for hver dag, likesom dengang I hadde halm.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Og opsynsmennene som Faraos arbeidsfogder hadde satt over Israels barn, fikk hugg, og arbeidsfogdene sa til dem: Hvorfor har I ikke gjort ferdig den fastsatte mengde teglsten, likesom før, hverken igår eller idag?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Da gikk opsynsmennene over Israels barn til Farao og klaget høilydt for ham og sa: Hvorfor gjør du således med dine tjenere?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Dine tjenere får ikke halm, og allikevel sier de til oss: Gjør tegl! Og så får dine tjenere hugg, enda det er ditt eget folk som har skylden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Men han sa: Dovne er I, dovne! Derfor sier I: Vi vil gå og ofre til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Så gå nu og arbeid! Halm får I ikke, men den fastsatte mengde tegl skal I komme med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Israels barns opsynsmenn så at de var ille farne, da det blev sagt til dem: I skal ikke avkorte noget i den teglsten I skal ha ferdig - fullt dagsverk for hver dag!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Og da de kom ut fra Farao, møtte de Moses og Aron, som stod og ventet på dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Og de sa til dem: Herren hjemsøke eder og dømme eder fordi I har ført oss i vanrykte hos Farao og hans tjenere, så I har gitt dem sverd i hånden til å slå oss ihjel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Da vendte Moses sig igjen til Herren og sa: Herre, hvorfor har du gjort så ille med dette folk? Hvorfor har du sendt mig?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'For fra den stund jeg gikk inn til Farao for å tale i ditt navn, har han gjort ille mot dette folk, og du har aldeles ikke hjulpet ditt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Da sa Herren til Moses: Nu skal du se hvad jeg vil gjøre med Farao; ved min sterke hånd skal han tvinges til å la dem fare, ja, ved min sterke hånd tvinges til å drive dem ut av sitt land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Og Gud talte til Moses og sa til ham: Jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Jeg åpenbarte mig for Abraham, for Isak og for Jakob som den allmektige Gud; men ved mitt navn Herren var jeg ikke kjent av dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Og jeg oprettet min pakt med dem, at jeg vilde gi dem Kana\'ans land, det land hvor de bodde som fremmede.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Og nu har jeg hørt hvorledes Israels barn sukker over at egypterne gjør dem til træler, og jeg har kommet min pakt i hu.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Si derfor til Israels barn: Jeg er Herren, og jeg vil føre eder ut fra egypternes tunge byrder og utfri eder fra trælarbeidet under dem, og jeg vil forløse eder med utrakt arm og ved store straffedommer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Og jeg vil ta eder til mitt folk, og jeg vil være eders Gud, og I skal kjenne at jeg er Herren eders Gud, han som fører eder ut fra egypternes tunge byrder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Og jeg vil føre eder til det land som jeg med opløftet hånd har svoret å ville gi til Abraham, Isak og Jakob, og jeg vil gi eder det til eiendom; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Og Moses sa dette til Israels barn; men de hørte ikke på Moses for angst og for det hårde trælarbeids skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Da talte Herren til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Gå inn og si til Farao, kongen i Egypten, at han skal la Israels barn fare ut av sitt land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Og Moses tok således til orde, der han stod for Herrens åsyn: Du ser Israels barn hører ikke på mig; hvorledes skulde da Farao høre på mig, jeg som enda har uomskårne leber?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Da talte Herren til Moses og Aron og sendte dem til Israels barn og til Farao, kongen i Egypten, med pålegg om at Israels barn skulde føres ut av Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Dette er overhodene for deres familier: Sønnene til Ruben, Israels førstefødte, var Hanok og Pallu, Hesron og Karmi; dette er Rubens ætter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Simeons sønner var Jemuel og Jamin og Ohad og Jakin og Sohar og Saul, som var sønn av en Kana\'anitterkvinne; dette er Simeons ætter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Og dette er navnene på Levis sønner efter deres ætter: Gerson og Kahat og Merari; og Levi blev hundre og syv og tretti år gammel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Gersons sønner var Libni og Sime\'i efter deres ætter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Kahats sønner var Amram og Jishar og Hebron og Ussiel; og Kahat blev hundre og tre og tretti år gammel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Meraris sønner var Mahli og Musi. Dette er Levis ætter efter deres ættetavle.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Amram tok Jokebed, sin fars søster, til hustru, og med henne fikk han Aron og Moses; og Amram blev hundre og syv og tretti år gammel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Jishars sønner var Korah og Nefeg og Sikri.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Ussiels sønner var Misael og Elsafan og Sitri.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Aron tok Eliseba, Amminadabs datter, Nahsons søster, til hustru, og med henne fikk han Nadab og Abihu, Eleasar og Itamar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Korahs sønner var Assir og Elkana og Abiasaf; dette er korahittenes ætter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Eleasar, Arons sønn, tok en av Putiels døtre til hustru, og med henne fikk han Pinehas. Dette var overhodene for levittenes familier efter deres ætter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Disse menn, Aron og Moses, var det Herren talte således til: Før Israels barn ut av Egyptens land, hær for hær!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Det var de som sa til Farao, kongen i Egypten, at Israels barn skulde føres ut av Egypten, disse menn, Moses og Aron.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Og det skjedde dengang Herren talte til Moses i Egyptens land,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'da sa Herren til Moses: Jeg er Herren; tal til Farao, kongen i Egypten, alt det jeg taler til dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Men Moses sa, der han stod for Herrens åsyn: Du vet jeg har uomskårne leber; hvorledes skulde da Farao høre på mig?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Da sa Herren til Moses: Se, jeg har satt dig til en Gud for Farao, og Aron, din bror, skal være din profet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Du skal tale alt det jeg byder dig; men Aron, din bror, skal tale til Farao, og han skal la Israels barn fare ut av sitt land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Men jeg vil forherde Faraos hjerte, og jeg vil gjøre mange tegn og under i Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Farao skal ikke høre på eder; men jeg vil legge min hånd på Egypten og føre mine hærer, mitt folk, Israels barn, ut av Egyptens land ved store straffedommer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Og egypterne skal kjenne at jeg er Herren, når jeg rekker ut min hånd over Egypten og fører Israels barn ut fra dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Og Moses og Aron gjorde dette; som Herren hadde pålagt dem, således gjorde de.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Moses var åtti år gammel, og Aron tre og åtti år, da de talte til Farao.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Og Herren sa til Moses og Aron:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Når Farao taler til eder og sier: La mig få se et under av eder, da skal du si til Aron: Ta din stav og kast den ned foran Farao! Og den skal bli til en slange.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Så gikk Moses og Aron inn til Farao og gjorde som Herren hadde sagt; Aron kastet sin stav ned foran Farao og hans tjenere, og den blev til en slange.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Da lot Farao sine vismenn og trollmenn kalle, og de, Egyptens tegnsutleggere, gjorde det samme med sine hemmelige kunster;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'de kastet hver sin stav, og de blev til slanger; men Arons stav slukte deres staver.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Men Faraos hjerte blev forherdet, og han hørte ikke på dem, således som Herren hadde sagt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Da sa Herren til Moses: Faraos hjerte er hårdt; han vil ikke la folket fare.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Gå til Farao imorgen tidlig når han går ned til elven, og still dig i hans vei på elvebredden, og staven som blev skapt om til en slange, skal du ta i hånden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Og du skal si til ham: Herren, hebreernes Gud, har sendt mig til dig og sier: La mitt folk fare, så de kan tjene mig i ørkenen! Men du har like til nu ikke villet lyde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Sa sier Herren: På dette skal du kjenne at jeg er Herren: Se, nu slår jeg med denne stav som jeg har i min hånd, på vannet i elven, og det skal bli til blod,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'og fiskene i elven skal dø, og elven skal lukte ille, så egypterne skal vemmes ved å drikke vannet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Og Herren sa til Moses: Si til Aron: Ta din stav og rekk ut din hånd over egypternes vann, over deres elver, over deres kanaler og over deres sjøer og over alle deres dammer, og de skal bli til blod, og det skal være blod i hele Egyptens land, både i trekar og i stenkar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Og Moses og Aron gjorde som Herren hadde sagt; han løftet staven og slo på vannet i elven så de så på det, både Farao og hans tjenere; da blev alt vannet i elven til blod,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'og fiskene i elven døde, og elven luktet ille, så egypterne ikke kunde drikke vannet, og det var blod i hele Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Men Egyptens tegnsutleggere gjorde det samme med sine hemmelige kunster, og Faraos hjerte blev forherdet, og han hørte ikke på dem, således som Herren hadde sagt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Og Farao vendte sig om og gikk hjem til sitt hus og la heller ikke dette på hjerte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Men alle egypterne gravde rundt omkring elven efter drikkevann; for de kunde ikke drikke elvevannet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Så gikk det syv dager efterat Herren hadde slått elven.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Da sa Herren til Moses: Gå inn til Farao og si til ham: Så sier Herren: La mitt folk fare, så de kan tjene mig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Dersom du nekter å la dem fare, da vil jeg plage hele ditt land med frosk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Og elven skal vrimle av frosk, og de skal krype op og komme inn i ditt hus og i ditt sengkammer og op i din seng og i dine tjeneres hus og på ditt folk og i dine bakerovner og i dine deigtrau.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Ja, på dig og på ditt folk og på alle dine tjenere skal froskene krype op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Og Herren sa til Moses: Si til Aron: Rekk ut din hånd med din stav over elvene, over kanalene og over sjøene, og la froskene komme op over Egyptens land!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Og Aron rakte ut sin hånd over Egyptens vann, og froskene kom op og dekket hele Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Men tegnsutleggerne gjorde det samme med sine hemmelige kunster og lot froskene komme op over Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Da kalte Farao Moses og Aron til sig og sa: Bed til Herren at han vil ta froskene bort fra mig og mitt folk! Da til jeg la folket fare, sa de kan ofre til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Og Moses sa til Farao: Ha selv den ære å si når jeg skal bede for dig og dine tjenere og ditt folk at froskene må bli drevet bort fra dig og dine hus, så de bare blir tilbake i elven.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Han svarte: Imorgen. Da sa Moses: La det bli som du sier, forat du kan kjenne at det ikke er nogen som Herren vår Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Froskene skal vike fra dig og dine hus og fra dine tjenere og ditt folk; bare i elven skal de bli tilbake.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Så gikk Moses og Aron ut igjen fra Farao, og Moses ropte til Herren for froskenes skyld som han hadde ført over Farao.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Og Herren gjorde som Moses hadde sagt, og froskene som var i husene og gårdene og på markene, døde bort;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'og de samlet dem i dyngevis, og landet blev fylt med stank.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Men da Farao så at han hadde fått luft, gjorde han sitt hjerte hårdt og hørte ikke på dem, således som Herren hadde sagt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Da sa Herren til Moses: Si til Aron: Rekk ut din stav og slå i støvet på jorden, så skal det bli til mygg i hele Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Og de gjorde således; Aron rakte ut sin hånd med sin stav og slo i støvet på jorden, og myggene kom både på folk og fe; alt støvet på jorden blev til mygg i hele Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Tegnsutleggerne gjorde likeså med sine hemmelige kunster; de søkte å få mygg frem, men kunde ikke. Og myggene blev sittende på folk og på fe.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Da sa tegnsutleggerne til Farao: Dette er Guds finger. Men Faraos hjerte var og blev forherdet, og han hørte ikke på dem, således som Herren hadde sagt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Da sa Herren til Moses: Stå tidlig op imorgen, og still dig frem for Farao når han går ned til elven, og si til ham: Så sier Herren: La mitt folk fare, så de kan tjene mig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'For dersom du ikke lar mitt folk fare, da sender jeg fluesvermer over dig og dine tjenere og ditt folk og dine hus, og egypternes hus skal fylles av fluesvermene, ja endog jorden de står på.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Men på den dag vil jeg undta Gosen, hvor mitt folk bor, så det ikke skal være fluesvermer der; da skal du kjenne at jeg, Herren, er midt i landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'For jeg vil frelse mitt folk og gjøre forskjell på mitt folk og ditt folk; imorgen skal dette tegn skje.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Og Herren gjorde som han hadde sagt, og det kom svære fluesvermer i Faraos hus og i hans tjeneres hus; i hele Egypten blev landet herjet av fluesvermer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Da kalte Farao Moses og Aron til sig og sa: Gå og ofre til eders Gud her i landet!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Men Moses sa: Det er ikke rådelig å gjøre så; for det vi ofrer til Herren vår Gud, er en vederstyggelighet for egypterne; om vi nu ofret for egypternes øine det som er en vederstyggelighet for dem, vilde de da ikke stene oss?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Tre dagsreiser vil vi gå ut i ørkenen og ofre til Herren vår Gud, således som han byder oss.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Da sa Farao: Jeg vil la eder fare, så I kan ofre til Herren eders Gud i ørkenen; men I må ikke dra langt bort. Bed for mig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Moses svarte: Se, jeg går nu ut og vil bede til Herren, og imorgen skal fluesvermene vike bort fra Farao, fra hans tjenere og fra hans folk; bare nu Farao ikke mere vil bruke svik, men la folket fare, så de kan ofre til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Så gikk Moses ut fra Farao og bad til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Og Herren gjorde som Moses bad, og lot fluesvermene vike bort fra Farao, fra hans tjenere og fra hans folk; det blev ikke én igjen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Men Farao forherdet sitt hjerte også denne gang; han lot ikke folket fare.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Og Herren sa til Moses: Gå inn til Farao og si til ham: Så sier Herren, hebreernes Gud: La mitt folk fare, så de kan tjene mig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'For dersom du nekter å la dem fare og fremdeles holder på dem,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'da skal Herrens hånd komme over ditt fe på marken, over hestene, over asenene, over kamelene, over storfeet og over småfeet med en forferdelig pest.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Men Herren skal gjøre forskjell på Israels fe og egypternes fe, og det skal ikke dø noget av alt det som hører Israels barn til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Og Herren fastsatte tiden og sa: Imorgen vil Herren la dette skje i landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Dagen efter gjorde Herren som han hadde sagt, og alt egypternes fe døde, men av Israels barns fe døde ikke ett liv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Og Farao sendte bud, og da var det ikke død et eneste liv av Israels fe; men Faraos hjerte blev hårdt, og han lot ikke folket fare.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Da sa Herren til Moses og Aron: Ta hendene fulle av aske fra ovnen, og Moses skal kaste den op i været så Farao ser på det,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'og den skal bli til støv utover hele Egyptens land, og den skal bli til bylder som bryter ut med blemmer, både på folk og fe i hele Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Så tok de asken fra ovnen og trådte frem for Farao, og Moses kastet den op i været; og det blev bylder som brøt ut med blemmer, både på folk og fe.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Og tegnsutleggerne kunde ikke holde stand mot Moses for byldenes skyld; for det var kommet bylder på tegnsutleggerne og på alle egypterne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Men Herren forherdet Faraos hjerte, så han ikke hørte på dem, således som Herren hadde sagt til Moses');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Da sa Herren til Moses: Stå tidlig op imorgen, og tred frem for Farao og si til ham: Så sier Herren, hebreernes Gud: La mitt folk fare, så de kan tjene mig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'For denne gang vil jeg sende alle mine plager over dig selv og over dine tjenere og ditt folk, forat du skal kjenne at ingen er som jeg på hele jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'For nu hadde jeg allerede rakt ut min hånd og vilde slått dig og ditt folk med pesten, så du var blitt utslettet av jorden;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'men derfor lot jeg dig bli i live at jeg kunde vise dig min makt, og mitt navn kunde bli kunngjort over hele jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Ennu stiller du dig i veien for mitt folk og vil ikke la dem fare.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Se, jeg vil på denne tid imorgen sende et forferdelig haglvær, som det aldri har vært make til i Egypten, like fra den dag det blev til, og til nu.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Så send da folk og berg din buskap og alt det du har på marken! Alt folk og alt fe som er ute på marken og ikke har kommet sig i hus, på dem skal haglet falle, og de skal dø.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'De av Faraos tjenere som fryktet Herrens ord, berget da sine folk og sin buskap i hus;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'men de som ikke gav akt på Herrens ord, lot sine folk og sin buskap bli ute på marken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Da sa Herren til Moses: Rekk din hånd op mot himmelen, og det skal komme hagl i hele Egyptens land, både over folk og fe og over alle markens urter i Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Og Moses rakte sin stav op mot himmelen, og Herren lot komme torden og hagl, og det fôr ild ned på jorden, og Herren lot falle hagl over Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Det kom hagl, og midt i haglskuren lyn i lyn, et uvær så svært at det aldri hadde vært maken i hele Egyptens land fra den tid folk hadde bosatt sig der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Og i hele Egyptens land slo haglet ned alt det som var på marken, både folk og fe; og alle markens urter slo haglet ned, og alle markens trær brøt det sønder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Bare i Gosens land, hvor Israels barn bodde, falt det ikke hagl.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Da sendte Farao bud efter Moses og Aron og sa til dem: Denne gang har jeg syndet; Herren er den som har rett, og jeg og mitt folk har urett.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Bed til Herren at det nu må være nok av hans torden og hagl! Så vil jeg la eder fare, og I skal ikke bie lenger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Moses svarte ham: Så snart jeg kommer ut av byen, vil jeg utbrede mine hender til Herren; så skal tordenen holde op og haglet ikke falle mere, forat du skal kjenne at jorden hører Herren til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Men om dig og dine tjenere vet jeg at I ennu ikke frykter for Gud Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Lin og bygg var slått ned; for bygget stod i aks og linet i knopp;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'men hvete og spelt var ikke slått ned, for de kommer senere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Og Moses gikk bort fra Farao og ut av byen og utbredte sine hender til Herren; da holdt tordenen og haglet op, og regnet strømmet ikke mere ned på jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Men da Farao så at regnet og haglet og tordenen hadde holdt op, blev han ved å synde, og han forherdet sitt hjerte, både han og hans tjenere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Faraos hjerte var og blev forherdet, og han lot ikke Israels barn fare, således som Herren hadde sagt ved Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Og Herren sa til Moses: Gå inn til Farao! For det er jeg som har forherdet hans hjerte og hans tjeneres hjerte, forat jeg kan gjøre disse mine tegn midt iblandt dem,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'og forat du skal fortelle din sønn og din sønnesønn hvad jeg har gjort mot egypterne, og hvad tegn jeg har gjort iblandt dem, så I skal kjenne at jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Så gikk Moses og Aron inn til Farao og sa til ham: Så sier Herren, hebreernes Gud: Hvor lenge vil du la være å ydmyke dig for mig? La mitt folk fare, så de kan tjene mig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'For dersom du nekter å la mitt folk fare, da vil jeg imorgen la gresshopper komme over ditt land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Og de skal dekke landet, så ingen kan se jorden, og de skal ete op hvert eneste grand av det som blev tilovers for eder efter haglet, og de skal avete hvert tre som vokser på eders marker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Og de skal fylle dine hus og alle dine tjeneres hus og alle egypternes hus, så hverken dine fedre eller dine fedres fedre har sett noget slikt fra den tid de blev til på jorden, og til denne dag. Dermed vendte han sig om og gikk ut fra Farao.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Da sa Faraos tjenere til ham: Hvor lenge skal denne mann være en snare for oss? La mennene fare, så de kan tjene Herren sin Gud! Ser du ikke ennu at Egypten blir ødelagt?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Så blev Moses og Aron hentet tilbake til Farao, og han sa til dem: Gå avsted, tjen Herren eders Gud! Men hvem er det som skal fare?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Moses svarte: Vi vil fare alle, både unge og gamle; både våre sønner og våre døtre vil vi ha med, både vårt småfe og vårt storfe; for vi skal holde høitid for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Da sa han til dem: Herren være med eder, så visst som jeg lar eder og eders små barn fare! Se der om I ikke har ondt i sinne!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Nei, ikke så! I menn kan fare og tjene Herren! For det var jo det I bad om. Dermed drev de dem ut fra Farao.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Da sa Herren til Moses: Rekk ut din hånd over Egyptens land, så skal gresshoppene komme inn over Egyptens land og ete op alle urter i landet, alt det haglet har levnet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Så rakte Moses ut sin stav over Egyptens land, og Herren lot en østenvind komme over landet hele den dag og hele natten; da det blev morgen, førte østenvinden gresshoppene med sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Og gresshoppene kom inn over hele Egyptens land og slo sig ned i hele Egypten i store mengder; aldri hadde det før vært en slik gresshoppesverm, og aldri vil det komme nogen slik mere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'De dekket hele landet, så landet blev mørkt, og de åt op alle urter i landet og all frukt på trærne som haglet hadde levnet, og det blev intet grønt tilbake på trærne eller på markens urter i hele Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Da skyndte Farao sig og sendte bud efter Moses og Aron og sa: Jeg har syndet mot Herren eders Gud og mot eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Men forlat mig nu min synd denne ene gang, og bed til Herren eders Gud at han bare vil avvende denne død fra mig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Og han gikk ut igjen fra Farao og bad til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Og Herren vendte vinden, så det blev en meget sterk vestenvind, og den førte gresshoppene bort og kastet dem ned i det Røde Hav; det blev ikke én gresshoppe tilbake i hele Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Men Herren forherdet Faraos hjerte, så han ikke lot Israels barn fare.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Og Herren sa til Moses: Rekk din hånd op mot himmelen, og det skal bli mørke over Egyptens land, et mørke så tykt at en kan ta på det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Så rakte Moses sin hånd op mot himmelen, og det blev et tykt mørke i hele Egyptens land i tre dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Den ene kunde ikke se den andre, og ingen torde flytte sig fra sin plass i tre dager; men hos alle Israels barn var det lyst der de bodde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Da kalte Farao Moses til sig og sa: Gå avsted, tjen Herren! Bare eders småfe og eders storfe skal bli tilbake; også eders små barn kan få dra med eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Men Moses sa: Du må også la oss få slaktoffer og brennoffer med, så vi kan ofre til Herren vår Gud;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'også vår buskap må være med oss, ikke en klov må bli igjen; for det er det vi må ta av når vi skal tjene Herren vår Gud, og vi vet ikke hvad vi skal ofre til Herren før vi kommer dit.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Men Herren forherdet Faraos hjerte, så han ikke vilde la dem fare.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Og Farao sa til Moses: Gå fra mig, vokt dig, kom ikke mere for mine øine! For på den dag du kommer for mine øine, skal du dø!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Moses svarte: Du har talt rett; jeg skal aldri mere komme for dine øine.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Herren hadde sagt til Moses: Ennu én plage vil jeg la komme over Farao og over Egypten, så skal han la eder fare herfra; ja, når han lar eder fare, skal han endog drive eder herfra med alt det I har.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Si nu så folket hører det at hver mann skal be sin granne og hver kvinne sin grannekvinne om smykker av sølv og gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Og Herren gav folket yndest hos egypterne; og så var også Moses en meget stor mann i Egypten, både for Faraos tjenere og for folket.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Og Moses sa: Så sier Herren: Ved midnatts tid vil jeg gå midt gjennem Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'og alle førstefødte i Egyptens land skal dø, fra den førstefødte sønn av Farao, som sitter på sin trone, til den førstefødte sønn av trælkvinnen, som står bak håndkvernen, og alt førstefødt blandt buskapen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Og det skal i hele Egyptens land bli et stort skrik som det ikke har vært maken til og heller ikke mere skal bli.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Men ikke en hund skal gjø mot nogen av Israels barn, hverken mot folk eller fe, så I skal kjenne at Herren gjør forskjell på egypterne og Israel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Da skal alle disse dine tjenere komme ned til mig og bøie sig for mig og si: Dra ut, både du og hele det folk som følger dig! Og så skal jeg dra ut. Og han gikk bort fra Farao i brennende harme.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Som Herren hadde sagt til Moses og Aron: Farao skal ikke høre på eder, så jeg kan få gjort mange under i Egyptens land,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'så gjorde Moses og Aron alle disse under for Farao; men Herren forherdet Faraos hjerte, så han ikke lot Israels barn dra bort fra sitt land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Og Herren sa til Moses og Aron i Egyptens land:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Denne måned skal være eders nytt årsmåned, den skal være den første av årets måneder hos eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Tal til hele Israels menighet og si: På den tiende dag i denne måned skal hver husfar ta sig ut et lam, et lam for hvert hus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Men dersom huset er for lite til et lam, skal han og hans nærmeste nabo ta et lam sammen efter tallet på deres husfolk; efter hvad enhver eter, skal I regne folk på hvert lam.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Det skal være et lam uten lyte, av hankjønn, årsgammelt; et lam eller et kje kan I ta.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Og I skal gjemme det til den fjortende dag i denne måned; da skal hele Israels samlede menighet slakte det mellem de to aftenstunder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Og de skal ta av blodet og stryke på begge dørstolpene og på det øverste dørtre på de hus hvor de eter det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Og de skal ete kjøttet samme natt; stekt ved ild og med usyret brød og bitre urter skal de ete det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'I må ikke ete noget av det rått eller kokt i vann, men stekt ved ild, med hode, føtter og innvoller.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Og I skal ikke levne noget av det til om morgenen; er det noget igjen om morgenen, skal I brenne det op i ilden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Og således skal I ete det: med ombundne lender, med sko på føttene og med stav i hånd, og I skal ete det i hast; det er påske for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'For samme natt vil jeg gå igjennem Egyptens land og slå ihjel alt førstefødt i Egyptens land, både folk og fe, og over alle Egyptens guder vil jeg holde dom; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Og blodet på de hus som I er i, skal være til et tegn for eder; når jeg ser blodet, vil jeg gå eder forbi; og ikke skal noget slag ramme eder til ødeleggelse når jeg slår Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Og denne dag skal være en minnedag for eder, og I skal holde den som en høitid for Herren; det skal være en evig forskrift for eder å holde den, slekt efter slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'I syv dager skal I ete usyret brød. Straks på den første dag skal I ha all surdeig bort av eders hus; enhver som eter syret brød fra den første til den syvende dag, han skal utryddes av Israel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Og på den første dag skal I holde en hellig sammenkomst, og likeså på den syvende dag en hellig sammenkomst. Intet arbeid skal gjøres nogen av de dager; bare den mat som enhver av eder trenger, må I lage til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'I skal holde de usyrede brøds høitid, for på denne samme dag førte jeg eders hærer ut av Egyptens land; derfor skal det være en evig forskrift for eder å holde denne dag, slekt efter slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'I den første måned, på den fjortende dag i måneden om aftenen skal I ete usyret brød, og det skal I gjøre helt til den enogtyvende dag om aftenen i samme måned.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'I syv dager skal det ikke finnes surdeig i eders hus; enhver som eter syret brød, han skal utryddes av Israels menighet, enten han er en fremmed eller innfødt i landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Intet syret skal I ete, i alle hus skal I ete usyret brød.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Da kalte Moses alle Israels eldste til sig og sa til dem: Gå og hent småfe for eders familier og slakt påskelammet!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Og I skal ta et knippe isop og dyppe i blodet som er i skålen, og stryke på det øverste dørtre og på begge dørstolpene noget av blodet i skålen, og ingen av eder skal gå ut av sin husdør før om morgenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'For Herren skal gå igjennem landet for å slå egypterne, og når han ser blodet på det øverste dørtre og på begge dørstolpene, skal han gå døren forbi og ikke la ødeleggeren få komme inn i eders hus og slå eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Dette skal I holde; det skal være en forskrift for dig og dine barn til evig tid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Og når I kommer inn i det land Herren skal gi eder, således som han har lovt, da skal I holde denne tjeneste.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Og når eders barn sier til eder: Hvad er dette for en tjeneste som I holder? -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'da skal I si: Det er påskeoffer for Herren, som gikk forbi Israels barns hus i Egypten da han slo egypterne og fridde våre hus. Og folket bøide sig og tilbad.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Og Israels barn gikk bort og gjorde dette; som Herren hadde sagt til Moses og Aron, således gjorde de.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Så skjedde det ved midnatts tid at Herren slo ihjel alle førstefødte i Egyptens land, fra den førstefødte sønn av Farao, som satt på sin trone, til den førstefødte sønn av fangen, som var i fengslet, og alt førstefødt blandt buskapen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Da stod Farao op om natten, han og alle hans tjenere og alle egypterne, og det blev et stort skrik i Egypten; for det var ikke et hus hvor det ikke var en død.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Og han kalte Moses og Aron til sig om natten og sa: Gjør eder rede, dra ut fra mitt folk, både I og Israels barn, far bort og tjen Herren, som I har sagt!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Ta med eder både eders småfe og eders storfe, som I har sagt, gå og bed godt også over mig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Og egypterne trengte hårdt på folket for å få dem hastig ut av landet; for de sa: Vi er dødsens alle sammen!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Så tok folket sin deig, før den var syret; de svøpte sine deigtrau i sine klær og bar dem på sine skuldrer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Og Israels barn gjorde som Moses hadde sagt, og bad egypterne om smykker av sølv og gull og om klær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Og Herren gav folket yndest hos egypterne, så de gjerne gav dem det de bad om. Det var det bytte de tok av egypterne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Så brøt da Israels barn op fra Ra\'amses og tok veien til Sukkot, omkring seks hundre tusen mann til fots foruten barna.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Og det drog også en stor hop av alle slags folk med dem, og småfeet og storfeet, en overmåte stor mengde fe.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Av den deig de hadde med sig fra Egypten, bakte de usyrede kaker; for den var ikke syret, fordi de var drevet ut av Egypten og ikke torde dryge der lenger; heller ikke hadde de laget i stand reisekost.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Men den tid Israels barn hadde bodd i Egypten, var fire hundre og tretti år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'På den dag de fire hundre og tretti år var til ende, da var det alle Herrens hærer drog ut av Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Denne natt tok Herren i akt for å føre dem ut av Egyptens land; den samme natt skal alle Israels barn ta i akt for Herren, slekt efter slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Og Herren sa til Moses og Aron: Dette er forskriften om påskelammet: Ingen fremmed skal ete av det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Men enhver træl som er kjøpt for sølv, ham skal du omskjære; da kan han ete av det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Ingen innerst eller dagarbeider skal ete av det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'I ett hus skal det etes; du skal ikke la noget av kjøttet komme utenfor huset, og I skal ikke bryte noget ben på det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Således skal hele Israels menighet gjøre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Og når en fremmed opholder sig hos dig og vil holde påske for Herren, skal alt mannkjønn hos ham omskjæres, og da kan han få være med og holde den; han skal være som en innfødt i landet; men ingen uomskåret skal ete av det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Det skal være en og samme lov for den innfødte og for den fremmede som opholder sig hos eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Og alle Israels barn gjorde således; som Herren hadde befalt Moses og Aron, således gjorde de.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'På denne samme dag var det Herren førte Israels barn ut av Egyptens land, hær efter hær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Du skal hellige mig alt førstefødt, alt det som åpner morsliv blandt Israels barn, enten det er folk eller fe! Mig hører det til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Og Moses sa til folket: Kom i hu denne dag da I gikk ut av Egypten, av trælehuset, for med sterk hånd førte Herren eder ut derfra! Da skal I ikke ete syret brød.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Idag drar I ut, i måneden abib.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Når da Herren fører dig inn i kana\'anittenes og hetittenes og amorittenes og hevittenes og jebusittenes land, som han tilsvor dine fedre å gi dig, et land som flyter med melk og honning, da skal du holde denne tjeneste i denne måned.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'I syv dager skal du ete usyret brød, og på den syvende dag skal det være høitid for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Usyret brød skal du ete alle de syv dager, det skal ikke finnes syret brød hos dig, og ikke surdeig i hele ditt land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Og samme dag skal du fortelle din sønn det og si: Dette er til minne om det som Herren gjorde for mig da jeg drog ut av Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Og det skal være dig til et tegn på din hånd og til en minneskrift på din panne, forat Herrens lov skal være i din munn; for med sterk hånd førte Herren dig ut av Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Og du skal gjøre efter denne lov til fastsatt tid, år efter år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Og når Herren har ført dig til kana\'anittenes land, således som han tilsvor dig og dine fedre, og gir dig det,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'da skal du overgi til Herren alt det som åpner morsliv; alt som åpner morsliv, som faller av det fe du har, hvis det er av hankjønn, hører det Herren til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Og alt som åpner morsliv blandt asen, skal du løse med et stykke småfe; men hvis du ikke løser det, skal du bryte nakken på det; og alt førstefødt av mennesker, blandt dine sønner, skal du løse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Og når din sønn siden spør dig og sier: Hvad betyr dette? da skal du svare ham: Med sterk hånd førte Herren oss ut av Egypten, av trælehuset.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'For dengang da Farao satte sig hårdt imot å la oss fare, da slo Herren ihjel alt førstefødt i Egyptens land, både folk og fe; derfor ofrer jeg Herren alt det som åpner morsliv, det som er av hankjønn, og alle førstefødte blandt mine sønner løser jeg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Og det skal være til et tegn på din hånd og til en minneseddel på din panne; for med sterk hånd førte Herren oss ut av Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Da nu Farao lot folket fare, da førte Gud dem ikke på veien til filistrenes land, skjønt den var den nærmeste; for Gud sa: Folket kunde angre det når de ser krig for sig, og så vende tilbake til Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Men Gud lot folket ta omveien gjennem ørkenen mot det Røde Hav. Og Israels barn drog fullt rustet ut av Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Og Moses tok Josefs ben med sig; for Josef hadde tatt en ed av Israels barn og sagt: Gud skal visselig se til eder, og da skal I føre mine ben med eder op herfra.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Så brøt de op fra Sukkot og slo leir i Etam ved grensen av ørkenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Og Herren gikk foran dem, om dagen i en skystøtte for å lede dem på veien og om natten i en ildstøtte for å lyse for dem, så de kunde dra frem både dag og natt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Skystøtten vek ikke fra folket om dagen, ikke heller ildstøtten om natten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Si til Israels barn at de skal vende om og slå leir foran Pi-Hakirot, mellem Migdol og havet; midt imot Ba\'al-Sefon, der skal I slå leir ved havet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Farao vil da si om Israels barn: De farer vill i landet, ørkenen har lukket dem inne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Og jeg vil forherde Faraos hjerte, så han forfølger dem, og jeg vil åpenbare min herlighet på Farao og hele hans hær, og egypterne skal kjenne at jeg er Herren. Og de gjorde så.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Da det nu blev meldt kongen i Egypten at folket var flyktet, skiftet Farao og hans tjenere sinn mot folket, og de sa: Hvorledes kunde vi gjøre dette og la Israel dra bort fra vår tjeneste?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Så lot han spenne for sin vogn og tok sitt hærfolk med sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Han tok seks hundre utvalgte vogner og alle de andre vogner i Egypten, og krigsmenn var det på dem alle.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'For Herren forherdet Faraos, egypterkongens, hjerte, så han forfulgte Israels barn; men Israels barn drog ut med løftet hånd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Så forfulgte egypterne dem og nådde dem igjen da de lå i leir ved havet, alle Faraos vogner og hestfolk og hele hans hær, ved Pi-Hakirot, foran Ba\'al-Sefon.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Og Farao kom nærmere og nærmere, og da Israels barn så sig om, fikk de se egypterne komme settende efter dem; da kom det stor redsel over Israels barn, og de ropte til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Og de sa til Moses: Var det da ingen graver i Egypten siden du har ført oss hit for å dø i ørkenen? Hvorfor har du gjort dette mot oss og ført oss ut av Egypten?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Var det ikke det vi sa til dig i Egypten: La oss være i fred, vi vil tjene egypterne; det er bedre for oss å tjene egypterne enn å dø i ørkenen?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Da sa Moses til folket: Frykt ikke, stå nu her og se Herrens frelse, som han vil sende eder idag! For som I ser egypterne idag, skal I aldri i evighet se dem mere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Herren skal stride for eder, og I skal være stille.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Og Herren sa til Moses: Hvorfor roper du til mig? Si til Israels barn at de skal bryte op!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Løft nu du op din stav og rekk ut din hånd over havet og skill det at, og Israels barn skal gå midt igjennem havet på det tørre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Men jeg vil forherde egypternes hjerte, så de setter efter eder; og jeg vil åpenbare min herlighet på Farao og hele hans hær, på hans vogner og hestfolk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Og egypterne skal kjenne at jeg er Herren, når jeg åpenbarer min herlighet på Farao, på hans vogner og hestfolk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Og Guds engel, som gikk foran Israels leir, flyttet sig og gikk bakefter dem; skystøtten, som var foran dem, flyttet sig og stilte sig bak dem,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'så den kom imellem egypternes leir og Israels leir; på den ene side var den sky og mørke, og på den annen side lyste den op natten; og den ene leir kom ikke inn på den andre hele natten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Da rakte Moses ut sin hånd over havet, og Herren drev havet bort med en sterk østenvind, som blåste hele natten, og han gjorde havet til tørt land, og vannet skiltes at.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Og Israels barn gikk midt igjennem havet på det tørre, og vannet stod som en mur på deres høire og på deres venstre side.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Og egypterne satte efter og fulgte dem til midt ut i havet, alle Faraos hester, hans vogner og hestfolk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Men ved morgenvaktens tid skuet Herren fra ild- og skystøtten ned på egypternes leir, og han forvirret egypternes leir,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'og han slo hjulene av deres vogner, så det blev tungt for dem å komme frem. Da sa egypterne: La oss flykte for Israel; for Herren strider for dem imot egypterne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Da sa Herren til Moses: Rekk ut din hånd over havet, så skal vannet vende tilbake over egypterne, over deres vogner og deres hestfolk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Så rakte Moses ut sin hånd over havet, og da det led mot morgenen, vendte havet tilbake til sitt vanlige leie, og egypterne flyktet like mot det; og Herren styrtet egypterne midt ut i havet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Vannet vendte tilbake og skjulte vognene og hestfolket i hele Faraos hær, som var kommet efter dem ut i havet; det blev ikke en eneste tilbake av dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Men Israels barn gikk på det tørre midt igjennem havet, og vannet stod som en mur på deres høire og på deres venstre side.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Således frelste Herren den dag Israel av egypternes hånd, og Israel så egypterne ligge døde på havstranden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Og da Israel så den veldige gjerning Herren hadde gjort med egypterne, da fryktet folket Herren; og de trodde på Herren og på hans tjener Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Da sang Moses og Israels barn denne sang for Herren: Jeg vil lovsynge Herren, for han er høit ophøiet; hest og mann styrtet han i havet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Herren er min styrke og lovsang, og han blev mig til frelse; han er min Gud, og jeg vil prise ham, min fars Gud, og jeg vil ophøie ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Herren er en stridsmann, Herren er hans navn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Faraos vogner og hans hær kastet han i havet, og hans utvalgte vognkjempere druknet i det Røde Hav.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Avgrunner skjulte dem, de sank som sten i dype vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Din høire hånd, Herre, er herliggjort i kraft, din høire hånd, Herre, knuser fiender.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Og i din høihets velde slår du dine motstandere ned; du slipper din vrede løs, den fortærer dem som strå.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Og ved ditt åndepust hopet vannene sig sammen, bølgene stod som voller, dype vann stivnet i havets hjerte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Fienden sa: Jeg vil forfølge dem, jeg vil innhente dem, jeg vil dele ut hærfang, jeg vil mette min sjel med dem; jeg vil dra mitt sverd, min hånd skal utrydde dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Du blåste med din ånde, havet skjulte dem; de sank som bly i de veldige vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Herre, hvem er som du blandt gudene? Hvem er som du herliggjort i hellighet, forferdelig å love, underfull i gjerning?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Du rakte ut din høire hånd, jorden slukte dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Du fører ved din miskunnhet det folk som du forløste; du leder dem ved din kraft til din hellige bolig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Folkene hører det, de skjelver; angst griper dem som bor i Filisterland.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Da forferdes Edoms stammefyrster, redsel griper Moabs høvdinger, alle Kana\'ans innbyggere forgår av angst.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Forferdelse og redsel faller over dem, ved din arms velde blir de målløse som sten, mens ditt folk drar frem, Herre, mens det folk drar frem som du har vunnet dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Du fører dem inn og planter dem på din arvs berg, det sted du har skapt dig til bolig, Herre, den helligdom, Herre, som dine hender har grunnlagt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Herren skal være konge i all evighet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'For da Faraos hester med hans vogner og menn for ut i havet, da lot Herren havets vann vende tilbake over dem, mens Israels barn gikk på det tørre midt igjennem havet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Og profetinnen Mirjam, Arons søster, tok en tromme i sin hånd, og alle kvinnene gikk efter henne med trommer og dans.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Og Mirjam sang fore: Lovsyng Herren, for han er høit ophøiet; hest og mann styrtet han i havet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Så lot Moses Israel bryte op fra det Røde Hav, og de drog ut i ørkenen Sur; og tre dager drog de frem i ørkenen uten å finne vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Så kom de til Mara; men de kunde ikke drikke vannet i Mara fordi det var beskt; derfor blev stedet kalt Mara.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Da knurret folket mot Moses og sa: Hvad skal vi drikke?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Og han ropte til Herren, og Herren viste ham et tre; det kastet han i vannet, og vannet blev godt. Der satte han dem lov og rett, og der prøvde han dem;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'og han sa: Dersom du hører på Herren din Guds røst, og gjør det som er rett i hans øine, og gir akt på hans bud, og holder alle hans forskrifter, da vil jeg ikke legge på dig nogen av de sykdommer som jeg la på egypterne; for jeg er Herren, din læge.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Så kom de til Elim; der var tolv vannkilder og sytti palmetrær; og de slo leir der ved vannet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Så brøt de op fra Elim, og den femtende dag i den annen måned efterat de hadde draget ut av Egyptens land, kom hele Israels barns menighet til ørkenen Sin, som ligger mellem Elim og Sinai.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Og hele Israels barns menighet knurret mot Moses og Aron i ørkenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Og Israels barn sa til dem: Å, om vi var død for Herrens hånd i Egyptens land da vi satt ved kjøttgrytene, og da vi åt brød til vi blev mette! For I har ført oss hit ut i ørkenen for å la hele denne store folkeskare dø av hunger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Da sa Herren til Moses: Se, jeg vil la regne ned brød fra himmelen til eder, og folket skal gå ut og sanke for hver dag det de trenger; således vil jeg prøve dem, om de vil følge min lov eller ikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Og på den sjette dag skal de lage til det som de har hatt med hjem, og det skal være dobbelt så meget som det de ellers sanker for hver dag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Og Moses og Aron sa til alle Israels barn: Iaften skal I kjenne at det er Herren som har ført eder ut av Egyptens land,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'og imorgen skal I få se Herrens herlighet, fordi han har hørt hvorledes I knurrer mot ham; for hvad er vi, at I knurrer mot oss?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Så sa Moses: I skal få se det når Herren iaften gir eder kjøtt å ete og imorgen brød, så I blir mette; for Herren har hørt hvorledes I knurrer og murrer mot ham; for hvad er vel vi? Det er ikke mot oss I knurrer, men mot Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Og Moses sa til Aron: Si til hele Israels barns menighet: Kom frem for Herrens åsyn; for han har hørt hvorledes I knurrer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Da så Aron talte til hele Israels barns menighet, vendte de sig mot ørkenen, og se, Herrens herlighet åpenbarte sig i skyen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Jeg har hørt hvorledes Israels barn knurrer; tal til dem og si: Imellem de to aftenstunder skal I få kjøtt å ete, og imorgen skal I mettes med brød, og I skal kjenne at jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Da det nu blev aften, kom det vaktler og dekket leiren, og om morgenen var det et lag av dugg rundt omkring leiren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Og da duggen gikk bort, se, da lå det utover ørkenen noget fint, kornet, fint som rim på jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Da Israels barn så det, sa de til hverandre: Hvad er det? for de visste ikke hvad det var. Da sa Moses til dem: Det er det brød Herren har gitt eder å ete.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Således har Herren befalt: Sank av det efter som enhver trenger, en omer til manns efter tallet på eders husfolk; enhver skal ta for dem som er i hans telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Og Israels barn gjorde således, og de sanket, den ene meget, den andre lite.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Og da de målte det med omeren, hadde den som hadde sanket meget, intet tilovers, og den som hadde sanket lite, fattedes intet; enhver hadde sanket efter som han trengte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Og Moses sa til dem: Ingen skal levne noget av det til om morgenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Men de lød ikke Moses, for nogen levnet noget av det til om morgenen; da vokste det makk i det, og det luktet ille. Og Moses blev vred på dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Siden sanket de det hver morgen efter som enhver trengte; men når solen brente hett, smeltet det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'På den sjette dag sanket de dobbelt så meget brød, to omer for hver; og alle menighetens høvdinger kom og meldte det til Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Da sa han til dem: Det er det Herren har sagt. Imorgen er det sabbat, hellig sabbat for Herren; bak nu det I vil bake, og kok det I vil koke, men alt det som blir tilovers, skal I legge til side og gjemme til imorgen!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Så lot de det ligge til om morgenen, således som Moses hadde befalt; og det luktet ikke, heller ikke var det makk i det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Da sa Moses: Et det idag. For idag er det sabbat for Herren; idag finner I ikke noget på marken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'I seks dager skal I sanke det; men på den syvende dag er det sabbat, da skal det ikke være å finne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Allikevel gikk nogen av folket ut den syvende dag for å sanke; men de fant intet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Da sa Herren til Moses: Hvor lenge vil I være gjenstridige og ikke holde mine bud og mine lover?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Kom i hu at Herren har gitt eder sabbaten; derfor gir han eder på den sjette dag brød for to dager; bli hjemme enhver hos sig, ingen gå hjemmefra på den syvende dag!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Så hvilte folket på den syvende dag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Og israelittene kalte det manna; det lignet korianderfrø, det var hvitt, og det smakte som honningkake.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Og Moses sa: Således har Herren befalt: Fyll en omer av det og gjem det for eders efterkommere, så de kan se det brød jeg gav eder å ete i ørkenen da jeg førte eder ut av Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Så sa Moses til Aron: Ta en krukke og legg i den en full omer manna, og sett den ned for Herrens åsyn til å gjemmes for eders efterkommere!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Som Herren hadde befalt Moses, således satte Aron den ned foran vidnesbyrdet til å gjemmes.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Og Israels barn åt manna i firti år, inntil de kom til bygget land; de åt manna helt til de kom til grensen av Kana\'ans land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'En omer er tiendedelen av en efa.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Så drog hele Israels barns menighet fra ørkenen Sin i dagsreiser efter Herrens befaling; de slo leir i Refidim, og folket hadde ikke vann å drikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Da kivedes folket med Moses og sa: Gi oss vann, så vi får drikke! Moses svarte dem: Hvorfor kives I med mig? Hvorfor frister I Herren?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Men folket tørstet efter vann og knurret mot Moses og sa: Hvorfor har du ført oss op fra Egypten for å la oss og våre barn og vår buskap dø av tørst?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Da ropte Moses til Herren og sa: Hvad skal jeg gjøre med dette folk? Det er ikke langt fra at de stener mig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Og Herren sa til Moses: Gå frem foran folket og ta med dig nogen av Israels eldste, og din stav som du slo i elven med, ta den i hånden og gå!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Se, jeg vil stå der foran dig på klippen ved Horeb, og du skal slå på klippen, og det skal flyte vann ut av den, så folket får drikke. Og Moses gjorde således så Israels eldste så på det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Og han kalte stedet Massa og Meriba, fordi Israels barn kivedes med ham, og fordi de fristet Herren og sa: Er Herren iblandt oss eller ikke?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Så kom Amalek og stred med Israel i Refidim.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Da sa Moses til Josva: Velg oss ut mannskap, dra så avsted og strid mot Amalek! Imorgen vil jeg stå øverst på haugen med Guds stav i min hånd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Og Josva gjorde som Moses hadde sagt ham, og stred mot Amalek; og Moses, Aron og Hur steg op øverst på haugen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Da gikk det så at så lenge Moses holdt sin hånd opløftet, hadde Israel overtaket; men når han lot sin hånd synke, da fikk Amalek overtaket.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Men da Moses\' hender blev tunge, tok de en sten og la under ham, og han satte sig på den; og Aron og Hur støttet hans hender, den ene på den ene side og den andre på den andre side; så holdt hans hender sig støe helt til solen gikk ned.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Og Josva hugg Amalek og hans folk ned med sverdets egg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Og Herren sa til Moses: Skriv dette op i en bok, så I kommer det i hu, og prent det i Josvas ører! For jeg vil aldeles utslette minnet om Amalek over hele jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Så bygget Moses et alter og kalte det: Herren er mitt banner.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Og han sa: En hånd er utrakt fra Herrens trone! Herren skal stride mot Amalek fra slekt til slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Jetro, presten i Midian, Moses\' svigerfar, fikk høre alt det Gud hadde gjort for Moses og for sitt folk Israel, hvorledes Herren hadde ført Israel ut av Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Da tok Jetro, Moses\' svigerfar, Sippora, Moses\' hustru, som Moses før hadde sendt hjem,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'og hennes to sønner - den ene hette Gersom, for Moses hadde sagt: Jeg er blitt gjest i et fremmed land,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'og den andre hette Elieser, for han hadde sagt: Min fars Gud var min hjelp og fridde mig fra Faraos sverd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Da nu Jetro, Moses\' svigerfar, kom med hans sønner og hans hustru til ham i ørkenen, der hvor Moses hadde slått leir, ved Guds berg,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'sendte han bud til Moses og sa: Jeg, din svigerfar Jetro, kommer til dig med din hustru og hennes to sønner.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Da gikk Moses sin svigerfar møte, bøide sig for ham og kysset ham, og de spurte hverandre hvorledes det stod til; så gikk de inn i teltet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Og Moses fortalte sin svigerfar alt det Herren hadde gjort med Farao og egypterne for Israels skyld, og all den møie de hadde hatt på veien, og hvorledes Herren hadde hjulpet dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Da blev Jetro glad over alt det gode Herren hadde gjort mot Israel, at han hadde fridd dem av egypternes hånd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Og Jetro sa: Lovet være Herren, som fridde eder av egypternes hånd Og av Faraos hånd - han som fridde folket av egypternes hånd!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nu vet jeg at Herren er større enn alle guder; for således viste han sig ved det hvormed egypterne viste sitt overmot mot dette folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Og Jetro, Moses\' svigerfar, tok og ofret brennoffer og slaktoffer til Gud; og Aron og alle Israels eldste kom og holdt måltid med Moses\' svigerfar for Guds åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Dagen efter satt Moses og skiftet rett mellem folket, og folket stod omkring Moses fra morgen til kveld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Da Moses\' svigerfar så hvor meget han hadde å gjøre for folket, sa han: Hvad er dette for et arbeid du legger på dig for folket? Hvorfor sitter du alene og dømmer mens hele folket står omkring dig fra morgen til kveld?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Moses svarte sin svigerfar: Folket kommer til mig for å få vite Guds vilje;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'når de har en sak, da kommer de til mig, og jeg skifter rett mellem dem og lærer dem Guds bud og lover.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Da sa Moses\' svigerfar til ham: Det er ikke klokt det du her gjør.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Du må jo bli altfor trett, både du og dette folk som er med dig; for dette arbeid er for svært for dig, du makter ikke å gjøre det alene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Men hør nu på mig! Jeg vil gi dig et råd, og Gud skal være med dig. Tred du frem for Gud på folkets vegne og legg deres saker frem for ham,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'forklar dem budene og lovene, og lær dem den vei de skal vandre, og den gjerning de skal gjøre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Velg dig så ut duelige menn av hele folket, menn som frykter Gud, troverdige menn, som hater urettferdig vinning, og sett dem til domsmenn over dem, nogen over tusen, nogen over hundre, nogen over femti og nogen over ti!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Og de skal skifte rett mellem folket til enhver tid; enhver stor sak skal de komme til dig med, men enhver liten sak skal de selv dømme i. Således letter du byrden for dig selv, og de bærer den med dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Dersom du gjør dette, og Gud byder dig det, da vil du kunne holde ut, og da vil også alt folket her kunne gå hjem i fred.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Moses lød sin svigerfars råd og gjorde alt det han sa.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Han valgte ut duelige menn av hele Israel og satte dem til høvdinger over folket, til domsmenn, nogen over tusen, nogen over hundre, nogen over femti og nogen over ti.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Og de skiftet rett mellem folket til enhver tid; enhver vanskelig sak kom de til Moses med, men i enhver liten sak dømte de selv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Så bad Moses farvel med sin svigerfar, og han drog hjem til sitt eget land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'På tremåneders-dagen efterat Israels barn var gått ut av Egyptens land, kom de til Sinai ørken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'De brøt op fra Refidim og kom til Sinai ørken og slo leir i ørkenen, og Israel leiret sig der midt imot fjellet. -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Men Moses steg op til Gud, og Herren ropte til ham fra fjellet og sa: Så skal du si til Jakobs hus og kunngjøre for Israels barn:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'I har sett hvad jeg har gjort med egypterne, og hvorledes jeg har båret eder på ørnevinger og ført eder til mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Dersom I nu lyder min røst og holder min pakt, da skal I være min eiendom fremfor alle folk; for hele jorden hører mig til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Og I skal være mig et kongerike av prester og et hellig folk. Dette er de ord du skal tale til Israels barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Da Moses kom tilbake, kalte han folkets eldste til sig og bar frem for dem alle disse ord som Herren hadde pålagt ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Da svarte folket alle som én og sa: Alt det Herren har sagt, vil vi gjøre. Og Moses bar folkets ord tilbake til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Da sa Herren til Moses: Se, jeg vil komme til dig i en tykk sky, så folket kan høre når jeg taler med dig, og alltid tro på dig. Og Moses bar folkets ord frem for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Og Herren sa til Moses: Gå til folket og la dem hellige sig idag og imorgen og tvette sine klær,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'og la dem holde sig rede den tredje dag; for på den tredje dag skal Herren stige ned på Sinai berg for hele folkets øine.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Og du skal avmerke en grense for folket rundt omkring og si: Vokt eder for å stige op på fjellet eller røre ved dets fot! Enhver som rører ved fjellet, skal visselig late livet;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'ingen hånd skal røre ved ham, han skal stenes eller skytes; enten det er dyr eller mennesker, skal de ikke leve. Når basunen lyder med lange toner, da skal de stige op på fjellet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Så gikk Moses ned fra fjellet til folket, og han lot folket hellige sig og tvette sine klær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Og han sa til folket: Hold eder rede den tredje dag, kom ikke nær nogen kvinne!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Så skjedde det den tredje dag da morgenen brøt frem, da tok det til å tordne og lyne, og det la sig en tung sky over fjellet, og det hørtes en sterk basunlyd; da skalv alt folket som var i leiren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Men Moses førte folket ut av leiren til møte med Gud, og de stilte sig nedenfor fjellet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Og hele Sinai berg stod i røk, fordi Herren var steget ned på det i ild, og røken av det steg op som røken av en ovn, og hele fjellet skalv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Og basunens lyd tok til og blev sterkere og sterkere; Moses talte, og Gud svarte ham med lydelig røst.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Og Herren steg ned på Sinai berg, på fjellets topp; og Herren kalte Moses op på fjellets topp, og Moses steg op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Og Herren sa til Moses: Stig ned og advar folket, så de ikke trenger sig frem til Herren for å se ham, for da kommer mange av dem til å falle.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Også prestene, de som treder Herren nær, skal hellige sig, forat Herren ikke skal bryte inn blandt dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Da sa Moses til Herren: Folket kan ikke stige op på Sinai berg; for du har selv advart oss og sagt at vi skulde avmerke en grense om fjellet og hellige det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Og Herren sa til ham: Stig nu ned og kom så her op igjen, både du og Aron; men prestene og folket må ikke trenge sig frem og stige op til Herren, forat han ikke skal bryte inn blandt dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Da steg Moses ned til folket og sa det til dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Da talte Gud alle disse ord og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Jeg er Herren din Gud, som førte dig ut av Egyptens land, av trælehuset.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Du skal ikke ha andre guder foruten mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Du skal ikke gjøre dig noget utskåret billede eller nogen avbildning av det som er oppe i himmelen, eller av det som er nede på jorden, eller av det som er i vannet nedenfor jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Du skal ikke tilbede dem og ikke tjene dem; for jeg, Herren din Gud, er en nidkjær Gud, som hjemsøker fedres misgjerninger på barn inntil tredje og fjerde ledd, på dem som hater mig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'og som gjør miskunnhet mot tusen ledd, mot dem som elsker mig og holder mine bud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Du skal ikke misbruke Herrens, din Guds navn; for Herren vil ikke holde den uskyldig som misbruker hans navn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Kom hviledagen i hu, så du holder den hellig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Seks dager skal du arbeide og gjøre all din gjerning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Men den syvende dag er sabbat for Herren din Gud; da skal du intet arbeid gjøre, hverken du eller din sønn eller din datter, din tjener eller din tjenestepike eller ditt fe eller den fremmede som er hos dig innen dine porter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'For i seks dager gjorde Herren himmelen og jorden, havet og alt det som i dem er, og han hvilte på den syvende dag; derfor velsignet Herren sabbatsdagen og helliget den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Hedre din far og din mor, så dine dager må bli mange i det land Herren din Gud gir dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Du skal ikke slå ihjel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Du skal ikke drive hor.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Du skal ikke stjele.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Du skal ikke si falskt vidnesbyrd mot din næste.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Du skal ikke begjære din næstes hus. Du skal ikke begjære din næstes hustru eller hans tjener eller hans tjenestepike eller hans okse eller hans asen eller noget som hører din næste til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Og alt folket så og hørte tordenen og luene og basunlyden og fjellet i røk; og da folket så og hørte dette, skalv de og holdt sig langt borte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Og de sa til Moses: Tal du med oss, så vil vi høre; men la ikke Gud tale med oss, forat vi ikke skal dø!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Men Moses sa til folket: Frykt ikke! Gud er kommet for å prøve eder, og forat frykt for ham skal være over eder, så I ikke synder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Så blev folket stående langt borte, og Moses gikk nær til mørket hvor Gud var.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Og Herren sa til Moses: Så skal du si til Israels barn: I har sett hvorledes jeg talte til eder fra himmelen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'I skal ikke gjøre eder nogen gud ved siden av mig; guder av sølv eller guder av gull skal I ikke gjøre eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Et alter av jord skal du gjøre mig, og på det skal du ofre dine brennoffer og dine takkoffer, ditt småfe og ditt storfe; på ethvert sted hvor jeg lar mitt navn ihukomme, vil jeg komme til dig og velsigne dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Men dersom du vil gjøre mig et alter av sten, da skal du ikke bygge det av huggen sten; for bruker du ditt huggjern på stenene, da vanhelliger du dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Og du skal ikke gå op til mitt alter på trapper, forat ikke din blusel skal blottes over det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Dette er de lover som du skal legge frem for dem:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Når du kjøper en hebraisk træl, skal han tjene i seks år; men i det syvende skal han gis fri uten vederlag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Dersom han kommer enslig, da skal han gå enslig bort; dersom han er gift mann, da skal hans hustru gå bort med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Dersom hans herre gir ham en hustru, og hun føder ham sønner eller døtre, da skal hustruen og barna høre hennes herre til, og han skal gå enslig bort.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Men dersom trælen sier: Jeg holder av min herre, min hustru og mine barn, jeg vil ikke være fri og gå bort,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'da skal hans herre føre ham frem for Gud og stille ham ved døren eller ved dørstolpen, og hans herre skal stikke en syl gjennem hans øre, og han skal tjene ham all sin tid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Når nogen selger sin datter til trælkvinne, da skal hun ikke gis fri som trælene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Dersom hun mishager sin herre, som hadde utsett henne for sig selv, da skal han la henne få kjøpe sig fri; til et fremmed folk skal han ikke ha rett til å selge henne, siden han har vært troløs mot henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Men dersom han utser henne for sin sønn, da skal han unne henne døtres rett.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Dersom han lar ham få en annen foruten henne, da skal han ikke avkorte noget i hennes kost, klær eller ekteskapsrett.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Men dersom han ikke lar henne få disse tre ting, da skal hun gis fri for intet, uten vederlag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Den som slår et menneske så det dør, han skal visselig late livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Men hvis han ikke har stått ham efter livet, men det er Gud som har latt ham komme ut for hans hånd, da vil jeg sette dig et fristed som han kan ty til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Men om nogen bærer sig så formastelig at, at han dreper sin næste med svik, da skal du ta ham om det så var fra mitt alter: han skal dø.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Den som slår sin far eller sin mor, skal visselig late livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Den som stjeler et menneske og selger ham eller holder ham fanget, skal visselig late livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Den som banner sin far eller sin mor, skal visselig late livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Når menn kommer i trette, og den ene slår den andre med en sten eller med neven, og han ikke dør, men blir sengeliggende -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'dersom han da kommer op igjen og går ute med stav, da skal den som slo, være fri for straff; men han skal gi ham vederlag for den tid han har tapt, og koste full lægedom på ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Når nogen slår sin træl eller trælkvinne med en stokk så de dør under hans hånd, da skal han straffes for det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Men dersom de blir i live én eller to dager, skal han ikke straffes; de er jo hans eiendom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Når menn kommer i slagsmål med hverandre og støter til en fruktsommelig kvinne, så hun føder i utide, men ellers ingen ulykke skjer, så skal den som gjorde det, gi den bot som kvinnens mann pålegger ham; han skal gi efter dommeres skjønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Men dersom det skjer en ulykke, da skal du gi liv for liv,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'øie for øie, tann for tann, hånd for hånd, fot for fot,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'brent for brent, sår for sår, skramme for skramme.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Når nogen slår sin træl eller trælkvinne i øiet og forderver det, da skal han gi dem fri til vederlag for øiet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Og dersom han slår ut en tann på sin træl eller trælkvinne, da skal han gi dem fri til vederlag for tannen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Om en okse stanger mann eller kvinne så de dør, da skal oksen stenes, og dens kjøtt skal ikke etes; men oksens eier skal være fri for straff.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Men dersom det er en okse som før har pleid å stange, og dens eier er advart, men ikke passer på den, og den dreper mann eller kvinne, da skal oksen stenes, og dens eier skal også lide døden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Men dersom bøter pålegges ham, da skal han gi så meget i løsepenger for sitt liv som det blir ham pålagt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Er det en gutt eller pike den stanger, skal det gjøres med ham efter denne lov.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Dersom oksen stanger en træl eller en trælkvinne, da skal eieren bøte tretti sekel sølv til deres herre; og oksen skal stenes.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Når nogen lar en brønn stå åpen eller graver en brønn og ikke dekker den til, og det faller en okse eller et asen i den,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'da skal brønnens eier godtgjøre det; han skal gi dyrets eier penger i vederlag, men det døde dyr skal være hans.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Når en manns okse stanger en annen manns okse ihjel, da skal de selge den levende okse og dele pengene for den, og det døde dyr skal de også dele.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Men er det vitterlig at det er en okse som før har pleid å stange, og dens eier ikke passer på den, da skal han gi en annen okse isteden, men det døde dyr skal være hans.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Når nogen stjeler en okse eller et får og slakter eller selger dem, så skal han gi fem okser istedenfor oksen og fire får for fåret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Dersom tyven blir grepet mens han bryter inn, og blir slått så han dør, da kommer det ingen blodskyld derav.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Men skjer det efterat solen er gått op, da blir det blodskyld derav. Tyven skal gi full bot; har han intet, skal han selges til vederlag for det han har stjålet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Dersom det han har stjålet, finnes levende hos ham, enten det er en okse eller et asen eller et får, da skal han gi dobbelt igjen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Når nogen lar sitt fe beite på sin aker eller i sin vingård, og han slipper det løs så det kommer til å beite på en annens aker, da skal han gi i vederlag det beste på sin aker og det beste i sin vingård.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Når ild bryter løs og fatter i tornehekker, og kornbånd eller det stående korn eller hele akeren brenner op, da skal den som voldte branden, gi fullt vederlag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Når nogen gir sin næste penger eller gods å gjemme, og det blir stjålet bort fra mannens hus, da skal tyven, om han finnes, gi dobbelt igjen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Men finnes ikke tyven, da skal husets eier føres frem for Gud, forat det kan avgjøres om han ikke har forgrepet sig på sin næstes eiendom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Hver gang det gjelder svikefull adferd med gods, enten det er en okse eller et asen eller et får eller klær eller i det hele noget som er kommet bort, og så en sier: her er det, da skal saken mellem de to komme frem for Gud; den som Gud dømmer skyldig, han skal gi sin næste dobbelt igjen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Når nogen gir sin næste et asen eller en okse eller et får eller i det hele noget husdyr å ta vare på, og det dør eller kommer til skade eller røves uten at nogen ser det,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'da skal ed ved Herren skille mellem dem og avgjøre om han ikke har forgrepet sig på sin næstes eiendom, og eieren skal ta eden for god, og den andre skal ikke gi noget vederlag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Men blir det stjålet fra ham, da skal han gi dets eier vederlag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Blir det revet ihjel, da skal han føre det frem til bevis; han skal ikke gi vederlag for det som er revet ihjel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Når nogen låner et dyr av sin næste, og det kommer til skade eller dør, og dets eier ikke er til stede, da skal han gi full bot.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Men dersom eieren er til stede, da skal han ikke gi vederlag; dersom det er leiet, går det inn i leien.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Når nogen forfører en jomfru som ikke er trolovet, og ligger hos henne, da skal han gi festegave for henne og ta henne til hustru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Dersom faren ikke vil la ham få henne, da skal han gi så meget i pengebøter som en pleier å gi i festegave for en jomfru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'En trollkvinne skal du ikke la leve');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Enhver som blander sig med fe, skal visselig late livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Den som ofrer til avgudene og ikke til Herren alene, skal være forbannet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'En fremmed skal du ikke plage og ikke undertrykke; for I har selv vært fremmede i Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'I skal ikke plage nogen enke eller farløs;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'dersom du plager dem, og de roper til mig, skal jeg visselig høre deres rop,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'og min vrede skal optendes, og jeg skal slå eder ihjel med sverdet, og eders hustruer skal bli enker og eders barn farløse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Dersom du låner penger til nogen av mitt folk, til den fattige som bor hos dig, da skal du ikke være imot ham som en ågerkar; I skal ikke kreve renter av ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Dersom du tar din næstes kappe i pant, skal du gi ham den igjen før solen går ned;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'for den er det eneste dekke han har, det er den han skal klæ sitt legeme med; hvad skal han ellers ligge i? Og når han roper til mig, vil jeg høre; for jeg er barmhjertig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Gud skal du ikke spotte, og en høvding blandt ditt folk skal du ikke banne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Av alt det som fyller din lade, og som flyter av din vinperse, skal du ikke dryge med å gi mig. Den førstefødte av dine sønner skal du gi mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Det samme skal du gjøre med ditt storfe og ditt småfe; syv dager skal det være hos moren; den åttende dag skal du gi mig det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'I skal være hellige mennesker for mig; I skal ikke ete kjøtt av ihjelrevne dyr som I finner på marken; I skal kaste det for hundene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Du skal ikke utbrede falskt rykte; du skal ikke gjøre felles sak med en ugudelig, så du blir et urettferdig vidne;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'du skal ikke følge mengden i det som ondt er, og du skal ikke vidne således i en rettssak at du bøier dig efter mengden og forvender retten;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'heller ikke om det gjelder en ringe mann, skal du pynte på hans sak.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Når du treffer din fiendes okse eller hans asen som har gått sig vill, da skal du føre dem tilbake til ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Når du ser din fiendes asen ligge under sin byrde, da vokt dig for å gå fra ham; du skal hjelpe ham med å løse byrden av.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Du skal ikke i nogen sak bøie retten for den fattige som bor hos dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Du skal holde dig langt borte fra en falsk sak og ikke hjelpe til at den uskyldige og rettferdige mister livet; for jeg dømmer ikke en skyldig å være uskyldig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Du skal ikke ta imot gave; for gaven gjør seende blinde og forvender de rettferdiges sak.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'En fremmed skal du ikke undertrykke; I vet jo hvorledes den fremmede er til mote; I var selv fremmede i Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Seks år skal du så ditt land til og høste dets grøde;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'men i det syvende år skal du la det hvile og ligge, så de fattige blandt ditt folk kan ete derav, og hvad de levner, kan markens dyr ete. Det samme skal du gjøre med din vingård og dine oljetrær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Seks dager skal du gjøre din gjerning; men på den syvende dag skal du hvile, så din okse og ditt asen kan ha ro, og din trælkvinnes sønn og den fremmede får hvile sig ut.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'I alt det jeg har sagt til eder, skal I ta eder i vare. Andre guders navn skal I ikke nevne; slikt skal ikke høres av din munn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Tre ganger om året skal du holde høitid for mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'De usyrede brøds høitid skal du holde: Syv dager skal du ete usyret brød, således som jeg har befalt dig, på den fastsatte tid i abib måned, for i den drog du ut av Egypten; og ingen skal vise sig for mitt åsyn tomhendt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Likeså kornhøstens høitid, når førstegrøden faller av ditt arbeid, av det som du sår på marken, og frukthøstens høitid ved årets utgang, når du samler inn frukten av ditt arbeid på marken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Tre ganger om året skal alle menn blandt eder møte frem for Herrens, Israels Guds åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Du skal ikke ofre blodet av mitt slaktoffer sammen med syret brød, og det fete av mitt høitidsoffer skal ikke bli liggende natten over til om morgenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Det første av din jords førstegrøde skal du bære til Herrens, din Guds hus. Du skal ikke koke et kje i dets mors melk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Se, jeg sender en engel foran dig for å vokte dig på veien og for å føre dig til det sted jeg har utsett for dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Ta dig i vare for ham og hør på hans røst, vær ikke gjenstridig mot ham! Han skal ikke bære over med eders overtredelser, for mitt navn er i ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Men dersom du lyder hans røst og gjør alt det jeg sier, da vil jeg være en fiende av dine fiender og en motstander av dine motstandere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'For min engel skal gå foran dig og føre dig frem til det land hvor amorittene og hetittene og ferisittene og kana\'anittene, hevittene og jebusittene bor, og jeg vil tilintetgjøre dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Du skal ikke tilbede deres guder eller tjene dem; du skal ikke gjøre som de gjør; men du skal rive deres avgudsbilleder ned og slå deres stenstøtter i stykker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'I skal tjene Herren eders Gud, og han skal velsigne ditt brød og ditt vann. Og jeg vil holde sykdom borte fra dig;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'det skal ikke være nogen kvinne i ditt land som føder i utide eller er ufruktbar; dine dagers tall vil jeg gjøre fullt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Redsel for mig vil jeg sende foran dig og forvirre alle de folk du kommer til, og jeg vil la alle dine fiender flykte for dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Og jeg vil sende hvepser foran dig, og de skal jage hevittene, kana\'anittene og hetittene bort fra dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Jeg vil ikke jage dem bort fra dig på ett år, forat ikke landet skal bli øde og de ville dyr bli for mange for dig;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'litt efter litt vil jeg jage dem bort fra dig, inntil du blir så stort et folk at du kan ta landet i eie.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Jeg vil la ditt lands grenser gå fra det Røde Hav til filistrenes hav og fra ørkenen til elven; for jeg vil gi landets innbyggere i eders hånd, og du skal jage dem bort fra dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Du skal ikke gjøre nogen pakt med dem eller med deres guder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'De skal ikke bo i ditt land, forat de ikke skal forføre dig til å synde mot mig; for du vilde da tjene deres guder, og det vilde bli en snare for dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Og til Moses sa han: Stig op til Herren, du og Aron, Nadab og Abihu og sytti av Israels eldste, og I skal tilbede på avstand.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Men Moses alene skal komme nær til Herren, de andre skal ikke gå nær til, og folket skal ikke stige op med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Så kom Moses og forkynte folket alle Herrens ord og alle lovene; og hele folket svarte med én røst: Alle de ord Herren har talt, vil vi holde oss efter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Så skrev Moses op alle Herrens ord, og han stod tidlig op om morgenen og bygget et alter nedenfor fjellet og tolv støtter for de tolv Israels stammer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Siden sendte han nogen unge menn av Israels barn dit, og de bar frem brennoffer og ofret slaktoffer av okser til takkoffer for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Og Moses tok halvdelen av blodet og helte det ut i skåler, og halvdelen av blodet sprengte han på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Så tok han paktens bok og leste den op for folket; og de sa: Alt det Herren har sagt, vil vi gjøre og lyde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Da tok Moses blodet og sprengte det på folket; og han sa: Se, dette er paktens blod, den pakt som Herren opretter med eder på alle disse ord.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Så steg Moses og Aron, Nadab og Abihu og sytti av Israels eldste op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Og de så Israels Gud; under hans føtter var det likesom et gulv av gjennemsiktig safirsten og som himmelen selv i klarhet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Og han løftet ikke sin hånd mot de ypperste av Israels barn, men de skuet Gud og åt og drakk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Og Herren sa til Moses: Stig op til mig på fjellet og bli der! Så vil jeg gi dig stentavler og loven og budet, som jeg har skrevet op for å veilede dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Da gikk Moses avsted med sin tjener Josva; og Moses gikk op på Guds berg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Og han sa til de eldste: Bli her til vi kommer tilbake til eder; Aron og Hur er jo hos eder; den som har en rettssak, kan gå til dem!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Så steg Moses op på fjellet, og skyen skjulte fjellet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Og Herrens herlighet hvilte på Sinai berg, og skyen skjulte det i seks dager; den syvende dag kalte han på Moses midt ut av skyen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Og Herrens herlighet var å se til for Israels barns øine som en fortærende ild på fjellets topp.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Og Moses gikk midt inn skyen og steg op på fjellet; og Moses var på fjellet i firti dager og firti netter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Si til Israels barn at de skal komme med en gave til mig; av hver mann som har hjertelag til det, skal I ta imot gaven til mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Og dette er den gave I skal ta imot av dem: gull og sølv og kobber');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'og blå og purpurrød og karmosinrød ull og fint lin og gjetehår');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'og rødfarvede værskinn og takasskinn og akasietre,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'olje til lysestaken, krydderier til salvings-oljen og til den velluktende røkelse,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'onyksstener og andre edelstener til å sette på livkjortelen og brystduken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Og de skal gjøre mig en helligdom, så vil jeg bo midt iblandt dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Tabernaklet og alt som dertil hører, skal I i alle måter gjøre efter det billede jeg vil vise dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'De skal gjøre en ark av akasietre, halvtredje alen lang og halvannen alen bred og halvannen alen høi.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Den skal du klæ med rent gull, både innvendig og utvendig skal du klæ den med gull; og du skal gjøre en gullkrans på den rundt omkring.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Du skal støpe fire gullringer og feste dem i de fire føtter på arken, to ringer på den ene side og to på den andre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Så skal du gjøre stenger av akasietre og klæ dem med gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Og du skal stikke stengene inn i ringene på sidene av arken, så arken kan bæres på dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Stengene skal bli i ringene på arken, de må aldri tas ut av dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Og i arken skal du legge vidnesbyrdet som jeg vil gi dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Så skal du gjøre en nådestol av rent gull, halvtredje alen lang og halvannen alen bred.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Og du skal gjøre to kjeruber av gull; i drevet arbeid skal du gjøre dem og sette dem ved begge endene av nådestolen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Den ene kjerub skal du sette ved den ene ende og den andre kjerub ved den andre ende; i ett med nådestolen skal I gjøre kjerubene, én på hver ende av den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Kjerubene skal holde vingene utbredt og opløftet, så de dekker over nådestolen med sine vinger, og deres ansikter skal vende mot hverandre; mot nådestolen skal kjerubene vende sitt ansikt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Så skal du sette nådestolen ovenpå arken, og i arken skal du legge vidnesbyrdet, som jeg vil gi dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Og jeg vil komme sammen med dig der; fra nådestolen mellem begge kjerubene som er på vidnesbyrdets ark, vil jeg tale med dig om alt det jeg vil byde dig å si Israels barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Så skal du gjøre et bord av akasietre, to alen langt og én alen bredt og halvannen alen høit.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Du skal klæ det med rent gull og gjøre en gullkrans på det rundt omkring.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Og du skal gjøre en list på det av en hånds bredde rundt omkring, og rundt om listen skal du gjøre en gullkrans.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Så skal du gjøre fire gullringer til det og sette ringene i de fire hjørner på de fire føtter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Like ved listen skal ringene sitte, de skal være til å stikke stengene i, så bordet kan bæres.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Stengene skal du gjøre av akasietre og klæ dem med gull, og bordet skal bæres på dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Så skal du gjøre fatene og skålene som hører til bordet, og kannene og begerne som det skal ofres drikkoffer med; av rent gull skal du gjøre dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Og på bordet skal du alltid legge skuebrød for mitt åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Så skal du gjøre en lysestake av rent gull; i drevet arbeid skal lysestaken gjøres; både foten på den og stangen, begerne, knoppene og blomstene skal være i ett med den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Seks armer skal gå ut fra lysestakens sider, tre armer fra den ene side, og tre fra den andre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Det skal være tre mandelformede beger på den første arm med knopp og blomst, og tre mandelformede beger på den annen arm med knopp og blomst; således skal det være på alle de seks armer som går ut fra lysestaken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'På selve lysestaken skal det være fire mandelformede beger med knopper og blomster,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'én knopp under de to første armer i ett med den, og én knopp under de to næste armer i ett med den, og én knopp under de to øverste armer i ett med den - én knopp under hvert par av de seks armer som går ut fra lysestaken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Både knoppene og armene skal være i ett med den; alt sammen skal være ett drevet arbeid av rent gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Så skal du gjøre syv lamper til lysestaken; og lampene skal settes således op at lyset faller rett frem for den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Lysesaksene og brikkene som hører til, skal være av rent gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'En talent rent gull skal I bruke til lysestaken og alle disse redskaper.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Se nu til at du gjør alt efter det billede som blev vist dig på fjellet!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Tabernaklet skal du gjøre av ti tepper av fint, tvunnet lingarn og blå og purpurrød og karmosinrød ull; du skal gjøre dem med kjeruber på i kunstvevning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Hvert teppe skal være åtte og tyve alen langt og fire alen bredt; alle teppene skal holde samme mål.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Fem av teppene skal festes sammen, det ene til det andre, og likeså de andre fem tepper.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Og du skal gjøre hemper av blå ull i kanten på det ene teppe, ytterst der hvor sammenfestingen skal være, og likeså i kanten på det ytterste teppe, der hvor den andre sammenfesting skal være.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Femti hemper skal du gjøre på det ene teppe, og femti hemper skal du gjøre på det teppe som er der hvor den andre sammenfesting skal være; hempene skal være like mot hverandre, den ene mot den andre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Og du skal gjøre femti gullkroker og feste teppene til hverandre med krokene, så tabernaklet blir et sammenhengende telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Så skal du gjøre tepper av gjetehår til et dekke over tabernaklet; elleve sådanne tepper skal du gjøre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Hvert teppe skal være tretti alen langt og fire alen bredt; alle de elleve tepper skal holde samme mål.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Og du skal feste fem av teppene sammen for sig, og seks for sig, og du skal legge det sjette teppe dobbelt på fremsiden av dekket.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Du skal gjøre femti hemper i kanten på det ene teppe, ytterst der hvor sammenfestingen skal være, og likeså femti hemper i kanten på det andre teppe, der hvor sammenfestingen skal være.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Og du skal gjøre femti kobberkroker og hekte krokene inn i hempene, og du skal feste teppene sammen, så de blir ett dekke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Men det overskytende av dekketeppene - det halve teppe som er tilovers - skal henge ned på baksiden av tabernaklet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Og den alen på hver av sidene som dekketeppene er for lange, skal henge ned på begge sider av tabernaklet for å dekke det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Over dekket skal du gjøre et varetak av rødfarvede værskinn og ovenpå det et varetak av takasskinn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Plankene til tabernaklet skal du gjøre av akasietre; de skal reises på ende.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Hver planke skal være ti alen lang og halvannen alen bred.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'På hver planke skal det være to tapper, med en tverrlist imellem; således skal du gjøre med alle plankene til tabernaklet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Og av plankene som du gjør til tabernaklet, skal du reise tyve planker på den side som vender mot syd;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'og firti fotstykker av sølv skal du gjøre til å sette under de tyve planker, to fotstykker under hver planke til å feste begge tappene i.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Likeså skal du til tabernaklets andre side, den som vender mot nord, gjøre tyve planker,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'og til dem firti fotstykker av sølv, to fotstykker under hver planke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Til baksiden av tabernaklet, mot vest, skal du gjøre seks planker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Og to planker skal du gjøre til tabernaklets hjørner på baksiden;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'de skal være dobbelte nedenfra og likeledes begge være dobbelte helt op, til den første ring; således skal det være med dem begge; de skal stå i hver sitt hjørne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Således blir det åtte planker med sine fotstykker av sølv - seksten fotstykker, to under hver planke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Så skal du gjøre tverrstenger av akasietre, fem til plankene på den ene side av tabernaklet,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'og fem til plankene på den andre side, og fem til plankene på baksiden av tabernaklet, mot vest.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Og den mellemste tverrstang, den som er midt på plankeveggen, skal gå tvert over, fra den ene ende til den andre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Plankene skal du klæ med gull, og ringene på dem, som tverrstengene skal stikkes i, skal du gjøre helt av gull; tverrstengene skal du også klæ med gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Du skal reise tabernaklet på den rette måte, således som det blev vist dig på fjellet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Så skal du gjøre et forheng av blå og purpurrød og karmosinrød ull og fint, tvunnet lingarn; det skal gjøres i kunstvevning med kjeruber på.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Og du skal henge det på fire gullklædde stolper av akasietre som det er gullhaker på, og som står på fire fotstykker av sølv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Og du skal henge forhenget under krokene og føre vidnesbyrdets ark dit og sette den innenfor forhenget; og forhenget skal være for eder en skillevegg mellem det Hellige og det Aller-helligste.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Og du skal sette nådestolen ovenpå vidnesbyrdets ark i det Aller-helligste.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Du skal sette bordet utenfor forhenget, og lysestaken midt imot bordet ved den søndre side av tabernaklet; bordet skal du sette ved den nordre side.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Til teltdøren skal du gjøre et teppe av blå og purpurrød og karmosinrød ull og fint, tvunnet lingarn med utsydd arbeid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Og du skal gjøre fem stolper av akasietre til teppet og klæ dem med gull; hakene på dem skal være av gull, og du skal støpe fem fotstykker av kobber til dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Du skal gjøre et alter av akasietre, fem alen langt og fem alen bredt; firkantet skal alteret være og tre alen høit.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Og du skal gjøre et horn på hvert av dets fire hjørner, og hornene skal være i ett med alteret; og du skal klæ det med kobber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Så skal du gjøre bøttene som asken skal bæres bort med, og ildskuffene og skålene til å sprenge blod med, og kjøttgaflene og fyrfatene; alle disse redskaper skal du gjøre av kobber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Til alteret skal du gjøre et gitter, et nettverk av kobber, og på nettet skal du gjøre fire kobberringer, én på hvert hjørne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Og du skal sette det under alterets avsats nedentil, så det rekker til midt på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Så skal du gjøre stenger til alteret, stenger av akasietre, og du skal klæ dem med kobber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Stengene skal stikkes inn i ringene, så de er på begge sider av alteret når det blir båret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Alteret skal du gjøre av bord; det skal være hult; som det blev vist dig på fjellet, således skal det gjøres.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Så skal du gjøre en forgård til tabernaklet. På den side som vender mot syd, skal det være et omheng om forgården av fint, tvunnet lingarn, hundre alen langt på den ene side,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'og tyve stolper dertil og til stolpene tyve fotstykker av kobber; hakene på stolpene og stengene til dem skal være av sølv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Likeså skal det på den nordre side efter lengden være et omheng, hundre alen langt, og tyve stolper dertil og til stolpene tyve fotstykker av kobber; hakene på stolpene og stengene til dem skal være av sølv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'På den ene tverrside av forgården, mot vest, skal det være et omheng på femti alen, ti stolper dertil og til stolpene ti fotstykker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'På den andre tverrside, som vender frem mot øst, skal forgården også holde femti alen i bredden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Således skal det være femten alen omheng på den ene kant med tre stolper og tre fotstykker til dem,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'og på den andre kant femten alen omheng med tre stolper og tre fotstykker til dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Og i porten til forgården skal det være et forheng, tyve alen langt, av blå og purpurrød og karmosinrød ull og fint, tvunnet lingarn med utsydd arbeid, med fire stolper og fire fotstykker til dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Alle stolpene rundt omkring forgården skal være sammenbundet med stenger av sølv; hakene på dem skal være av sølv og fotstykkene under dem av kobber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Lengden på forgården skal være hundre alen, og bredden overalt femti alen; og omhenget skal være fem alen høit av fint, tvunnet lingarn, og fotstykkene til det skal være av kobber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Alle arbeidsredskaper i tabernaklet og alle pluggene, både til tabernaklet og til forgården, skal være av kobber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Og du skal byde Israels barn at de skal la dig få ren olje av støtte oliven til lysestaken, så lampene kan settes op til enhver tid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'I sammenkomstens telt, utenfor forhenget som henger foran vidnesbyrdet, skal Aron og hans sønner holde lampene i stand fra aften til morgen for Herrens åsyn; det skal være en evig gyldig vedtekt for Israels barn, fra slekt til slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Så skal du kalle din bror Aron ut av Israels barns mengde, og la ham trede frem til dig, både han og hans sønner, og sette dem til prester for mig - Aron og Nadab og Abihu og Eleasar og Itamar, Arons sønner.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Og du skal gjøre hellige klær for Aron, din bror, til ære og til pryd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Og du skal tale til alle kunstforstandige menn, alle som jeg har fylt med kunstnerånd; og de skal gjøre de klær som Aron skal bære, forat han kan helliges til å tjene mig som prest.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Dette er de klær som de skal gjøre: en brystduk og en livkjortel og en overkjortel og en ternet underkjortel, en hue og et belte - hellige klær skal de gjøre til Aron, din bror, og hans sønner, så han kan tjene mig som prest.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'De skal ta gullet og den blå og den purpurrøde og den karmosinrøde ull og det fine lingarn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'og de skal gjøre livkjortelen av gull, blå, purpurrød og karmosinrød ull og fint, tvunnet lingarn i kunstvevning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Den skal ha to skulderstykker som kan festes til hverandre, ett i hver ende; det skal være til å hekte den sammen med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Og beltet som skal sitte på den og holde den sammen, skal være av samme slags vevning og i ett stykke med den, av gull og blå og purpurrød og karmosinrød ull og fint, tvunnet lingarn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Og du skal ta to onyksstener, og på dem skal du inngrave navnene på Israels barn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'seks navn på den ene sten og de andre seks navn på den andre sten efter alderen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Som en arbeider i sten og skjærer ut et signet, således skal du la navnene på Israels barn skjære ut på begge stenene; du skal sette dem inn i flettverk av gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Og du skal sette begge stenene på livkjortelens skulderstykker, forat de skal minne om Israels barn; og når Aron står for Herrens åsyn, skal han bære deres navn på begge sine skuldrer for å minne om dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Så skal du gjøre flettverk av gull');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'og to kjeder av rent gull; de skal være slynget, således som de slynger snorer; disse slyngede kjeder skal du feste til flettverkene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Så skal du gjøre en doms-brystduk i kunstvevning, i samme slags vevning som livkjortelen; av gull og blå, purpurrød og karmosinrød ull og fint, tvunnet lingarn skal du gjøre den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Den skal være firkantet og dobbelt lagt, et spann lang og et spann bred.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Og du skal sette på den fire rader med innfattede stener. I en rad skal det være en karneol, en topas og en smaragd; det er den første rad.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'I den annen rad skal det være en karfunkel, en safir og en diamant,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'og i den tredje rad en hyasint, en agat og en ametyst,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'og i den fjerde rad en krysolitt og en onyks og en jaspis. De skal være innfattet i flettverk av gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Stenene skal være tolv i tallet, efter navnene på Israels sønner, en for hvert navn; på hver sten skal navnet på en av de tolv stammer være innskåret likesom på et signet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Til brystduken skal du også gjøre kjeder av rent gull, slynget som snorer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Likeså skal du gjøre to gullringer til brystduken, og dem skal du sette på hver sitt hjørne av den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Og du skal feste de to slyngede gullkjeder i de to ringer på hjørnene av brystduken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Og de to andre ender av de to slyngede kjeder skal du feste i de to flettverk og så feste dem til livkjortelens skulderstykker på fremsiden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Så skal du gjøre to andre gullringer og sette dem på de to andre hjørner av brystduken på den indre side av den, den som vender inn mot livkjortelen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Og du skal gjøre ennu to gullringer og sette dem på livkjortelens to skulderstykker nedentil på fremsiden, der hvor den festes sammen, ovenfor livkjortelens belte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Så skal ringene på brystduken bindes til ringene på livkjortelen med en snor av blå ull, så brystduken kommer til å sitte ovenfor livkjortelens belte og ikke kan skilles fra livkjortelen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Og når Aron går inn i helligdommen, skal han bære navnene på Israels barn i doms-brystduken på sitt hjerte for alltid å minne om dem for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'I doms-brystduken skal du legge urim og tummim; de skal ligge ved Arons hjerte når han går inn for Herrens åsyn, så Aron alltid skal bære Israels barns dom på sitt hjerte for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Overkjortelen som hører til livkjortelen, skal du gjøre helt igjennem av blå ull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Midt på den skal det være en åpning for hodet, og rundt omkring åpningen skal det være en vevet bord - likesom åpningen på en brynje - forat den ikke skal revne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Og rundt omkring på kanten av den nedentil skal du sette granatepler av blå, purpurrød og karmosinrød ull og mellem dem gullbjeller rundt omkring,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'først en gullbjelle og et granateple og så atter en gullbjelle og et granateple, og således rundt omkring hele kanten av overkjortelen nedentil.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Denne overkjortel skal Aron ha på hver gang han gjør tjeneste, så lyden av den kan høres når han går inn i helligdommen for Herrens åsyn, og når han går ut - forat han ikke skal dø.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Så skal du gjøre en plate av rent gull og skjære ut på den således som en skjærer ut et signet: Helliget Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Du skal feste den til en snor av blå ull, og den skal sitte på huen; på fremsiden av huen skal den sitte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Over Arons panne skal den sitte, så Aron kan bære den synd som henger ved de hellige ting Israels barn vier til Herren, alle de hellige gaver de bærer frem; den skal alltid sitte over hans panne, forat de kan finne velbehag for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Så skal du veve en ternet underkjortel av fint lin og gjøre en hue av fint lin, og et belte med utsydd arbeid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Og til Arons sønner skal du gjøre underkjortler, og du skal gjøre dem belter, og du skal gjøre dem høie huer, til ære og til pryd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Med dette skal du klæ Aron, din bror, og likeså hans sønner, og du skal salve dem og fylle deres hender og hellige dem, så de kan tjene mig som prester.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Så skal du gjøre dem benklær av lerret til å skjule deres blusel; fra lendene ned til lårene skal de nå.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Og dem skal Aron og hans sønner ha på når de går inn i sammenkomstens telt, eller når de treder frem til alteret for å gjøre tjeneste i helligdommen, så de ikke skal føre skyld over sig og dø. Dette skal være en evig lov for ham og hans ætt efter ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Og dette er hvad du skal gjøre med dem for å hellige dem til å tjene mig som prester: Ta en ung okse og to værer som er uten lyte,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'Og usyret brød Og usyrede kaker med olje i, og usyrede, tynne brødleiver, smurt med olje; av fint hvetemel skal du lage dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Og du skal legge dem i en kurv og bære dem frem i kurven, og lede frem oksen og de to værer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Så skal du føre Aron og hans sønner frem til inngangen til sammenkomstens telt, og du skal tvette dem med vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Og du skal ta klærne og klæ Aron i underkjortelen og overkjortelen som hører til livkjortelen, og livkjortelen og brystduken og binde livkjortelens belte om ham');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Og sette huen på hans hode Og feste det hellige hodesmykke på huen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Og du skal ta salvings-oljen og helle ut over hans hode og salve ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Så skal du føre hans sønner frem og klæ dem i underkjortler');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'og spenne beltet om dem - både om Aron og hans sønner - og binde de høie huer på dem, og de skal ha prestedømmet som en evig rett. Så skal du fylle Arons hånd og hans sønners hånd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Du skal lede oksen frem foran sammenkomstens telt, og Aron og hans sønner skal legge sine hender på oksens hode.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Og du skal slakte oksen for Herrens åsyn ved inngangen til sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Og du skal ta av oksens blod og stryke på alterets horn med din finger, Og resten av blodet skal du helle ut ved alterets fot.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Og du skal ta alt fettet som dekker innvollene, og den store leverlapp og begge nyrene med fettet som er på dem, og du skal brenne det på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Men kjøttet av oksen og dens hud og dens skarn skal du brenne op med ild utenfor leiren - det er et syndoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Så skal du ta den ene vær, og Aron og hans sønner skal legge sine hender på værens hode.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Og du skal slakte væren og ta dens blod og sprenge rundt om på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Men væren selv skal du dele op i sine stykker; og du skal tvette innvollene og føttene og legge dem ovenpå stykkene og hodet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Og du skal brenne hele væren på alteret - det er et brennoffer for Herren, en velbehagelig duft; det er et ildoffer for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Så skal du ta den andre vær, og Aron og hans sønner skal legge sine hender på værens hode.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Og du skal slakte væren og ta av dens blod og stryke på den høire ørelapp på Aron og hans sønner og på tommelfingeren på deres høire hånd og på stortåen på deres høire fot, og du skal sprenge resten av blodet rundt om på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Og du skal ta av blodet som er på alteret, og av salvings-oljen og sprenge på Aron og på hans klær, og likeledes på hans sønner og på deres klær, så blir han hellig, han selv og hans klær, og likeledes hans sønner og deres klær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Og du skal ta det feteste på væren, bade halen og fettet som dekker innvollene, og den store leverlapp og begge nyrene og fettet på dem og det høire lår; for dette er innvielses-væren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Så skal du ta et rundt brød og en oljekake og en tynn brødleiv av kurven med de usyrede brød som står for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Alt dette skal du legge i Arons hender og i hans sønners hender, og du skal svinge det for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Så skal du ta det av deres hånd og brenne det på alteret sammen med brennofferet til en velbehagelig duft for Herrens åsyn; det er et ildoffer for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Derefter skal du ta brystet av Arons innvielses-vær og svinge det for Herrens åsyn; det skal være din del.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Og du skal hellige svingebrystet og løftelåret - det som svinges og det som løftes av Arons og hans sønners innvielses-vær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Det skal være en rettighet for Aron og hans sønner hos Israels barn til evig tid; for det er en gave, en gave som Israels barn skal gi av sine takkoffer, en gave fra dem til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'De hellige klær som Aron har, skal hans sønner ha efter ham; dem skal de ha på når de salves og vies til prester.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'I syv dager skal den av hans sønner som blir prest i hans sted, bære disse klær - han som skal gå inn i sammenkomstens telt for å gjøre tjeneste i helligdommen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Så skal du ta innvielses-væren og koke kjøttet på et hellig sted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Og Aron og hans sønner skal ete kjøttet av væren og brødet som er i kurven, ved inngangen til sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'De skal ete dette soningsoffer, det som bæres frem når de vies til prester og helliges; men en uinnvidd skal ikke ete av det; for det er hellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Men dersom det blir noget tilovers av innvielses-kjøttet eller av brødet til om morgenen, da skal du brenne op det som er tilovers; det skal ikke etes, for det er hellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Således skal du gjøre med Aron og hans sønner, i ett og alt således som jeg har befalt dig. Syv dager skal deres innvielse vare.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Du skal hver dag ofre en okse som syndoffer til soning, og du skal rense alteret fra synd idet du gjør soning for det, og du skal salve det for å hellige det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'I syv dager skal du gjøre soning for alteret og hellige det, og da skal alteret være høihellig; hver den som rører ved alteret, blir hellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Dette er det du alltid skal ofre på alteret: hver dag to årsgamle lam.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Det ene lam skal du ofre om morgenen, og det andre lam skal du ofre mellem de to aftenstunder,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'og til det første lam tiendedelen av en efa fint mel, blandet med fjerdedelen av en hin olje av støtte oliven, og til drikkoffer fjerdedelen av en hin vin.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Det andre lam skal du ofre mellem de to aftenstunder; med det samme matoffer som om morgenen og med det samme drikkoffer skal du ofre det, til en velbehagelig duft, et ildoffer for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Dette skal være et stadig brennoffer hos eders efterkommere, og det skal bæres frem for Herrens åsyn ved inngangen til sammenkomstens telt, hvor jeg vil komme sammen med eder for å tale til eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Der vil jeg komme sammen med Israels barn, og det skal helliges ved min herlighet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Og jeg vil hellige sammenkomstens telt og alteret; og Aron og hans sønner vil jeg hellige til å tjene mig som prester.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Og jeg vil bo midt iblandt Israels barn, og jeg vil være deres Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Og de skal kjenne at jeg er Herren deres Gud, som førte dem ut av Egyptens land for å bo midt iblandt dem. Jeg er Herren deres Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Så skal du gjøre et alter til å brenne røkelse på; av akasietre skal du gjøre det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Det skal være en alen langt og en alen bredt, firkantet, og to alen høit; hornene på det skal være i ett med det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Du skal klæ det med rent gull både ovenpå og på sidene rundt omkring og på hornene; og du skal gjøre en gullkrans på det rundt omkring.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Og du skal gjøre to gullringer til det og sette dem nedenfor kransen, på begge sider av det; du skal sette to på hver side; de skal være til å stikke stenger i, så alteret kan bæres på dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Stengene skal du gjøre av akasietre og klæ dem med gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Og du skal sette alteret foran forhenget som henger foran vidnesbyrdets ark, foran nådestolen som er ovenover vidnesbyrdet, hvor jeg vil komme sammen med dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Og Aron skal brenne velluktende røkelse på det; hver morgen når han steller lampene, skal han brenne den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Og når han setter lampene op mellem de to aftenstunder, skal han også brenne den; det skal være et stadig røkoffer for Herrens åsyn hos eders efterkommere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'I skal ikke ofre fremmed røkelse på alteret, heller ikke brennoffer eller matoffer; og I skal ikke helle ut drikkoffer på det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Én gang om året skal Aron gjøre soning for dets horn; med blodet av sonings-syndofferet skal han én gang om året gjøre soning for det, slekt efter slekt; det er høihellig for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Når du holder manntall over Israels barn, da skal alle de som kommer med i manntallet, gi Herren løsepenger for sitt liv når de telles, så det ikke skal komme nogen ulykke over dem fordi de telles.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Dette skal enhver gi som kommer med i manntallet: en halv sekel efter helligdommens vekt - sekelen er tyve gera - denne halve sekel er en gave til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Enhver som kommer med i manntallet fra tyveårsalderen og opover, skal gi denne gave til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Den rike skal ikke gi mere og den fattige ikke mindre enn en halv sekel når I gir gaven til Herren som løsepenger for eders liv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Og du skal ta imot løsepengene av Israels barn og bruke dem til arbeidet ved sammenkomstens telt, så det kan være til å minne om Israels barn for Herrens åsyn, til løsepenger for eders liv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Du skal gjøre et kar av kobber med fotstykke av kobber til å tvette sig i; og du skal sette det mellem sammenkomstens telt og alteret og ha vann i det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Og Aron og hans sønner skal tvette sine hender og sine føtter i det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Når de går inn i sammenkomstens telt, skal de tvette sig med vann forat de ikke skal dø; likeså når de treder frem til alteret for å gjøre tjeneste og brenne ildoffer for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'De skal tvette sine hender og sine føtter forat de ikke skal dø; dette skal være en evig lov for dem, for ham og hans ætt, slekt efter slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Ta dig krydderier av ypperste slag, av den edleste myrra fem hundre sekel og av krydder-kanel halvt så meget, to hundre og femti sekel, og av krydder-kalmus to hundre og femti sekel');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'og av kassia fem hundre sekel efter helligdommens vekt og en hin olivenolje.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Av det skal du lage en hellig salvings-olje, en kryddersalve, slik som det gjøres av dem som lager salver; en hellig salvings-olje skal det være,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'og med den skal du salve sammenkomstens telt og vidnesbyrdets ark');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'og bordet med alt som dertil hører, og lysestaken med det som hører til den, og røkoffer-alteret');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'og brennoffer-alteret med alt som dertil hører, og karet med sitt fotstykke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Og du skal hellige dem, så de blir høihellige; hver den som rører ved dem, skal være hellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Og du skal salve Aron og hans sønner, og du skal hellige dem til å tjene mig som prester.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Og du skal tale til Israels barn og si: Dette skal være min hellige salvings-olje hos eder, slekt efter slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'På et annet menneskes legeme må den ikke komme, og I skal ikke lage nogen annen olje således blandet som den; hellig er den, hellig skal den være for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Den som lager maken til denne kryddersalve, eller som bruker den på en uinnvidd, han skal utryddes av sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Og Herren sa til Moses: Ta dig røkelses-krydderier, stakte og sjønegl og galban - disse tre slags krydderier - og ren virak; det skal være like meget av hvert.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Av det skal du gjøre røkelse, en krydderblanding slik som det gjøres av dem som lager salve, saltet, ren, hellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Og du skal støte noget av det smått og legge det foran vidnesbyrdet i sammenkomstens telt, hvor jeg vil komme sammen med dig; høihellig skal det være for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Og ingen annen røkelse skal I lage eder således blandet som denne; hellig for Herren skal den være dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Den som lager maken til den for å røke med, han skal utryddes av sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Se, jeg har kalt Besalel, sønn av Uri, Hurs sønn, av Juda stamme,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'og jeg har fylt ham med Guds Ånd, med visdom og med forstand og med kunnskap og med dyktighet til alle slags arbeid,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'til å uttenke kunstverker, til å arbeide i gull og i sølv og i kobber');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'og til å slipe stener til innfatning og skjære ut i tre, til å utføre alle slags arbeid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Og se, jeg har gitt ham til medhjelper Oholiab, Akisamaks sønn, av Dans stamme, og alle kunstforstandige menn har jeg gitt visdom i hjertet, så de kan gjøre alt det jeg har sagt dig:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'sammenkomstens telt og vidnesbyrdets ark og nådestolen ovenover den og alt som hører teltet til,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'og bordet med det som dertil hører, og lysestaken av rent gull med alt som hører til den, og røkofferalteret');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'og brennoffer-alteret med alt som dertil hører, og tvettekaret med sitt fotstykke,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'og embedsklærne og de hellige klær til Aron, presten, og presteklærne til hans sønner,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'og salvings-oljen og røkelsen av velluktende krydderier til helligdommen. De skal i ett og alt gjøre således som jeg har sagt dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Og Herren sa til Moses:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Tal til Israels barn og si: Mine sabbater skal I holde; for det er et tegn mellem mig og eder fra slekt til slekt, forat I skal vite at jeg er Herren som helliger eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Derfor skal I holde sabbaten; den skal være eder hellig; den som vanhelliger den, skal visselig late livet; hver den som gjør noget arbeid på den dag, han skal utryddes av sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'I seks dager skal der arbeides; men på den syvende dag skal det være høihellig sabbat, hellig for Herren; hver den som gjør noget arbeid på sabbatsdagen, skal visselig late livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Og Israels barn skal ta vare på sabbaten, så de holder den slekt efter slekt, en evig pakt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Den skal være et evig tegn mellem mig og Israels barn; for i seks dager gjorde Herren himmelen og jorden, og på den syvende dag hvilte han og holdt sig i ro.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Og da han hadde talt ut med Moses på Sinai berg, gav han ham vidnesbyrdets to tavler, tavler av sten, skrevet med Guds finger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Men da folket så at Moses drygde med å komme ned fra fjellet, samlet folket sig om Aron og sa til ham: Kom, gjør oss en gud som kan dra foran oss! For denne Moses, han som førte oss op fra Egyptens land - vi vet ikke hvad det er blitt av ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Da sa Aron til dem: Ta gullringene som eders hustruer, eders sønner og eders døtre har i sine ører, og kom til mig med dem!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Da tok alt folket gullringene ut av sine ører og kom til Aron med dem;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'og han tok imot gullet og støpte det om og laget det med meiselen til en kalv. Da sa de: Dette er din Gud, Israel, som førte dig op fra Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Da Aron så dette, bygget han et alter for den og lot utrope: Imorgen er det høitid for Herren!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Dagen efter stod de tidlig op og ofret brennoffer og bar frem takkoffer; og folket satte sig ned for å ete og drikke og stod op for å leke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Da sa Herren til Moses: Skynd dig og stig ned! Ditt folk, som du har ført op fra Egyptens land, har fordervet sin vei.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'De er hastig veket av fra den vei jeg bød dem å vandre; de har gjort sig en støpt kalv; den har de tilbedt og ofret til og sagt: Dette er din Gud, Israel, som førte dig op fra Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Og Herren sa til Moses: Jeg har lagt merke til dette folk og sett at det er et hårdnakket folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'La nu mig få råde, så min vrede kan optendes mot dem, og jeg kan ødelegge dem; så vil jeg gjøre dig til et stort folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Men Moses bønnfalt Herren sin Gud og sa: Herre! Hvorfor skal din vrede optendes mot ditt folk, som du har ført ut av Egyptens land med stor kraft og med veldig hånd?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Hvorfor skal egypterne si: Til ulykke har han ført dem ut; han vilde slå dem ihjel i fjellene og utrydde dem av jorden? Vend om fra din brennende vrede og angre det onde du har tenkt å gjøre mot ditt folk!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Kom i hu dine tjenere Abraham, Isak og Israel, til hvem du har sagt og svoret ved dig selv: Jeg vil gjøre eders ætt tallrik som stjernene på himmelen, og hele dette land som jeg har talt om, vil jeg gi eders ætt, og de skal eie det til evig tid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Så angret Herren det onde han hadde talt om å gjøre mot sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Og Moses vendte sig og gikk ned fra fjellet med vidnesbyrdets to tavler i sin hånd, og på begge sider av tavlene var der skrevet; både på forsiden og baksiden var der skrevet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Og tavlene var Guds arbeid, og skriften var Guds skrift, som var inngravd på tavlene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Da Josva hørte hvorledes folket støiet og skrek, sa han til Moses: Det lyder krigsrop i leiren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Men han svarte: Det lyder ikke som seiersrop og ikke som skrik over mannefall; det er lyd av sang jeg hører.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Og da Moses kom nær til leiren, så han kalven og dansen; da optendtes hans vrede; han kastet tavlene fra sig og slo dem i stykker ved foten av fjellet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Og han tok kalven som de hadde gjort, og kastet den på ilden og knuste den til den blev til støv, og støvet strødde han ovenpå vannet og gav Israels barn det å drikke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Så sa Moses til Aron: Hvad har dette folk gjort dig, siden du har ført så stor en synd over det?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aron svarte: La ikke din vrede optendes, herre! Du vet selv at dette folk ligger i det onde;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'de sa til mig: Gjør oss en gud som kan dra foran oss! For denne Moses, han som førte oss op fra Egyptens land - vi vet ikke hvad det er blitt av ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Da sa jeg til dem: Den som har gullsmykker på sig, ta dem av sig! Så gav de mig dem, og jeg kastet dem på ilden, og således blev denne kalv til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Da Moses så at folket var ustyrlig - for Aron hadde sloppet det løs til spott for deres motstandere -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'så stilte han sig i porten til leiren og sa: Hver den som hører Herren til, han komme hit til mig! Da samlet alle Levis barn sig om ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Og han sa til dem: Så sier Herren, Israels Gud: Hver binde sitt sverd ved sin lend! Gå så frem og tilbake fra port til port i leiren og slå ihjel hver sin bror og hver sin venn og hver sin frende!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Og Levis barn gjorde som Moses sa; og den dag falt det av folket omkring tre tusen mann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'For Moses sa: Innvi eder idag til prester for Herren, om det så er med blodet av sønn eller bror; så skal han idag gi eder sin velsignelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Dagen efter sa Moses til folket: I har gjort en stor synd. Nu vil jeg stige op til Herren; kanskje jeg kunde gjøre soning for eders synd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Så vendte Moses tilbake til Herren og sa: Akk, dette folk har gjort en stor synd; de har gjort sig en gud av gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Å, om du vilde forlate dem deres synd! Men hvis ikke, da slett mig ut av din bok som du har skrevet!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Da sa Herren til Moses: Hver den som har syndet mot mig, ham vil jeg slette ut av min bok.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Så gå nu og før folket dit jeg har sagt dig! Se, min engel skal gå foran dig, men på min hjemsøkelses dag vil jeg hjemsøke dem for deres synd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Således slo Herren folket fordi de hadde gjort kalven - den som Aron hadde laget.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Og Herren talte til Moses: Dra nu bort herfra, både du og det folk som du har ført op fra Egyptens land, til det land jeg tilsvor Abraham, Isak og Jakob, da jeg sa: Din ætt vil jeg gi det;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'og jeg vil sende en engel foran dig og drive ut kana\'anittene, amorittene og hetittene og ferisittene og hevittene og jebusittene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Dra op til et land som flyter med melk og honning; jeg vil ikke selv dra op med dig, fordi du er et hårdnakket folk; jeg vilde ellers komme til å ødelegge dig på veien.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Da folket hørte denne hårde tale, sørget de, og ingen tok sine smykker på sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'For Herren sa til Moses: Si til Israels barn: I er et hårdnakket folk; drog jeg endog bare et øieblikk op med dig, så måtte jeg ødelegge dig; men legg nu dine smykker av dig, så jeg kan vite hvad jeg skal gjøre med dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Da tok Israels barn sine smykker av og bar dem ikke mere, efterat de hadde draget fra fjellet Horeb.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Men Moses tok et telt og slo det op utenfor leiren et godt stykke fra; han kalte det sammenkomstens telt, og enhver som søkte Herren, gikk ut til sammenkomstens telt utenfor leiren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Og hver gang Moses gikk ut til teltet, reiste hele folket sig, og de stod hver i døren til sitt telt og så efter Moses, til han var kommet inn i teltet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Og når Moses var kommet inn i teltet, da senket skystøtten sig og stod i døren til teltet, og han talte med Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Og alt folket så skystøtten stå i døren til teltet, og alt folket reiste sig og bøide sig hver i døren til sitt telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Og Herren talte til Moses åsyn til åsyn, likesom en mann taler med sin næste. Så vendte han tilbake til leiren, men hans tjener Josva, Nuns sønn, en ung mann, vek ikke fra teltet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Og Moses sa til Herren: Se, du sier til mig: Før dette folk op! Men du har ikke latt mig vite hvem du vil sende med mig, enda du selv har sagt: Jeg kjenner dig ved navn, og du har funnet nåde for mine øine.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Dersom jeg nu har funnet nåde for dine øine, så la mig se din vei, så jeg kan kjenne dig og finne nåde for dine øine, og kom i hu at dette folk er ditt folk!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Da sa han: Mitt åsyn skal gå med, og jeg vil føre dig til hvile.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Men han sa til ham: Dersom ditt åsyn ikke går med, da la oss ikke dra op herfra!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Hvorav kan jeg da vite at jeg har funnet nåde for dine øine, jeg og ditt folk, medmindre du går med oss, så jeg og ditt folk blir æret fremfor alle folkeslag på jorden?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Da sa Herren til Moses: Også det du nu ber om, vil jeg gjøre; for du har funnet nåde for mine øine, og jeg kjenner dig ved navn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Men han sa: La mig da få se din herlighet!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Og han sa: Jeg vil la all min godhet gå forbi ditt åsyn, og jeg vil rope ut Herrens navn for ditt åsyn; for jeg vil være nådig mot den som jeg er nådig imot, og miskunne mig over den som jeg miskunner mig over.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Og han sa: Du kan ikke se mitt åsyn; for intet menneske kan se mig og leve.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Derefter sa Herren: Se, her tett ved mig er et sted; still dig der på berget,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'og når min herlighet går forbi, da vil jeg la dig stå i fjellkløften, og jeg vil dekke med min hånd over dig til jeg er gått forbi;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'så vil jeg ta min hånd bort; da kan du se mig bakfra, men mitt åsyn kan ingen se.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Og Herren sa til Moses: Hugg dig ut to stentavler likesom de første! Så vil jeg skrive på tavlene de ord som stod på de første tavler, de som du slo i stykker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Hold dig så rede til imorgen tidlig! Da skal du stige op på Sinai berg og vente på mig der på toppen av fjellet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Ingen må gå med dig op, og ingen må vise sig på hele fjellet, heller ikke må får eller okser beite under dette fjell.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Så hugg Moses ut to stentavler likesom de første, og han stod tidlig op om morgenen og steg op på Sinai berg, som Herren hadde befalt ham, og hadde de to stentavler i sin hånd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Og Herren steg ned i skyen og stilte sig der hos ham og ropte ut Herrens navn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Og Herren gikk forbi hans ansikt og ropte: Herren, Herren er en barmhjertig og nådig Gud, langmodig og rik på miskunnhet og sannhet;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'han bevarer miskunnhet imot tusen ledd, han forlater misgjerning og overtredelse og synd; men han lar ikke den skyldige ustraffet, han hjemsøker fedres misgjerning på barn og på barnebarn, på dem i tredje og på dem i fjerde ledd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Da bøide Moses sig hastig til jorden og tilbad.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Og han sa: Herre, dersom jeg har funnet nåde for dine øine, så gå med oss, Herre! For vel er det et hårdnakket folk; men du vil jo forlate oss vår misgjerning og vår synd og gjøre oss til din eiendom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Han svarte: Se, jeg vil gjøre en pakt: For hele ditt folks øine vil jeg gjøre underfulle ting, ting som det ikke har vært make til på hele jorden eller hos noget folkeslag; og hele det folk som du lever blandt, skal se Herrens gjerning, hvor forferdelig den er, den som jeg vil gjøre for dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Hold du de bud jeg gir dig idag! Se, jeg vil jage amorittene og kana\'anittene og hetittene og ferisittene og hevittene og jebusittene bort for dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Ta dig i vare så du ikke gjør nogen pakt med innbyggerne i det land du kommer til, forat de ikke skal bli til en snare blandt eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'I skal rive ned deres altere, og I skal slå i stykker deres billedstøtter, og I skal hugge ned deres Astarte-billeder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Du skal ikke tilbede nogen fremmed gud; for Herren heter Nidkjær, en nidkjær Gud er han.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Ta dig i vare så du ikke gjør nogen pakt med landets innbyggere! For de vil drive avgudsdyrkelse og ofre til sine guder, og når de da innbyr dig, så vil du ete av deres offer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Og du vil ta hustruer blandt deres døtre til dine sønner, og deres døtre vil drive avgudsdyrkelse med sine guder og få dine sønner til å gjøre det samme.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Støpte gudebilleder skal du ikke gjøre dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'De usyrede brøds høitid skal du holde; i syv dager skal du ete usyret brød, som jeg har befalt dig, på den fastsatte tid i måneden abib; for i måneden abib drog du ut av Egypten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Alt det som åpner morsliv, hører mig til, alt ditt fe av hankjønn som åpner morsliv, enten det er storfe eller småfe.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Og det som åpner morsliv av asener, skal du løse med et stykke småfe, men dersom du ikke løser det, da skal du bryte nakken på det. Hver førstefødt blandt dine sønner skal du løse, og ingen skal vise sig tomhendt for mitt åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Seks dager skal du arbeide, og på den syvende dag skal du hvile; om det så er i våronnen eller høstonnen, så skal du holde hviledagen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Ukenes høitid skal du holde når du får førstegrøden av hvetehøsten, og innsamlingens høitid når året er omme.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Tre ganger om året skal alle menn blandt eder vise sig for Herrens, Israels Guds åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'For jeg vil jage hedningene bort for dig og utvide ditt land, og ingen skal attrå ditt land mens du går op for å vise dig for Herren din Guds åsyn tre ganger om året.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Du skal ikke ofre blodet av mitt slaktoffer, så lenge det er syret brød hos dig, og påskehøitidens slaktoffer skal ikke bli liggende natten over til om morgenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Det første av din jords førstegrøde skal du bære til Herren din Guds hus. Du skal ikke koke et kje i dets mors melk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Og Herren sa til Moses: Skriv nu du op disse ord! For efter disse ord har jeg gjort en pakt med dig og med Israel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Og han var der hos Herren firti dager og firti netter uten å ete brød og uten å drikke vann; og han skrev på tavlene paktens ord, de ti ord.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Så gikk Moses ned fra Sinai berg, og da han gikk ned fra fjellet, hadde han vidnesbyrdets to tavler i sin hånd; men Moses visste ikke at hans ansikts hud skinte fordi han hadde talt med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Og Aron og alle Israels barn så at huden på Moses\' ansikt skinte; og de fryktet for å komme nær til ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Da kalte Moses på dem, og Aron og alle menighetens høvdinger vendte tilbake til ham, og Moses talte til dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Derefter gikk alle Israels barn nær til, og han bar frem til dem alle de bud som Herren hadde gitt ham på Sinai berg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Og da Moses holdt op å tale til dem, la han et dekke over sitt ansikt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Men når Moses gikk inn for Herrens åsyn for å tale med ham, tok han dekket av, til han gikk ut igjen; og når han kom ut, talte han til Israels barn det som var blitt sagt ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Og Israels barn så at huden på Moses\' ansikt skinte; og Moses la atter dekket over sitt ansikt, til han gikk inn igjen for å tale med ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Og Moses kalte sammen hele Israels barns menighet og sa til dem: Dette er det som Herren har befalt at I skal gjøre:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'I seks dager skal der gjøres arbeid, men den syvende dag skal I holde hellig hvile, en høihellig sabbat for Herren; enhver som gjør noget arbeid på den dag, skal lide døden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'I skal ikke tende op ild i nogen av eders boliger i sabbatsdagen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Og Moses sa til hele Israels barns menighet: Dette er det som Herren har befalt:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Ta ut en gave til Herren av det I eier! Enhver som har hjertelag til det, skal komme med gaven til Herren, gull og sølv og kobber');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'og blå og purpurrød og karmosinrød ull og fint lingarn og gjetehår');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'og rødfarvede værskinn og takasskinn og akasietre');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'og olje til lysestaken og krydderier til salvings-oljen og til den velluktende røkelse');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'og onyksstener og andre edelstener til å sette på livkjortelen og brystduken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Og enhver av eder som er kunstforstandig, skal komme og gjøre alt det Herren har befalt:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'tabernaklet med dekke og varetak, med kroker og planker, tverrstenger, stolper og fotstykker,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'arken med stenger, nådestolen og det dekkende forheng,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'bordet med stenger og alt som hører til, og skuebrødene');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'og lysestaken og det som hører til den, og lampene og oljen til lysestaken,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'og røkoffer-alteret med stenger og salvings-oljen og den velluktende røkelse og dekket for inngangen - for inngangen til tabernaklet,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'brennoffer-alteret med kobbergitteret, stengene og alt som hører til, karet med fotstykke,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'omhengene til forgården med stolpene og fotstykkene, og forhenget til forgårdens port,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'pluggene både til tabernaklet og til forgården og snorene dertil,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'embedsklærne til tjenesten i helligdommen, de hellige klær til Aron, presten, og klærne for hans sønner til prestetjenesten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Og hele Israels barns menighet gikk bort fra Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Og de kom enhver hvis hjerte drev ham til det; og enhver hvis ånd tilskyndte ham, kom med gaver til Herren til arbeidet på sammenkomstens telt og til all tjeneste der og til de hellige klær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'De kom både menn og kvinner: Enhver som hadde hjertelag til det, kom med spenner og ørenringer og fingerringer og kulekjeder, alle slags saker av gull; og likeså kom enhver som vilde vie en gave av gull til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Og enhver som eide blå og purpurrød og karmosinrød ull og fint lingarn og gjetehår og rødfarvede værskinn og takasskinn, kom med det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Enhver som vilde gi en gave av sølv eller kobber, kom med sin gave til Herren; og enhver som eide akasietre til noget av det som skulde arbeides, han kom med det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Og enhver kvinne som var kunstforstandig, spant med sine hender, og de kom med det de hadde spunnet, blå og purpurrød og karmosinrød ull og fint lingarn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Og alle kvinner hvis hu og evner drev dem til det, spant gjetehårene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Og høvdingene bar frem onyksstenene og de andre edelstener til å sette på livkjortelen og på brystduken,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'og krydderiene og oljen til lysestaken og til salvings-oljen og til den velluktende røkelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Enhver mann og kvinne av Israels barn hvis hjerte drev dem til å gi noget til det store verk som Herren ved Moses hadde befalt å gjøre, de kom med det som en frivillig gave til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Og Moses sa til Israels barn: Se, Herren har kalt Besalel, sønn av Uri, Hurs sønn, av Juda stamme;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'han har fylt ham med Guds Ånd, med visdom, med forstand og med kunnskap og med dyktighet til alle slags arbeid');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'og til å uttenke kunstverker, til å arbeide i gull og i sølv og i kobber');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'og til å slipe stener til innfatning og skjære ut i tre, til å utføre alle slags kunstverker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Og forstand til å lære andre har han gitt både ham og Oholiab, Akisamaks sønn, av Dans stamme.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Han har fylt dem med kunstnergaver, så de kan utføre alle slags treskjæring og kunstvevning og utsydd arbeid med blå og purpurrød og karmosinrød ull og fint lingarn og almindelig vevning - utføre alle slags arbeid og uttenke kunstverker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Og Besalel og Oholiab og alle kunstforstandige menn, som Herren hadde gitt forstand og kunnskap, så de forstod sig på alt det arbeid som skulde til for å få helligdommen ferdig, gjorde i ett og alt som Herren hadde sagt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'For Moses kalte Besalel og Oholiab og alle kunstforstandige menn, som Herren hadde gitt kunstnergaver, alle hvis hjerte drev dem, til å skride til verket for å fullføre det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Og de fikk hos Moses hele den gave som Israels barn hadde båret frem til det arbeid som skulde utføres for å få helligdommen ferdig. Men folket bar fremdeles frivillige gaver frem til ham hver morgen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Da kom alle de kunstforstandige menn som utførte alt arbeidet ved helligdommen, enhver fra det arbeid han var i ferd med,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'og de sa til Moses: Folket bærer frem meget mere enn det trenges til det arbeid som Herren har befalt å fullføre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Da lot Moses rope ut i hele leiren: Ingen, hverken mann eller kvinne, skal lenger bære noget frem som gave til helligdommen! Så holdt folket op med å bære frem gaver.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Men det som var gitt, var nok til hele det arbeid som skulde fullføres, ja mere enn nok.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Så gjorde da alle de kunstforstandige blandt dem som var med i arbeidet, tabernaklet av ti tepper; av fint, tvunnet lingarn og blå og purpurrød og karmosinrød ull blev de gjort med kjeruber på i kunstvevning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Hvert teppe var åtte og tyve alen langt og fire alen bredt; alle teppene holdt samme mål.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Fem av teppene festet de sammen, det ene til det andre, og likeså de andre fem tepper.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Og de gjorde hemper av blå ull i kanten på det ene teppe, ytterst der hvor sammenfestingen skulde være; likeså gjorde de i kanten på det ytterste teppe, der hvor den andre sammenfesting skulde være.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Femti hemper gjorde de på det ene teppe, og femti hemper gjorde de ytterst på det teppe som var der hvor den andre sammenfesting skulde være; hempene var like mot hverandre, den ene mot den andre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Og de gjorde femti gullkroker og festet teppene til hverandre med krokene, så tabernaklet blev et sammenhengende telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Så gjorde de tepper av gjetehår til et dekke over tabernaklet; elleve sådanne tepper gjorde de.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Hvert teppe var tretti alen langt og fire alen bredt; alle de elleve tepper holdt samme mål.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Og de festet fem av teppene sammen for sig og seks for sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'De gjorde femti hemper i kanten på det ene teppe, ytterst der hvor sammenfestingen skulde være, og likeså femti hemper i kanten på det andre teppe, der hvor sammenfestingen skulde være.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Og de gjorde femti kobberkroker til å feste teppene sammen med så det blev ett dekke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Over dekket gjorde de et varetak av rødfarvede værskinn og ovenpå det et varetak av takasskinn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Plankene til tabernaklet gjorde de av akasietre og reiste dem på ende.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Hver planke var ti alen lang og halvannen alen bred.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'På hver planke var det to tapper, med en tverrlist imellem; således gjorde de med alle plankene til tabernaklet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Og av plankene som de gjorde til tabernaklet, reiste de tyve planker på den side som vendte mot syd;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'og firti fotstykker av sølv gjorde de til å sette under de tyve planker, to fotstykker under hver planke til å feste begge tappene i.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Likeså gjorde de tyve planker til tabernaklets andre side, den som vendte mot nord,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'og til dem firti fotstykker av sølv, to fotstykker under hver planke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Til baksiden av tabernaklet, mot vest, gjorde de seks planker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Og to planker gjorde de til tabernaklets hjørner på baksiden;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'de var dobbelte nedenfra og likeledes begge dobbelte helt op, til den første ring; således gjorde de med dem begge på begge hjørnene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Således blev det åtte planker med sine fotstykker av sølv - seksten fotstykker, to under hver planke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Så gjorde de tverrstenger av akasietre, fem til plankene på den ene side av tabernaklet');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'og fem til plankene på den andre side, og fem til plankene på baksiden av tabernaklet, mot vest.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Og den mellemste tverrstang satte de således at den gikk tvert over midt på plankeveggen, fra den ene ende til den andre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Plankene klædde de med gull, og ringene på dem, som tverrstengene skulde stikkes i, gjorde de helt av gull; tverrstengene klædde de også med gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Så gjorde de forhenget av blå og purpurrød og karmosinrød ull og fint, tvunnet lingarn; de gjorde det i kunstvevning med kjeruber på.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Og de gjorde fire stolper av akasietre til forhenget og klædde dem med gull; hakene på dem var av gull, og de støpte fire fotstykker av sølv til dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Til teltdøren gjorde de et teppe av blå og purpurrød og karmosinrød ull og fint, tvunnet lingarn med utsydd arbeid,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'og til teppet fem stolper med sine haker, og de klædde stolpehodene og stengene med gull; og til stolpene gjorde de fem fotstykker av kobber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Og Besalel gjorde arken av akasietre, halvtredje alen lang og halvannen alen bred og halvannen alen høi.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Han klædde den med rent gull, både innvendig og utvendig, og han gjorde en gullkrans på den rundt omkring.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Han støpte fire gullringer som han festet i de fire føtter på arken, to ringer på den ene side og to på den andre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Så gjorde han stenger av akasietre og klædde dem med gull,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'og han stakk stengene inn i ringene på sidene av arken, så arken kunde bæres.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Så gjorde han en nådestol av rent gull, halvtredje alen lang og halvannen alen bred.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Og han gjorde to kjeruber av gull; i drevet arbeid gjorde han dem og satte dem ved begge endene av nådestolen,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'en kjerub ved den ene ende og en kjerub ved den andre ende; i ett med nådestolen gjorde han kjerubene, én på hver ende av den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Kjerubene holdt vingene utbredt og opløftet, så de dekket over nådestolen med sine vinger, og deres ansikter vendte mot hverandre; mot nådestolen vendte kjerubene sitt ansikt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Så gjorde han bordet av akasietre, to alen langt og én alen bredt og halvannen alen høit.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Han klædde det med rent gull og gjorde en gullkrans på det rundt omkring.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Og han gjorde en list på det av en hånds bredde rundt omkring, og rundt om listen gjorde han en gullkrans.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Så støpte han fire gullringer til det og satte ringene i de fire hjørner på de fire føtter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Like ved listen satt ringene til å stikke stengene i, så bordet kunde bæres.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Stengene gjorde han av akasietre og klædde dem med gull; på dem skulde bordet bæres.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Så gjorde han karene som skulde stå på bordet, av rent gull, fatene og skålene som hørte til bordet, og begerne og kannene som det skulde ofres drikkoffer med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Så gjorde han lysestaken av rent gull; i drevet arbeid gjorde han den; både foten på den og stangen, begerne og knoppene og blomstene var i ett med den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Seks armer gikk ut fra dens sider, tre armer fra den ene side og tre fra den andre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Det var tre mandelformede beger på den første arm med knopp og blomst, og tre mandelformede beger på den annen arm med knopp og blomst; således var det på alle de seks armer som gikk ut fra lysestaken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'På selve lysestaken var det fire mandelformede beger med knopper og blomster,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'én knopp under de to første armer i ett med den, og én knopp under de to næste armer i ett med den, og én knopp under de to øverste armer i ett med den - én knopp under hvert par av de seks armer som gikk ut fra lysestaken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Både knoppene og armene var i ett med den; alt sammen var ett drevet arbeid av rent gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Så gjorde han syv lamper til lysestaken og lysesakser og brikker til den av rent gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Én talent rent gull brukte han til lysestaken og alle redskaper som hørte til den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Så gjorde han røkoffer-alteret av akasietre, en alen langt og en alen bredt, firkantet, og to alen høit; hornene på alteret var i ett med det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Han klædde det med rent gull, både ovenpå og på sidene rundt omkring og på hornene; og han gjorde en gullkrans på det rundt omkring.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Og han gjorde to gullringer til det og satte dem nedenfor kransen, på begge sider av det, to på hver side; de skulde være til å stikke stenger i, så alteret kunde bæres på dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Stengene gjorde han av akasietre og klædde dem med gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Så laget han den hellige salvings-olje og den rene røkelse av velluktende krydderier, slik som det gjøres av dem som lager salver.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Så gjorde han brennoffer-alteret av akasietre, fem alen langt og fem alen bredt, firkantet, og tre alen høit.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Og han gjorde et horn på hvert av dets fire hjørner, og hornene var i ett med alteret; og han klædde det med kobber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Derefter gjorde han alle de redskaper som hørte til alteret, bøttene og ildskuffene og skålene til å sprenge blod med, kjøttgaflene og fyrfatene; alle disse redskaper gjorde han av kobber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Til alteret gjorde han et gitter, et nettverk av kobber, og han satte det under dets avsats nedentil, så det rakk til midt på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Og han støpte fire ringer til de fire hjørner av kobber-gitteret til å stikke stengene i.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Stengene gjorde han av akasietre og klædde dem med kobber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Og han stakk stengene inn i ringene på alterets sider, så det kunde bæres på dem; alteret gjorde han av bord, så det var hult.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Siden gjorde han karet og dets fotstykke av kobber og brukte dertil speil som tilhørte de kvinner som gjorde tjeneste ved inngangen til sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Så gjorde han forgården: På den side som vendte mot syd, gjorde han omhengene til forgården av fint, tvunnet lingarn, hundre alen lange,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'de tyve stolper dertil og de tyve fotstykker til dem av kobber og hakene på stolpene og stengene til dem av sølv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'På den nordre side gjorde han også omheng, hundre alen lange, de tyve stolper dertil og de tyve fotstykker til dem av kobber og hakene på stolpene og stengene til dem av sølv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'På den vestre side gjorde han omheng på femti alen, de ti stolper dertil og de ti fotstykker til dem, hakene på stolpene og stengene til dem av sølv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Og på forsiden, mot øst, gjorde han også omheng på femti alen,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'femten alen på den ene kant, de tre stolper dertil og de tre fotstykker til dem,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'og femten alen på den andre kant, de tre stolper dertil og de tre fotstykker til dem, så det blev likt på begge sider av forgårdens port.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Alle forgårdens omheng helt rundt var av fint, tvunnet lingarn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Fotstykkene til stolpene var av kobber; hakene på stolpene og stengene til dem var av sølv, og stolpehodene var klædd med sølv. Alle disse stolper i forgården var sammenbundet med stenger av sølv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Forhenget til forgårdens port var i utsydd arbeid av blå og purpurrød og karmosinrød ull og fint, tvunnet lingarn, tyve alen langt og fem alen høit efter vevens bredde, i likhet med forgårdens omheng.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'De fire stolper dertil og de fire fotstykker til dem var av kobber; hakene på dem var av sølv; stolpehodene var klædd med sølv, og stengene til dem var av sølv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Alle pluggene til tabernaklet og til forgården helt rundt var av kobber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Her følger regnskapet over hvad som gikk med til tabernaklet, vidnesbyrdets telt - for Moses bød levittene å regne det over, og Itamar, sønn av Aron, presten, forestod utregningen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Men Besalel, sønn av Uri, Hurs sønn, av Juda stamme, var den som gjorde alt det Herren hadde befalt Moses,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'og sammen med ham Oholiab, Akisamaks sønn, av Dans stamme, som var kyndig i utskjæring og i kunstvevning og utsyning med blå og purpurrød og karmosinrød ull og med fint lingarn -:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Alt det gull som blev brukt til arbeidet med å gjøre hele helligdommen ferdig, det vidde gul, var ni og tyve talenter og syv hundre og tretti sekel efter helligdommens vekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Og sølvet som blev gitt av dem i menigheten som var mønstret, var hundre talenter og ett tusen, syv hundre og fem og sytti sekel efter helligdommens vekt,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'en beka eller en halv sekel efter helligdommens vekt for hver enkelt som blev optatt blandt de mønstrede, fra tyveårsalderen og opover, og det var seks hundre og tre tusen, fem hundre og femti mann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'De hundre talenter sølv blev brukt til å støpe fotstykkene til helligdommen og fotstykkene til forhenget, hundre fotstykker av de hundre talenter, en talent til hvert fotstykke.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Og de tusen, syv hundre og fem og sytti sekel brukte de til hakene på stolpene, til å klæ stolpehodene og til å sammenbinde dem med stenger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Det vidde kobber var sytti talenter og to tusen og fire hundre sekel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Av det gjorde de fotstykkene ved inngangen til sammenkomstens telt og kobber-alteret og kobber-gitteret som hørte til, og alle alterets redskaper');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'og fotstykkene til forgården rundt omkring og fotstykkene ved forgårdens port og alle pluggene til tabernaklet og alle pluggene til forgården rundt omkring.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Av den blå og purpurrøde og karmosinrøde ull gjorde de embedsklær til tjenesten i helligdommen; og de gjorde de hellige klær som Aron skulde ha, således som Herren hadde befalt Moses');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Livkjortelen gjorde de av gull og blå og purpurrød og karmosinrød ull og fint, tvunnet lingarn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'De hamret ut gullet til plater og klippet det op til tråder, så det kunde virkes inn i den blå og purpurrøde og karmosinrøde ull og i det fine lingarn med kunstvevning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'De gjorde skulderstykker som blev festet til hverandre; med dem blev den hektet sammen i begge ender.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Beltet som skulde sitte på den og holde den sammen, gjorde de i ett stykke med den og i samme slags vevning som den, av gull og blå og purpurrød og karmosinrød ull og fint, tvunnet lingarn, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Så gjorde de onyksstenene i stand og satte dem inn i flettverk av gull; på dem var navnene på Israels barn innskåret, likesom på et signet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Og de satte dem på livkjortelens skulderstykker, forat de skulde minne om Israels barn, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Så gjorde de brystduken i kunstvevning, i samme slags vevning som livkjortelen, av gull og blå og purpurrød og karmosinrød ull og fint, tvunnet lingarn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Den var firkantet og dobbelt lagt; et spann lang og et spann bred var den og dobbelt lagt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Og de satte på den fire rader med stener. I en rad var det en karneol, en topas og en smaragd; det var den første rad.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'I den annen rad var det en karfunkel, en safir og en diamant,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'og i den tredje rad en hyasint, en agat og en ametyst,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'og i den fjerde rad en krysolitt, en onyks og en jaspis. De blev innfattet i hver sitt flettverk av gull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Stenene var tolv i tallet efter navnene på Israels sønner, en for hvert navn; på hver sten var navnet på en av de tolv stammer innskåret, likesom på et signet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Til brystduken gjorde de også kjeder av rent gull, slynget som snorer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Likeså gjorde de to flettverk av gull og to gullringer, og de satte de to ringer på hver sitt hjørne av brystduken,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'og de festet de to slyngede gullkjeder i de to ringer på hjørnene av brystduken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Og de to andre ender av de to slyngede kjeder festet de i de to flettverk og festet dem så til livkjortelens skulderstykker på fremsiden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Så gjorde de to gullringer og satte dem på de to andre hjørner av brystduken, på den indre side av den, den som vender inn mot livkjortelen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Og de gjorde ennu to gullringer og satte dem på livkjortelens to skulderstykker nedentil på fremsiden, der hvor den festes sammen, ovenfor livkjortelens belte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Ringene på brystduken bandt de til ringene på livkjortelen med en snor av blå ull, så brystduken satt ovenfor livkjortelens belte og ikke kunde skilles fra livkjortelen - således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Så gjorde de overkjortelen som hører til livkjortelen, av vevd arbeid, helt igjennem av blå ull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Midt på overkjortelen var det en åpning - likesom åpningen på en brynje - og rundt omkring åpningen var det en bord, forat den ikke skulde revne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'På overkjortelens kant nedentil satte de granatepler av tvunnet blå og purpurrød og karmosinrød ull.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Og de gjorde bjeller av rent gull, og de satte bjellene rundt omkring hele kanten av overkjortelen nedentil, imellem granateplene,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'en bjelle og et granateple og så atter en bjelle og et granateple, og således rundt omkring hele kanten av overkjortelen nedentil, til bruk ved tjenesten, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Så gjorde de de vevde underkjortler av fint lin til Aron og hans sønner,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'og huen av fint lin og de høie huer til pryd av fint lin og lerretsbenklærne av fint, tvunnet lingarn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'og beltet av fint, tvunnet lingarn og blå og purpurrød og karmosinrød ull i utsydd arbeid, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Så gjorde de platen, det hellige hodesmykke, av rent gull, og de skrev på den, således som en skjærer ut et signet: Helliget Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Og de satte en snor av blå ull i den for å feste den til huen oventil, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Således blev hele arbeidet med tabernaklet, sammenkomstens telt, fullendt. Israels barn gjorde det i ett og alt således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Og de førte tabernaklet frem til Moses: teltet med alt som hørte til det, krokene, plankene, tverrstengene og stolpene og fotstykkene');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'og varetaket av rødfarvede værskinn og varetaket av takasskinn og det dekkende forheng,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'vidnesbyrdets ark med sine stenger og nådestolen,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'bordet med alt som hørte til, og skuebrødene,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'lysestaken av rent gull med lampene som skulde settes i rad, og alt som hørte til, og oljen til lysestaken');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'Og det gullklædde alter og salvings-oljen og den velluktende røkelse og teppet for inngangen til teltet,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'kobber-alteret og kobber-gitteret til det, stengene og alt som hørte til, tvettekaret med sitt fotstykke,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'omhengene til forgården med stolpene og fotstykkene og teppet til forgårdens port, snorene og pluggene og alle de ting som skulde brukes til tjenesten i tabernaklet, sammenkomstens telt,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'embedsklærne til tjenesten i helligdommen, de hellige klær til Aron, presten, og presteklærne til hans sønner.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Som Herren hadde befalt Moses, således gjorde Israels barn i ett og alt hele arbeidet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Og Moses så på alt det som var gjort, og da han så at det var ferdig, og at de i alle deler hadde gjort det således som Herren hadde befalt, da velsignet han dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'I den første måned, på den første dag i måneden, skal du reise tabernaklet, sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Der skal du sette vidnesbyrdets ark og dekke for arken med forhenget.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Så skal du sette inn bordet, og på det skal du legge alt som skal ligge på det; og du skal bære inn lysestaken og sette op lampene på den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Og du skal sette det gullklædde røkoffer-alter foran vidnesbyrdets ark og henge op teppet for inngangen til tabernaklet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Brennoffer-alteret skal du sette foran inngangen til tabernaklet, sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Og tvettekaret skal du sette mellem sammenkomstens telt og alteret og ha vann i det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Og så skal du sette op forgården rundt omkring og henge op teppet for porten til forgården.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Derefter skal du ta salvingsoljen og salve tabernaklet og alt som er i det, og du skal hellige tabernaklet og alt som hører det til, så det blir hellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Og du skal salve brennofferalteret og alt som hører det til, og du skal hellige alteret, og alteret skal være høihellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Og du skal salve tvettekaret og dets fotstykke og hellige det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Så skal du føre Aron og hans sønner frem til inngangen til sammenkomstens telt Og tvette dem med vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Og du skal klæ Aron i de hellige klær og salve ham og hellige ham, og så skal han tjene mig som prest.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Og hans sønner skal du også føre frem og klæ dem i underkjortlene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Og du skal salve dem, likesom du salvet deres far, og så skal de tjene mig som prester; og denne salving skal gi dem retten til prestedømmet for evig tid, slekt efter slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Og Moses gjorde så; han gjorde i ett og alt således som Herren befalte ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'I den første måned i det annet år, på den første dag i måneden, var det tabernaklet blev reist.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Da reiste Moses tabernaklet: Han satte ned fotstykkene og stilte op plankene, la tverrstengene inn og reiste stolpene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Så bredte han ut dekket over tabernaklet og la varetaket ovenpå, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Derefter tok han og la vidnesbyrdet i arken og satte stengene i og satte nådestolen ovenpå arken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Og arken satte han inn i tabernaklet og hengte op det dekkende forheng foran vidnesbyrdets ark, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Så satte han bordet i sammenkomstens telt ved den nordre vegg av tabernaklet utenfor forhenget');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'og la brødene i rad på det for Herrens åsyn, således som Herren hadde befalt Moses');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Lysestaken satte han i sammenkomstens telt midt imot bordet ved den søndre vegg av tabernaklet');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'og satte op lampene for Herrens åsyn, således som Herren hadde befalt Moses');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Så satte han det gullklædde alter i sammenkomstens telt foran forhenget');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'og brente velluktende røkelse på det, således som Herren hadde befalt Moses');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Derefter hengte han op teppet for inngangen til tabernaklet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Brennoffer-alteret satte han ved inngangen til tabernaklet, sammenkomstens telt, og ofret brennoffer og matoffer på det, således som Herren hadde befalt Moses');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Tvettekaret satte han mellem sammenkomstens telt og alteret og hadde vann i det til å tvette sig med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Og Moses og Aron og hans sønner tvettet sine hender og sine føtter i det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Når de gikk inn i sammenkomstens telt, og når de trådte nær til alteret, tvettet de sig, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Så reiste han op forgården omkring tabernaklet og alteret og hengte op teppet for porten til forgården. Således fullendte Moses verket.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Da dekket skyen sammenkomstens telt, og Herrens herlighet fylte tabernaklet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Og Moses kunde ikke gå inn i sammenkomstens telt fordi skyen hvilte over det, og Herrens herlighet fylte tabernaklet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Og når skyen løftet sig fra tabernaklet, brøt Israels barn op; så gjorde de på alle sine tog.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Men når skyen ikke løftet sig, brøt de ikke op, men ventet til den dag den atter løftet sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'For Herrens sky lå over tabernaklet om dagen, og om natten lyste den som ild, for alle Israels barns øine på alle deres tog.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Og Herren kalte på Moses og talte til ham fra sammenkomstens telt og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Tal til Israels barn og si til dem: Når nogen av eder vil bære frem for Herren et offer av buskapen, så kan I ta eders offer enten av storfeet eller av småfeet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Dersom hans offer er et brennoffer av storfeet, skal han ofre en han uten lyte; han skal føre den frem til inngangen til sammenkomstens telt, forat han kan være til velbehag for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Og han skal legge sin hånd på brennofferets hode, så vil Herren ha velbehag i det og la det bli til soning for ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Så skal han slakte den unge okse for Herrens åsyn; og Arons sønner, prestene, skal bære blodet frem og sprenge blodet rundt om på det alter som står ved inngangen til sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Og så skal han flå brennofferet og dele det op i sine stykker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Og Arons, prestens, sønner skal gjøre op ild på alteret og legge ved til rette på ilden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Så skal Arons sønner, prestene, legge stykkene, hodet og fettet, til rette på veden over ilden på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Innvollene og føttene skal tvettes med vann, og så skal presten brenne det alt sammen på alteret; det er et brennoffer, et ildoffer til velbehagelig duft for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Men dersom hans offer er et brennoffer av småfeet, av fårene eller av gjetene, så skal han ofre en han uten lyte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Og han skal slakte den på nordsiden av alteret for Herrens åsyn; og Arons sønner, prestene, skal sprenge dens blod rundt om på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Så skal han dele den op i sine stykker og ta med hodet og fettet; og presten skal legge dem til rette på veden over ilden på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Innvollene og føttene skal tvettes med vann, og så skal presten bære det alt sammen frem og brenne det på alteret; det er et brennoffer, et ildoffer til velbehagelig duft for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Men dersom hans offer til Herren er et brennoffer av fugler, så skal han ta sitt offer enten av turtelduer eller av dueunger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Og presten skal bære fuglen frem til alteret og vri hodet av den og brenne det på alteret; og dens blod skal krystes ut mot alterets vegg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Så skal han ta ut dens kro med urenheten som er i den, og kaste den på askehaugen ved østsiden av alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Derefter skal han flekke fuglen ved vingene, dog uten å rive dem av, og så skal presten brenne den på alteret på veden over ilden; det er et brennoffer, et ildoffer til velbehagelig duft for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Når nogen vil ofre et matoffer til Herren, så skal hans offer være fint mel; og han skal helle olje på det og legge virak ved.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Så skal han bære det frem til Arons sønner, prestene, og presten skal ta en håndfull av det, av det fine mel og av oljen, dessuten all viraken, og han skal brenne det som ihukommelses-offer på alteret; det er et ildoffer til velbehagelig duft for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Det som blir tilovers av matofferet, skal Aron og hans sønner ha; det hører til det som er høihellig av Herrens ildoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Og når du vil ofre et matoffer av noget som er bakt i ovn, så skal det være av fint mel, usyrede kaker med olje i eller usyrede brødleiver smurt med olje.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Og dersom ditt offer er et matoffer som er stekt på helle, så skal det være av fint mel som er blandet med olje og usyret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Du skal bryte det i stykker og helle olje på det; det er et matoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Og dersom ditt offer er et matoffer som er stekt i panne, så skal det lages av fint mel med olje.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Det matoffer som er tillaget på en av disse måter, skal du bære frem for Herren; du skal komme til presten med det, og han skal bære det frem til alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Og presten skal av matofferet ta ut ihukommelses-offeret og brenne det på alteret; det er et ildoffer til velbehagelig duft for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Og det som blir tilovers av matofferet, skal Aron og hans sønner ha; det hører til det som er høihellig av Herrens ildoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Intet matoffer som I vil ofre til Herren, skal lages til med noget som er surt; for hverken av surdeig eller av honning skal I brenne ildoffer for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Som en førstegrøde-gave kan I bære slike offer frem for Herren, men på alteret skal de ikke komme, til velbehagelig duft.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Alle dine matoffer skal du salte; du skal ikke la det fattes på salt i ditt matoffer; for saltet hører til din Guds pakt; til alle dine offer skal du bære frem salt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Dersom du vil ofre et matoffer av førstegrøden til Herren, så skal du ofre aks som er ristet over ilden, nyhøstet korn som er knust; det skal være ditt matoffer av førstegrøden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Du skal ha olje på det og legge virak ved; det er et matoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Og presten skal til ihukommelses-offer brenne noget av det knuste korn og av oljen og dessuten all viraken; det er et ildoffer for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Dersom nogen vil bære frem et takkoffer, og han tar det av storfeet, så skal det offerdyr han fører frem for Herrens åsyn, enten det er han eller hun, være uten lyte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Han skal legge sin hånd på offerdyrets hode og slakte det ved inngangen til sammenkomstens telt; og Arons sønner, prestene, skal sprenge blodet rundt om på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Så skal han av takkofferet ofre et ildoffer til Herren, og det skal være fettet som dekker innvollene, og alt det fett som er på innvollene,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'og begge nyrene med det fett som er på dem, ved lendene, og den store leverlapp; den skal han ta ut sammen med nyrene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Og Arons sønner skal brenne det på alteret sammen med brennofferet som ligger over veden på ilden; det er et ildoffer til velbehagelig duft for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Dersom han vil bære frem for Herren et takkoffer av småfeet, så skal han ofre en han eller hun uten lyte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Er det et får han vil ofre, så skal han føre det frem for Herrens åsyn');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'og legge sin hånd på offerdyrets hode og slakte det foran sammenkomstens telt; og Arons sønner skal sprenge blodet rundt om på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Så skal han av takkofferet bære frem et ildoffer for Herren, og det skal være fettet: hele halen - den skal han skjære av like ved ryggbenet - og fettet som dekker innvollene, og alt det fett som er på innvollene,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'og begge nyrene med det fett som er på dem, ved lendene, og den store leverlapp; den skal han ta ut sammen med nyrene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Og presten skal brenne det på alteret; det er et ildoffermåltid for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Er det en gjet han vil ofre, så skal han føre den frem for Herrens åsyn');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'og legge sin hånd på dens hode og slakte den foran sammenkomstens telt; og Arons sønner skal sprenge blodet rundt om på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Så skal han av sitt offer bære frem et ildoffer for Herren, og det skal være fettet som dekker innvollene, og alt det fett som er på innvollene,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'og begge nyrene med det fett som er på dem, ved lendene, og den store leverlapp; den skal han ta ut sammen med nyrene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Og presten skal brenne det på alteret; det er et ildoffermåltid til velbehagelig duft. Alt fett hører Herren til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Det skal være en evig lov for eder, fra slekt til slekt, hvor I så bor. Intet fett og intet blod skal I ete.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Tal til Israels barn og si: Når nogen synder av vanvare mot noget av Herrens bud og gjør noget som han har forbudt å gjøre,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'så skal han, dersom det er den salvede prest som synder og således fører skyld over folket, ofre Herren en ung okse uten lyte til bot for den synd han har gjort; det er hans syndoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Han skal føre oksen frem for Herrens åsyn, til inngangen til sammenkomstens telt, og han skal legge sin hånd på oksens hode, og han skal slakte oksen for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Så skal han - den salvede prest - ta av oksens blod og bære det inn i sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Og han - presten - skal dyppe sin finger i blodet, og han skal sprenge av blodet syv ganger for Herrens åsyn, like foran helligdommens forheng.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Noget av blodet skal han stryke på hornene av alteret med den velluktende røkelse, det som står for Herrens åsyn i sammenkomstens telt; og resten av oksens blod skal han helle ut ved foten av brennofferalteret, som står ved inngangen til sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Alt fettet på syndoffer-oksen skal han ta ut av den, både fettet som dekker innvollene, og alt det fett som er på innvollene,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'og begge nyrene med det fett som er på dem, ved lendene, og den store leverlapp; den skal han ta ut sammen med nyrene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Alt dette skal tas ut, likesom det tas ut av takkoffer-oksen; og presten skal brenne det på brennoffer-alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Men oksens hud og alt dens kjøtt med hode og med føtter og innvoller og skarn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'hele oksen skal han føre utenfor leiren til et rent sted, der hvor de slår ut asken, og han skal brenne den op på veden; der hvor de slår ut asken, der skal den brennes.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Dersom det er hele Israels menighet som synder av vanvare mot noget av Herrens bud, så det er skjult for folkets øine, og de gjør noget som han har forbudt å gjøre, og således fører skyld over sig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'og så den synd de har gjort, blir vitterlig, da skal folket ofre en ung okse til syndoffer. Den skal de føre frem foran sammenkomstens telt,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'og menighetens eldste skal legge sine hender på oksens hode for Herrens åsyn, og så skal oksen slaktes for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Den salvede prest skal bære noget av oksens blod inn i sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Og han - presten - skal dyppe sin finger i blodet og sprenge syv ganger for Herrens åsyn, like foran forhenget.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Noget av blodet skal han stryke på hornene av det alter som står for Herrens åsyn i sammenkomstens telt; og resten av blodet skal han helle ut ved foten av brennoffer-alteret, som står ved inngangen til sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Alt fettet på oksen skal han ta ut av den og brenne på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Han skal gjøre med denne okse likesom han gjorde med den første syndoffer-okse. Og presten skal gjøre soning for dem, så de får forlatelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Så skal de føre oksen utenfor leiren og brenne den op likesom den første okse; det er syndofferet for menigheten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Er det en høvding som synder av vanvare mot noget av Herrens, sin Guds bud og gjør noget som han har forbudt å gjøre, og således fører skyld over sig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'og så den synd han har gjort, blir vitterlig for ham, da skal han som sitt offer føre frem en gjetebukk, en han uten lyte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Og han skal legge sin hånd på bukkens hode og slakte den på det sted hvor de slakter brennofferet for Herrens åsyn; det er et syndoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Presten skal ta av syndofferets blod på sin finger og stryke det på hornene av brennoffer-alteret; og resten av blodet skal han helle ut ved foten av brennoffer-alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Alt fettet skal han brenne på alteret likesom takkofferets fett. Og presten skal gjøre soning for ham og fri ham for hans synd, så han får forlatelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Dersom det er nogen av det menige folk som synder av vanvare mot noget av Herrens bud og gjør noget som han har forbudt å gjøre, og således fører skyld over sig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'og så den synd han har gjort, blir vitterlig for ham, da skal han som sitt offer for den synd han har gjort, føre frem en gjet uten lyte, en hun.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Og han skal legge sin hånd på syndofferets hode og slakte syndofferet der hvor brennofferet slaktes.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Presten skal ta av gjetens blod på sin finger og stryke det på hornene av brennoffer-alteret; og resten av blodet skal han helle ut ved alterets fot.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Alt fettet skal han ta ut, likesom fettet tas ut av takkofferet, og presten skal brenne det på alteret til en velbehagelig duft for Herren. Således skal presten gjøre soning for ham, så han får forlatelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Er det et får han fører frem som syndoffer, så skal han komme med en hun uten lyte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Og han skal legge sin hånd på offerdyrets hode og slakte det til syndoffer på det sted hvor brennofferet slaktes.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Presten skal ta av syndofferets blod på sin finger og stryke det på hornene av brennoffer-alteret; og resten av blodet skal han helle ut ved alterets fot.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Alt fettet skal han ta ut, likesom fettet på fåret tas ut av takkofferet, og presten skal brenne det på alteret sammen med Herrens ildoffer. Således skal presten gjøre soning for ham for den synd han har gjort, så han får forlatelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Når nogen synder, idet han hører opropet til ed og kunde vidne om noget som han enten har sett eller er blitt vitende om, men allikevel ikke gir oplysning derom, og det således ligger en misgjerning på ham,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'eller når nogen uten å vite det rører ved noget urent, enten det er åtselet av et urent vilt dyr eller åtselet av et urent tamt dyr eller åtselet av et urent kryp, og han således er blitt uren og har ført skyld over sig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'eller når han uten å vite det rører ved et menneskes urenhet, hvad det så er for urenhet det gjelder, og han siden får vite det og kjenner sig skyldig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'eller når nogen uten å sanse sig sverger tankeløst med sine leber at han vil gjøre noget, enten ondt eller godt, hvad det så kan være et menneske tankeløst sverger på, og han siden blir det var og kjenner sig skyldig i noget av disse stykker -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'når nogen altså har ført skyld over sig med noget av dette og bekjenner det han har syndet i,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'da skal han til bot for den synd han har gjort, bære frem for Herren et syndoffer; det skal være en hun av småfeet, et får eller en gjet. Og presten skal gjøre soning for ham og fri ham for hans synd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Men dersom han ikke har råd til et stykke småfe, skal han til bot for sin synd bære frem for Herren to turtelduer eller to dueunger, en til syndoffer og en til brennoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Han skal føre dem frem til presten, og presten skal først ofre den som er til syndoffer; han skal vri hodet av den like over nakken, dog uten å rive det av.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Så skal han sprenge av syndofferets blod på alterets vegg, og det som er tilovers av blodet, skal krystes ut ved alterets fot; det er et syndoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Den andre fugl skal han ofre som brennoffer, som foreskrevet er. Og presten skal gjøre soning for ham og fri ham for den synd han har gjort sig skyldig i, så han får forlatelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Men dersom han ikke har råd til to turtelduer eller to dueunger, så skal han til bot for det han har syndet, ofre tiendedelen av en efa fint mel som syndoffer; han skal ikke ha olje på det og ikke legge virak ved; for det er et syndoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Han skal bære det til presten, og presten skal ta en håndfull av det som ihukommelses-offer og brenne det på alteret sammen med Herrens ildoffer; det er et syndoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Og presten skal gjøre soning for ham for den synd han har gjort i noget av hine stykker, så han får forlatelse. Og resten av det skal høre presten til på samme måte som ved matofferet');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Når nogen farer troløst frem og av vanvare forsynder sig mot nogen av Herrens hellige ting, så skal han til bot for sin synd ofre Herren som skyldoffer en vær uten lyte av sitt småfe, en som efter din verdsetning er verd minst to sekler i sølv efter helligdommens sekel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Og det hellige han har forsyndet sig mot, skal han gi vederlag for, og han skal legge femtedelen til og gi det til presten. Og presten skal gjøre soning for ham med skyldoffer-væren, så han får forlatelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Når nogen uten å vite det synder mot noget av Herrens bud og gjør noget han har forbudt å gjøre, og han således har ført skyld over sig, og det ligger misgjerning på ham,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'så skal han som skyldoffer føre frem til presten en vær uten lyte av sitt småfe, efter din verdsetning. Og presten skal gjøre soning for ham for den synd han uvitterlig har gjort, så han får forlatelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Det er et skyldoffer; han er blitt skyldig for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Når nogen synder og farer troløst frem mot Herren, idet han for sin næste lyver om noget som er ham betrodd eller nedlagt hos ham, eller om noget han har røvet, eller han med vold har fratatt sin næste noget,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'eller han har funnet noget som var tapt, og lyver om det, eller han sverger falsk om noget av alt det et menneske kan forsynde sig med,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'da skal den som således har syndet og ført skyld over sig, gi tilbake det han har røvet eller har tatt med vold, eller som var ham betrodd, eller som var tapt, og som han har funnet,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'eller hvad det kan være som han har svoret falsk om, og han skal godtgjøre det med dets fulle verd, og enda legge til femtedelen; han skal gi det til eiermannen samme dag som han bærer frem sitt skyldoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Og til bot for sin synd skal han føre frem til presten et skyldoffer for Herren: en vær uten lyte av sitt småfe, efter din verdsetning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Og presten skal gjøre soning for ham for Herrens åsyn, så han får forlatelse, hvad han så har gjort og ført skyld over sig med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Byd Aron og hans sønner og si: Dette er loven om brennofferet: Brennofferet skal ligge på sitt bål på alteret hele natten til om morgenen, og således skal alterilden holdes brennende.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Og presten skal klæ sig i sin lerretskjortel og ha lerretsbenklær på nærmest legemet, og han skal ta bort asken efter brennofferet som ilden har fortært på alteret, og legge den ved siden av alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Så skal han ta av sig sine klær og ta på sig andre klær og bære asken utenfor leiren til et rent sted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Ilden skal holdes brennende på alteret, den må ikke slukne; hver morgen skal presten legge ny ved på ilden og legge brennofferet til rette på den og brenne takkofferets fettstykker på den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'En stadig ild skal holdes tendt på alteret; den må ikke slukne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Og dette er loven om matofferet: Arons sønner skal bære det frem for Herrens åsyn, foran alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Og presten skal ta en håndfull av matofferets fine mel og av dets olje og all viraken som er på matofferet, og brenne det på alteret til en velbehagelig duft, som et ihukommelses-offer til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Og det som blir tilovers, skal Aron og hans sønner ete; det skal etes usyret på et hellig sted; i forgården til sammenkomstens telt skal de ete det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Det skal ikke bakes med surdeig; jeg har gitt dem det som deres del av mine ildoffer, det er høihellig likesom syndofferet og skyldofferet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Alt mannkjønn blandt Arons barn kan ete det; det skal til alle tider, fra slekt til slekt, være eders del av Herrens ildoffere; enhver som rører ved dem, skal være hellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Dette er Arons og hans sønners offer, som de skal ofre Herren den dag en av dem blir salvet: tiendedelen av en efa fint mel som stadig matoffer, halvdelen om morgenen og halvdelen om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Det skal lages til med olje på en helle; godt knadd skal det være når du bærer det frem; et matoffer som er bakt, skal du bære frem i små stykker til en velbehagelig duft for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Den av hans sønner som blir salvet til prest i hans sted, skal lage det til; det er en evig lov; det skal brennes op helt for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Ethvert matoffer som en prest bærer frem for sig selv, skal brennes helt; det må ikke etes.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Tal til Aron og hans sønner og si: Dette er loven om syndofferet: På det sted hvor brennofferet slaktes, skal syndofferet slaktes for Herrens åsyn; det er høihellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Den prest som bærer frem syndofferet, kan ete det; det skal etes på et hellig sted, i forgården til sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Enhver som rører ved dets kjøtt, skal være hellig; og om det skvetter noget av dets blod på et klædningsstykke, skal du tvette det på et hellig sted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Er det et lerkar det kokes i, så skal det slås i stykker; men er det kokt i et kobberkar, så skal karet skures og skylles med vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Alt mannkjønn blandt prestene kan ete det; det er høihellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Men intet syndoffer som der bæres blod av inn i sammenkomstens telt for å gjøre soning i helligdommen, må etes; det skal brennes op med ild.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Og dette er loven om skyldofferet: Det er høihellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'På det sted hvor brennofferet slaktes, skal skyldofferet slaktes, og dets blod skal sprenges rundt om på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Og alt fettet skal ofres, både halen og fettet som dekker innvollene,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'og begge nyrene med det fett som er på dem, ved lendene, og den store leverlapp; den skal tas ut sammen med nyrene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Og presten skal brenne det på alteret som ildoffer til Herren; det er et skyldoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Alt mannkjønn blandt prestene kan ete det; på et hellig sted skal det etes; det er høihellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Med skyldofferet skal det være likesom med syndofferet; det gjelder én lov for begge; den prest som gjør soning med det, ham skal det tilhøre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Når en prest ofrer brennoffer for nogen, så skal huden av det brennoffer han har ofret, tilhøre den samme prest.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Og ethvert matoffer som bakes i ovn, eller som stekes i panne eller på helle, skal tilhøre den prest som ofrer det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Og ethvert matoffer som er blandet med olje, eller som er tørt, skal høre alle Arons sønner til, den ene som den andre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Og dette er loven om takkofferet som ofres til Herren:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Dersom nogen ofrer det til lovprisning, så skal han foruten slaktofferet som bæres frem til lovprisning, ofre usyrede kaker med olje i og usyrede brødleiver smurt med olje, og fint mel knadd til kaker med olje i.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Dette er den offergave han skal bære frem foruten det slaktoffer som bæres frem til takk og lovprisning, og dessuten syrede kaker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Av dette offer skal han bære frem én kake av hvert slag som gave til Herren; det skal tilhøre presten som sprenger takkofferets blod på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Kjøttet av et takkoffer som bæres frem til lovprisning, skal etes på den dag det ofres; intet av det skal bli liggende til om morgenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Dersom nogens slaktoffer er et lovet offer eller et frivillig offer, skal det etes på den dag det ofres; men det som levnes, kan etes den næste dag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Men hvad som enda blir tilovers av slaktofferets kjøtt, skal på den tredje dag brennes op med ild.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Om nogen på den tredje dag eter av takkofferets kjøtt, da har Herren ikke velbehag i offeret; det skal ikke regnes den som ofret det, til gode, det skal være en vederstyggelighet, og den som eter av det, gjør en misgjerning som han kommer til å bøte for.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Kjøtt som kommer nær noget urent, skal ikke etes, det skal brennes op med ild; ellers kan alle som er rene, ete av kjøttet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Men den som eter kjøtt av Herrens takkoffer mens det er noget urent på ham, han skal utryddes av sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Og når nogen rører ved noget urent, enten det er et menneskes urenhet eller et urent dyr eller noget annet urent og vederstyggelig, og så eter av kjøttet av Herrens takkoffer, da skal han utryddes av sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Tal til Israels barn og si: I skal ikke ete fett av okse eller får eller gjet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Fettet av et selvdødt dyr eller av et sønderrevet dyr kan brukes til alle slags arbeid; men ete det må I ikke;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'for hver den som eter fettet av noget dyr som det ofres ildoffer av til Herren, han skal utryddes av sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Og blod skal I ikke ete, hverken av fugl eller fe, hvor I så bor.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Enhver som nogensinne eter blod, han skal utryddes av sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Tal til Israels barn og si: Den som ofrer sitt takke-slaktoffer til Herren, han skal bære frem for Herren sin offergave av sitt takke-slaktoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Med egne hender skal han bære frem Herrens ildoffer; både fettet og brystet skal han bære frem, og brystet skal svinges for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Og presten skal brenne fettet på alteret; men brystet skal høre Aron og hans sønner til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Og det høire lår skal I gi presten som gave av eders takkoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Den av Arons sønner som ofrer takkoffer-blodet og fettet, han skal ha det høire lår som sin del;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'for svinge-brystet og løfte-låret har jeg tatt fra Israels barn av deres takke-slaktoffer og gitt til Aron, presten, og til hans sønner som en evig rettighet de kan kreve av Israels barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Dette er Arons del og hans sønners del av Herrens ildoffer, som gis dem på den dag de føres frem for å tjene Herren som prester,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'den del som Herren befalte skulde gis dem av Israels barn på den dag de salves, en evig rettighet, fra slekt til slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Dette er loven om brennofferet, om matofferet og om syndofferet og om skyldofferet og om innvielsesofferet og om takkofferet,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'den som Herren gav Moses på Sinai berg den dag han bød Israels barn å ofre Herren sine offer i Sinai ørken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Hent Aron og hans sønner og ta deres klær og salvings-oljen og syndoffer-oksen og de to værer og kurven med de usyrede brød,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'og kall hele menigheten sammen ved inngangen til sammenkomstens telt!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Og Moses gjorde som Herren bød ham; og menigheten samledes ved inngangen til sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Og Moses sa til menigheten: Således har Herren befalt å gjøre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Så førte Moses Aron og hans sønner frem og tvettet dem med vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Og han gav ham underkjortelen på og spente beltet om ham og klædde ham i overkjortelen og gav ham livkjortelen på og bandt livkjortelens belte om ham, og med det snørte han livkjortelen sammen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Så satte han brystduken på ham, og la brystduken la han urim og tummim.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Og han satte huen på hans hode, og på dens forside satte han gullplaten, det hellige hodesmykke, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Og Moses tok salvings-oljen og salvet tabernaklet og alt som var i det, og helliget det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Og han sprengte av oljen syv ganger på alteret og salvet alteret og alt som hørte det til, og tvette-karet med sitt fotstykke, og således helliget han dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Og han helte av salvings-oljen på Arons hode og salvet ham og helliget ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Så førte Moses Arons sønner frem og klædde dem i underkjortler og spente belte om dem og bandt høie huer på dem, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Så ledet han syndoffer-oksen frem, og Aron og hans sønner la sine hender på syndoffer-oksens hode.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Og de slaktet den, og Moses tok blodet og strøk det rundt om på alterets horn med sin finger og renset alteret for synd; og resten av blodet helte han ut ved alterets fot. Således gjorde han soning for det og helliget det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Og han tok alt fettet som var på innvollene, og den store leverlapp og begge nyrene og fettet på dem, og Moses brente det på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Men oksen med dens hud og dens kjøtt og dens skarn brente han op med ild utenfor leiren, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Så ledet han brennoffer-væren frem, og Aron og hans sønner la sine hender på værens hode.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Og de slaktet den, og Moses sprengte blodet rundt om på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Men væren selv delte de op i sine stykker, og Moses brente hodet og stykkene og fettet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Og de tvettet innvollene og føttene med vann, og Moses brente hele væren på alteret; det var et brennoffer til en velbehagelig duft, det var et ildoffer for Herren, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Så ledet han frem den andre vær, innvielses-væren, og Aron og hans sønner la sine hender på værens hode.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Og de slaktet den, og Moses tok av dens blod og strøk på Arons høire ørelapp og på tommelfingeren på hans høire hånd og på stortåen på hans høire fot.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Så førte de Arons sønner frem, og Moses strøk noget av blodet på deres høire ørelapp og på tommelfingeren på deres høire hånd og på stortåen på deres høire fot. Og Moses sprengte resten av blodet rundt om på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Og han tok fettet, både halen og alt fettet som var på innvollene, og den store leverlapp Og begge nyrene og fettet på dem og det høire lår;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'og av kurven med de usyrede brød, som stod for Herrens åsyn, tok han en usyret kake og en oljekake og en brødleiv og la på fettstykkene og på det høire lår.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Alt dette la han i Arons hender og i hans sønners hender; og han svinget det for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Så tok Moses det av deres hånd og brente det på alteret sammen med brennofferet; det var et innvielsesoffer til en velbehagelig duft, det var et ildoffer for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Derefter tok Moses brystet og svinget det for Herrens åsyn; det var den del Moses fikk av innvielses væren, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Og Moses tok av salvingsoljen og av blodet som var på alteret, og sprengte på Aron og på hans klær og likeledes på hans sønner og deres klær; således helliget han Aron og hans klær og likeledes hans sønner og hans sønners klær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Og Moses sa til Aron og hans sønner: Kok kjøttet ved inngangen til sammenkomstens telt og et det der sammen med brødet som er i innvielses-kurven, således som jeg har befalt og sagt: Aron og hans sønner skal ete det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Men det som blir tilovers av kjøttet og av brødet, skal I brenne op med ild.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Og i syv dager skal I ikke gå bort fra inngangen til sammenkomstens telt - helt til den dag da eders innvielses-tid er til ende; for syv dager skal eders innvielse vare.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Som det er gjort idag, så har Herren befalt det skal gjøres også de andre dager, for å gjøre soning for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'I skal bli ved inngangen til sammenkomstens telt i syv dager, både dag og natt, og ta vare på det som Herren vil ha varetatt, så I ikke skal dø; for således er mig befalt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Og Aron og hans sønner gjorde alt det som Herren hadde befalt ved Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Og på den åttende dag kalte Moses Aron og hans sønner og Israels eldste til sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Og han sa til Aron: Ta dig en oksekalv til syndoffer og en vær til brennoffer, begge uten lyte, og led dem frem for Herrens åsyn!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Og du skal tale til Israels barn og si: Ta en gjetebukk til syndoffer og en kalv og et lam, begge årsgamle og uten lyte, til brennoffer,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'og en okse og en vær til takkoffer, for å ofre dem for Herrens åsyn, og et matoffer, tillaget med olje! For idag vil Herren åpenbare sig for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Og de tok det som Moses hadde befalt, og farte det frem foran sammenkomstens telt; og hele menigheten trådte til og stod for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Da sa Moses: Dette er det Herren har befalt eder å gjøre; så skal Herrens herlighet åpenbare sig for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Så sa Moses til Aron: Tred frem til alteret og ofre ditt syndoffer og ditt brennoffer og gjør soning for dig og for folket, og ofre så folkets offer og gjør soning for dem, således som Herren har befalt!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Og Aron trådte frem til alteret og slaktet den kalv som skulde være syndoffer for ham selv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Og Arons sønner bar blodet til ham, og han dyppet sin finger i blodet og strøk det på alterets horn, og resten av blodet helte han ut ved alterets fot.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Men fettet og nyrene og den store leverlapp av syndofferet brente han på alteret, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Og kjøttet og huden brente han op med ild utenfor leiren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Så slaktet han brennofferet; og Arons sønner rakte ham blodet, og han sprengte det rundt om på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Og de rakte ham brennofferet, stykke for stykke, og hodet, og han brente det på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Og han tvettet innvollene og føttene og brente dem sammen med brennofferet på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Så førte han folkets offer frem; han tok bukken som skulde være syndoffer for folket, og slaktet den og ofret den til et syndoffer, likesom det første offerdyr.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Så førte han brennofferet frem og ofret det, som det var foreskrevet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Derefter bar han matofferet frem og tok en håndfull av det og brente på alteret, foruten morgenbrennofferet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Så slaktet han oksen og væren som skulde være folkets takkoffer; og Arons sønner rakte ham blodet, og han sprengte det rundt om på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Men fettstykkene av oksen, og halen og fettet som dekket innvollene, og nyrene og den store leverlapp av væren -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'disse fettstykker la de på bryststykkene; og han brente fettstykkene på alteret,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'men bryststykkene og det høire lår svinget Aron for Herrens åsyn, således som Moses hadde befalt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Og Aron løftet sine hender over folket og velsignet dem; og så steg han ned, efterat han hadde ofret syndofferet og brennofferet og takkofferet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Derefter gikk Moses og Aron inn i sammenkomstens telt, og da de kom ut igjen, velsignet de folket. Da åpenbarte Herrens herlighet sig for hele folket,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'og det gikk ild ut fra Herrens åsyn og fortærte brennofferet og fettstykkene på alteret; og hele folket så det, og de ropte høit av glede og falt ned på sitt ansikt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Men Arons sønner Nadab og Abihu tok hver sitt ildkar og la ild i dem og la røkelse på ilden og bar fremmed ild inn for Herrens åsyn, som han ikke hadde befalt dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Da gikk det ild ut fra Herrens åsyn og fortærte dem, og de døde for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Da sa Moses til Aron: Dette var det Herren talte om da han sa: På dem som står mig nær, vil jeg åpenbare min hellighet, og for alt folkets åsyn vil jeg forherlige mig. Og Aron tidde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Men Moses kalte på Misael og Elsafan, sønner av Arons farbror Ussiel, og sa til dem: Tred frem og bær eders brødre bort fra helligdommen og utenfor leiren!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Og de trådte frem og bar dem i deres kjortler utenfor leiren, som Moses hadde sagt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Da sa Moses til Aron og hans sønner Eleasar og Itamar: I skal ikke rake eders hoder og ikke sønderrive eders klær, forat I ikke skal dø, og forat han ikke skal vredes på hele menigheten; men eders brødre, hele Israels hus, skal gråte over denne brand som Herren har optendt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Og I skal ikke gå bort fra inngangen til sammenkomstens telt, forat I ikke skal dø; for Herrens salvings-olje er på eder. Og de gjorde som Moses sa.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Og Herren talte til Aron og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Vin eller sterk drikk skal hverken du eller dine sønner drikke når I går inn i sammenkomstens telt, forat I ikke skal dø - det skal være en evig lov for eder, fra slekt til slekt -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'så I kan gjøre forskjell mellem hellig og vanhellig, mellem urent og rent,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'og lære Israels barn alle de lover som Herren har kunngjort dem ved Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Så sa Moses til Aron og hans sønner Eleasar og Itamar, som ennu var i live: Ta det matoffer som er tilovers av Herrens ildoffer, og et det usyret ved siden av alteret; for det er høihellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'I skal ete det på et hellig sted, for det er din og dine sønners fastsatte del av Herrens ildoffer; således er det mig befalt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Og svinge-brystet og løfte-låret skal I ete på et rent sted, du og dine sønner og dine døtre med dig; for det er gitt dig og dine barn som eders fastsatte del av Israels barns takkoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Løfte-låret og svinge-brystet skal de bære frem sammen med ildofferfettstykkene og svinge dem for Herrens åsyn; og det skal være din og dine barns fastsatte del til evig tid, således som Herren har befalt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Da nu Moses spurte efter syndoffer-bukken, viste det sig at den var opbrent; da blev han vred på Eleasar og Itamar, Arons sønner som ennu var i live, og han sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Hvorfor har I ikke ett syndofferet på det hellige sted? Det er jo høihellig, og han har gitt eder det forat I skal bortta menighetens syndeskyld og gjøre soning for dem for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Blodet blev jo ikke båret inn i helligdommen; derfor skulde I ha ett kjøttet på det hellige sted, således som jeg har befalt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Da sa Aron til Moses: De har jo idag ofret sitt syndoffer og sitt brennoffer for Herrens åsyn, og enda er slik en ulykke hendt mig. Om jeg nu hadde ett syndoffer idag, skulde da det ha vært godt i Herrens øine?');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Da Moses hørte dette, syntes han det var rett.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Og Herren talte til Moses og Aron og sa til dem:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Tal til Israels barn og si: Dette er de dyr som I kan ete av alle firføtte dyr på jorden:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Alle de firføtte dyr som har klover og har klovene kløvd helt igjennem, og som tygger drøv, dem kan I ete.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Det er bare disse I ikke skal ete blandt dem som tygger drøv, og blandt dem som har klover: kamelen, for den tygger vel drøv, men den har ikke klover, den skal være uren for eder,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'og fjellgrevlingen, for den tygger vel drøv, men har ikke klover, den skal være uren for eder,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'og haren, for den tygger vel drøv, men har ikke klover, den skal være uren for eder,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'og svinet, for det har vel klover og har klovene kløvd helt igjennem, men det tygger ikke drøv, det skal være urent for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Av disse dyrs kjøtt skal I ikke ete, og ved deres døde kropper skal I ikke røre; de skal være urene for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Dette kan I ete av alt det som er i vannet: Alt det i vannet - i havene og i elvene - som har finner og skjell, det kan I ete.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Men det som ikke har finner og skjell av alt det som finnes i havene og i elvene, av alt det som vrimler i vannet, og av alt levende som er i vannet, det skal være en vederstyggelighet for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'En vederstyggelighet skal de være for eder; av deres kjøtt skal I ikke ete, og deres døde kropper skal I holde for en vederstyggelighet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Alt i vannet som ikke har finner og skjell, det skal være en vederstyggelighet for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Dette er de fugler I skal holde for en vederstyggelighet, de skal ikke etes, de er en vederstyggelighet: landørnen og havørnen og fiskeørnen');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'og glenten, og falken efter sine arter,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'alle ravner efter sine arter,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'og strutsen og gjøken og måken, og høken efter sine arter,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'og kattuglen og dykkeren og hubroen');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'og nattravnen og pelikanen og gribben');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'og storken, og heiren efter sine arter, og hærfuglen og flaggermusen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Alt kryp som har vinger og går på fire føtter, skal være en vederstyggelighet for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Av alt kryp som har vinger og går på fire føtter, må I bare ete dem som har springben ovenfor sine føtter til å hoppe på marken med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Av dem kan I ete: arbe efter sine arter og solam efter sine arter og hargol efter sine arter og hagab efter sine arter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Men alt annet kryp som har vinger og fire føtter, skal være en vederstyggelighet for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Ved disse dyr blir I urene; enhver som rører ved deres døde kropper, skal være uren til om aftenen,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'og enhver som har båret slik en død kropp, skal tvette sine klær og være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Ethvert firføtt dyr som vel har klover, men ikke har klovene kløvd helt igjennem og ikke tygger drøv, skal være urent for eder; enhver som rører ved dem, blir uren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Og alle firføtte dyr som går på labber, skal være urene for eder; enhver som rører ved deres døde kropper, skal være uren til om aftenen,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'og den som har båret deres døde kropper, skal tvette sine klær og være uren til om aftenen; de skal være urene for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Og blandt de smådyr som kryper på jorden, skal disse være de ureneste for eder: muldvarpen og musen og alle slags firben,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'og pinnsvinet og jordrotten og padden og sneglen og kameleonen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Disse skal være de ureneste for eder blandt alle smådyr; enhver som rører ved dem når de er døde, skal være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Og alt det som noget av disse dyr faller på når de er døde, blir urent, enten det er et trekar eller klær eller skinn eller sekker, eller hvad redskap det kan være som det gjøres noget arbeid med; det skal legges i vann og være urent til om aftenen; da er det rent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Og om noget av dem faller i et lerkar, så blir alt det som er i karet urent, og karet selv skal I slå i stykker;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'all mat som folk eter, og som tillages med vann, blir da uren, og alt drikke som folk drikker, blir urent, hvad kar det enn er i.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Og alt det som slik en død kropp faller på, blir urent; enten det er ovn eller gryte, skal de brytes i stykker, de er urene og skal være urene for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Bare kilder og brønner som det samler sig vann i, blir like rene; men den som rører ved deres døde kropper, blir uren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Og om slik en død kropp faller på korn som skal såes, er kornet like rent;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'men slåes det vann på såkornet, og en av de døde kropper faller på det, da skal kornet være urent for eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Dør noget av de firføtte dyr som er til føde for eder, da skal den som rører ved dets døde kropp, være uren til om aftenen,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'og den som har ett av dets døde kropp, skal tvette sine klær og være uren til om aftenen; og den som har båret dets døde kropp, skal tvette sine klær og være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Alle smådyr som kryper på jorden, skal være en vederstyggelighet; de skal ikke etes.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Hverken det som kryper på buken, eller det som går på fire føtter, eller det som har flere føtter iblandt alle smådyr som kryper på jorden, må I ete; det skal være en vederstyggelighet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Gjør ikke eder selv vederstyggelige ved noget sådant kryp, og la eder ikke smitte ved dem, så I blir urene!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'For jeg er Herren eders Gud, og I skal hellige eder, og I skal være hellige, for jeg er hellig; I skal ikke gjøre eder selv urene ved noget av det kryp som rører sig på jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'For jeg er Herren, som førte eder op fra Egyptens land for å være eders Gud, og I skal være hellige, for jeg er hellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Dette er loven om de firføtte dyr og fuglene og alle de liv som rører Sig i vannet, og om alle de dyr som kryper på jorden,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'så I kan skille mellem urent og rent, mellem dyr som kan etes, og dyr som ikke skal etes.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Tal til Israels barn og si: Når en kvinne får barn og føder en gutt, så skal hun være uren i syv dager; hun skal være uren like så lenge som hun er uren i sin månedlige svakhet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Den åttende dag skal hans forhuds kjøtt omskjæres.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Derefter skal hun holde sig inne i tre og tretti dager under sitt blods renselse; hun skal ikke røre ved noget hellig og ikke komme til helligdommen før hennes renselses-dager er til ende.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Men føder hun en pike, da skal hun være uren i to uker likesom ved sin månedlige urenhet og holde sig inne i seks og seksti dager under sitt blods renselse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Når hennes renselses-dager er til ende, enten det er en sønn eller en datter hun har født, skal hun komme med et årsgammelt lam til brennoffer og en dueunge eller en turteldue til syndoffer og bære det frem til inngangen til sammenkomstens telt, til presten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Og han skal ofre det for Herrens åsyn og gjøre soning for henne; da blir hun ren efter sin blodflod. Dette er loven for den kvinne som har født, enten barnet er en gutt eller en pike.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Men har hun ikke råd til et lam, så skal hun ta to turtelduer eller to dueunger, en til brennoffer og en til syndoffer. Og presten skal gjøre soning for henne; da blir hun ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Og Herren talte til Moses og Aron og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Når det på et menneskes hud viser sig en knute eller et utslett eller en lys flekk, så det på hans hud er noget som ser ut til å bli spedalskhet, da skal han føres til Aron, presten, eller til en av hans sønner, prestene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Presten skal se på det syke sted på huden, og dersom hårene på det er blitt hvite, og det syke sted ser dypere ut enn huden ellers, da er det spedalskhet, og når presten ser det, skal han si ham uren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Men er det en hvit, lys flekk på huden, og den ikke ser dypere ut enn huden ellers, og hårene på den ikke er blitt hvite, da skal presten holde den syke innestengt i syv dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Den syvende dag skal presten se på ham igjen, og dersom han finner at det syke sted er uforandret å se til og ikke har bredt sig videre ut på huden, da skal han atter holde ham innestengt i syv dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Når så presten den syvende dag ser på ham ennu en gang og finner at det syke sted er bleknet og ikke har bredt sig videre ut på huden, da skal han si ham ren; det er da bare et utslett, og han skal tvette sine klær, så er han ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Men brer utslettet sig på huden efterat han har vist sig frem for presten for å bli sagt ren, da skal han ennu en gang vise sig frem for presten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Når presten da ser på ham og finner at utslettet har bredt sig videre ut på huden, da skal han si ham uren; det er spedalskhet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Når et menneske er blitt syk av spedalskhet, skal han føres til presten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Når presten da ser på ham og finner at det er en hvit knute på huden, og at hårene på den er blitt hvite, og at det er tegn til vilt kjøtt i knuten,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'da er det en gammel spedalskhet i huden på hans legeme, og presten skal si ham uren; han skal ikke lukke ham inne, for han er alt uren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Men når spedalskheten bryter ut i huden, så den dekker den sykes hud helt fra hode til fot, overalt hvor prestens øie faller,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'og presten da ser på det og finner at spedalskheten dekker hele hans legeme, da skal han si den syke ren; han er blitt hvit over det hele - han er ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Men så snart det viser sig vilt kjøtt på ham, blir han uren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Og når presten ser det ville kjøtt, skal han si ham uren; for det ville kjøtt er urent, det er spedalskhet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Men dersom det ville kjøtt atter forandrer sig og blir hvitt, da skal han gå til presten,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'og når presten ser på ham og finner at det syke sted er blitt hvitt, da skal han si den syke ren; for da er han ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Når nogen har en byld på sin hud, og den læges,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'og det på det sted hvor bylden var, blir en hvit knute eller en lyserød flekk, da skal han vise sig frem for presten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Og når presten ser på ham og finner at stedet ser dypere ut enn huden ellers, og at hårene på det er blitt hvite, da skal presten si ham uren; det er spedalskhet som er brutt ut i bylden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Men når presten ser på det syke sted og finner at det ikke er hvite hår på det, og at det ikke er dypere enn huden ellers, og at det er blekt, da skal presten holde ham innestengt i syv dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Brer det sig da videre ut på huden, skal presten si ham uren; det er spedalskhet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Men dersom den lyse flekk blir uforandret på sitt sted og ikke har bredt sig ut, da er det bare arret efter bylden, og presten skal si ham ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Når nogen får et brandsår på huden, og kjøttet som gror i brandsåret, viser sig som en lyserød eller hvit flekk,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'så skal presten se på den, og dersom han finner at hårene på den lyse flekk er blitt hvite, og at den ser dypere ut enn huden ellers, da er det spedalskhet som er brutt ut i brandsåret, og presten skal si ham uren; det er spedalskhet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Men finner presten, når han ser på den, at det ikke er hvite hår på den lyse flekk, og at den ikke er dypere enn huden ellers, og at den er blek, da skal han holde ham innestengt i syv dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Den syvende dag skal presten se på ham; dersom flekken da har bredt sig videre ut på huden, skal presten si ham uren; det er spedalskhet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Men dersom den lyse flekk blir uforandret på sitt sted og ikke har bredt sig ut på huden, og den er blek, da er det en knute efter brandsåret, og presten skal si ham ren; for det er bare arret efter brandsåret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Når en mann eller kvinne har et sykt sted på hodet eller i skjegget,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'så skal presten se på det syke sted, og dersom han finner at det ser dypere ut enn huden ellers, og at det er gule, tynne hår på det, da skal han si ham uren; det er skurv, spedalskhet på hodet eller i skjegget.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Men dersom presten, når han ser på skurven, finner at den ikke ser dypere ut enn huden ellers, men at det ikke er sorte hår på den, da skal presten holde den som har skurven, innestengt i syv dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Den syvende dag skal presten se på det syke sted, og dersom han finner at skurven ikke har bredt sig ut, og at det ikke er gule hår på den, og at skurven ikke ser dypere ut enn huden ellers,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'da skal den som har skurven rake sig, dog ikke der hvor skurven er; og presten skal atter holde ham innestengt i syv dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Dersom da presten, når han den syvende dag ser på skurven, finner at skurven ikke har bredt sig ut på huden, og at den ikke ser dypere ut enn huden ellers, da skal han si ham ren, og han skal tvette sine klær, så er han ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Men dersom skurven brer sig ut på huden efterat han er sagt ren,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'så skal presten se på ham, og dersom han finner at skurven har bredt sig ut på huden, da skal han ikke søke efter de gule hår; han er uren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Men ser det for ham ut som skurven er uforandret, og det er vokset sorte hår på den, da er skurven lægt; han er ren, og presten skal si ham ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Når en mann eller kvinne får lyse flekker, hvite, lyse flekker, på huden,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'og presten da ser på dem og finner lyse flekker av en blek, hvit farve på deres hud, da er det bare et ufarlig utslett som er brutt ut på huden; en sådan er ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Når en mann mister håret på hodet, så han blir skallet, da er han ren;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'og når han mister håret fremme på hodet, så han blir fleinskallet, da er han ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Men er det en lyserød flekk der hvor han er skallet, enten det er bak eller fremme på hodet, da er det spedalskhet som bryter ut på det skallete sted, på bakhodet eller forhodet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Og når presten ser på ham og finner at det er en lyserød knute på hans skallete bakhode eller forhode, av samme utseende som spedalskhet på huden,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'så er mannen spedalsk, han er uren; presten skal si ham uren; han har fått sykdommen på sitt hode.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Den som er blitt rammet av spedalskhet, skal gå med sønderrevne klær og med uflidd hår; han skal tildekke sitt skjegg og rope: Uren, uren!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Hele den tid han lider av sykdommen, skal han være uren; uren er han, han skal bo for sig selv, hans bolig skal være utenfor leiren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Når det kommer spedalskhet på et klæsplagg av ull eller av lin,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'eller på renning eller på islett av lin eller av ull eller på skinn eller på noget som er gjort av skinn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'og flekkene på klæsplagget eller på skinnet eller på renningen eller på isletten eller på noget som er gjort av skinn, er grønnlige eller rødlige, da er det spedalskhet, og det skal vises frem for presten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Og når presten har sett på flekkene, skal han holde det som flekkene er på, innelåst i syv dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Dersom han da den syvende dag ser at flekkene har bredt sig ut på klæsplagget eller på renningen eller på isletten eller på skinnet eller på noget som er gjort av skinn, da er det ondartet spedalskhet; det er urent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Og enten det er klæsplagget eller renningen eller isletten av ull eller av lin eller noget som er gjort av skinn, hvad det nu kan være, så skal det som flekkene er på brennes op; det er ondartet spedalskhet, det skal brennes op med ild.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Men dersom presten, når han ser på det, finner at flekkene ikke har bredt sig ut på klæsplagget eller på renningen eller på isletten eller på det som er gjort av skinn, hvad det nu kan være,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'da skal han la det som flekkene er på tvette, og atter holde det innelåst i syv dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Og når presten så ser på det, efterat det er tvettet, og han finner at flekkene ikke ser anderledes ut enn før, men at de heller ikke har bredt sig videre ut, da er det urent, du skal brenne det op med ild; det er av det slag som eter sig inn, på vrangen eller på retten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Men dersom presten, når han ser på det, finner at det sted som flekkene er på, er blitt blekt efter tvetningen, da skal han rive det av klæsplagget eller av skinnet eller av renningen eller av isletten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Men sees flekkene enda på klæsplagget eller på renningen eller på isletten eller på det som er gjort av skinn, hvad det nu kan være, da er det spedalskhet som bryter ut; du skal brenne det som flekkene er på op med ild.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Men det klæsplagg eller den renning eller den islett eller de ting av skinn som flekkene går bort av når det tvettes, det skal atter tvettes, så er det rent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Dette er loven om spedalskhet på et klæsplagg av ull eller av lin eller på renning eller på islett eller på noget som er gjort av skinn, hvad det nu kan være - når det skal sies rent og når urent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Dette er loven om den spedalske, når han skal renses: Han skal føres til presten;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'og presten skal gå utenfor leiren, og når da presten ser på ham og finner at han er helbredet for sin spedalskhet,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'da skal presten befale at det for den som lar sig rense, skal tas to levende rene fugler og sedertre og karmosinrød ull og isop,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'og la dem slakte den ene fugl over et lerkar som er fylt med rinnende vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Så skal han ta den levende fugl og sedertreet og den karmosinrøde ull og isopen og dyppe dem sammen med den levende fugl i blodet av den fugl som er slaktet over det rinnende vann,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'og sprenge syv ganger på den som lar sig rense for spedalskhet, og således rense ham, og den levende fugl skal han la flyve sin vei bortover marken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Og den som lar sig rense, skal tvette sine klær og rake av alt sitt hår og bade sig i vann, så er han ren, og derefter kan han gå inn i leiren; men han skal holde sig utenfor sitt telt i syv dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Den syvende dag skal han rake av alt sitt hår, både sitt hodehår og sitt skjegg og sine øienbryn - alt sitt hår skal han rake av, og han skal tvette sine klær og bade sitt legeme i vann, så er han ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Den åttende dag skal han ta to værlam uten lyte og et årsgammelt hunlam uten lyte og til matoffer tre tiendedeler av en efa fint mel, blandet med olje, og så en log olje.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Og presten som forestår renselsen, skal stille den mann som lar sig rense, og de ting han skal ofre, frem for Herrens åsyn, ved inngangen til sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Så skal presten ta det ene værlam og bære det frem til skyldoffer sammen med den tilhørende log olje, og han skal svinge dem for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Værlammet skal slaktes på det sted hvor syndofferet og brennofferet blir slaktet, på det hellige sted; for likesom syndofferet, således hører også skyldofferet presten til, det er høihellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Så skal presten ta av skyldofferets blod og stryke på den høire ørelapp på den som lar sig rense, og på hans høire tommelfinger og på hans høire stortå.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Og presten skal ta av den tilhørende log olje og helle i sin venstre hånd');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'og så dyppe sin høire pekefinger i oljen som han har i sin venstre hånd, og sprenge av oljen med sin finger syv ganger for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Og av resten av oljen som er i hans hånd, skal presten stryke noget på den høire ørelapp på den som lar sig rense, og på hans høire tommelfinger og på hans høire stortå, ovenpå blodet av skyldofferet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Og det som enda er tilovers av oljen som presten har i sin hånd, skal han helle på hodet på den som lar sig rense. Og således skal presten gjøre soning for ham for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Så skal presten ofre syndofferet og gjøre soning for den som lar sig rense for sin urenhet; og derefter skal han slakte brennofferet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Og presten skal ofre brennofferet og matofferet på alteret og således gjøre soning for ham, så er han ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Men er det en fattig mann, som ikke har råd til så meget, da skal han ta et værlam til skyldoffer - det skal svinges til soning for ham - og en tiendedel av en efa fint mel, blandet med olje, til matoffer, og en log olje');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'og to turtelduer eller to dueunger, efter som han har råd til; den ene skal være til syndoffer, og den andre til brennoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'På den åttende dag av sin renselse skal han bære dette frem til presten, til inngangen til sammenkomstens telt, for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Og presten skal ta skyldofferlammet og den tilhørende log olje og svinge dem for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Og de skal slakte skyldofferlammet, og presten skal ta av skyldofferets blod og stryke på den høire ørelapp på den som lar sig rense, og på hans høire tommelfinger og på hans høire stortå.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Så skal presten helle av oljen i sin venstre hånd,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'og med sin høire pekefinger skal han sprenge syv ganger for Herrens åsyn av oljen som han har i sin venstre hånd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Så skal presten stryke noget av oljen som han har i sin hånd, på den høire ørelapp på den som lar sig rense, og på hans høire tommelfinger og på hans høire stortå, ovenpå det sted hvor blodet av skyldofferet er.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Og det som enda er tilovers av oljen som presten har i sin hånd, skal han helle på hodet på den som lar sig rense, for å gjøre soning for ham for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Så skal han ofre den ene av turtelduene eller av dueungene - det som han har råd til -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'som syndoffer og den andre som brennoffer sammen med matofferet; og presten skal gjøre soning for den som lar sig rense, for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Dette er loven om den som lider av spedalskhet, men ikke har råd til å ofre meget når han skal renses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Og Herren talte til Moses og Aron og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Når I kommer inn i Kana\'ans land, som jeg gir eder til eiendom, og jeg lar spedalskhet komme på noget hus i det land I får i eie,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'da skal den som eier huset, gå og melde det til presten og si: Det ser ut for mig som det er kommet spedalskhet på huset.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Så skal presten la huset rydde, før han selv kommer for å se på flekkene, så ikke alt det som er i huset, skal bli urent; og derefter skal han komme og se på huset.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Dersom han da, når han ser på flekkene, finner at flekkene på husets vegger viser sig som grønnlige eller rødlige fordypninger som synes å ligge dypere enn veggen,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'da skal han gå ut av huset til husets dør, og han skal stenge huset og holde det tillåst i syv dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Den syvende dag skal presten komme igjen, og når han da ser på det og finner at flekkene har bredt sig ut på husets vegger,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'da skal han la de stener som flekkene er på, brytes ut og kastes utenfor byen, på et urent sted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Derefter skal huset skrapes innvendig rundt omkring, og det støv som er skrapet av, skal kastes utenfor byen, på et urent sted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Så skal de ta andre stener og sette dem inn istedenfor de gamle stener, og de skal ta nytt ler og overstryke huset med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Bryter flekkene ut igjen på huset efterat stenene er tatt ut og huset skrapet og overstrøket,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'da skal presten komme og se på det, og dersom han da finner at flekkene har bredt sig ut på huset, da er det ondartet spedalskhet på huset; det er urent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Og da skal de rive huset ned, både stener og treverket og alt leret, og føre det utenfor byen, til et urent sted.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Den som går inn i huset i hele den tid det holdes tillåst, skal være uren til om aftenen,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'og den som ligger i huset, skal tvette sine klær, og den som eter i huset, skal tvette sine klær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Men dersom presten, når han kommer og ser på det, finner at flekkene ikke har bredt sig ut på huset efterat det er blitt overstrøket, da skal han si huset rent; for da er ondet borte.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Så skal han, forat huset kan bli renset, ta to fugler og sedertre og karmosinrød ull og isop.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Den ene fugl skal han slakte over et lerkar som er fylt med rinnende vann,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'og så skal han ta sedertreet og isopen og den karmosinrøde ull og den levende fugl og dyppe dem i blodet av den fugl som er slaktet, og i det rinnende vann og sprenge på huset syv ganger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Og han skal rense huset med fuglens blod og med det rinnende vann og med den levende fugl og med sedertreet og med isopen og med den karmosinrøde ull');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'og så la den levende fugl flyve utenfor byen, bortover marken; således skal han gjøre soning for huset, så det blir rent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Dette er loven om alle slags spedalskhet og om skurv');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'og om spedalskhet på klær og på hus');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'og om knuter i huden og om utslett og om lyse flekker på huden -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'til oplysning om når noget er urent, og når det er rent. Dette er loven om spedalskhet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Og Herren talte til Moses og Aron og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Tal til Israels barn og si til dem: Når det går ut flod fra en manns legeme, da er han uren for sitt flods skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Så lenge hans flod varer, er det således med hans urenhet: Enten hans legeme gir flodet fra sig eller holder det tilbake, i begge tilfelle er han uren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Hvert leie som den som har flod, ligger på, skal være urent, og alt det han sitter på, skal være urent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Den som rører ved hans leie, skal tvette sine klær og bade sig i vann og være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Og den som setter sig på noget som den som har flod, sitter på, han skal tvette sine klær og bade sig i vann og være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Og den som rører ved den sykes legeme, skal tvette sine klær og bade sig i vann og være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Kommer den som har flod, til å spytte på en som er ren, da skal den han spyttet på, tvette sine klær og bade sig i vann og være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Hver sal som den som har flod, rider på, skal være uren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Enhver som rører ved noget av det han har under sig, skal være uren til om aftenen, og den som bærer det bort, skal tvette sine klær og bade sig i vann og være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Og enhver som den som har flod, rører ved uten å ha skyllet sine hender i vann, skal tvette sine klær og bade sig i vann og være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Og et lerkar som den som har flod, rører ved, skal brytes i stykker, og ethvert trekar skal skylles i vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Når den som har flod, blir ren for sitt flod, da skal han telle syv dager frem fra den dag han blev ren, og så tvette sine klær og bade sitt legeme i rinnende vann, så er han ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Og den åttende dag skal han ta to turtelduer eller to dueunger og komme for Herrens åsyn, til inngangen til sammenkomstens telt, og gi dem til presten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Og presten skal ofre dem, den ene til syndoffer og den andre til brennoffer; og således skal presten gjøre soning for ham for Herrens åsyn og rense ham for hans flod.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Når det går sæd fra en mann, da skal han bade hele sitt legeme i vann og være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Og ethvert klæsplagg og ethvert skinn som det kommer sæd på, skal tvettes i varm og være urent til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Og når en mann ligger hos en kvinne, og det går sæd fra ham, da skal de begge bade sig i vann og være urene til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Når en kvinne har flod, idet det flyter blod fra hennes legeme, da skal hun være uren i syv dager, og enhver som rører ved henne, skal være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Alt hun ligger på mens hun således er uren, skal være urent, og alt hun sitter på, skal være urent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Enhver som rører ved hennes leie, skal tvette sine klær og bade sig i vann og være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Og enhver som rører ved noget hun sitter på, skal tvette sine klær og bade sig i vann og være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Og dersom nogen rører ved noget som er på leiet eller på det hun sitter på, skal han være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Og dersom en mann ligger hos henne, og hennes urenhet kommer på ham, så skal han være uren i syv dager, og ethvert leie han ligger på, skal være urent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Når en kvinne har blodflod i mange dager, uten at det er hennes månedlige urenhets tid, eller hun har flod lenger enn sedvanlig i sin månedlige urenhets tid, da skal hun være uren alle de dager hennes urenhets flod varer, likesom i sin månedlige urenhets dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Ethvert leie hun ligger på alle de dager hennes flod varer, skal være urent, likesom hennes leie i hennes månedlige urenhet, og alt hun sitter på, skal være urent, likesom når hun har sin månedlige urenhet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Enhver som rører ved det, skal være uren; han skal tvette sine klær og bade sig i vann og være uren til om aftenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Men når hun blir ren for sitt flod, da skal hun telle syv dager frem, og derefter skal hun være ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Og den åttende dag skal hun ta to turtelduer eller to dueunger og komme med dem til presten, til inngangen til sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Og presten skal ofre den ene til syndoffer og den andre til brennoffer; og således skal presten gjøre soning for henne for Herrens åsyn og rense henne for hennes urenhets flod.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'I skal skille Israels barn av med deres urenhet, forat de ikke skal dø i sin urenhet når de gjør mitt tabernakel urent, det som står midt iblandt dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Dette er loven om den som har flod, og om den fra hvem det går sæd, så han blir uren derved,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'og om den kvinne som har sin månedlige urenhet, og om den som har flod, enten det er mann eller kvinne, og om den mann som ligger hos en uren kvinne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Og Herren talte til Moses efterat de to Arons sønner var døde, de som måtte dø dengang de trådte frem for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Og Herren sa til Moses: Tal til Aron, din bror, og si at han ikke til enhver tid må gå inn i helligdommen innenfor forhenget, frem til nådestolen som er over arken, forat han ikke skal dø; for jeg vil åpenbare mig i skyen over nådestolen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Dette skal Aron ha med sig når han går inn i helligdommen: en ung okse til syndoffer og en vær til brennoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Han skal klæ sig i en hellig underkjortel av lin og ha benklær av lin på sitt legeme og omgjorde sig med et belte av lin og binde en hue av lin på sitt hode; dette er de hellige klær, og han skal bade sitt legeme i vann før han klær sig i dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Og av Israels barns menighet skal han få to gjetebukker til syndoffer og en vær til brennoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Så skal Aron føre frem sin egen syndoffer-okse og gjøre soning for sig og sitt hus.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Og han skal ta de to gjetebukker og stille dem frem for Herrens åsyn, ved inngangen til sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Og Aron skal kaste lodd om de to gjetebukker, ett lodd for Herren og ett lodd for Asasel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Og den bukk som ved loddet er tilfalt Herren, skal Aron føre frem og ofre til syndoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Men den bukk som ved loddet er tilfalt Asasel, skal stilles levende frem for Herrens åsyn, forat det skal gjøres soning ved den, og så skal den sendes ut i ørkenen til Asasel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Når Aron fører frem sin egen syndoffer-okse og gjør soning for sig og sitt hus, skal han først slakte syndoffer-oksen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Så skal han fylle ildkaret med glør fra alteret for Herrens åsyn og sine hender med finstøtt velluktende røkelse og bære det innenfor forhenget.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Og han skal legge røkelsen på ilden for Herrens åsyn, så skyen av røkelsen skjuler nådestolen, som er over vidnesbyrdet, forat han ikke skal dø.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Så skal han ta noget av oksens blod og sprenge med sin finger på fremsiden av nådestolen, og foran nådestolen skal han sprenge noget av blodet syv ganger med sin finger.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Derefter skal han slakte den bukk som skal være syndoffer for folket, og bære dens blod innenfor forhenget; han skal gjøre med dens blod likesom han gjorde med oksens blod, og sprenge det på nådestolen og foran nådestolen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Således skal han gjøre soning for helligdommen og rense den for Israels barns urenhet og for alle deres overtredelser som de har forsyndet sig med; og likeså skal han gjøre med sammenkomstens telt, som er reist blandt dem midt i deres urenhet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Og det må ikke være noget menneske i sammenkomstens telt når han går inn for å gjøre soning i helligdommen, og til han går ut igjen; og således skal han gjøre soning for sig og for sitt hus og for hele Israels menighet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Så skal han gå ut til alteret som er reist for Herrens åsyn, og gjøre soning for det; han skal ta av oksens blod og av bukkens blod og stryke rundt om på alterets horn');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'og sprenge noget av blodet på det syv ganger med sin finger og således rense og hellige det fra Israels barns urenhet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Når han så har fullført soningen for helligdommen og for sammenkomstens telt og for alteret, da skal han føre frem den levende bukk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Og Aron skal legge begge sine hender på den levende bukks hode og bekjenne over den alle Israels barns misgjerninger og alle deres overtredelser som de har forsyndet sig med; han skal legge dem på bukkens hode og sende den ut i ørkenen med en mann som står rede dertil.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Og bukken skal bære alle deres misgjerninger med sig ut i villmarken, og så skal han slippe bukken løs i ørkenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Derefter skal Aron gå inn i sammenkomstens telt og ta av sig de linklær som han tok på da han gikk inn i helligdommen, og han skal la dem bli der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Så skal han bade sitt legeme i vann på et hellig sted og ta på sig sine andre klær og så gå ut og ofre sitt eget brennoffer og folkets brennoffer og gjøre soning for sig og for folket.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Og fettet av syndofferet skal han brenne på alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Men den som førte bukken ut til Asasel, skal tvette sine klær og bade sitt legeme i vann; derefter kan han gå inn i leiren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Syndoffer-oksen og syndofferbukken, hvis blod blev båret inn for å gjøre soning i helligdommen, skal føres utenfor leiren, og deres skinn og deres kjøtt og deres skarn skal brennes op med ild.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Og den som brenner det op, skal tvette sine klær og bade sitt legeme i vann; derefter kan han gå inn i leiren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Og dette skal være en evig lov for eder: I den syvende måned, på den tiende dag i måneden, skal I faste og ikke gjøre noget arbeid, hverken den innfødte eller den fremmede som bor iblandt eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'For på denne dag skal det gjøres soning for eder for å rense eder, så I blir rene for Herren for alle eders synder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'En høihellig sabbat skal det være for eder, og da skal I faste - det skal være en evig lov.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Og den prest som salves, og som innvies til å gjøre prestetjeneste i sin fars sted, skal utføre soningen; han skal klæ sig i linklærne, de hellige klær,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'og han skal gjøre soning for det Aller-helligste og gjøre soning for sammenkomstens telt og for alteret og gjøre soning for prestene og for hele det samlede folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Og dette skal være en evig lov for eder, at det gjøres soning for Israels barn til renselse for alle deres synder én gang om året. Og Aron gjorde som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Tal til Aron og hans sønner og til alle Israels barn og si til dem: Således har Herren befalt:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Hver mann av Israels hus som slakter en okse eller et får eller en gjet enten i leiren eller utenfor leiren');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'og ikke fører dem frem til inngangen til sammenkomstens telt for å bære frem et offer til Herren foran Herrens tabernakel, den mann skal det tilregnes som blodskyld, han har utøst blod; den mann skal utryddes av sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Derfor skal Israels barn komme til Herren med sine slaktedyr som de pleier å slakte på fri mark, og føre dem frem til inngangen til sammenkomstens telt, til presten, og ofre dem som takkoffer til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Og presten skal sprenge blodet på Herrens alter ved inngangen til sammenkomstens telt og brenne fettet til en velbehagelig duft for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Og de skal ikke mere ofre sine slaktoffer til de onde ånder som de driver avgudsdyrkelse med. Dette skal være en evig lov for dem, fra slekt til slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Og du skal si til dem: Når nogen mann av Israels hus eller av de fremmede som bor iblandt dem, ofrer et brennoffer eller slaktoffer');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'og ikke fører det frem til inngangen til sammenkomstens telt for å ofre det til Herren, så skal den mann utryddes av sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Og når nogen av Israels hus eller av de fremmede som bor iblandt dem, eter blod, om aldri så lite, da vil jeg sette mitt åsyn mot den som eter blodet, og utrydde ham av hans folk;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'for kjøttets sjel er i blodet, og jeg har gitt eder det på alteret til å gjøre soning for eders sjeler; for blodet er det som gjør soning, fordi sjelen er I det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Derfor har jeg sagt til Israels barn: Ingen av eder skal ete blod, og den fremmede som bor iblandt eder, skal heller ikke ete blod.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Og når nogen av Israels barn eller av de fremmede som bor iblandt dem, feller et vilt dyr eller en fugl som kan etes, da skal han la blodet renne ut og dekke det til med ord;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'for blodet er sjelen i alt kjøtt, fordi sjelen er i det; derfor sa jeg til Israels barn: I skal ikke ete blod av noget kjøtt, for blodet er sjelen i alt kjøtt; enhver som eter det, skal utryddes.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Og enhver som eter noget selvdødt eller sønderrevet dyr, enten han er innfødt eller fremmed, skal tvette sine klær og bade sig i vann og være uren til om aftenen; så er han ren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Dersom han ikke tvetter sine klær og ikke bader sitt legeme, da skal han komme til å lide for sin misgjerning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Tal til Israels barn og si til dem: Jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'I skal ikke gjøre som de gjør i Egyptens land, som I bodde i, og I skal ikke gjøre som de gjør i Kana\'ans land, som jeg vil føre eder til, og I skal ikke vandre efter deres skikker.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'I skal gjøre efter mine bud, og I skal holde mine lover, så I følger dem; jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Og I skal holde mine lover og mine bud, for det menneske som gjør efter dem, skal leve ved dem; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Ingen av eder skal røre ved nogen kvinne av sin nære slekt for å ha omgang med henne; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Din fars og din mors leie skal du ikke vanære; hun er din mor, du skal ikke ha omgang med henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Din stedmor skal du ikke ha omgang med; hun er din fars hustru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Din søster, enten det er din fars datter eller din mors datter, enten hun er født hjemme eller født ute, skal du ikke ha omgang med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Din sønnedatter eller din datterdatter skal du ikke ha omgang med; for det er ditt eget kjød.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Din stedmors datter, som også er din fars datter, skal du ikke ha omgang med; hun er din søster.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Din fars søster skal du ikke ha omgang med; hun er din fars nære slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Din mors søster skal du ikke ha omgang med; for hun er din mors nære slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Din farbrors leie skal du ikke vanære, hans hustru skal du ikke komme for nær; hun er din fars søster.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Din sønnekone skal du ikke ha omgang med; hun er din sønns hustru, du skal ikke ha omgang med henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Din brors hustru skal du ikke ha omgang med - ikke vanære din brors leie.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Du skal ikke ha omgang med en kvinne og tillike med hennes datter; hennes sønnedatter eller hennes datterdatter skal du heller ikke ta og ha omgang med; de er hennes nære slekt, det er skammelig ferd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Du skal ikke ta din hustrus søster til ekte mens din hustru lever, så du vekker fiendskap mellem dem ved å ha omgang med dem begge.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'En kvinne som er uren i sin månedlige svakhet, skal du ikke gå inn til og ha omgang med.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Din næstes hustru skal du ikke ha samleie med, sa du blir uren ved henne.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Du skal ikke gi noget av dine barn fra dig til ildoffer for Molok; du skal ikke vanhellige din Guds navn; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Hos en mann skal du ikke ligge som en ligger hos en kvinne; det er en vederstyggelighet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Du skal ikke ha omgang med noget dyr, for da blir du uren; heller ikke skal en kvinne la noget dyr ha omgang med sig; det er skamløs ferd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Gjør eder ikke urene med noget sådant! For alt dette gjorde de sig urene med de hedninger som jeg driver ut for eders øine,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'og landet blev urent, og jeg hjemsøker det for dets misgjerning, så landet utspyr sine innbyggere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Men I skal holde mine lover og mine bud og ikke gjøre nogen av disse vederstyggelige gjerninger, hverken den innfødte eller den fremmede som bor iblandt eder;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'for alle disse vederstyggelige gjerninger har landets innbyggere gjort, de som var der før eder, og således blev landet urent.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Ellers kommer landet til å utspy eder, fordi I gjør det urent, likesom det utspyr det folk som har vært der før eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'For hver den som gjør nogen av alle disse vederstyggelige gjerninger, skal utryddes av sitt folk, hver og en som gjør sådant.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Så skal I da ta vare på det jeg vil ha varetatt, så I ikke gjør efter nogen av de vederstyggelige skikker som de har fulgt før eder, og ikke fører urenhet over eder ved dem; jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Tal til hele Israels barns menighet og si til dem: I skal være hellige; for jeg, Herren eders Gud, er hellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'I skal ha ærefrykt enhver for sin mor og sin far, og I skal holde mine sabbater; jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'I skal ikke vende eder til avgudene og ikke gjøre eder støpte guder; jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Når I vil ofre takkoffer til Herren, da skal I ofre det således at han kan ha velbehag i eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Den dag I ofrer det, skal det etes, eller og dagen efter; men det som blir tilovers til den tredje dag, skal brennes op med ild.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Dersom det etes på den tredje dag, da er det en vederstyggelighet; Herren har da ikke velbehag i det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Og den som eter det, kommer til å lide for sin misgjerning, for han har vanhelliget det som var helliget Herren; han skal utryddes av sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Når I høster grøden i eders land, så skal du ikke skjære kornet helt ut til den ytterste kant av din aker, og de aks som blir liggende efter innhøstingen, skal du ikke sanke op,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Og du skal ikke holde efterhøst i din vingård og ikke sanke op de nedfalne bær i din vingård; du skal la dem ligge til den fattige og den fremmede; jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'I skal ikke stjele, og I skal ikke lyve, og ingen av eder skal gå svikefullt frem mot sin næste.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'I skal ikke sverge på løgn ved mitt navn, så du vanhelliger din Guds navn; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Du skal ikke frata din næste noget med urett og ikke rane noget fra ham; du skal ikke la en dagarbeiders lønn bli natten over hos dig til om morgenen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Du skal ikke banne en døv og ikke legge støt for en blind, men du skal frykte din Gud; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'I skal ikke gjøre urett i dommen; du skal ikke holde med nogen fordi han er ringe, og ikke gi nogen rett fordi han er mektig; du skal dømme din næste med rettferdighet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Du skal ikke gå omkring og baktale folk, du skal ikke stå din næste efter livet; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Du skal ikke hate din bror i ditt hjerte, men du skal irettesette din næste, forat du ikke skal få synd på dig for hans skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Du skal ikke hevne dig og ikke gjemme på vrede mot ditt folks barn, men du skal elske din næste som dig selv; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'I skal holde mine lover: Du skal ikke la to slags dyr av ditt fe parre sig med hverandre; du skal ikke så to slags sæd på din mark, og klær som er vevd av to slags garn, skal ikke komme på dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Når en mann ligger hos en kvinne og har omgang med henne, og hun er trælkvinne og festet til en annen mann, men ikke løskjøpt eller frigitt, da skal de straffes, men de skal ikke bøte med livet, fordi hun ikke var frigitt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Men han skal føre sitt skyldoffer frem for Herren, til inngangen til sammenkomstens telt, en skyldoffer-vær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Og med skyldoffer-væren skal presten gjøre soning for ham for Herrens åsyn, for den synd han har gjort; så får han forlatelse for den synd han har gjort.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Når I kommer inn i landet og planter alle slags frukttrær, da skal I holde deres første frukt for uren; i tre år skal de være urene for eder, og I skal ikke ete av dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'I det ferde år skal all deres frukt vies til Herren i en gledesfest,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'og først i det femte år kan I ete deres frukt - forat de siden kan bære dess mere for eder; jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'I skal ikke ete noget med blodet i. I skal ikke gi eder av med å tyde varsler eller spå av skyene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'I skal ikke rundskjære eders hår; heller ikke skal du klippe ditt skjegg kort.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'I skal ikke skjære i eders kjøtt av sorg over en avdød, og ikke brenne inn skrifttegn på eder; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Du skal ikke vanhellige din datter ved å la henne drive hor, forat ikke landet skal drive hor og bli fullt av skjensel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Mine sabbater skal I holde og ha ærefrykt for min helligdom; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'I skal ikke vende eder til dødningemanere og ikke ty til sannsigere, så I gjør eder urene ved dem; jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'For de grå hår skal du reise dig og ære den gamle, og du skal frykte din Gud; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Når en fremmed bor hos eder i eders land, da skal I ikke undertrykke ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Den fremmede som bor hos eder, skal regnes som en innfødt blandt eder, og du skal elske ham som dig selv, for I har selv vært fremmede i Egyptens land; jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'I skal ikke gjøre urett i dom, i lengdemål, i vekt eller i hulmål.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Rette vektskåler, rette vektlodder, rett efa og rett hin skal I ha; jeg er Herren eders Gud, som førte eder ut av Egyptens land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'I skal ta vare på alle mine lover og alle mine bud og holde dem; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Du skal si til Israels barn: Om nogen av Israels barn eller av de fremmede som bor i Israel, gir noget av sine barn fra sig til Molok, skal han late livet; folket i landet skal stene ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Jeg vil sette mitt åsyn mot den mann og utrydde ham av hans folk fordi han har gitt sitt barn fra sig til Molok og gjort min helligdom uren og vanhelliget mitt hellige navn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Om folket i landet lukker øinene til og ikke straffer en sådan mann med døden når han gir sitt barn fra sig til Molok,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'da vil jeg sette mitt åsyn mot denne mann og hans slekt, og ham og alle dem som følger ham i å drive avgudsdyrkelse med Molok, vil jeg utrydde av deres folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Når nogen vender sig til dødningemanere og sannsigere og driver avgudsdyrkelse med dem, da vil jeg sette mitt åsyn mot den mann og utrydde ham av hans folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'I skal hellige eder og være hellige; for jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Og I skal ta vare på mine lover og holde dem; jeg er Herren, som helliger eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Hver den som banner sin far eller sin mor, skal late livet; sin far og sin mor har han bannet, hans blod være over ham!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Når en mann driver hor med en annen manns hustru - med sin næstes hustru, da skal de begge late livet, både mannen og kvinnen som har drevet hor.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Når en mann ligger hos sin fars hustru, har han vanæret sin fars leie; de skal begge late livet, deres blod være over dem!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Når en mann ligger hos sin sønnekone, skal de begge late livet; de har gjort en vederstyggelig gjerning, deres blod være over dem!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Når en mann ligger hos en annen mann som en ligger hos en kvinne, da har de begge gjort en vederstyggelig gjerning; de skal late livet, deres blod være over dem!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Når en mann tar både mor og datter til ekte, da er det skammelig ferd; både han og kvinnene skal brennes med ild; slik skam skal ikke finnes blandt eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'En mann som har omgang med et dyr, skal late livet, og dyret skal I drepe.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Når en kvinne kommer nær noget dyr og har omgang med det, da skal du slå ihjel både kvinnen og dyret; de skal late livet, deres blod være over dem!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Når en mann tar sin søster, sin fars eller sin mors datter, til ekte og har omgang med henne, og hun med ham, da er det skammelig ferd, og de skal utryddes for sitt folks øine; han har hatt omgang med sin søster, han skal lide for sin misgjerning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Når en mann ligger hos en kvinne som har sin månedlige urenhet, og har omgang med henne, da har han avdekket hennes kilde, og hun har avdekket sitt blods kilde; de skal begge utryddes av sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Din mors eller din fars søster skal du ikke ha omgang med, for den som gjør dette, vanærer sin nærmeste slekt; de skal lide for sin misgjerning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Når en mann ligger hos sin farbrors hustru, har han vanæret sin farbror; de skal lide for sin synd, de skal dø barnløse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Når en mann tar sin brors hustru, da er det skamløs ferd; han har vanæret sin bror, de skal være barnløse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'I skal ta vare på alle mine lover og alle mine bud og holde dem, forat ikke landet skal utspy eder, det land som jeg fører eder til og vil la eder bo i,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'og I skal ikke følge det folks skikker som jeg driver ut for eder; for alt dette har de gjort, og jeg vemmedes ved dem,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'og jeg sa til eder: I skal ta deres land i eie, og jeg vil gi eder det til eiendom, et land som flyter med melk og honning; jeg er Herren eders Gud, som har skilt eder ut fra folkene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Derfor skal I skille mellem rene dyr og urene og mellem urene fugler og rene og ikke gjøre eder selv vederstyggelige ved å ete de firføtte dyr eller de fugler eller det kryp på jorden som jeg har skilt ut for eder, forat I skal holde dem for urene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'I skal være hellige for mig; for jeg, Herren, er hellig, og jeg har skilt eder ut fra folkene, forat I skal høre mig til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Når det i en mann eller kvinne er en dødningemaner-ånd eller en sannsiger-ånd, da skal de late livet; de skal stenes, deres blod være over dem!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Og Herren sa til Moses: Tal til prestene, Arons sønner, og si til dem: En prest skal ikke gjøre sig uren blandt sitt folk ved å røre et lik,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'undtagen det er hans nærmeste slekt, hans mor, hans far, hans sønn, hans datter, hans bror');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'eller hans ugifte søster, som ennu hører til ætten og ikke er blitt nogen manns hustru; ved henne kan han gjøre sig uren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Han skal ikke gjøre sig uren som ektemann, så han vanhelliger sig blandt sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'De skal ikke rake sig skallet på nogen del av sitt hode og ikke klippe sitt skjegg kort og ikke skjære i sitt kjøtt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'De skal være hellige for sin Gud og ikke vanhellige sin Guds navn; for de bærer frem Herrens ildoffer, sin Guds mat, derfor skal de være hellige.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'En skjøge eller en kvinne som er vanæret, skal de ikke ta til ekte, og heller ikke en kvinne som hennes mann har skilt sig fra; for presten er hellig for sin Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Og du skal holde ham hellig, for han bærer frem din Guds mat; han skal være hellig for dig, for jeg, Herren, som helliger eder, er hellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Og dersom en prests datter vanhelliger sig ved å drive hor, så vanhelliger hun sin far; hun skal brennes med ild.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Den som er yppersteprest blandt sine brødre, han på hvis hode salvings-oljen er utøst, og som er innvidd og har iklædd sig de hellige klær, han skal ikke rake sitt hode og ikke sønderrive sine klær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Han skal ikke gå inn til noget lik; ikke engang ved sin far eller sin mor skal han føre urenhet over sig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Han skal ikke gå ut av helligdommen for ikke å vanhellige sin Guds helligdom; for innvielsen han fikk ved sin Guds salvings-olje, er over ham; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Til hustru skal han ta en ren jomfru;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'en enke eller en fraskilt eller en vanæret kvinne eller en skjøge - nogen sådan må han ikke gifte sig med; bare en jomfru av sitt folk skal han ta til hustru.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Han skal ikke vanhellige sin ætt blandt sitt folk; for jeg er Herren, som helliger ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Tal til Aron og si: Ingen av din ætt, enten nu eller i kommende tider, som har noget lyte, skal trede nær for å bære frem sin Guds mat.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Ingen som har noget lyte, skal trede nær, ingen som er blind eller halt eller har noget ansiktslyte eller et lem som er for stort,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'ingen som har brukket fot eller hånd,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'eller som er pukkelrygget eller dverg eller har en hvit flekk på øiet eller har skabb eller noget annet utslett, eller hvis stener er knust.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Ingen av Arons, prestens, ætt, som har noget lyte, skal trede nær for å bære frem Herrens ildoffer; han har et lyte, han skal ikke trede nær for å bære frem sin Guds mat.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Sin Guds mat kan han nok ete, både av de høihellige og av de hellige gaver;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'men han må ikke gå frem til forhenget og ikke trede nær til alteret, fordi han har et lyte; han skal ikke vanhellige mine helligdommer, for jeg er Herren, som helliger dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Og Moses sa dette til Aron og hans sønner og til alle Israels barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Tal til Aron og hans sønner og si at de skal se sig vel for med de hellige gaver som Israels barn helliger mig, og ikke vanhellige mitt hellige navn; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Si til dem: Dersom nogen av hele eders ætt, nu eller i kommende tider, kommer nær de hellige gaver som Israels barn helliger Herren, mens han har nogen urenhet på sig, så skal han utryddes fra mitt åsyn; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Ingen av Arons ætt som er spedalsk eller har flod, skal ete av de hellige gaver før han er blitt ren, ikke heller den som rører ved nogen som er blitt uren ved lik, eller den fra hvem det går sæd,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'eller den som rører ved noget kryp som en blir uren ved, eller ved et menneske som en blir uren ved, hvad urenhet det enn er.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'Den som rører ved noget sådant, skal være uren til om aftenen, og han skal ikke ete av de hellige gaver før han har badet sitt legeme i vann.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Når solen er gått ned, er han ren, og derefter kan han ete av de hellige gaver; for det er hans mat.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Det som er selvdødt eller sønderrevet, skal han ikke ete, for da blir han uren; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'De skal ta vare på det jeg vil ha varetatt, forat de ikke skal bære synd for noget sådant og dø fordi de vanhelliger det hellige; jeg er Herren, som helliger dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Ingen fremmed skal ete det hellige; en som har sitt tilhold hos presten eller er dagarbeider hos ham, må ikke ete det hellige.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Men når en prest kjøper en træl for sine penger, da kan trælen ete av det, likeså den som er født i hans hus; de kan ete av hans mat.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Når en prests datter blir en fremmed manns hustru, skal hun ikke ete av de hellige offergaver;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'men blir hun enke, eller er hun skilt fra sin mann, og hun ingen barn har, og hun vender tilbake til sin fars hus og bor hos ham likesom i sin ungdom, da kan hun ete av sin fars mat; men ingen fremmed skal ete av den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Når nogen eter noget hellig og ikke vet om det, skal han godtgjøre presten det hellige og legge femtedelen til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Prestene skal ikke vanhellige de hellige gaver som Israels barn ofrer til Herren,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'og således føre over dem misgjerning og skyld, når de eter deres hellige gaver; for jeg er Herren, som helliger dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Tal til Aron og hans sønner og til alle Israels barn og si til dem: Når nogen av Israels hus eller av de fremmede i Israel vil ofre sitt offer, enten det er et lovet offer eller et frivillig offer de vil ofre til Herren som brennoffer,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'da skal I gjøre det således at Herren kan ha velbehag i eder: Det skal være en han uten lyte av storfeet, av fårene eller av gjetene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Noget som det er lyte på, må I ikke ofre; for da har Herren ikke velbehag i eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Og når nogen vil ofre Herren et takkoffer av storfeet eller av småfeet, enten for å opfylle et løfte eller for å gi et frivillig offer, da skal det være uten lyte, forat Herren kan ha velbehag i det; der skal aldeles ikke være noget lyte på det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Dyr som er blinde eller benbrutt eller lemlestet, eller som har verkesår eller skabb eller annet utslett, skal I ikke ofre til Herren, og I skal ikke legge ildoffer av dem på alteret for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Et stykke storfe eller småfe som har et lem som er for stort eller for lite, kan du ofre som frivillig offer, men som lovet offer har Herren ikke velbehag i det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Et dyr som er gildet ved å trykkes eller knuses eller rives eller skjæres, skal I ikke bære frem for Herren; sådant skal I ikke gjøre i eders land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Heller ikke av en utlendings hånd skal I motta og ofre sådanne dyr som matoffer til eders Gud; for de er utskjemt, det er lyte på dem; med dem vinner I ikke Herrens velbehag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Når en kalv eller et lam eller et kje fødes, da skal de bli Syv dager hos moren; men fra den åttende dag av er de velbehagelige for Herren som ildoffer for ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'I skal ikke slakte et stykke storfe eller småfe på samme dag som dets unge.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Når I ofrer Herren et lovprisnings-offer, skal I gjøre det således at Herren kan ha velbehag i eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Det skal etes samme dag, I skal ikke levne noget av det til om morgenen; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'I skal ta vare på mine bud og holde dem; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'I skal ikke vanhellige mitt hellige navn, for jeg vil være helliget blandt Israels barn; jeg er Herren, som helliger eder,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'som førte eder ut av Egyptens land for å være eders Gud; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Tal til Israels barn og si til dem: Dette er Herrens høitider - mine høitider - som I skal utrope som hellige sammenkomster:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'I seks dager skal I arbeide; men på den syvende dag er det høihellig sabbat, en hellig sammenkomst; da skal I ikke gjøre noget arbeid; det er sabbat for Herren i alle eders hjem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Dette er Herrens høitider, de hellige sammenkomster, som I skal utrope til deres fastsatte tider:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'I den første måned, på den fjortende dag i måneden, mellem de to aftenstunder, er det påske for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Og på den femtende dag i samme måned er det de usyrede brøds høitid for Herren; i syv dager skal I ete usyret brød.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'På den første dag skal I holde en hellig sammenkomst, I skal ikke gjøre nogen arbeidsgjerning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'I syv dager skal I ofre ildoffer for Herren; på den syvende dag skal det være en hellig sammenkomst, I skal ikke gjøre nogen arbeidsgjerning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Tal til Israels barn og si til dem: Når I kommer inn i det land som jeg vil gi eder, og I høster dets grøde, da skal I komme til presten med det første kornbånd av eders høst.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Og han skal svinge kornbåndet for Herrens åsyn, forat Herren kan ha velbehag i eder; dagen efter sabbaten skal presten svinge det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Og samme dag som I svinger kornbåndet, skal I ofre et årsgammelt lam uten lyte til brennoffer for Herren');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'og matofferet som hører til: to tiendedeler av en efa fint mel, blandet med olje, til ildoffer for Herren, til en velbehagelig duft, og drikkofferet som hører til: fjerdedelen av en hin vin.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Og I skal ikke ete brød eller ristet eller friskt korn før den dag - før I har båret frem offeret for eders Gud; det skal være en evig lov for eder, fra slekt til slekt, i alle eders hjem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Fra dagen efter sabbaten, fra den dag I bærer frem svinge-kornbåndet, skal I telle fulle syv uker;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'femti dager skal I telle til dagen efter den syvende sabbat, og da skal I bære frem for Herren et offer av den nye grøde:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Fra eders hjemsteder skal I komme med to svingebrød, som er laget av to tiendedeler av en efa fint mel og bakt med surdeig; de er en førstegrøde for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Og sammen med brødet skal I føre frem syv årsgamle lam uten lyte og en oksekalv og to værer - de skal være til brennoffer for Herren - og matofferet og drikkofferne som hører til; det er et ildoffer til velbehagelig duft for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Og I skal ofre en gjetebukk til syndoffer og to årsgamle lam til takkoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Og presten skal svinge dem sammen med førstegrødens brød og to lam for Herrens åsyn; de skal være Herren helliget og tilhøre presten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Og samme dag skal I la utrope at det skal holdes en hellig sammenkomst; I skal ikke gjøre nogen arbeidsgjerning; det skal være en evig lov for eder, fra slekt til slekt, hvor I så bor.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Og når I høster grøden i eders land, skal du ikke under din innhøsting skjære kornet helt ut til ytterste kant av din aker, og de aks som blir liggende efter innhøstingen, skal du ikke sanke op; du skal la dem være igjen til den fattige og den fremmede; jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Tal til Israels barn og si: I den syvende måned, på den første dag i måneden, skal I holde hviledag med basunklang til ihukommelse og en hellig sammenkomst.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Da skal I ikke gjøre nogen arbeidsgjerning, og I skal ofre ildoffer til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Men på den tiende dag i den samme syvende måned er det soningsdag; da skal I holde en hellig sammenkomst, og I skal faste og ofre ildoffer til Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Den dag skal I ikke gjøre noget arbeid; for det er en sonings-dag; da skal det gjøres soning for eder for Herrens, eders Guds åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'For enhver som ikke faster den dag, skal utryddes av sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Og enhver som gjør noget arbeid den dag, han skal utryddes av sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Intet arbeid må I gjøre den dag; det skal være en evig lov for eder, fra slekt til slekt, hvor I så bor.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'En høihellig sabbat skal den være for eder, og I skal faste; på den niende dag i måneden om aftenen, fra den aften til den næste, skal I holde eders sabbatshvile.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Tal til Israels barn og si: På den femtende dag i denne samme syvende måned skal løvsalenes fest holdes for Herren, og den skal vare syv dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'På den første dag skal det være en hellig sammenkomst; I skal ikke gjøre nogen arbeidsgjerning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'I syv dager skal I ofre ildoffer til Herren; på den åttende dag skal I holde en hellig sammenkomst og ofre ildoffer til Herren; det er en festsammenkomst; I skal ikke gjøre nogen arbeidsgjerning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Dette er Herrens høitider; dem skal I utrope som hellige sammenkomster, og på dem skal I ofre Herren ildoffer, brennoffer og matoffer, slaktoffer og drikkoffer, hver dag det som hører dagen til,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'foruten Herrens sabbater og foruten eders gaver og foruten alle eders lovede offer og foruten alle eders frivillige offer som I gir Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Men på den femtende dag i den syvende måned, når I innsamler landets grøde, skal I holde Herrens fest, og den skal vare i syv dager; den første dag skal være hviledag, og den åttende dag skal være hviledag.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Og den første dag skal I ta frukter av fagre trær, palmegrener og kvister av løvrike trær og siljer som vokser ved bekkene; og I skal være glade for Herrens, eders Guds åsyn i syv dager.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Denne høitid skal I holde som en fest for Herren syv dager om året; det skal være en evig lov for eder, fra slekt til slekt; i den syvende måned skal I holde den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'I skal bo i løvhytter i syv dager, alle innfødte i Israel skal bo i løvhytter,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'forat eders efterkommere skal vite at jeg lot Israels barn bo i løvhytter da jeg førte dem ut av Egyptens land; jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Og Moses kunngjorde Herrens høitider for Israels barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Byd Israels barn at de skal la dig få ren olje av støtte oliven til lysestaken, så lampene kan settes op til enhver tid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Utenfor vidnesbyrdets forheng i sammenkomstens telt skal Aron alltid holde dem i stand fra aften til morgen for Herrens åsyn; det skal være en evig lov for eder, fra slekt til slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'På lysestaken av rent gull skal han alltid holde lampene i stand for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Du skal ta fint mel og bake tolv kaker av det; hver kake skal være to tiendedeler av en efa.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Og du skal legge dem i to rader, seks i hver rad, på bordet av rent gull for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Og du skal legge ren virak på hver rad, og den skal være et ihukommelses-offer for brødene, et ildoffer for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'På hver sabbatsdag skal brødene gjennem alle tider legges frem for Herrens åsyn; det skal være en gave fra Israels barn - en evig pakt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'De skal høre Aron og hans sønner til, og de skal ete dem på et hellig sted; for de er høihellige og er hans del av Herrens ildoffer - en evig rettighet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'En mann som var sønn av en israelittisk kvinne, men hadde en egypter til far, gikk engang ut blandt Israels barn. Da kom den israelittiske kvinnes sønn og en israelittisk mann i trette med hverandre i leiren,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'og den israelittiske kvinnes sønn spottet Herrens navn og bannet det, og de førte ham til Moses. Hans mor hette Selomit, Dibris datter, av Dans stamme.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'De satte ham fast, forat de kunde få avgjørelse ved et ord fra Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Før spotteren utenfor leiren, og alle de som hørte det, skal legge sine hender på hans hode, og hele menigheten skal stene ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Og du skal tale til Israels barn og si: Når nogen banner sin Gud, skal han lide for sin synd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Og den som spotter Herrens navn, skal late livet, hele menigheten skal stene ham; enten det er en fremmed eller en innfødt, skal han stenes når han spotter Herrens navn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Når en slår et menneske ihjel, skal han late livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Men den som slår et stykke fe ihjel, skal godtgjøre det, liv for liv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Når nogen volder sin næste mén på hans legeme, skal der gjøres det samme med ham som han selv har gjort:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'brudd for brudd, øie for øie, tann for tann; det samme mén som han volder en annen, skal han selv få.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Den som slår et stykke fe ihjel, skal godtgjøre det; men den som slår et menneske ihjel, skal late livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'En og samme rett skal gjelde for eder, den skal gjelde for den fremmede som for den innfødte; for jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Og Moses sa dette til Israels barn, og de førte spotteren utenfor leiren og stenet ham - Israels barn gjorde som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Og Herren talte til Moses på Sinai berg og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Tal til Israels barn og si til dem: Når I kommer inn i det land jeg vil gi eder, da skal landet ha en sabbatshvile for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'I seks år skal du tilså din aker, og i seks år skal du stelle med din vingård og høste landets grøde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Men i det syvende år skal det være en høihellig sabbat for landet, en sabbat for Herren; da skal du ikke tilså din aker og ikke stelle med din vingård.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Det som vokser av sig selv efterat du har høstet, skal du ikke skjære, og druene på ditt ustelte vintre skal du ikke sanke; det skal være et sabbatsår for landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Og det som vokser i landets sabbatsår, skal være til føde for eder, for dig og din tjener og din tjenestepike og din dagarbeider og de fremmede som holder til hos dig;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'og din buskap og de ville dyr som er i ditt land, skal også ete av all den grøde som vokser der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Så skal du telle frem syv sabbatsår, syv ganger syv år, så tiden for de syv sabbatsår blir ni og firti år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Og i den syvende måned, på den tiende dag i måneden, skal du la basunen lyde gjennem landet; på soningsdagen skal I la basunen lyde gjennem hele eders land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Og I skal holde det femtiende år hellig og utrope frihet i landet for alle dem som bor der; det skal være et jubelår for eder, og I skal komme tilbake, enhver til sin eiendom og enhver til sin slekt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Et jubelår skal dette femtiende år være for eder; ikke skal I så, og ikke skal I høste det som vokser av sig selv i det år, og ikke skal I sanke druene av de ustelte vintrær i det år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'For det er jubelår, hellig skal det være for eder; av marken skal I ete det den bærer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'I dette jubelår skal I komme tilbake, enhver til sin eiendom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Når du selger noget til din næste, eller du kjøper noget av din næste, da skal I ikke gjøre hverandre urett.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Efter tallet av år siden jubelåret skal du kjøpe av din næste; efter tallet av innhøstings-årene skal han selge til dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'For et større tall av år skal du gjøre kjøpesummen større, og for et mindre tall av år skal du gjøre kjøpesummen mindre; for det er bare et visst tall av avlinger han selger til dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Og ingen av eder skal gjøre sin næste urett, men du skal frykte din Gud; for jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'I skal holde mine lover og ta vare på mine bud og holde dem; så skal I bo trygt i landet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Og landet skal gi sin frukt, og I skal ete og bli mette og bo der trygt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Og om I sier: Hvad skal vi ete i det syvende år, når vi ikke sår og ikke samler inn vår grøde? -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'da vil jeg sende min velsignelse over eder i det sjette år, så det gir grøde for tre år.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'I det åttende år skal I så, men ennu ete av den gamle grøde; like til det niende års grøde kommer, skal I ete gammelt korn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Jorden må ikke selges for alle tider; for mig hører landet til, I er fremmede og gjester hos mig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'I hele det land I får til eie, skal I tillate innløsning av jorden.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Når din bror blir fattig og må selge noget av sin jordeiendom, da skal hans løser, hans nærmeste frende, komme og innløse det som hans bror har solgt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Og om en ikke har nogen løser, men selv får råd til det og kommer til å eie det som skal til for å innløse det,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'da skal han regne efter hvor mange år det er gått siden han solgte, og bare betale det overskytende til den mann han solgte til; så skal han komme til sin jordeiendom igjen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Men dersom han ikke har nok til å betale ham med, da skal det han har solgt, bli i dens eie som kjøpte det, helt til jubelåret; men i jubelåret skal det gis fritt, så han kommer til sin jordeiendom igjen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Når nogen selger et våningshus i en by som er omgitt med murer, da skal hans innløsningsrett vare inntil et helt år er gått efterat han har solgt; et år skal hans innløsningsrett vare.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Men dersom det ikke blir innløst innen et helt år er til ende, da skal huset, om det ligger i en by med murer omkring, for alle tider tilhøre den som kjøpte det, og hans efterkommere; det skal ikke gis fritt i jubelåret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Men husene i småbyer som ikke har murer omkring, skal regnes like med jordene på landet; de skal kunne innløses, og i jubelåret skal de gis fri.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Men gjelder det huser i byer som hører levittene til, da skal innløsningsretten vare gjennem alle tider.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Når en kjøper noget av en levitt, så skal et hus som er solgt, såfremt det ligger i hans egen by, gis fritt i jubelåret; for husene i levittenes byer er deres eiendom blandt Israels barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Men løkkene omkring deres byer må ikke selges; for de er deres eiendom for all tid.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Når din bror blir fattig og ikke lenger kan holde sig oppe, da skal du støtte ham; som en fremmed og en innerst skal han leve hos dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Du må ikke ta rente eller overmål av ham, men du skal frykte din Gud, så din bror kan leve med dig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Du skal ikke låne ham penger mot rente og ikke kreve noget i tillegg for den mat du låner ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Jeg er Herren eders Gud, som førte eder ut av Egyptens land for å gi eder Kana\'ans land og være eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Når din bror blir fattig og selger sig til dig, da skal du ikke la ham tjene hos dig som en træl tjener.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Han skal være hos dig som en dagarbeider eller innerst og tjene hos dig til jubelåret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Da skal han flytte fra dig, både han og hans barn, og dra hjem til sin slekt; til sin fedrene-eiendom skal han vende tilbake.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'For de er mine tjenere, som jeg har ført ut av Egyptens land; de skal ikke selges som en træl selges.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Du skal ikke herske over ham med hårdhet, men du skal frykte din Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Men vil du få dig en træl eller en trælkvinne, da skal I kjøpe dem av de hedningefolk som bor omkring eder,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'og likeledes blandt barna av de innerster som bor hos eder som fremmede; blandt dem og deres efterkommere, som bor hos eder og er født i eders land, kan I kjøpe træler eller trælkvinner, og de skal være eders eiendom,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'og I kan efterlate dem som arv til eders barn efter eder, så de kan ha dem til eiendom; I kan for all tid bruke dem som træler. Men over eders brødre, Israels barn, skal du ikke herske med hårdhet, bror over bror.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Når en fremmed eller innerst hos dig kommer til velstand, og en av dine brødre som bor nær ham, blir fattig og må selge sig til den fremmede som har tilhold hos dig, eller til en som stammer fra en fremmed manns slekt,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'da skal han kunne løses ut efterat han har solgt sig. En av hans brødre skal løse ham ut,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'eller hans farbror eller hans farbrors sønn eller en annen av de nærmeste slektninger i hans ætt, skal løse ham ut, eller får han råd til det, da skal han løse sig selv ut.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Når han da gjør op med den som har kjøpt ham, skal de regne ut tiden fra det år han solgte sig til ham, og til jubelåret, og pengene som han solgte sig for, skal deles med årenes tall; den tid han har vært hos ham, skal regnes som om han hadde vært dagarbeider.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Dersom det ennu er mange år tilbake, da skal han til utløsning betale tilbake en tilsvarende del av de penger han blev kjøpt for.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Men dersom det er få år tilbake til jubelåret, så skal han gjøre op med ham efter dem; efter sine tjeneste-år skal han betale sin løsningssum.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Som en dagarbeider som tjener år for år, skal han være hos ham; du må ikke tåle at han hersker over ham med hårdhet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Men dersom han ikke løses ut på en av disse måter, da skal han bli fri i jubelåret, både han og hans barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'For mig hører Israels barn til som tjenere, de er mine tjenere, som jeg har ført ut av Egyptens land; jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'I skal ikke gjøre eder avguder og ikke reise op utskårne billeder eller støtter og ikke sette stener med billeder i eders land for å tilbede ved dem; for jeg er Herren eders Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Mine sabbater skal I holde, og for min helligdom skal I ha ærefrykt; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Dersom I vandrer i mine lover og tar vare på mine bud og holder dem,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'da vil jeg gi eder regn i rette tid, og jorden skal gi sin grøde, og markens trær skal gi sin frukt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Og tresketiden skal vare hos eder like til vinhøsten, og vinhøsten skal vare inntil kornet såes, og I skal ete eder mette av brødet som I har avlet, og bo trygt i eders land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Og jeg vil gi fred i landet, og I skal hvile i ro, og ingen skal forferde eder; jeg vil rydde ut de ville dyr av landet, og sverd skal ikke fare gjennem eders land.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Og I skal forfølge eders fiender, og de skal falle for eders sverd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Fem av eder skal forfølge hundre, og hundre av eder skal forfølge ti tusen, og eders fiender skal falle for eders sverd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Og jeg vil vende mig til eder og gjøre eder fruktbare og tallrike, - og jeg vil holde min pakt med eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Og I skal ha gammel grøde å ete inntil I må føre den bort for den nye grødes skyld.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Og jeg vil sette min bolig midt iblandt eder, og jeg skal aldri forkaste eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Og jeg vil vandre midt iblandt eder, og jeg vil være eders Gud, og I skal være mitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Jeg er Herren eders Gud, som førte eder ut av Egyptens land, forat I ikke mere skulde være deres træler, og jeg brøt sønder eders åks stenger og lot eder gå opreist.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Men dersom I ikke lyder mig og ikke holder alle disse bud,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'dersom I forakter mine forskrifter, og dersom I forkaster mine lover, så I ikke holder alle mine bud, men bryter min pakt,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'da vil også jeg gjøre således mot eder: Jeg vil hjemsøke eder med redsler, med tærende sott og brennende feber, så eders øine slukner og sjelen vansmekter; til ingen nytte skal I så eders sæd, eders fiender skal ete den op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Og jeg vil sette mitt åsyn mot eder, og eders fiender skal slå eder, og de som hater eder, skal herske over eder, og I skal flykte skjønt ingen forfølger eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Og dersom I enda ikke lyder mig, da vil jeg tukte eder syvfold mere for eders synder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Jeg vil bryte eders styrkes overmot, og jeg vil gjøre eders himmel som jern og eders jord som kobber.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Til ingen nytte skal I fortære eders kraft, og eders land skal ikke gi sin grøde, og trærne i landet skal ikke gi sin frukt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Og dersom I enda står mig imot og ikke vil lyde mig, da vil jeg slå eder syvfold mere, som eders synder fortjener.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Jeg vil sende ville dyr imot eder, og de skal røve eders barn fra eder og ødelegge eders fe og forminske eders tall, og eders veier skal bli øde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Og dersom I enda ikke lar eder tukte av mig, men står mig imot,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'da vil også jeg stå eder imot og slå eder syvfold mere for eders synder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Jeg vil føre over eder et sverd som hevner pakten, og samler I eder i eders byer, da vil jeg sende pest inn iblandt eder, og I skal gis i fiendens hånd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Når jeg bryter sønder brødets stav for eder, da skal ti kvinner bake eders brød i én ovn og gi eder brødet igjen efter vekt, og I skal ete og ikke bli mette.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Og dersom I enda ikke lyder mig, men står mig imot,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'da vil også jeg stå eder imot i vrede og tukte eder syvfold mere for eders synder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'I skal ete eders sønners kjøtt og ete eders døtres kjøtt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Og jeg vil ødelegge eders offerhauger og utrydde eders solstøtter og kaste eders døde kropper ovenpå de døde kropper av eders vederstyggelige avguder, og min sjel skal vemmes ved eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Og jeg vil gjøre eders byer til en ørken og legge eders helligdommer øde, og jeg vil ikke nyte vellukten av eders offer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Og jeg vil legge landet øde, så eders fiender som bor der, skal forferdes over det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Men eder vil jeg sprede blandt hedningene, og med draget sverd vil jeg forfølge eder; eders land skal bli øde og eders byer en ørken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Da skal landet gjøre fyldest for sine sabbatsår hele den tid det ligger øde, mens I er i eders fienders land; da skal landet hvile og gjøre fyldest for sine sabbatsår.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Hele den tid det ligger øde, skal det ha hvile, den hvile som det ikke fikk i eders sabbatsår, da I bodde der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Og de som blir igjen av eder, dem vil jeg gi et motløst hjerte i sine fienders land, så lyden av et henværet blad vil jage dem, og de skal flykte som en flykter for sverd, og falle skjønt ingen forfølger dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Og de skal falle, den ene over den andre, som for sverd skjønt ingen forfølger dem; og I skal ikke holde stand mot eders fiender.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Og I skal gå til grunne blandt hedningene, og eders fienders land skal fortære eder.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Og de som blir igjen av eder, skal visne bort i eders fienders land for sin misgjernings skyld; også for sine fedres misgjerninger, som hviler på dem, skal de visne bort.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Da skal de bekjenne sin misgjerning og sine fedres misgjerning, som de gjorde i sin troløshet mot mig, og bekjenne at de stod mig imot');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, '- derfor stod også jeg dem imot og førte dem inn i deres fienders land - ja, da skal deres uomskårne hjerte ydmyke sig, og de skal bøte for sin misgjerning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Og så vil jeg komme i hu min pakt med Jakob, og min pakt med Isak og min pakt med Abraham vil jeg komme i hu, og landet vil jeg komme i hu.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Men landet skal først være forlatt av dem og gjøre fyldest for sine sabbatsår, mens det ligger øde og forlatt av dem, og de skal bøte for sin misgjerning, efterdi de foraktet mine lover og forkastet mine bud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Men selv da, når de er i sine fienders land, vil jeg ikke støte dem bort og ikke forkaste dem, så jeg skulde tilintetgjøre dem og bryte min pakt med dem; for jeg er Herren deres Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Og jeg vil til beste for dem komme i hu pakten med fedrene, som jeg førte ut av Egyptens land midt for hedningenes øine for å være deres Gud; jeg er Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Dette er de forskrifter og de bud og de lover som Herren satte mellem sig og Israels barn på Sinai berg ved Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Tal til Israels barn og si til dem: Når nogen gjør et hellig løfte efter det verd du setter på folk som helliger sig til Herren,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'da skal du verdsette en mann som er mellem tyve og seksti år gammel, til femti sekel sølv efter helligdommens sekel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Men er det en kvinne, da skal du verdsette henne til tretti sekel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Er det en som er mellem fem år og tyve år gammel, da skal du verdsette en som er av mannkjønn, til tyve sekel, og en som er av kvinnekjønn, til ti sekel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Er det en som er mellem en måned og fem år gammel, da skal du verdsette en gutt til fem sekel sølv og en pike til tre sekel sølv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Er det en som er seksti år gammel eller derover, da skal du, dersom det er en mann, verdsette ham til femten sekel, og en kvinne til ti sekel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Men dersom nogen er for fattig til å betale efter din verdsetning, da skal han stilles frem for presten, og presten skal verdsette ham; efter som den som har gjort løftet, har råd til, skal presten verdsette ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Dersom det er dyr, sådanne som en ofrer til Herren, da skal alt det en gir Herren av sådant, være hellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'En skal ikke gi noget annet i stedet og ikke bytte det, hverken et godt med et dårlig eller et dårlig med et godt; bytter nogen et dyr med et annet, da skal både det og det som det byttes med, være hellig.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Men dersom det er et eller annet urent dyr, som en ikke ofrer til Herren, da skal dyret stilles frem for presten,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'og presten skal verdsette det efter som det er, godt eller dårlig; som du, prest, verdsetter det, således skal det være.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Men vil nogen innløse det, da skal han gi femtedelen mere enn det du har verdsatt det til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Når nogen helliger sitt hus som gave til Herren, da skal presten verdsette det efter som det er, godt eller dårlig; som presten verdsetter, til hvis arvejord i landet den har således skal det stå ved makt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Men dersom den som har helliget sitt hus, vil innløse det, da skal han gi femtedelen mere enn du har verdsatt det til, så blir det hans.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Dersom nogen helliger Herren noget av sin jordeiendom, da skal du verdsette det efter utsæden, en homer byggsæd til femti sekel sølv.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Dersom han helliger sin jord fra jubelåret av, da skal din verdsetning stå ved makt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Men dersom han helliger sin jord efter jubelåret, da skal presten utregne pengene efter de år som er tilbake til næste jubelår; og der skal gjøres avkortning i det verd du har satt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Vil den som har helliget jorden, innløse den, da skal han gi femtedelen mere enn du har verdsatt den til, så skal den være hans for godt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Men dersom han ikke innløser jorden, eller han selger den til en annen, da kan den ikke innløses mere.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Men når jorden gis fri i jubelåret, skal den være helliget Herren, likesom bannlyst jord; den skal høre presten til som hans eiendom.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Men dersom nogen helliger Herren et jordstykke som han har kjøpt, som ikke har hørt til den jordeiendom han har arvet,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'da skal presten utregne for ham hvor høit det skal verdsettes, efter tiden inntil jubelåret, og han skal samme dag gi det du verdsetter det til; det skal være helliget Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'I jubelåret skal jorden komme tilbake til den han har kjøpt den av, til hvis arvejord i lander har hørt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'All din verdsetning skal skje efter helligdommens sekel; sekelen skal være tyve gera.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Det førstefødte i buskapen skal ikke nogen hellige; som førstefødt hører det Herren til, enten det er et stykke storfe eller småfe, hører det Herren til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Men dersom det er av de urene dyr, da skal en innløse det efter din verdsetning og legge femtedelen til; dersom det ikke innløses, da skal det selges efter din verdsetning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Men intet bannlyst som nogen vier til Herren av alt det han eier, må selges eller innløses, enten det er folk eller fe eller jordeiendom; alt bannlyst er høihellig for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Intet menneske som lyses i bann, skal løses; han skal late livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'All landets tiende av jordens sæd og av trærnes frukt hører Herren til; den er helliget Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Vil nogen innløse noget av sin tiende, da skal han legge femtedelen til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Og all tiende av storfe og av småfe, av alt det som går under hyrdestaven - hvert tiende stykke - skal være helliget Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'En skal ikke se efter om det er godt eller dårlig, og ikke bytte det; bytter en det, da skal både det og det som det byttes med, være hellig; det skal ikke innløses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Dette er de bud som Herren gav Moses på Sinai berg og bød ham kunngjøre for Israels barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Og Herren talte til Moses i Sinai ørken i sammenkomstens telt på den første dag i den annen måned i det annet år efterat de var gått ut av Egyptens land, og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Ta op manntall over hele Israels barns menighet efter deres ætter og familier og skriv op deres navn - alle som er av mannkjønn, en for en,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'fra tyveårsalderen og opover; alle dem i Israel som kan dra ut i krig, skal I mønstre, hær efter hær, du og Aron.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'I skal ha med eder en mann for hver stamme, den som er overhode for stammens familier.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Dette er navnene på de menn som I skal ha til hjelp: For Ruben: Elisur, Sede\'urs sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'for Simeon: Selumiel, Surisaddais sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'for Juda: Nahson, Amminadabs sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'for Issakar: Netanel, Suars sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'for Sebulon: Eliab, Helons sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'for Josefs sønner, for Efra\'im: Elisama, Ammihuds sønn, for Manasse: Gamliel, Pedasurs sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'for Benjamin: Abidan, Gideonis sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'for Dan: Akieser, Ammisaddais sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'for Aser: Pagiel, Okrans sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'for Gad: Eljasaf, De\'uels sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'for Naftali: Akira, Enans sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Dette var menighetens utkårne, høvdingene for sine fedrenestammer, overhodene for Israels tusener.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Da lot Moses og Aron disse menn, som var nevnt ved navn, komme,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'og de samlet hele menigheten på den første dag i den annen måned; og de lot sig innføre i ættelistene med sine navn, efter sine ætter og familier, fra tyveårsalderen og opover, en for en,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'således som Herren hadde befalt Moses; og han mønstret dem i Sinai ørken.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Efterkommerne av Rubens sønner - han som var Israels førstefødte - opskrevet efter sine ætter og familier, med sine navn, en for en, alt mannkjønn fra tyveårsalderen og opover, alle som kunde dra ut i krig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'så mange som blev mønstret av Rubens stamme, var seks og firti tusen og fem hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Efterkommerne av Simeons sønner, opskrevet efter sine ætter og familier, med sine navn, så mange av dem som blev mønstret, en for en, alt mannkjønn fra tyveårsalderen og opover, alle som kunde dra ut i krig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'så mange som blev mønstret av Simeons stamme, var ni og femti tusen og tre hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Efterkommerne av Gads sønner, opskrevet efter sine ætter og familier, med sine navn, fra tyveårsalderen og opover, alle som kunde dra ut i krig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'så mange som blev mønstret av Gads stamme, var fem og firti tusen, seks hundre og femti.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Efterkommerne av Judas sønner, opskrevet efter sine ætter og familier, med sine navn, fra tyveårsalderen og opover, alle som kunde dra ut i krig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'så mange som blev mønstret av Juda stamme, var fire og sytti tusen og seks hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Efterkommerne av Issakars sønner, opskrevet efter sine ætter og familier, med sine navn, fra tyveårsalderen og opover, alle som kunde dra ut i krig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'så mange som blev mønstret av Issakars stamme, var fire og femti tusen og fire hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Efterkommerne av Sebulons sønner, opskrevet efter sine ætter og familier, med sine navn, fra tyveårsalderen og opover, alle som kunde dra ut i krig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'så mange som blev mønstret av Sebulons stamme, var syv og femti tusen og fire hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Josefs barn: Efterkommerne av Efra\'ims sønner, opskrevet efter sine ætter og familier, med sine navn, fra tyveårsalderen og opover, alle som kunde dra ut i krig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'så mange som blev mønstret av Efra\'ims stamme, var firti tusen og fem hundre;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'efterkommerne av Manasses sønner, opskrevet efter sine ætter og familier, med sine navn, fra tyveårsalderen og opover, alle som kunde dra ut i krig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'så mange som blev mønstret av Manasse stamme, var to og tretti tusen og to hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Efterkommerne av Benjamins sønner, opskrevet efter sine ætter og familier, med sine navn, fra tyveårsalderen og opover, alle som kunde dra ut i krig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'så mange som blev mønstret av Benjamins stamme, var fem og tretti tusen og fire hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Efterkommerne av Dans sønner, opskrevet efter sine ætter og familier, med sine navn, fra tyveårsalderen og opover, alle som kunde dra ut i krig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'så mange som blev mønstret av Dans stamme, var to og seksti tusen og syv hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Efterkommerne av Asers sønner, opskrevet efter sine ætter og familier, med sine navn, fra tyveårsalderen og opover, alle som kunde dra ut i krig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'så mange som blev mønstret av Asers stamme, var en og firti tusen og fem hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Efterkommerne av Naftalis sønner, opskrevet efter sine ætter og familier, med sine navn, fra tyveårsalderen og opover, alle som kunde dra ut i krig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'så mange som blev mønstret av Naftali stamme, var tre og femti tusen og fire hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Dette var de som blev mønstret, de som Moses og Aron og Israels høvdinger mønstret, og høvdingene var tolv i tallet, en for hver stamme.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Og alle de av Israels barn som blev mønstret efter sine familier, fra tyveårsalderen og opover, alle i Israel som kunde dra ut i krig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'så mange som blev mønstret, var seks hundre og tre tusen, fem hundre og femti;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Men levittene efter sin fedrenestamme blev ikke mønstret sammen med dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'For Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Bare Levi stamme skal du ikke mønstre, og over dem skal du ikke opta manntall sammen med de andre Israels barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Men du skal sette levittene over vidnesbyrdets tabernakel og over alle dets redskaper og over alt som hører til; de skal bære tabernaklet og alle dets redskaper, og de skal tjene ved tabernaklet og leire sig rundt omkring det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Når tabernaklet skal bryte op, skal levittene ta det ned, og når tabernaklet skal leire sig, skal levittene reise det op; kommer nogen fremmed;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Israels barn skal leire sig, hver i sin leir og hver ved sitt banner, hær for hær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Men levittene skal leire sig rundt omkring vidnesbyrdets tabernakel, forat det ikke skal komme vrede over Israels barns menighet; og levittene skal ta vare på det som er å vareta ved vidnesbyrdets tabernakel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Og Israels barn gjorde så; de gjorde i ett og alt således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Og Herren talte til Moses og Aron og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Israels barn skal leire sig, hver ved sitt banner, ved sin families hærmerke; de skal leire sig midt imot sammenkomstens telt, rundt omkring det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'På fremsiden, mot øst, skal Juda leire sig under sitt banner, hær for hær; og høvdingen for Judas barn er Nahson, Amminadabs sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'og hans hær, så mange av dem som er mønstret, er fire og sytti tusen og seks hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Ved siden av ham skal Issakars stamme leire sig; og høvdingen for Issakars barn er Netanel, Suars sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'og hans hær, så mange av dem som er mønstret, er fire og femti tusen og fire hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Likeså Sebulons stamme; og høvdingen for Sebulons barn er Eliab, Helons sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'og hans hær, så mange av dem som er mønstret, er syv og femti tusen og fire hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Alle som er mønstret av Judas leir, hær for hær, er hundre og seks og åtti tusen og fire hundre; de skal være den første fylking som bryter op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Mot syd skal Ruben leire sig under sitt banner, hær for hær; og høvdingen for Rubens barn er Elisur, Sede\'urs sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'og hans hær, så mange av dem som er mønstret, er seks og firti tusen og fem hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Ved siden av ham skal Simeons stamme leire sig; og høvdingen for Simeons barn er Selumiel, Surisaddais sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'og hans hær, så mange av dem som er mønstret, er ni og femti tusen og tre hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Likeså Gads stamme; og høvdingen for Gads barn er Eljasaf, Re\'uels sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'og hans hær, så mange av dem som er mønstret, er fem og firti tusen, seks hundre og femti.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Alle som er mønstret av Rubens leir, hær for hær, er hundre og en og femti tusen, fire hundre og femti; de skal være den annen fylking som bryter op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Så skal sammenkomstens telt bryte op, levittenes leir i midten av leirene; de skal bryte op efter som de har leiret sig, hver på sin plass under sine banner.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Mot vest skal Efra\'im leire sig under sitt banner, hær for hær; og høvdingen for Efra\'ims barn er Elisama, Ammihuds sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'og hans hær, så mange av dem som er mønstret, er firti tusen og fem hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Ved siden av ham Manasse stamme; og høvdingen for Manasses barn er Gamliel, Pedasurs sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'og hans hær, så mange av dem som er mønstret, er to og tretti tusen og to hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Likeså Benjamins stamme; og høvdingen for Benjamins barn er Abidan, Gideonis sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'og hans hær, så mange av dem som er mønstret, er fem og tretti tusen og fire hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Alle som er mønstret av Efra\'ims leir, hær for hær, er hundre og åtte tusen og et hundre; de skal være den tredje fylking som bryter op.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Mot nord skal Dan leire sig under sitt banner, hær for hær; og høvdingen for Dans barn er Akieser, Ammisaddais sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'og hans hær, så mange av dem som er mønstret, er to og seksti tusen og syv hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Ved siden av ham skal Asers stamme leire sig; og høvdingen for Asers barn er Pagiel, Okrans sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'og hans hær, så mange av dem som er mønstret, er en og firti tusen og fem hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Likeså Naftali stamme; og høvdingen for Naftalis barn er Akira, Enans sønn,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'og hans hær, så mange av dem som er mønstret, er tre og femti tusen og fire hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Alle som er mønstret av Dans leir, er hundre og syv og femti tusen og seks hundre; de skal være den siste fylking som bryter op under sine banner.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Dette var de av Israels barn som blev mønstret, efter sine familier; i alt var det seks hundre og tre tusen, fem hundre og femti mann som blev mønstret i leirene, hær for hær.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Men levittene blev ikke mønstret sammen med de andre Israels barn, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Og Israels barn gjorde så; de leiret sig under sine banner og brøt op, enhver efter sin ætt og sin familie, i alle deler således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Dette var Arons og Moses\' ætt på den tid Herren talte med Moses på Sinai berg.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Navnene på Arons sønner var: Nadab, som var den førstefødte, dernæst Abihu, Eleasar og Itamar.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Dette var navnene på Arons sønner, de salvede prester, som var innvidd til å gjøre prestetjeneste.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Men Nadab og Abihu døde for Herrens åsyn, dengang de bar fremmed ild inn for Herrens åsyn i Sinai ørken, og de hadde ingen sønner; siden utførte Eleasar og Itamar prestetjenesten for Arons, sin fars øine.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'La Levi stamme komme hit og still den frem for Aron, presten, så de kan tjene ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Og de skal ta vare på det han og hele menigheten skulde varetatt foran sammenkomstens telt, og således utføre tjenesten ved tabernaklet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Og de skal ta vare på alt som hører til sammenkomstens telt, og på det som Israels barn skulde varetatt; og således skal de utføre tjenesten ved tabernaklet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Du skal gi levittene til Aron og hans sønner; blandt Israels barn skal de være helt overgitt til ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Men Aron og hans sønner skal du sette til å ta vare på sin prestetjeneste; kommer en fremmed nær til, skal han late livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Se, jeg har tatt levittene ut blandt Israels barn i stedet for alle førstefødte, dem som åpner morsliv blandt Israels barn, forat levittene skal høre mig til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'For mig hører alt førstefødt til; den dag jeg slo alt førstefødt i Egyptens land, helliget jeg mig alt som førstefødt er i Israel, både folk og fe; de skal høre mig til, mig, Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Og Herren talte til Moses i Sinai ørken og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Du skal mønstre Levis barn efter deres familier og ætter! Alt mannkjønn, fra den som er en måned gammel, og opover, skal du mønstre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Så mønstret Moses dem efter Herrens ord, som det var befalt ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Navnene på Levis sønner var: Gerson og Kahat og Merari.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Og navnene på Gersons sønner efter deres ætter var: Libni og Sime\'i.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Og Kahats sønner efter sine ætter var Amram og Jishar, Hebron og Ussiel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Og Meraris sønner efter sine ætter var Mahli og Musi. Dette var Levis ætter med sine familier.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Til Gerson hørte libnittenes ætt og sime\'ittenes ætt; dette var gersonittenes ætter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'De av dem som blev mønstret, idet der blev tatt tall på alt mannkjønn, fra den som var en måned gammel, og opover, var syv tusen og fem hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Gersonittenes ætter hadde sin leir bak tabernaklet, mot vest.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Og høvdingen for gersonittenes familie var Eljasaf, Laels sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Og det som Gersons barn hadde å ta vare på ved sammenkomstens telt, var selve tabernaklet med dekke og varetak og dekket for inngangen til sammenkomstens telt,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'og omhengene til forgården og forhenget for inngangen til forgården som er rundt om tabernaklet og alteret, og dets snorer og alt arbeidet derved.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Til Kahat hørte amramittenes ætt og jisharittenes ætt og hebronittenes ætt og ussielittenes ætt; dette var kahatittenes ætter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Da der blev tatt tall på alt mannkjønn, fra den som var en måned gammel, og opover, var de åtte tusen og seks hundre mann, som skulde ta vare på det som var å vareta ved helligdommen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Kahats barns ætter hadde sin leir ved siden av tabernaklet mot syd.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Og høvdingen for Kahat-ættenes familie var Elisafan, Ussiels sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Og det de hadde å ta vare på, var arken og bordet og lysestaken og alterne og helligdommens redskaper som bruktes ved tjenesten, og forhenget og alt arbeidet derved.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Men den øverste høvding for levittene var Eleasar, sønn til Aron, presten; han var satt over dem som skulde ta vare på det som var å vareta ved helligdommen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Til Merari hørte mahlittenes ætt og musittenes ætt; dette var merarittenes ætter.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'De av dem som blev mønstret, idet der blev tatt tall på alt mannkjønn, fra dén som var en måned gammel, og opover, var seks tusen og to hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Og høvdingen for Merariættenes familie var Suriel, Abiha\'ils sønn; de hadde sin leir ved siden av tabernaklet mot nord.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Og det som Meraris barn var satt til å ta vare på, var tabernaklets planker og dets tverrstenger og dets stolper og dets fotstykker og alt som hørte til, og alt arbeidet derved');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'og stolpene til forgården rundt omkring og fotstykkene og pluggene og snorene som hørte til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Men foran tabernaklet, mot øst, foran sammenkomstens telt, mot solens opgang, hadde Moses og Aron og hans sønner sin leir, og de tok vare på det som var å vareta ved helligdommen, det som Israels barn skulde varetatt; men kom en fremmed nær til, skulde han late livet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Alle de av levittene som blev mønstret, de som Moses og Aron mønstret efter Herrens ord, ætt for ætt, alt mannkjønn, fra den som var en måned gammel, og opover, var to og tyve tusen.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Og Herren sa til Moses: Du skal mønstre alle førstefødte av mannkjønn blandt Israels barn, fra den som er en måned gammel, og opover, og føre deres navn inn i manntallet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Og så skal du la mig, Herren, få levittene i stedet for alle førstefødte blandt Israels barn, og levittenes fe i stedet for alt førstefødt blandt Israels barns fe.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Da mønstret Moses alle førstefødte blandt Israels barn, således som Herren hadde befalt ham.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Og da han tok tall på alle førstefødte av mannkjønn og skrev op deres navn, fra den som var en måned gammel, og opover, var de, så mange som blev mønstret, to og tyve tusen, to hundre og tre og sytti.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Du skal ta levittene i stedet for alle førstefødte blandt Israels barn og levittenes fe i stedet for deres fe; og levittene skal høre mig til, mig, Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Men som løsepenger for de to hundre og tre og sytti førstefødte av Israels barn som overskrider levittenes tall,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'skal du ta fem sekel for hver; efter helligdommens sekel skal du ta dem, sekelen regnet til tyve gera.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Og du skal gi Aron og hans sønner disse penger som løsepenger for de overtallige blandt dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Så tok Moses løsepengene for dem som overskred deres tall som blev utløst ved levittene;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'av Israels barns førstefødte fikk han pengene, et tusen, tre hundre og fem og seksti sekel efter helligdommens sekel.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Og Moses gav Aron og hans sønner løsepengene efter Herrens ord, således som Herren hadde befalt Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Og Herren talte til Moses og Aron og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Ta op manntal over Kahats barn blandt levittene efter deres ætter og familier,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'fra trettiårsalderen og opover inntil femtiårsalderen, over alle som skal trede inn i tjenesten og utføre arbeid ved sammenkomstens telt!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Det som Kahats barn skal stelle med ved sammenkomstens telt, det er de høihellige ting.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Når leiren bryter op, skal Aron og hans sønner gå inn og ta ned det dekkende forheng og bre det over vidnesbyrdets ark.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'De skal legge et dekke av takasskinn over den og over dette igjen bre et klæde, helt igjennem av blå ull, og så sette inn bærestengene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Over skuebrøds-bordet skal de bre et klæde av blå ull, og på det skal de legge fatene og skålene og begerne og drikkoffer-kannene, og det stadige brød skal også ligge der.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Over alt dette skal de bre et klæde av karmosinrød ull og legge et dekke av takasskinn om det og sette inn bærestengene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Så skal de ta et klæde av blå ull og med det dekke lysestaken og dens lamper og lysesaksene og brikkene og alle oljekarene som brukes til tjenesten ved den.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Og de skal legge den og alt som hører til den, i et dekke av takasskinn og legge det på en bærebør.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Over det gullklædde alter skal de bre et klæde av blå ull og legge et dekke av takasskinn om det og sette inn bærestengene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Så skal de ta alle de redskaper som brukes til tjenesten i helligdommen, og legge dem i et klæde av blå ull og dekke dem til med et dekke av takasskinn og legge dem på en bærebør.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Alteret skal de rense for asken og bre et klæde av purpurrød ull over det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'og på det legge alle de redskaper som brukes til tjenesten ved alteret: fyrfatene, kjøttgaflene og ildskuffene og skålene til å sprenge blod med, alle alterets redskaper; de skal bre et dekke av takasskinn over og sette inn bærestengene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Når så Aron og hans sønner ved leirens opbrudd er ferdig med å dekke over helligdommen og alle helligdommens redskaper, så skal Kahats barn komme og bære; men de må ikke røre ved helligdommen, forat de ikke skal dø. Dette er det Kahats barn har å bære av det som hører til sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Men Eleasar, sønn til Aron, presten, skal ha opsynet med oljen til lysestaken og den velluktende røkelse og det stadige matoffer og salvingsoljen, og opsynet med hele tabernaklet og alt som i det er av hellige ting og redskaper som hører til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Og Herren talte til Moses og Aron og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'La ikke kahatittenes ættegren bli utryddet av levittenes stamme,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'men gjør således med dem forat de skal leve og ikke dø når de kommer nær til de høihellige ting: Aron og hans sønner skal gå inn og sette enhver av dem til sin tjeneste og til det han skal bære;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'men selv må de ikke gå inn og se på de hellige ting, enn ikke et øieblikk, forat de ikke skal dø.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Ta også op manntall over Gersons barn efter deres familier og ætter!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Fra trettiårsalderen og opover inntil femtiårsalderen skal du mønstre dem, alle som skal trede inn i tjenesten og utføre arbeid ved sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Dette skal være Gerson-ættenes gjerning med å tjene og bære:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'De skal bære tabernaklets tepper og sammenkomstens telt med dekket og varetaket av takasskinn, som ligger ovenpå, og dekket for inngangen til sammenkomstens telt');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'og omhengene til forgården og forhenget for porten til forgården som er rundt om tabernaklet og alteret, og snorene som hører til, og alle redskapene som brukes til arbeidet derved; og alt som er å gjøre med disse ting, skal de utføre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Efter Arons og hans sønners ord skal all tjeneste utføres som Gersons barn har å gjøre, både med alt det de har å bære, og med hele deres tjeneste; og I skal overgi til deres varetekt alt det de har å bære.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Dette skal være Gerson-ættenes tjeneste ved sammenkomstens telt; og Itamar, sønn til Aron, presten, skal ha opsyn med det de har å ta vare på.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Meraris barn skal du mønstre efter deres ætter og familier.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Fra trettiårsalderen og opover inntil femtiårsalderen skal du mønstre dem, alle som skal trede inn i tjenesten og utføre arbeidet ved sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Og dette er det som de har å bære, alt det de skal stelle med ved sammenkomstens telt: tabernaklets planker og dets tverrstenger og stolper og fotstykker');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'og stolpene til forgården rundt omkring med deres fotstykker og plugger og snorer, alle redskaper som hører til, og alt som brukes til arbeidet derved; og I skal ved navn overgi dem de ting som de har å bære.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Dette skal være Merari-ættenes tjeneste, alt det de skal stelle med ved sammenkomstens telt under opsyn av Itamar, sønn til Aron, presten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Så mønstret Moses og Aron og menighetens høvdinger kahatittene efter deres ætter og familier,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'fra trettiårsalderen og opover inntil femtiårsalderen, alle som skulde trede inn i tjenesten og utføre arbeid ved sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Og de av dem som blev mønstret, hver efter sin ætt, var to tusen, syv hundre og femti.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Så mange var de som blev mønstret i kahatittenes ætter, alle de som tjente ved sammenkomstens telt, og som Moses og Aron mønstret efter Herrens ord ved Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Og de av gersonittene som blev mønstret efter sine ætter og familier,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'fra trettiårsalderen og opover inntil femtiårsalderen, alle som skulde trede inn i tjenesten og utføre arbeid ved sammenkomstens telt -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'de av dem som blev mønstret efter sine ætter og familier - var to tusen, seks hundre og tretti.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Så mange var de som blev mønstret i gersonittenes ætter, alle de som tjente ved sammenkomstens telt, og som Moses og Aron mønstret efter Herrens ord.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Og de som blev mønstret i merarittenes ætter, hver efter sin ætt og familie,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'fra trettiårsalderen og opover inntil femtiårsalderen, alle som skulde trede inn i tjenesten og utføre arbeid ved sammenkomstens telt -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'de av dem som blev mønstret efter sine ætter - var tre tusen og to hundre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Så mange var de som Moses og Aron mønstret i merarittenes ætter efter Herrens ord ved Moses.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Alle de som Moses og Aron og Israels høvdinger mønstret av levittene efter deres ætter og familier,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'fra trettiårsalderen og opover inntil femtiårsalderen, alle som skulde utføre arbeid ved sammenkomstens telt med å tjene og med å bære -');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'de som blev mønstret - var åtte tusen, fem hundre og åtti.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Efter Herrens ord blev de mønstret under Moses\' opsyn, og hver blev satt til å utføre den tjeneste og bære den byrde han skulde; og de som blev mønstret av Moses, var de som Herren hadde befalt ham å mønstre.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Byd Israels barn at de skal sende ut av leiren alle spedalske og alle som har flod, og alle som er blitt urene ved lik!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Både mann og kvinne skal I sende bort; utenfor leiren skal I sende dem, forat de ikke skal gjøre deres leir uren, der hvor jeg bor midt iblandt dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Og Israels barn gjorde så og sendte dem utenfor leiren; som Herren hadde sagt til Moses, således gjorde Israels barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Si til Israels barn: Når en mann eller kvinne gjør nogen av de synder som mennesker gjør, og bærer sig troløst at mot Herren, så de fører skyld over sig,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'da skal de bekjenne den synd som de har gjort, og godtgjøre det de med urette har tatt, med dets fulle verd og enda legge til femtedelen; de skal gi det til den som de har syndet mot.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Men dersom mannen ikke har efterlatt sig nogen nær slektning som de kan gi vederlaget til, da skal vederlaget høre Herren til og tilfalle presten foruten sonings-væren, som skal ofres til soning for dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Og alle gaver, alt det som Israels barn helliger og kommer til presten med, skal høre ham til;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'hver manns hellige gaver skal høre presten til; det nogen gir ham, skal høre ham til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Tal til Israels barn og si til dem: Når en manns hustru forsynder sig og er ham utro,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'og en annen mann har samleie med henne, men hennes mann ikke vet om det, fordi hun har latt sig vanære i lønndom, og der ikke er noget vidne mot henne, og hun ikke er grepet på fersk gjerning,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'og det så kommer en skinnsykens ånd over ham, så han blir skinnsyk på sin hustru, og hun virkelig har latt sig vanære, eller det kommer en skinnsykens ånd over ham, så han blir skinnsyk på sin hustru, uaktet hun ikke har latt sig vanære,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'da skal mannen ta sin hustru med sig til presten og som offer for henne ha med tiendedelen av en efa byggmel; men han skal ikke helle olje på det, heller ikke legge virak på det; for det er et skinnsyke-matoffer, et ihukommelses-matoffer, som skal minne om en brøde.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Så skal presten føre henne frem og stille henne for Herrens åsyn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Og presten skal ta hellig vann i et lerkar og ta noget av støvet som er på tabernaklets gulv, og kaste i vannet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Og når presten har stilt kvinnen frem for Herrens åsyn, skal han løse hennes hår og legge ihukommelses-matofferet i hennes hender - et skinnsyke-matoffer er det - og i sin hånd skal presten ha bitterhetens vann, som volder forbannelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Så skal presten ta kvinnen i ed og si til henne: Så sant ingen har ligget hos dig, og så sant du ikke har vært utro mot din mann og latt dig vanære, så skal du intet mén ha av dette bitterhetens vann som volder forbannelse.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Men er det så at du har vært utro mot din mann og latt dig vanære, og at nogen annen enn din mann har hatt samleie med dig');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, '- nu skal presten lese op forbannelses-eden for kvinnen og si til henne: - så gjøre Herren dig til en forbannelse og til en ed blandt ditt folk; han la dine hofter svinne inn og din buk hovne op;');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'og dette vann som volder forbannelse, skal trenge inn i dine innvoller, så din buk hovner op og dine hofter svinner inn. Og kvinnen skal si: Amen! Amen!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Derefter skal presten skrive op disse forbannelser på et blad og vaske dem ut i bitterhetens vann,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'og han skal la kvinnen drikke bitterhetens vann, som volder forbannelse, og vannet som volder forbannelse, skal trenge inn i henne og volde bitter ve.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Så skal presten ta skinnsyke-matofferet av kvinnens hånd og svinge det for Herrens åsyn og bære det frem til alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Og presten skal ta en håndfull av matofferet som ihukommelses-offer og brenne det på alteret; Og så skal han la kvinnen drikke vannet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Og når han har latt henne drikke vannet, da skal det skje at dersom hun har latt sig vanære og har vært utro mot sin mann, så skal vannet som volder forbannelse, trenge inn i henne og volde bitter ve; hennes buk skal hovne op og hennes hofter svinne inn; og den kvinne skal bli til en forbannelse blandt sitt folk.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Men har kvinnen ikke latt sig vanære, og er hun ren, da skal hun intet mén ha av det, og hun skal få barn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Dette er skinnsyke-loven: Når en kvinne er utro mot sin mann og lar sig vanære,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'eller når en skinnsykens ånd kommer over en mann, så han blir skinnsyk på sin hustru, så skal han stille kvinnen frem for Herrens åsyn, og presten skal gjøre med henne alt det som er sagt i denne lov.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Og mannen skal være fri for skyld, men kvinnen skal lide for sin misgjerning.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Tal til Israels barn og si til dem: Når en mann eller kvinne gjør et hellig løfte om å ville være nasireer og vie sig til Herren,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'så skal han holde sig fra vin og sterk drikk; eddik av vin eller annen sterk eddik skal han ikke drikke og heller ikke nogen saft som er tillaget av druer; hverken friske eller tørre druer skal han ete.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Så lenge hans innvielse varer, skal han ikke ete noget av det som tillages av vintreet, like fra kjerne til skall.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Så lenge hans innvielses-løfte gjelder, skal der ikke gå rakekniv over hans hode; inntil hans innvielses-tid er til ende, skal han være hellig, han skal la sitt hodehår vokse fritt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Så lenge han er innvidd til Herren, skal han ikke komme nær noget lik.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Ikke engang om hans far eller mor eller bror eller søster dør, må han føre urenhet over sig for deres skyld; for han bærer på sitt hode tegnet på innvielsen til sin Gud.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Hele sin innvielses-tid er han hellig for Herren.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Men dør der nogen hos ham uventet og brått og fører urenhet over hans innvidde hode, da skal han rake sitt hode den dag han blir ren; den syvende dag skal han rake det.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Og på den åttende dag skal han komme til presten med to turtelduer eller to dueunger, til inngangen til sammenkomstens telt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Og presten skal ofre den ene til syndoffer og den andre til brennoffer og gjøre soning for ham og rense ham for den synd han har ført over sig ved å komme nær liket. Så skal han samme dag hellige sitt hode,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'og på ny vie sig til Herren for like sa lang tid som han først hadde lovt, og føre frem et årsgammelt lam til skyldoffer; den første tid gjelder ikke mere, fordi hans innvielse blev utskjemt.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Dette er loven for nasireeren: Den dag hans innvielses-tid er til ende, skal han føres frem til inngangen til sammenkomstens telt,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'og han skal bære frem for Herren sitt offer, et årsgammelt værlam uten lyte til brennoffer og et årsgammelt hunlam uten lyte til syndoffer og en vær uten lyte til takkoffer');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'og en kurv med usyrede kaker av fint mel, kaker med olje i, og usyrede brødleiver smurt med olje, og matofferet og drikkofferne som hører til.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Og presten skal bære det frem for Herrens åsyn og ofre hans syndoffer og hans brennoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Og væren skal han ofre som takkoffer til Herren sammen med kurven med de usyrede kaker, og så skal presten ofre hans matoffer og hans drikkoffer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Derefter skal nasireeren rake sitt innvidde hode ved inngangen til sammenkomstens telt, og han skal ta sitt innvidde hodehår og legge det på ilden som er under takkofferet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Og presten skal ta en bog av væren, efterat den er kokt, og en usyret kake av kurven og en usyret brødleiv og legge dem i hendene på nasireeren, efterat han har raket av sitt innvielsestegn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Så skal presten svinge dem for Herrens åsyn; det er helliget presten foruten svinge-brystet og løfte-låret. Siden kan nasireeren drikke vin.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Dette er loven for den som gjør et nasireer-løfte, dette er det han skal ofre til Herren på grunn av sin innvielse, foruten det han ellers har råd til; han skal holde sig efter det løfte han har gjort, foruten det loven om hans innvielse krever.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Og Herren talte til Moses og sa:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Tal til Aron og hans sønner og si: Således skal I si når I velsigner Israels barn:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Herren velsigne dig og bevare dig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Herren la sitt åsyn lyse over dig og være dig nådig!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Herren løfte sitt åsyn på dig og gi dig fred!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Således skal de legge mitt navn på Israels barn, og jeg vil velsigne dem.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Da nu Moses var ferdig med å reise tabernaklet og hadde salvet det og helliget det med alt som hørte til det, og likeledes salvet og helliget alteret med alt som hørte til det,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'da kom Israels høvdinger, overhodene for sine familier, stammefyrstene, de som stod over alle som var blitt mønstret, og bar frem gaver.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'De bar sin gave frem for Herrens åsyn, seks vogner med dekke over og tolv okser, en vogn for to høvdinger og en okse for hver; og de førte dem frem foran tabernaklet.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Og Herren sa til Moses:');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Ta imot dette av dem, forat det kan brukes til tjenesten ved sammenkomstens telt, og du skal gi det til levittene, efter som enhver av dem trenger det til sin tjeneste.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Da tok Moses vognene og oksene og gav dem til levittene.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'To av vognene og fire av oksene gav han til Gersons barn, efter deres særlige tjeneste.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Og fire av vognene og åtte av oksene gav han til Meraris barn, efter deres særlige tjeneste under opsyn av Itamar, sønn til Aron, presten.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Men til Kahats barn gav han ikke noget, fordi de skulde ta vare på de hellige ting og bære dem på sine skuldrer.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Den dag alteret blev salvet, kom høvdingene med gaver til dets innvielse, og de bar sin gave frem foran alteret.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Da sa Herren til Moses: La høvdingene komme med sin gave til alterets innvielse hver sin dag!');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Og den som bar frem sin gave den første dag, var Nahson, Amminadabs sønn, høvdingen for Juda stamme.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Hans gave var et sølvfat som veide hundre og tretti sekel, en sølvskål på sytti sekel efter helligdommens vekt, begge fulle av fint mel blandet med olje, til matoffer,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'en skål av gull på ti sekel, full av røkelse,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'en ung okse, en vær og et årsgammelt lam til brennoffer,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'en gjetebukk til syndoffer');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'og til takkoffer to okser, fem værer, fem bukker og fem årsgamle lam. Dette var Nahsons, Amminadabs sønns gave.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Den annen dag kom Netanel, Suars sønn, Issakars høvding, med sin gave.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Han bar frem som sin gave et sølvfat som veide hundre og tretti sekel, en sølvskål på sytti sekel efter helligdommens vekt, begge fulle av fint mel blandet med olje, til matoffer,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'en skål av gull på ti sekel, full av røkelse,');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'en ung okse, en vær og et årsgammelt lam til brennoffer,');
