INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'og til takkoffer to okser, fem værer, fem bukker og fem årsgamle lam. Dette var Netanels, Suars sønns gave.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Den tredje dag kom høvdingen for Sebulons barn, Eliab, Helons sønn.');
