INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Den niende dag kom høvdingen for Benjamins barn, Abidan, Gideonis sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Hans gave var et sølvfat som veide hundre og tretti sekel, en sølvskål på sytti sekel efter helligdommens vekt, begge fulle av fint mel blandet med olje, til matoffer,');
