INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Den ellevte dag kom høvdingen for Asers barn, Pagiel, Okrans sønn.');
INSERT INTO `Norsk_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Hans gave var et sølvfat som veide hundre og tretti sekel, en sølvskål på sytti sekel efter helligdommens vekt, begge fulle av fint mel blandet med olje, til matoffer,');
