            CREATE TABLE IF NOT EXISTS `translations` (
                `translation` VARCHAR(255) PRIMARY KEY,
                `title` VARCHAR(255),
                `license` TEXT
            );
            

            VALUES ('Norsk', '# Norsk: Bibelen på Norsk (1930)', 'Public Domain')
            ON DUPLICATE KEY UPDATE
                `title` = VALUES(`title`),
                `license` = VALUES(`license`);
            

            CREATE TABLE `Norsk_books` (
                `id` INT AUTO_INCREMENT PRIMARY KEY,
                `name` VARCHAR(255)
            );
            

            CREATE TABLE `Norsk_verses` (
                `id` INT AUTO_INCREMENT PRIMARY KEY,
                `book_id` INT,
                `chapter` INT,
                `verse` INT,
                `text` TEXT,
                FOREIGN KEY (book_id) REFERENCES `Norsk_books`(id)
            );
            
